function encodePublicMediaPath(value = "") {
  const raw = String(value || "").replaceAll("\\", "/").trim();

  if (!raw) return "";
  if (/^https?:\/\//i.test(raw) || raw.startsWith("blob:")) return raw;

  return raw
    .split("/")
    .map((part, index) => {
      if (index === 0 && part === "") return "";
      try {
        return encodeURIComponent(decodeURIComponent(part));
      } catch {
        return encodeURIComponent(part);
      }
    })
    .join("/");
}

function getPlayableMediaUrl(item = {}, preview = {}) {
  const previewQuery = new URLSearchParams();
  if (preview.width) previewQuery.set("width", String(preview.width));
  if (preview.quality) previewQuery.set("quality", String(preview.quality));
  const previewSuffix = previewQuery.toString() ? `&${previewQuery}` : "";
  const sourcePath =
    item.sourcePath ||
    item.file?.sourcePath ||
    item.audioFile?.sourcePath ||
    item.videoFile?.sourcePath ||
    item.media?.sourcePath ||
    "";

  if (sourcePath) {
    const rawSource = String(sourcePath).trim();
    if (/^(?:https?:|blob:|data:)/i.test(rawSource)) return rawSource;
    if (/^\/api\/file(?:\?|$)/i.test(rawSource)) return `${rawSource}${previewQuery.toString() ? `${rawSource.includes("?") ? "&" : "?"}${previewQuery}` : ""}`;
    if (/^\/(?:media|assets|images|placeholder(?:-|\/)|favicon)/i.test(rawSource)) return encodePublicMediaPath(rawSource);
    if (/^\/api\//i.test(rawSource)) return rawSource;
    return `/api/file?path=${encodeURIComponent(rawSource)}${previewSuffix}`;
  }

  const publicPath =
    item.audioUrl ||
    item.videoUrl ||
    item.mediaUrl ||
    item.src ||
    item.path ||
    item.publicPath ||
    item.url ||
    item.file?.path ||
    item.audioFile?.path ||
    item.videoFile?.path ||
    item.media?.path ||
    "";

  if (publicPath) {
    const rawPublic = String(publicPath).trim();
    if (/^(?:https?:|blob:|data:)/i.test(rawPublic)) return rawPublic;
    if (/^\/api\/file(?:\?|$)/i.test(rawPublic)) return `${rawPublic}${previewQuery.toString() ? `${rawPublic.includes("?") ? "&" : "?"}${previewQuery}` : ""}`;
    if (/^\/(?:media|assets|images|placeholder(?:-|\/)|favicon)/i.test(rawPublic)) return encodePublicMediaPath(rawPublic);
    if (/^\/api\//i.test(rawPublic)) return rawPublic;
    if (/^(?:[A-Za-z]:[\\/]|\\\\|\/)/.test(rawPublic)) return `/api/file?path=${encodeURIComponent(rawPublic)}${previewSuffix}`;
  }

  return encodePublicMediaPath(publicPath);
}


const DEFAULT_HOMESTEAD_APP_ICON = "/assets/images/homestead-icon.png";

function getHomesteadBrandingVersion(source = {}) {
  const branding = source?.branding || source || {};
  return String(
    branding.appIconVersion ||
    branding.version ||
    branding.updatedAt ||
    "default"
  );
}

function getHomesteadAppIconUrl(source = {}) {
  const branding = source?.branding || source || {};
  const configuredUrl = String(
    branding.appIconUrl ||
    branding.iconUrl ||
    "/api/branding/icon"
  ).trim();

  if (!configuredUrl) return DEFAULT_HOMESTEAD_APP_ICON;
  if (/^(?:data:|blob:)/i.test(configuredUrl)) return configuredUrl;

  const separator = configuredUrl.includes("?") ? "&" : "?";
  return `${configuredUrl}${separator}v=${encodeURIComponent(getHomesteadBrandingVersion(branding))}`;
}

function upsertHomesteadHeadLink(rel, href, attributes = {}) {
  if (typeof document === "undefined" || !href) return;
  let link =
    document.head.querySelector(`link[data-homestead-branding="${rel}"]`) ||
    document.head.querySelector(`link[rel="${rel}"]`);
  if (!link) {
    link = document.createElement("link");
    document.head.appendChild(link);
  }
  link.dataset.homesteadBranding = rel;
  link.rel = rel;
  link.href = href;
  Object.entries(attributes).forEach(([key, value]) => {
    if (value !== undefined && value !== null) link.setAttribute(key, String(value));
  });
  return link;
}

function removeLegacyHomesteadIconLinks(activeLinks = []) {
  if (typeof document === "undefined") return;
  const keep = new Set(activeLinks.filter(Boolean));
  document.head
    .querySelectorAll('link[rel="icon"], link[rel="shortcut icon"], link[rel="apple-touch-icon"], link[rel="manifest"]')
    .forEach((link) => {
      if (keep.has(link)) return;
      const href = String(link.getAttribute("href") || "");
      if (/vite(?:\.svg|\.png)?|manifest(?:\.webmanifest|\.json)?|site\.webmanifest|pwa-?\d+/i.test(href)) {
        link.remove();
      }
    });
}

function applyHomesteadDocumentBranding({ branding = {}, serverName = "" } = {}) {
  if (typeof document === "undefined") return;
  const iconUrl = getHomesteadAppIconUrl(branding);
  const version = getHomesteadBrandingVersion(branding);

  const iconLink = upsertHomesteadHeadLink("icon", iconUrl, {
    type: "image/png",
    sizes: "512x512",
  });
  const shortcutIconLink = upsertHomesteadHeadLink("shortcut icon", iconUrl, {
    type: "image/png",
  });
  const appleTouchLink = upsertHomesteadHeadLink("apple-touch-icon", iconUrl, {
    sizes: "512x512",
  });
  const manifestLink = upsertHomesteadHeadLink(
    "manifest",
    `/api/branding/manifest.webmanifest?v=${encodeURIComponent(version)}`
  );
  removeLegacyHomesteadIconLinks([
    iconLink,
    shortcutIconLink,
    appleTouchLink,
    manifestLink,
  ]);

  let themeMeta = document.head.querySelector('meta[name="theme-color"]');
  if (!themeMeta) {
    themeMeta = document.createElement("meta");
    themeMeta.name = "theme-color";
    document.head.appendChild(themeMeta);
  }
  themeMeta.content = "#11141d";

  if (serverName) document.title = String(serverName).trim() || "Homestead";
}

function createSquareAppIconDataUrl(file, size = 512) {
  return new Promise((resolve, reject) => {
    if (!file || !String(file.type || "").startsWith("image/")) {
      reject(new Error("Choose a PNG, JPG, or WebP image."));
      return;
    }
    if (file.size > 12 * 1024 * 1024) {
      reject(new Error("Choose an image smaller than 12 MB."));
      return;
    }

    const objectUrl = URL.createObjectURL(file);
    const image = new Image();
    image.onload = () => {
      try {
        if (!image.naturalWidth || !image.naturalHeight) {
          throw new Error("The selected image could not be read.");
        }
        const canvas = document.createElement("canvas");
        canvas.width = size;
        canvas.height = size;
        const context = canvas.getContext("2d");
        if (!context) throw new Error("This browser cannot prepare the app icon.");

        const sourceSize = Math.min(image.naturalWidth, image.naturalHeight);
        const sourceX = Math.max(0, (image.naturalWidth - sourceSize) / 2);
        const sourceY = Math.max(0, (image.naturalHeight - sourceSize) / 2);
        context.clearRect(0, 0, size, size);
        context.drawImage(
          image,
          sourceX,
          sourceY,
          sourceSize,
          sourceSize,
          0,
          0,
          size,
          size
        );
        resolve(canvas.toDataURL("image/png"));
      } catch (error) {
        reject(error);
      } finally {
        URL.revokeObjectURL(objectUrl);
      }
    };
    image.onerror = () => {
      URL.revokeObjectURL(objectUrl);
      reject(new Error("The selected image could not be loaded."));
    };
    image.src = objectUrl;
  });
}

function BrandingIconEditor({
  branding = {},
  serverName = "Homestead",
  onBrandingChange,
  title = "App Icon",
  description = "Used in the desktop sidebar, browser tab, and when Homestead is added to a phone home screen.",
  compact = false,
}) {
  const inputRef = useRef(null);
  const [status, setStatus] = useState("");
  const [loadingMore, setLoadingMore] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const browserCardRef = useRef(null);
  const [busy, setBusy] = useState(false);
  const iconUrl = getHomesteadAppIconUrl(branding);

  async function uploadIcon(file) {
    if (!file || busy) return;
    setBusy(true);
    setStatus("Preparing icon…");
    try {
      const imageData = await createSquareAppIconDataUrl(file, 512);
      setStatus("Saving icon…");
      const response = await fetch("/api/branding/icon", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ imageData }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || data.ok === false) {
        throw new Error(data.message || "Unable to save the app icon.");
      }
      const nextBranding = data.branding || {
        ...branding,
        appIconUrl: "/api/branding/icon",
        appIconVersion: String(Date.now()),
        hasCustomIcon: true,
      };
      onBrandingChange?.(nextBranding);
      applyHomesteadDocumentBranding({ branding: nextBranding, serverName });
      window.dispatchEvent(new CustomEvent("homestead-branding-updated", { detail: nextBranding }));
      setStatus("App icon saved.");
    } catch (error) {
      setStatus(error.message || "Unable to save the app icon.");
    } finally {
      setBusy(false);
      if (inputRef.current) inputRef.current.value = "";
    }
  }

  async function resetIcon() {
    if (busy) return;
    setBusy(true);
    setStatus("Restoring default icon…");
    try {
      const response = await fetch("/api/branding/icon", { method: "DELETE" });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || data.ok === false) {
        throw new Error(data.message || "Unable to restore the default icon.");
      }
      const nextBranding = data.branding || {
        appIconUrl: "/api/branding/icon",
        appIconVersion: String(Date.now()),
        hasCustomIcon: false,
      };
      onBrandingChange?.(nextBranding);
      applyHomesteadDocumentBranding({ branding: nextBranding, serverName });
      window.dispatchEvent(new CustomEvent("homestead-branding-updated", { detail: nextBranding }));
      setStatus("Default icon restored.");
    } catch (error) {
      setStatus(error.message || "Unable to restore the default icon.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className={`branding-icon-editor ${compact ? "compact" : ""}`}>
      <div className="branding-icon-preview">
        <img
          key={iconUrl}
          src={iconUrl}
          alt={`${serverName || "Homestead"} app icon`}
          onError={(event) => {
            event.currentTarget.onerror = null;
            event.currentTarget.src = DEFAULT_HOMESTEAD_APP_ICON;
          }}
        />
      </div>
      <div className="branding-icon-copy">
        <div>
          <h4>{title}</h4>
          <p>{description}</p>
        </div>
        <div className="branding-icon-actions">
          <button
            className="secondary-button"
            type="button"
            disabled={busy}
            onClick={() => inputRef.current?.click()}
          >
            {branding?.hasCustomIcon ? "Replace Icon" : "Choose Icon"}
          </button>
          {branding?.hasCustomIcon && (
            <button className="setup-back-button" type="button" disabled={busy} onClick={resetIcon}>
              Use Default
            </button>
          )}
          <input
            ref={inputRef}
            className="branding-icon-file-input"
            type="file"
            accept="image/png,image/jpeg,image/webp"
            onChange={(event) => uploadIcon(event.target.files?.[0])}
          />
        </div>
        <small>Homestead center-crops the image to a 512 × 512 PNG. A simple square image works best.</small>
        {status && <span className="branding-icon-status">{status}</span>}
      </div>
    </section>
  );
}

