function MediaGallery({ files, openImageViewer, adultMediaActions = null }) {
  function fileUrl(file) {
    return getPlayableMediaUrl(file, { width: 512, quality: 78 });
  }

  const isArtworkSelectionMode = Boolean(adultMediaActions?.enabled && adultMediaActions?.selectionMode);
  const artworkSelectionLabel = {
    poster: "Poster",
    banner: "Banner",
    headshot: "Headshot",
    breasts: "Breasts",
    pussy: "Pussy",
    ass: "Ass",
  }[adultMediaActions?.selectionMode] || "Artwork";
  const getMediaKind = (file = {}) => {
    const value = String(file?.sourcePath || file?.path || file?.publicPath || file?.url || file?.name || "").toLowerCase();
    if (file?.type === "video" || /\.(mp4|m4v|mov|webm|mkv)(?:$|[?#])/i.test(value)) return "video";
    if (file?.type === "image" || /\.(jpe?g|png|webp|gif)(?:$|[?#])/i.test(value)) return "image";
    return String(file?.type || "").toLowerCase();
  };
  const canUseForArtwork = (file = {}) => {
    const kind = getMediaKind(file);
    return kind === "image" || (adultMediaActions?.selectionMode === "banner" && kind === "video");
  };

  if (!files.length) {
    return (
      <div className="panel">
        <h3>No Media Found</h3>
        <p>
          Add files to this folder, run <strong>npm run scan:media</strong>, then refresh.
        </p>
      </div>
    );
  }

  return (
    <div className={`media-gallery ${isArtworkSelectionMode ? "media-gallery-select-artwork" : ""}`}>
      {files.map((file) => (
        <button
          key={file.sourcePath || file.path}
          className="media-thumb"
          type="button"
          onClick={() => {
            const mediaKind = getMediaKind(file);
            if (isArtworkSelectionMode && canUseForArtwork(file)) {
              adultMediaActions.onAction?.(adultMediaActions.selectionMode, file);
              return;
            }

            if (mediaKind === "image") {
              const imageFiles = files
                .filter((item) => getMediaKind(item) === "image")
                .map((item) => adultMediaActions?.enabled
                  ? { ...item, adultArtworkActions: adultMediaActions }
                  : item
                );
              const imageIndex = imageFiles.findIndex(
                (item) =>
                  (item.sourcePath || item.path) ===
                  (file.sourcePath || file.path)
              );

              openImageViewer?.(imageFiles, imageIndex);
            }

            if (mediaKind === "video") {
              openImageViewer?.([file], 0);
            }
          }}
        >
          {getMediaKind(file) === "video" ? (
            <div className="video-thumb-placeholder">▶</div>
          ) : (
            <img src={fileUrl(file)} alt="" loading="lazy" decoding="async" fetchPriority="low" />
          )}

          {isArtworkSelectionMode && canUseForArtwork(file) && (
            <span className="media-thumb-select-badge">
              Set {artworkSelectionLabel}
            </span>
          )}
        </button>
      ))}
    </div>
  );
}


