function normalizeProfileNoteEntries(value) {
  if (!Array.isArray(value)) return [];
  return value
    .map((note, index) => {
      if (!note) return null;
      if (typeof note === "string") {
        const body = note.trim();
        if (!body) return null;
        return {
          id: `legacy-note-${index}`,
          category: "General Notes",
          title: "Note",
          body,
          pinned: false,
          updatedAt: "",
        };
      }
      const body = String(note.body || note.note || note.text || note.description || "").trim();
      const title = String(note.title || note.name || "").trim();
      if (!body && !title) return null;
      return {
        id: note.id || `note-${index}-${title || body}`.replace(/[^a-z0-9_-]+/gi, "-").slice(0, 80),
        category: String(note.category || note.type || "General Notes").trim() || "General Notes",
        title: title || "Untitled note",
        body,
        pinned: !!note.pinned,
        updatedAt: note.updatedAt || note.createdAt || "",
      };
    })
    .filter(Boolean);
}

function createBlankProfileNoteDraft() {
  return {
    id: "",
    category: "General Notes",
    title: "",
    body: "",
    pinned: false,
  };
}

function normalizeProfileTimelineDate(value) {
  if (!value) return new Date().toISOString();
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return new Date().toISOString();
  return parsed.toISOString();
}

function formatProfileTimelineDate(value, precision = "day") {
  return formatHomesteadPreciseDate(value, precision);
}

function normalizeProfileTimelineEntries(entries = [], source = "saved") {
  if (!Array.isArray(entries)) return [];
  return entries
    .map((entry, index) => {
      if (!entry || typeof entry !== "object") return null;
      const date = normalizeProfileTimelineDate(entry.effectiveAt || entry.date || entry.eventDate || entry.createdAt || entry.updatedAt);
      const title = String(entry.title || entry.label || entry.event || "Timeline entry").trim();
      const type = String(entry.type || entry.category || "note").trim().toLowerCase() || "note";
      return {
        id: entry.id || `${source}-${date}-${type}-${index}`,
        date,
        type,
        title,
        note: String(entry.note || entry.description || entry.summary || "").trim(),
        source: entry.source || source,
        effectiveAt: entry.effectiveAt || date,
        effectivePrecision: entry.effectivePrecision || "day",
        recordedAt: entry.recordedAt || entry.createdAt || entry.updatedAt || "",
        showRecordedAt: entry.showRecordedAt !== false,
        revertsEventId: entry.revertsEventId || "",
        changes: Array.isArray(entry.changes) ? entry.changes : [],
        correction: Boolean(entry.correction),
        saved: source === "metadata" || source === "profile",
      };
    })
    .filter(Boolean);
}

function buildInferredProfileTimelineEntries(profile = {}) {
  const metadata = profile.metadata || {};
  const entries = [];

  const createdAt = profile.createdAt || metadata.createdAt || metadata.profileCreatedAt || metadata.created || null;
  if (createdAt) {
    entries.push({
      id: "inferred-profile-created",
      date: normalizeProfileTimelineDate(createdAt),
      type: "profile",
      title: "Profile created",
      note: "This profile record was created in Homestead.",
      source: "inferred",
      saved: false,
    });
  }

  const metadataFetchedAt = metadata.metadataFetchedAt || metadata.lastMetadataFetchAt || metadata.fetchUpdatedAt || metadata.updatedAt || null;
  if (metadataFetchedAt) {
    entries.push({
      id: "inferred-metadata-updated",
      date: normalizeProfileTimelineDate(metadataFetchedAt),
      type: "metadata",
      title: "Metadata updated",
      note: metadata.source || metadata.provider ? `Source: ${metadata.source || metadata.provider}` : "Profile metadata was updated.",
      source: "inferred",
      saved: false,
    });
  }

  if (metadata.profileFactsUpdatedAt) {
    entries.push({
      id: "inferred-biography-updated",
      date: normalizeProfileTimelineDate(metadata.profileFactsUpdatedAt),
      type: "biography",
      title: "Biography updated",
      note: "Biography, notes, or profile facts were edited.",
      source: "inferred",
      saved: false,
    });
  }

  if (metadata.socialLinksUpdatedAt) {
    entries.push({
      id: "inferred-social-updated",
      date: normalizeProfileTimelineDate(metadata.socialLinksUpdatedAt),
      type: "social",
      title: "Social links updated",
      note: "Profile social links were added or refreshed.",
      source: "inferred",
      saved: false,
    });
  }

  if (metadata.profileNotesUpdatedAt) {
    entries.push({
      id: "inferred-notes-updated",
      date: normalizeProfileTimelineDate(metadata.profileNotesUpdatedAt),
      type: "note",
      title: "Notes updated",
      note: "Private profile notes were edited.",
      source: "inferred",
      saved: false,
    });
  }

  const importedAt = metadata.mediaImportedAt || metadata.lastMediaImportAt || metadata.profileMediaUpdatedAt || null;
  if (importedAt) {
    entries.push({
      id: "inferred-media-imported",
      date: normalizeProfileTimelineDate(importedAt),
      type: "media",
      title: "Media imported",
      note: "Profile media was imported or refreshed.",
      source: "inferred",
      saved: false,
    });
  }

  return entries;
}

function getProfileTimelineEntries(profile = {}) {
  const metadata = profile.metadata || {};
  const savedEntries = normalizeProfileTimelineEntries(metadata.timeline || metadata.timelineEntries || profile.timeline || [], "metadata");
  const inferredEntries = buildInferredProfileTimelineEntries(profile);
  const seen = new Set();
  return [...savedEntries, ...inferredEntries]
    .filter((entry) => {
      const key = `${entry.type}|${entry.title}|${entry.date.slice(0, 10)}|${entry.note}`.toLowerCase();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
}

function getProfileTimelineTypeLabel(type = "") {
  const match = PROFILE_TIMELINE_TYPES.find(([key]) => key === String(type || "").toLowerCase());
  return match?.[1] || "Note";
}

function ProfileTimelinePanel({ profile = {}, onMetadataSaved, editRequest = 0 }) {
  const metadata = profile.metadata || {};
  const [showEditor, setShowEditor] = useState(false);
  const [saving, setSaving] = useState(false);
  const [status, setStatus] = useState("");
  const [viewMode, setViewMode] = useState("split");
  const [draft, setDraft] = useState({
    type: "note",
    date: new Date().toISOString().slice(0, 10),
    title: "",
    note: "",
  });

  useEffect(() => {
    setStatus("");
    setShowEditor(false);
    setDraft({ type: "note", date: new Date().toISOString().slice(0, 10), title: "", note: "" });
  }, [profile?.id]);

  const savedEntries = normalizeProfileTimelineEntries(metadata.timeline || metadata.timelineEntries || [], "metadata");
  const entries = getProfileTimelineEntries(profile);

  function updateDraft(field, value) {
    setDraft((current) => ({ ...(current || {}), [field]: value }));
  }

  async function saveTimelineEntries(nextEntries, message = "Timeline saved.") {
    setSaving(true);
    setStatus("Saving timeline…");

    try {
      const updatedAt = new Date().toISOString();
      const nextMetadata = {
        ...metadata,
        timeline: nextEntries,
        timelineUpdatedAt: updatedAt,
      };
      const response = await fetch("/api/metadata/adult/apply", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          person: {
            ...profile,
            library: profile.library || "personal",
            profileDir: profile.profileDir || profile.folderPath || profile.sourcePath || profile.path || "",
            folderPath: profile.folderPath || profile.profileDir || profile.sourcePath || "",
          },
          metadata: nextMetadata,
          libraryType: profile.library || "personal",
        }),
      });
      const data = await readAdultMetadataJson(response, "Timeline save");
      if (!response.ok || !data.ok) throw new Error(data.message || "Timeline save failed.");

      onMetadataSaved?.(data.metadata || nextMetadata);
      setStatus(data.message || message);
      window.dispatchEvent(new CustomEvent("homestead-adult-profile-updated", {
        detail: {
          reason: "timeline-updated",
          profileId: profile.id,
          profileName: profile.name || profile.title,
          libraryType: profile.library,
          metadata: data.metadata || nextMetadata,
        },
      }));
      window.dispatchEvent(new Event("homestead-metadata-match-updated"));
    } catch (error) {
      setStatus(error.message || "Timeline save failed.");
    } finally {
      setSaving(false);
    }
  }

  async function addTimelineEntry() {
    const title = String(draft.title || "").trim();
    const note = String(draft.note || "").trim();
    if (!title && !note) {
      setStatus("Add a title or note first.");
      return;
    }
    const date = normalizeProfileTimelineDate(draft.date || new Date().toISOString());
    const entry = {
      id: `manual-${Date.now()}`,
      date,
      type: draft.type || "note",
      title: title || getProfileTimelineTypeLabel(draft.type),
      note,
      source: "manual",
    };
    const nextEntries = [entry, ...savedEntries].slice(0, 200);
    await saveTimelineEntries(nextEntries, "Timeline entry added.");
    setDraft({ type: "note", date: new Date().toISOString().slice(0, 10), title: "", note: "" });
    setShowEditor(false);
  }

  async function removeSavedTimelineEntry(entryId) {
    const nextEntries = savedEntries.filter((entry) => entry.id !== entryId);
    await saveTimelineEntries(nextEntries, "Timeline entry removed.");
  }

  async function revertMetadataEntry(entry, confirmConflicts = false) {
    setSaving(true);
    setStatus("Reverting metadata change…");
    try {
      const response = await fetch("/api/metadata/adult/revert", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ person: profile, eventId: entry.id, confirmConflicts }),
      });
      const data = await readAdultMetadataJson(response, "Metadata revert");
      if (response.status === 409 && data.code === "CURRENT_VALUE_CHANGED") {
        const confirmed = window.confirm(`These fields have newer values: ${(data.conflicts || []).join(", ")}. Revert them anyway?`);
        if (confirmed) return revertMetadataEntry(entry, true);
        setStatus("Revert cancelled; current values were left unchanged.");
        return;
      }
      if (!response.ok || !data.ok) throw new Error(data.message || "Metadata revert failed.");
      onMetadataSaved?.(data.metadata);
      setStatus("Previous stored values restored and logged in the timeline.");
      window.dispatchEvent(new CustomEvent("homestead-adult-profile-updated", { detail: { reason: "metadata-reverted", profileId: profile.id, profileName: profile.name || profile.title, libraryType: profile.library, metadata: data.metadata } }));
    } catch (error) {
      setStatus(error.message || "Metadata revert failed.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="profile-timeline-panel">
      <div className="profile-timeline-header">
        <div>
          <h3>Timeline</h3>
          <p>Profile history, manual notes, metadata changes, imports, social updates, and milestones.</p>
        </div>
        <div className="profile-timeline-actions">
          <span className="profile-media-count">{entries.length} {entries.length === 1 ? "entry" : "entries"}</span>
          <button type="button" className="secondary-button" onClick={() => setShowEditor((value) => !value)}>
            {showEditor ? "Close" : "+ Add Entry"}
          </button>
        </div>
      </div>

      {status && <div className="adult-profile-inline-status">{status}</div>}

      {showEditor && (
        <div className="profile-timeline-editor">
          <label>
            <span>Type</span>
            <select value={draft.type || "note"} onChange={(event) => updateDraft("type", event.target.value)}>
              {PROFILE_TIMELINE_TYPES.map(([key, label]) => <option key={key} value={key}>{label}</option>)}
            </select>
          </label>
          <label>
            <span>Date</span>
            <input type="date" value={draft.date || ""} onChange={(event) => updateDraft("date", event.target.value)} />
          </label>
          <label className="profile-timeline-title-field">
            <span>Title</span>
            <input value={draft.title || ""} onChange={(event) => updateDraft("title", event.target.value)} placeholder="ex. Photos imported, first interview, favorite food changed" />
          </label>
          <label className="profile-timeline-note-field">
            <span>Note</span>
            <textarea rows={3} value={draft.note || ""} onChange={(event) => updateDraft("note", event.target.value)} placeholder="Optional details for this timeline entry…" />
          </label>
          <div className="profile-timeline-editor-actions">
            <button type="button" className="secondary-button request-button" onClick={addTimelineEntry} disabled={saving}>{saving ? "Saving…" : "Save Entry"}</button>
          </div>
        </div>
      )}

      {entries.length ? (
        <div className="profile-timeline-list">
          {entries.map((entry) => (
            <article className={`profile-timeline-entry profile-timeline-entry-${entry.type || "note"}`} key={entry.id}>
              <div className="profile-timeline-marker" aria-hidden="true" />
              <div className="profile-timeline-entry-card">
                <div className="profile-timeline-entry-topline">
                  <span className="profile-timeline-type">{getProfileTimelineTypeLabel(entry.type)}</span>
                  <time>{formatProfileTimelineDate(entry.effectiveAt || entry.date, entry.effectivePrecision)}</time>
                </div>
                <h4>{entry.title}</h4>
                {entry.note && <p>{entry.note}</p>}
                {!!entry.changes?.length && (
                  <dl className="profile-timeline-change-list">
                    {entry.changes.map((change, index) => (
                      <div key={`${entry.id}-${change.field || index}`}>
                        <dt>{change.label || change.field || "Field"}</dt>
                        <dd><span>{formatHomesteadField(change.field, change.previous ?? change.previousLabel)}</span><b>→</b><strong>{formatHomesteadField(change.field, change.value ?? change.valueLabel)}</strong></dd>
                      </div>
                    ))}
                  </dl>
                )}
                <div className="profile-timeline-entry-footer">
                  <span>{entry.saved ? "Saved in metadata.json" : "Auto-detected"}{entry.showRecordedAt && entry.recordedAt && (entry.effectivePrecision === "unknown" || String(entry.recordedAt).slice(0, 10) !== String(entry.effectiveAt || entry.date).slice(0, 10)) ? ` · Recorded ${formatProfileTimelineDate(entry.recordedAt)}` : ""}{entry.source ? ` · ${entry.source}` : ""}</span>
                  {entry.saved && (
                    <span className="profile-timeline-entry-buttons">
                      {!!entry.changes?.length && <button type="button" className="secondary-button" onClick={() => revertMetadataEntry(entry)} disabled={saving}>Undo / revert</button>}
                      <button type="button" className="secondary-button" onClick={() => removeSavedTimelineEntry(entry.id)} disabled={saving}>Remove event</button>
                    </span>
                  )}
                </div>
              </div>
            </article>
          ))}
        </div>
      ) : (
        <div className="profile-media-empty-state profile-timeline-empty-state">
          <div className="profile-media-empty-icon">🕒</div>
          <strong>No timeline entries yet.</strong>
          <p>Add the first event, note, import, metadata update, or profile milestone for this person.</p>
          <button type="button" className="secondary-button request-button" onClick={() => setShowEditor(true)}>+ Add First Entry</button>
        </div>
      )}
    </div>
  );
}

function ProfileNotesPanel({ profile = {}, onMetadataSaved, editRequest = 0 }) {
  const metadata = mergeAdultLoadedMetadata(profile.metadata || {}, profile || {});
  const [saving, setSaving] = useState(false);
  const [status, setStatus] = useState("");
  const [viewMode, setViewMode] = useState("split");
  const [showEditor, setShowEditor] = useState(false);
  const [editingId, setEditingId] = useState("");
  const [generalDraft, setGeneralDraft] = useState(metadata.privateNotes || metadata.profilePrivateNotes || "");
  const [localNotes, setLocalNotes] = useState(() => normalizeProfileNoteEntries(metadata.profileNotes || metadata.privateNoteCards || []));
  const [draft, setDraft] = useState(createBlankProfileNoteDraft());

  useEffect(() => {
    const nextMetadata = mergeAdultLoadedMetadata(profile?.metadata || {}, profile || {});
    setStatus("");
    setShowEditor(false);
    setEditingId("");
    setGeneralDraft(nextMetadata.privateNotes || nextMetadata.profilePrivateNotes || "");
    setLocalNotes(normalizeProfileNoteEntries(nextMetadata.profileNotes || nextMetadata.privateNoteCards || []));
    setDraft(createBlankProfileNoteDraft());
  }, [profile?.id, profile?.updatedAt, profile?.metadata?.profileNotesUpdatedAt, profile?.profileNotesUpdatedAt]);

  useEffect(() => {
    if (editRequest > 0) setShowEditor(true);
  }, [editRequest]);

  const savedNotes = localNotes;
  const sortedNotes = [...savedNotes].sort((a, b) => {
    if (a.pinned !== b.pinned) return a.pinned ? -1 : 1;
    const aTime = new Date(a.updatedAt || 0).getTime();
    const bTime = new Date(b.updatedAt || 0).getTime();
    return bTime - aTime;
  });
  const pinnedCount = sortedNotes.filter((note) => note.pinned).length;

  function updateDraft(field, value) {
    setDraft((current) => ({ ...(current || {}), [field]: value }));
  }

  function startNewNote() {
    setDraft(createBlankProfileNoteDraft());
    setEditingId("");
    setShowEditor(true);
    setStatus("");
  }

  function startEditNote(note) {
    setDraft({
      id: note.id || "",
      category: note.category || "General Notes",
      title: note.title || "",
      body: note.body || "",
      pinned: !!note.pinned,
    });
    setEditingId(note.id || "");
    setShowEditor(true);
    setStatus("");
  }

  async function saveNotes(nextNotes, nextGeneral = generalDraft, message = "Notes saved to metadata.json.") {
    const normalizedNextNotes = normalizeProfileNoteEntries(nextNotes || []);
    const previousNotes = savedNotes;
    const previousGeneral = generalDraft;
    const updatedAt = new Date().toISOString();
    const nextMetadata = {
      ...metadata,
      privateNotes: nextGeneral || "",
      profilePrivateNotes: nextGeneral || "",
      profileNotes: normalizedNextNotes,
      privateNoteCards: normalizedNextNotes,
      profileNotesUpdatedAt: updatedAt,
    };

    // Optimistic local update so the Notes tab changes immediately without waiting
    // for a scan, refresh, or parent profile reload.
    setLocalNotes(normalizedNextNotes);
    setGeneralDraft(nextGeneral || "");
    setSaving(true);
    setStatus("Saving notes…");
    try {
      const response = await fetch("/api/metadata/adult/apply", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          person: {
            ...profile,
            library: profile.library || "personal",
            profileDir: profile.profileDir || profile.folderPath || profile.sourcePath || profile.path || "",
            folderPath: profile.folderPath || profile.profileDir || profile.sourcePath || "",
          },
          metadata: nextMetadata,
          libraryType: profile.library || "personal",
        }),
      });
      const data = await readAdultMetadataJson(response, "Profile notes save");
      if (!response.ok || !data.ok) throw new Error(data.message || "Profile notes save failed.");

      const savedMetadata = mergeAdultLoadedMetadata(data.metadata || nextMetadata, data.metadata || nextMetadata);
      const confirmedNotes = normalizeProfileNoteEntries(savedMetadata.profileNotes || savedMetadata.privateNoteCards || normalizedNextNotes);
      setLocalNotes(confirmedNotes);
      setGeneralDraft(savedMetadata.privateNotes || savedMetadata.profilePrivateNotes || nextGeneral || "");
      onMetadataSaved?.(data.metadata || nextMetadata);
      setStatus(data.message || message);
      window.dispatchEvent(new CustomEvent("homestead-adult-profile-updated", {
        detail: {
          reason: "profile-notes-updated",
          profileId: profile.id,
          profileName: profile.name || profile.title,
          libraryType: profile.library,
          metadata: data.metadata || nextMetadata,
        },
      }));
      window.dispatchEvent(new Event("homestead-metadata-match-updated"));
    } catch (error) {
      setLocalNotes(previousNotes);
      setGeneralDraft(previousGeneral || "");
      setStatus(error.message || "Profile notes save failed.");
    } finally {
      setSaving(false);
    }
  }

  async function saveGeneralNotes() {
    await saveNotes(savedNotes, generalDraft, "General notes saved.");
  }

  async function saveNoteCard() {
    const title = String(draft.title || "").trim();
    const body = String(draft.body || "").trim();
    if (!title && !body) {
      setStatus("Add a title or note before saving.");
      return;
    }
    const updatedAt = new Date().toISOString();
    const nextCard = {
      id: editingId || draft.id || `profile-note-${Date.now()}`,
      category: draft.category || "General Notes",
      title: title || "Untitled note",
      body,
      pinned: !!draft.pinned,
      updatedAt,
    };
    const nextNotes = editingId
      ? savedNotes.map((note) => (note.id === editingId ? nextCard : note))
      : [nextCard, ...savedNotes];
    await saveNotes(nextNotes.slice(0, 300), generalDraft, editingId ? "Note updated." : "Note added.");
    setDraft(createBlankProfileNoteDraft());
    setEditingId("");
    setShowEditor(false);
  }

  async function removeNoteCard(noteId) {
    const nextNotes = savedNotes.filter((note) => note.id !== noteId);
    await saveNotes(nextNotes, generalDraft, "Note removed.");
  }

  async function togglePinned(note) {
    const nextNotes = savedNotes.map((item) => item.id === note.id ? { ...item, pinned: !item.pinned, updatedAt: new Date().toISOString() } : item);
    await saveNotes(nextNotes, generalDraft, note.pinned ? "Note unpinned." : "Note pinned.");
  }

  return (
    <div className="profile-notes-panel">
      <div className="profile-notes-header">
        <div>
          <h3>Notes</h3>
          <p>Private freeform notes, preferences, reminders, gift ideas, and custom profile details.</p>
        </div>
        <div className="profile-notes-actions">
          <span className="profile-media-count">{sortedNotes.length} {sortedNotes.length === 1 ? "card" : "cards"}</span>
          {pinnedCount > 0 && <span className="profile-notes-pill">{pinnedCount} pinned</span>}
          <button type="button" className="secondary-button" onClick={startNewNote}>+ Add Note</button>
        </div>
      </div>

      {status && <div className="adult-profile-inline-status">{status}</div>}

      <section className="profile-notes-general-card">
        <div>
          <h4>General Notes</h4>
          <p>Quick private notes that do not need their own card.</p>
        </div>
        <textarea
          rows={5}
          value={generalDraft || ""}
          onChange={(event) => setGeneralDraft(event.target.value)}
          placeholder="Add general private notes, context, reminders, or anything you want to remember for this profile…"
        />
        <div className="profile-notes-general-actions">
          <button type="button" className="secondary-button request-button" onClick={saveGeneralNotes} disabled={saving}>{saving ? "Saving…" : "Save General Notes"}</button>
        </div>
      </section>

      {showEditor && (
        <section className="profile-notes-editor">
          <div className="profile-notes-editor-title">
            <h4>{editingId ? "Edit Note" : "Add Note Card"}</h4>
            <button type="button" className="secondary-button" onClick={() => { setShowEditor(false); setEditingId(""); setDraft(createBlankProfileNoteDraft()); }}>Close</button>
          </div>
          <div className="profile-notes-editor-grid">
            <label>
              <span>Category</span>
              <select value={draft.category || "General Notes"} onChange={(event) => updateDraft("category", event.target.value)}>
                {PROFILE_NOTE_CATEGORIES.map((category) => <option key={category} value={category}>{category}</option>)}
              </select>
            </label>
            <label>
              <span>Title</span>
              <input value={draft.title || ""} onChange={(event) => updateDraft("title", event.target.value)} placeholder="ex. Favorite snacks, birthday gift idea, reminder" />
            </label>
          </div>
          <label className="profile-notes-body-field">
            <span>Note</span>
            <textarea rows={5} value={draft.body || ""} onChange={(event) => updateDraft("body", event.target.value)} placeholder="Write the note details here…" />
          </label>
          <label className="profile-notes-pin-toggle">
            <input type="checkbox" checked={!!draft.pinned} onChange={(event) => updateDraft("pinned", event.target.checked)} />
            <span>Pin this note to the top</span>
          </label>
          <div className="profile-notes-editor-actions">
            <button type="button" className="secondary-button request-button" onClick={saveNoteCard} disabled={saving}>{saving ? "Saving…" : editingId ? "Save Changes" : "Save Note"}</button>
          </div>
        </section>
      )}

      {sortedNotes.length ? (
        <div className="profile-notes-card-grid">
          {sortedNotes.map((note) => (
            <article key={note.id} className={`profile-note-card ${note.pinned ? "profile-note-card-pinned" : ""}`}>
              <div className="profile-note-card-topline">
                <span>{note.category || "General Notes"}</span>
                {note.pinned && <strong>Pinned</strong>}
              </div>
              <h4>{note.title || "Untitled note"}</h4>
              {note.body && <p>{note.body}</p>}
              <div className="profile-note-card-footer">
                <small>{note.updatedAt ? `Updated ${formatProfileTimelineDate(note.updatedAt)}` : "Saved in metadata.json"}</small>
                <div>
                  <button type="button" className="secondary-button" onClick={() => togglePinned(note)} disabled={saving}>{note.pinned ? "Unpin" : "Pin"}</button>
                  <button type="button" className="secondary-button" onClick={() => startEditNote(note)} disabled={saving}>Edit</button>
                  <button type="button" className="secondary-button" onClick={() => removeNoteCard(note.id)} disabled={saving}>Remove</button>
                </div>
              </div>
            </article>
          ))}
        </div>
      ) : (
        <div className="profile-media-empty-state profile-notes-empty-state">
          <div className="profile-media-empty-icon">📝</div>
          <strong>No note cards yet.</strong>
          <p>Add preferences, reminders, gift ideas, important details, or private organization notes for this profile.</p>
          <button type="button" className="secondary-button request-button" onClick={startNewNote}>+ Add First Note</button>
        </div>
      )}
    </div>
  );
}

function ProfileBiographyPanel({ profile = {}, bioText = "", onMetadataSaved, editRequest = 0 }) {
  const [isEditing, setIsEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [status, setStatus] = useState("");
  const [viewMode, setViewMode] = useState("split");
  const [draft, setDraft] = useState(() => getInitialProfileFactDraft(profile));

  useEffect(() => {
    setDraft(getInitialProfileFactDraft(profile));
    setIsEditing(false);
    setStatus("");
  }, [profile?.id, profile?.metadata?.profileFactsUpdatedAt, profile?.metadata?.biography, profile?.metadata?.description]);

  useEffect(() => {
    if (editRequest > 0) setIsEditing(true);
  }, [editRequest]);

  const metadata = profile.metadata || {};
  const showPersonalFacts = isPersonalProfileFactsLibrary(profile);
  const currentDraft = draft || getInitialProfileFactDraft(profile);
  const safeBioText = String(bioText || "").trim().startsWith("<!doctype html") || String(bioText || "").includes('<div id="root">')
    ? ""
    : String(bioText || "").trim();
  const displayBiography = normalizeProfileFactValue(currentDraft.biography || metadata.biography || metadata.description || safeBioText || profile.summary || "").trim();
  const displayNotes = normalizeProfileFactValue(currentDraft.notes || metadata.notes || "").trim();
  const filledFacts = DEFAULT_PROFILE_FACT_FIELDS
    .map(([key, label]) => ({ key, label, value: formatHomesteadField(key, currentDraft[key] || metadata.profileFacts?.[key] || metadata[key], {}, "").trim() }))
    .filter((item) => item.value);
  const customFacts = Array.isArray(currentDraft.customFacts) ? currentDraft.customFacts.filter((fact) => fact?.label || fact?.value) : [];

  function updateDraftField(field, value) {
    setDraft((current) => ({ ...(current || {}), [field]: value }));
  }

  function updateCustomFact(index, field, value) {
    setDraft((current) => {
      const facts = Array.isArray(current?.customFacts) ? [...current.customFacts] : [];
      facts[index] = { ...(facts[index] || {}), [field]: value };
      return { ...(current || {}), customFacts: facts };
    });
  }

  function addCustomFact() {
    setDraft((current) => ({
      ...(current || {}),
      customFacts: [...(Array.isArray(current?.customFacts) ? current.customFacts : []), { label: "", value: "" }],
    }));
    setIsEditing(true);
  }

  function removeCustomFact(index) {
    setDraft((current) => ({
      ...(current || {}),
      customFacts: (Array.isArray(current?.customFacts) ? current.customFacts : []).filter((_, itemIndex) => itemIndex !== index),
    }));
  }

  async function saveProfileFacts() {
    setSaving(true);
    setStatus("Saving profile facts…");

    try {
      const cleanCustomFacts = (Array.isArray(currentDraft.customFacts) ? currentDraft.customFacts : [])
        .map((fact) => ({ label: String(fact?.label || "").trim(), value: String(fact?.value || "").trim() }))
        .filter((fact) => fact.label || fact.value);
      const updatedAt = new Date().toISOString();
      const profileFacts = {
        ...(metadata.profileFacts || {}),
        customFacts: showPersonalFacts ? cleanCustomFacts : (metadata.profileFacts?.customFacts || []),
        notes: currentDraft.notes || "",
        updatedAt,
      };

      if (showPersonalFacts) {
        DEFAULT_PROFILE_FACT_FIELDS.forEach(([key]) => {
          profileFacts[key] = currentDraft[key] || "";
        });
      }

      const nextMetadata = {
        ...metadata,
        biography: currentDraft.biography || "",
        description: currentDraft.biography || metadata.description || "",
        notes: currentDraft.notes || "",
        profileFacts,
        profileFactsUpdatedAt: updatedAt,
      };

      if (showPersonalFacts) {
        DEFAULT_PROFILE_FACT_FIELDS.forEach(([key]) => {
          nextMetadata[key] = currentDraft[key] || "";
        });
      }

      const response = await fetch("/api/metadata/adult/apply", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          person: {
            ...profile,
            library: profile.library || "personal",
            profileDir: profile.profileDir || profile.folderPath || profile.sourcePath || profile.path || "",
            folderPath: profile.folderPath || profile.profileDir || profile.sourcePath || "",
          },
          metadata: nextMetadata,
          libraryType: profile.library || "personal",
        }),
      });
      const data = await readAdultMetadataJson(response, "Profile facts save");
      if (!response.ok || !data.ok) throw new Error(data.message || "Profile facts save failed.");

      onMetadataSaved?.(data.metadata || nextMetadata);
      setDraft(getInitialProfileFactDraft({ ...profile, metadata: data.metadata || nextMetadata }));
      setIsEditing(false);
      setStatus(data.message || "Profile facts saved to metadata.json.");
      window.dispatchEvent(new CustomEvent("homestead-adult-profile-updated", {
        detail: {
          reason: "profile-facts-updated",
          profileId: profile.id,
          profileName: profile.name || profile.title,
          libraryType: profile.library,
          metadata: data.metadata || nextMetadata,
        },
      }));
      window.dispatchEvent(new Event("homestead-metadata-match-updated"));
    } catch (error) {
      setStatus(error.message || "Profile facts save failed.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="profile-biography-panel">
      <div className="profile-biography-header">
        <div>
          <h3>{showPersonalFacts ? "Biography & Profile Facts" : "Biography"}</h3>
          <p>{showPersonalFacts ? "Editable personal notes and quick facts saved into this profile's metadata.json." : "Editable public biography and notes saved into this profile's metadata.json."}</p>
        </div>
        <div className="profile-biography-actions">
          {showPersonalFacts && <button type="button" className="secondary-button" onClick={addCustomFact}>+ Add Fact</button>}
          <button type="button" className="secondary-button" onClick={() => setIsEditing((value) => !value)}>
            {isEditing ? "Preview" : "Edit Biography"}
          </button>
          {isEditing && (
            <button type="button" className="secondary-button request-button" onClick={saveProfileFacts} disabled={saving}>
              {saving ? "Saving…" : "Save to metadata.json"}
            </button>
          )}
        </div>
      </div>

      {status && <div className="adult-profile-inline-status">{status}</div>}

      {isEditing ? (
        <div className="profile-biography-editor">
          <label className="profile-biography-wide-field">
            <span>Biography</span>
            <textarea value={currentDraft.biography || ""} onChange={(event) => updateDraftField("biography", event.target.value)} rows={6} placeholder="Write or edit the profile biography…" />
          </label>

          {showPersonalFacts && (
            <div className="profile-fact-edit-grid">
              {DEFAULT_PROFILE_FACT_FIELDS.map(([key, label, placeholder]) => (
                <label key={key}>
                  <span>{label}</span>
                  <input value={currentDraft[key] || ""} onChange={(event) => updateDraftField(key, event.target.value)} placeholder={placeholder || label} />
                </label>
              ))}
            </div>
          )}

          <label className="profile-biography-wide-field">
            <span>Notes</span>
            <textarea value={currentDraft.notes || ""} onChange={(event) => updateDraftField("notes", event.target.value)} rows={4} placeholder="Private notes, reminders, personality details, preferences, etc." />
          </label>

          {showPersonalFacts && (
            <div className="profile-custom-facts-editor">
              <div className="profile-custom-facts-header">
                <strong>Custom Facts</strong>
                <button type="button" className="secondary-button" onClick={addCustomFact}>+ Add Custom Fact</button>
              </div>
              {(Array.isArray(currentDraft.customFacts) ? currentDraft.customFacts : []).map((fact, index) => (
                <div className="profile-custom-fact-row" key={`custom-fact-${index}`}>
                  <input value={fact?.label || ""} onChange={(event) => updateCustomFact(index, "label", event.target.value)} placeholder="Field name, ex. Favorite Flower" />
                  <input value={fact?.value || ""} onChange={(event) => updateCustomFact(index, "value", event.target.value)} placeholder="Value" />
                  <button type="button" className="secondary-button" onClick={() => removeCustomFact(index)}>Remove</button>
                </div>
              ))}
              {(!Array.isArray(currentDraft.customFacts) || currentDraft.customFacts.length === 0) && (
                <p className="small-muted">No custom facts yet. Add anything you want to track as you go.</p>
              )}
            </div>
          )}
        </div>
      ) : (
        <>
          <div className="profile-biography-text-card">
            <p>{displayBiography || "No biography saved yet. Click Edit Biography to start building this profile."}</p>
          </div>

          {showPersonalFacts && (
            <div className="profile-fact-card-grid">
              {filledFacts.map((fact) => (
                <div className="profile-fact-card" key={fact.key}>
                  <span>{fact.label}</span>
                  <strong>{fact.value}</strong>
                </div>
              ))}
              {customFacts.map((fact, index) => (
                <div className="profile-fact-card" key={`custom-display-${index}`}>
                  <span>{fact.label || "Custom Fact"}</span>
                  <strong>{fact.value || "—"}</strong>
                </div>
              ))}
              {!filledFacts.length && !customFacts.length && (
                <div className="profile-facts-empty-state">
                  <strong>No quick facts saved yet.</strong>
                  <p>Add favorite color, favorite food, favorite animal, hobbies, or any custom facts you want to remember.</p>
                </div>
              )}
            </div>
          )}

          {displayNotes && (
            <div className="profile-biography-notes-card">
              <span>Notes</span>
              <p>{displayNotes}</p>
            </div>
          )}
        </>
      )}
    </div>
  );
}

function SocialLinksPanel({ profile = {}, onMetadataSaved }) {
  const [showEditor, setShowEditor] = useState(false);
  const [saving, setSaving] = useState(false);
  const [fetchingSocialMetadata, setFetchingSocialMetadata] = useState(false);
  const [status, setStatus] = useState("");
  const [viewMode, setViewMode] = useState("split");
  const [socialForm, setSocialForm] = useState({
    platform: "instagram",
    url: "",
    handle: "",
    avatar: "",
    note: "",
  });

  const socialLinks = getProfileSocialLinks(profile);
  const fallbackPoster = getProfilePosterValue(profile);
  const detectedSocialLinks = mergeSocialLinks([], detectSocialLinksFromValues(
    profile.socials,
    profile.socialMedia,
    profile.referenceLinks,
    profile.metadata?.socials,
    profile.metadata?.socialMedia,
    profile.metadata?.referenceLinks,
    profile.metadata?.sourceUrls,
    profile.metadata?.sources,
    profile.metadata?.metadataMatch,
    profile.metadataCandidates
  ));
  const newDetectedCount = detectedSocialLinks.filter((detected) => !socialLinks.some((link) => String(link.url || "").toLowerCase() === String(detected.url || "").toLowerCase())).length;
  const displaySocialLinks = mergeSocialLinks(socialLinks, detectedSocialLinks);

  function updateSocialForm(field, value) {
    setSocialForm((current) => ({ ...current, [field]: value }));
  }

  async function saveSocialLinks(nextLinks, message = "Social links saved.") {
    setSaving(true);
    setStatus("Saving social links…");

    try {
      const metadata = {
        ...(profile.metadata || {}),
        socialLinks: socialLinksArrayToMetadataBlock(nextLinks),
        socialLinksUpdatedAt: new Date().toISOString(),
      };

      const response = await fetch("/api/metadata/adult/apply", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ person: profile, metadata }),
      });
      const data = await response.json();
      if (!response.ok || !data.ok) throw new Error(data.message || "Social link save failed.");

      setStatus(data.message || message);
      onMetadataSaved?.(data.metadata || metadata);
      window.dispatchEvent(new CustomEvent("homestead-adult-profile-updated", {
        detail: {
          reason: "social-links-updated",
          profileId: profile.id,
          profileName: profile.name || profile.title,
          libraryType: profile.library,
          metadata: data.metadata || metadata,
        },
      }));
      window.dispatchEvent(new Event("homestead-metadata-match-updated"));
    } catch (error) {
      setStatus(error.message || "Social link save failed.");
    } finally {
      setSaving(false);
    }
  }

  async function addManualSocialLink() {
    const normalized = normalizeSocialLinkRecord({
      ...socialForm,
      platform: socialForm.platform || getSocialPlatformFromUrl(socialForm.url),
      source: "manual",
      status: "manual",
    }, socialForm.platform, profile);

    if (!normalized) {
      setStatus("Enter a social profile URL first.");
      return;
    }

    const merged = mergeSocialLinks(socialLinks, [normalized]);
    await saveSocialLinks(merged, "Social link added.");
    setSocialForm({ platform: "instagram", url: "", handle: "", avatar: "", note: "" });
  }

  async function autoDetectAndSaveSocialLinks() {
    if (!detectedSocialLinks.length) {
      setStatus("No social links were detected in metadata/reference links yet.");
      return;
    }
    const merged = mergeSocialLinks(socialLinks, detectedSocialLinks);
    await saveSocialLinks(merged, `Auto-detected ${newDetectedCount || detectedSocialLinks.length} social link${(newDetectedCount || detectedSocialLinks.length) === 1 ? "" : "s"}.`);
  }

  async function fetchSavedSocialMetadata() {
    if (!socialLinks.length) {
      setStatus("Add or auto-detect social links first.");
      return;
    }

    setFetchingSocialMetadata(true);
    setStatus("Fetching social avatars and page metadata…");

    try {
      const response = await fetch("/api/metadata/social/fetch", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          person: profile,
          links: socialLinks,
          downloadAvatars: true,
        }),
      });
      const data = await response.json();
      if (!response.ok || !data.ok) throw new Error(data.message || "Social metadata fetch failed.");

      const failedCount = Array.isArray(data.results)
        ? data.results.filter((result) => result.fetchStatus === "failed").length
        : 0;
      const okCount = Array.isArray(data.results)
        ? data.results.filter((result) => result.fetchStatus === "ok").length
        : socialLinks.length;

      setStatus(`${data.message || "Social metadata fetched."}${failedCount ? ` ${failedCount} failed.` : ""}`);
      onMetadataSaved?.(data.metadata || {
        ...(profile.metadata || {}),
        socialLinks: data.socialLinks || profile.metadata?.socialLinks || {},
      });

      window.dispatchEvent(new CustomEvent("homestead-adult-profile-updated", {
        detail: {
          reason: "social-links-fetched",
          profileId: profile.id,
          profileName: profile.name || profile.title,
          libraryType: profile.library,
          metadata: data.metadata,
          socialFetchResults: data.results || [],
        },
      }));
      window.dispatchEvent(new Event("homestead-metadata-match-updated"));
    } catch (error) {
      setStatus(error.message || "Social metadata fetch failed.");
    } finally {
      setFetchingSocialMetadata(false);
    }
  }

  return (
    <div className="panel social-links-panel">
      <div className="section-header-row social-links-header">
        <div>
          <h3>Social Media</h3>
          <p>Links are read from and saved to this profile’s metadata.json.</p>
        </div>
        <div className="social-links-header-actions">
          <span>{socialLinks.length} link{socialLinks.length === 1 ? "" : "s"}</span>
          <button className="secondary-button" type="button" onClick={() => setShowEditor((value) => !value)}>
            {showEditor ? "Hide Editor" : "Add Social Link"}
          </button>
          <button className="secondary-button" type="button" onClick={autoDetectAndSaveSocialLinks} disabled={saving || !detectedSocialLinks.length}>
            Auto-detect{newDetectedCount ? ` (${newDetectedCount})` : ""}
          </button>
          <button className="secondary-button" type="button" onClick={fetchSavedSocialMetadata} disabled={saving || fetchingSocialMetadata || !socialLinks.length}>
            {fetchingSocialMetadata ? "Fetching…" : "Fetch Avatars"}
          </button>
        </div>
      </div>

      {showEditor && (
        <div className="social-link-editor-card">
          <div className="social-link-editor-grid">
            <label>
              <span>Platform</span>
              <select value={socialForm.platform} onChange={(event) => updateSocialForm("platform", event.target.value)}>
                {["instagram", "tiktok", "youtube", "spotify", "apple-music", "soundcloud", "twitter", "facebook", "threads", "snapchat", "tumblr", "reddit", "twitch", "patreon", "onlyfans", "fansly", "official-website", "model-site", "linktree", "beacons", "linkhub", "website"].map((platform) => (
                  <option key={platform} value={platform}>{getSocialPlatformMeta(platform).label}</option>
                ))}
              </select>
            </label>
            <label className="social-link-editor-wide">
              <span>Profile URL</span>
              <input value={socialForm.url} onChange={(event) => updateSocialForm("url", event.target.value)} placeholder="https://instagram.com/example" />
            </label>
            <label>
              <span>Handle</span>
              <input value={socialForm.handle} onChange={(event) => updateSocialForm("handle", event.target.value)} placeholder="@example" />
            </label>
            <label className="social-link-editor-wide">
              <span>Avatar / poster URL or local path</span>
              <input value={socialForm.avatar} onChange={(event) => updateSocialForm("avatar", event.target.value)} placeholder="/media/celebrities/name/social/instagram.jpg" />
            </label>
            <label className="social-link-editor-wide">
              <span>Note</span>
              <input value={socialForm.note} onChange={(event) => updateSocialForm("note", event.target.value)} placeholder="Official account, fan page, archived source, etc." />
            </label>
          </div>
          <div className="social-link-editor-actions">
            <button className="secondary-button" type="button" onClick={addManualSocialLink} disabled={saving}>
              {saving ? "Saving…" : "Save Social Link"}
            </button>
          </div>
        </div>
      )}

      {status && <div className="social-link-save-status">{status}</div>}

      {detectedSocialLinks.length > 0 && (
        <div className="social-link-detected-row">
          <strong>Detected from metadata:</strong>
          {detectedSocialLinks.slice(0, 8).map((link) => (
            <span key={link.url}>{link.icon} {link.handle || link.label}</span>
          ))}
        </div>
      )}

      {displaySocialLinks.length ? (
        <div className="social-link-card-grid">
          {displaySocialLinks.map((link) => {
            const poster = normalizeProfileImageUrl(link.poster || link.avatar || "");
            const fallback = normalizeProfileImageUrl(fallbackPoster || "");
            const inferredPlatform = getSocialPlatformFromUrl(link.url);
            const platformKey = isGenericSocialPlatformValue(link.platform) ? inferredPlatform : (link.platform || inferredPlatform);
            const platformMeta = getSocialPlatformMeta(platformKey);
            const platformTitle = platformMeta.label || "Social Link";
            const handleText = link.handle || getHandleFromSocialUrl(link.url) || link.url;
            const sourceText = link.fetchStatus === "failed"
              ? `Fetch failed${link.fetchError ? `: ${link.fetchError}` : ""}`
              : (shouldShowSocialSource(link.source) ? link.source : "");

            return (
              <a
                key={link.id}
                className={`social-link-card social-link-card-${link.color || platformMeta.color || "neutral"}`}
                href={link.url}
                target="_blank"
                rel="noreferrer"
                title={link.url}
              >
                <div className="social-link-poster">
                  {poster || fallback ? (
                    <img src={poster || fallback} alt={`${platformTitle} profile`} />
                  ) : (
                    <span>{link.icon || platformMeta.icon || "↗"}</span>
                  )}
                </div>
                <div className="social-link-info">
                  <div className="social-link-title-row">
                    <span className="social-link-icon">{link.icon || platformMeta.icon || "↗"}</span>
                    <strong>{platformTitle}</strong>
                  </div>
                  <p>{handleText}</p>
                  {link.title && link.title !== platformTitle && <small>{link.title}</small>}
                  {link.note && <small>{link.note}</small>}
                  {sourceText && <em>{sourceText}</em>}
                </div>
              </a>
            );
          })}
        </div>
      ) : (
        <div className="social-links-empty-state">
          <strong>No social links saved yet.</strong>
          <p>Add a social link here or click Auto-detect after metadata search/fetch adds social references.</p>
        </div>
      )}
    </div>
  );
}


