          <label><span>Overlay transparency</span><input type="range" min="0" max="1" step="0.01" value={1 - values.overlayOpacity} onInput={(event) => updateNumber("overlayOpacity", 1 - Number(event.currentTarget.value))} onChange={(event) => updateNumber("overlayOpacity", 1 - Number(event.currentTarget.value))} /><strong>{Math.round((1 - values.overlayOpacity) * 100)}%</strong></label>
