function EmbeddedBrowser({ url }) {
  if (!url) {
    return (
      <div className="panel">
        <p>No URL available.</p>
      </div>
    );
  }

  return (
    <div className="embedded-browser">
      <iframe
        src={url}
        title="Embedded Browser"
      />

      <div className="embedded-browser-toolbar">
        <a
          href={url}
          target="_blank"
          rel="noreferrer"
          className="reference-link"
        >
          Open In Browser
        </a>
      </div>
    </div>
  );
}

function MyDrivePage({ onBack }) {
  const folders = [
    ["📄", "Documents", "PDFs, notes, records, manuals, and saved files."],
    ["🖼️", "Photos", "General images and personal cloud photo storage."],
    ["🎞️", "Videos", "Personal videos and synced video files."],
    ["🧠", "AI", "AI generations, prompts, references, and exports."],
    ["🗄️", "Archive", "Long-term stored files and organized collections."],
    ["🛡️", "Backups", "Device, appdata, and system backups."],
    ["👥", "Shared", "Files shared with other users."],
  ];

  const recentFiles = [
    ["Trista metadata backup.json", "JSON", "Today", "12 KB"],
    ["Sadie diet plan.pdf", "PDF", "Yesterday", "245 KB"],
    ["Garden planning notes.md", "Markdown", "2 days ago", "8 KB"],
  ];

  return (
    <div className="drive-page">
      <div className="drive-header">
        <div>
          <button className="secondary-button" onClick={onBack}>Back to Cloud</button>
          <h3>My Drive</h3>
          <p>Personal cloud folders, synced files, documents, backups, and AI-organized storage.</p>
        </div>

        <div className="drive-actions">
          <button className="secondary-button">Upload</button>
          <button className="secondary-button">New Folder</button>
          <button className="secondary-button">AI Sort</button>
        </div>
      </div>

      <div className="panel">
        <h3>Storage</h3>
        <div className="cloud-storage-bar">
          <div className="cloud-storage-used"></div>
        </div>
        <p className="cloud-storage-text">2.1 TB used of 10 TB available • 18,420 files</p>
      </div>

      <div className="drive-folder-grid">
        {folders.map(([icon, title, description]) => (
          <button key={title} className="drive-folder-card">
            <div className="drive-folder-icon">{icon}</div>
            <div>
              <h3>{title}</h3>
              <p>{description}</p>
            </div>
          </button>
        ))}
      </div>

      <div className="panel">
        <h3>Recent Files</h3>
        <div className="file-list">
          {recentFiles.map(([name, type, modified, size]) => (
            <div key={name} className="file-row">
              <span>{name}</span>
              <span>{type}</span>
              <span>{modified}</span>
              <span>{size}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

