      {cloudView === "overview" && <div className="cloud-dashboard-grid"><div className="panel"><h3>Storage Overview</h3><div className="metadata-grid"><div><strong>Total Storage</strong><p>Coming Soon</p></div><div><strong>Used Storage</strong><p>Coming Soon</p></div><div><strong>Free Storage</strong><p>Coming Soon</p></div><div><strong>Photos</strong><p>Coming Soon</p></div><div><strong>Videos</strong><p>Coming Soon</p></div><div><strong>Music</strong><p>Coming Soon</p></div><div><strong>Books</strong><p>Coming Soon</p></div><div><strong>Documents</strong><p>Coming Soon</p></div></div></div><div className="panel"><h3>Connected Devices</h3><p>No devices connected.</p><div className="metadata-grid"><div><strong>Windows</strong><p>Planned</p></div><div><strong>macOS</strong><p>Planned</p></div><div><strong>Linux</strong><p>Planned</p></div><div><strong>iPhone</strong><p>Planned</p></div><div><strong>Android</strong><p>Planned</p></div><div><strong>Homestead Mobile</strong><p>Planned</p></div></div></div></div>}
      {cloudView === "my-drive" && <CloudPlaceholder title="My Drive" icon="📁" text="Personal cloud folder browser, uploads, downloads, and file previews." />}
      {cloudView === "sync" && <CloudPlaceholder title="Sync" icon="🔁" text="Phone sync, desktop sync, watch folders, and background upload jobs." />}
      {cloudView === "devices" && <CloudPlaceholder title="Connected Devices" icon="📱" text="Windows, macOS, Linux, iPhone, Android, and Homestead mobile clients." />}
      {cloudView === "shared" && <CloudPlaceholder title="Shared" icon="🤝" text="Shared folders, household drops, links, and permission-aware sharing." />}
      {cloudView === "backups" && <CloudPlaceholder title="Backups" icon="🛡️" text="Device backups, photo backups, documents, export jobs, and retention policies." />}
      {cloudView === "providers" && <div className="cloud-grid">{cloudProviders.map((provider) => <button key={provider.id} className="cloud-card" onClick={() => setCloudView(provider.id)}><div className="cloud-card-bg">{provider.icon}</div><div className="cloud-card-content"><h3>{provider.name}</h3><div className="cloud-provider-status">{provider.status}</div><p>{provider.description}</p><small>{provider.authType}</small></div></button>)}</div>}
