function cleanDashboardMediaTitle(value = "", libraryType = "media") {
  let title = String(value || "")
    .replace(/\\/g, "/")
    .split("/")
    .pop()
    .replace(/\.(mkv|mp4|m4v|mov|avi|webm|mp3|flac|m4a|aac|ogg|wav|epub|pdf|cbz|cbr|jpg|jpeg|png|webp|heic|heif)$/i, "")
    .replace(/[_]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  // Strip common downloader / archive cruft without touching normal titles.
  title = title
    .replace(/\[[^\]]*(?:1080p|720p|2160p|4k|x264|x265|h\.264|h\.265|web[- ]?dl|bluray|aac|dts|yts|rarbg|eztv|psa|hevc)[^\]]*\]/gi, "")
    .replace(/\((?:19|20)\d{2}\)\s*(?:-|–)?\s*$/g, "")
    .replace(/\b(?:1080p|720p|2160p|4k|x264|x265|h\.264|h\.265|web[- ]?dl|bluray|webrip|brrip|hdrip|dvdrip|aac|dts|hevc)\b/gi, "")
    .replace(/\b[a-f0-9]{12,}\b/gi, "")
    .replace(/\s+/g, " ")
    .replace(/\s+[-–]\s*$/g, "")
    .trim();

  if (libraryType === "tv" || libraryType === "youtube") {
    title = title.replace(/\bS(\d{1,2})E(\d{1,2})\b\s*[-–:]?\s*/i, (match, season, episode) => {
      const suffix = title.replace(match, "").trim();
      return suffix ? `S${season.padStart(2, "0")}E${episode.padStart(2, "0")} · ` : `S${season.padStart(2, "0")}E${episode.padStart(2, "0")}`;
    });
  }

  if (libraryType === "book") {
    title = title
      .replace(/\s+--\s+.*$/g, "")
      .replace(/\s+-\s+(?:[^-]+)$/g, (match) => (/\bby\b/i.test(match) ? "" : match));
  }

  title = title
    .replace(/\s{2,}/g, " ")
    .replace(/\s+([:;,.!?])/g, "$1")
    .trim();

  return title || "Untitled";
}

function getDashboardMediaSubtitle(item = {}, libraryType = "media", suppliedSubtitle = "") {
  const subtitle = suppliedSubtitle || item.subtitle || item.artist || item.creatorName || item.series || item.showTitle || "";
  if (!subtitle) return "";
  const cleanSubtitle = cleanDashboardMediaTitle(subtitle, libraryType);
  const cleanTitle = cleanDashboardMediaTitle(item.title || item.name || item.filename || "", libraryType);
  return cleanSubtitle && cleanSubtitle !== cleanTitle ? cleanSubtitle : "";
}

function getDashboardFallbackIcon(libraryType = "media") {
  const icons = {
    movie: "🎬",
    movies: "🎬",
    tv: "📺",
    tvshows: "📺",
    book: "📚",
    books: "📚",
    music: "🎵",
    youtube: "▶️",
    liveTV: "📡",
    livetv: "📡",
    photos: "🖼️",
    adult: "🔞",
    inventory: "📦",
    cloud: "☁️",
    ai: "✨",
  };

  return icons[libraryType] || "🏠";
}

function HomeDashboardMiniPosterCard({
  item = {},
  title,
  subtitle,
  poster,
  libraryType = "media",
  progress = null,
  progressLabel = "",
  onClick,
}) {
  const [imageCandidateIndex, setImageCandidateIndex] = useState(0);
  const rawTitle = title || item.title || item.name || item.filename || "Untitled";
  const displayTitle = cleanDashboardMediaTitle(rawTitle, libraryType);
  const displaySubtitle = getDashboardMediaSubtitle(item, libraryType, subtitle);
  const posterCandidates = Array.from(new Set([
    poster,
    ...(Array.isArray(item.posterCandidates) ? item.posterCandidates : []),
    item.metadataMatch?.poster,
    item.poster,
    item.cover,
    item.coverImage,
    item.artwork?.poster,
    item.metadata?.poster,
    item.metadata?.cover,
    item.thumb,
    item.thumbnail,
    item.image,
    item.banner,
  ].filter(Boolean).map((value) => getLocalApiFileUrl(value))));
  const posterSource = posterCandidates[imageCandidateIndex] || "";
  const hasPoster = Boolean(posterSource);
  const progressValue = Number.isFinite(progress) ? Math.max(0, Math.min(100, progress)) : null;

  useEffect(() => {
    setImageCandidateIndex(0);
  }, [posterCandidates.join("|")]);

  return (
    <button
      className={`mini-poster-card mini-poster-card-${libraryType}`}
      type="button"
      onClick={onClick}
      title={displayTitle}
    >
      <div className={`mini-poster-art ${hasPoster ? "" : "mini-poster-art-fallback"}`}>
        {hasPoster ? (
          <img
            src={posterSource}
            alt=""
            loading="lazy"
            onError={() => setImageCandidateIndex((current) => current + 1)}
          />
        ) : (
          <div className="mini-poster-fallback-card">
            <span className="mini-poster-fallback-icon">
              {getDashboardFallbackIcon(libraryType)}
            </span>
            <strong>{displayTitle}</strong>
          </div>
        )}
      </div>

      <div className="continue-card-info">
        {progressValue != null && (
          <div className="continue-progress-track">
            <div
              className="continue-progress-fill"
              style={{ width: `${progressValue}%` }}
            />
          </div>
        )}

        {progressLabel && <small>{progressLabel}</small>}
        <span>{displayTitle}</span>
        {displaySubtitle && <small>{displaySubtitle}</small>}
      </div>
    </button>
  );
}

const EMPTY_RECIPE_DRAFT = {
  title: "",
  description: "",
  categoryId: "",
  servings: "",
  prepTime: "",
  cookTime: "",
  totalTime: "",
  ingredients: "",
  directions: "",
  tags: "",
  notes: "",
  sourceUrl: "",
  sourceName: "",
  imageUrl: "",
  imageDataUrl: "",
  favorite: false,
};

function RecipeWizard({ onClose, onSaved, categories = [] }) {
  const [step, setStep] = useState("choose");
  const [method, setMethod] = useState("");
  const [draft, setDraft] = useState(EMPTY_RECIPE_DRAFT);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [savedRecipe, setSavedRecipe] = useState(null);

  useEffect(() => {
    const closeOnEscape = (event) => { if (event.key === "Escape" && !busy) onClose?.(); };
    window.addEventListener("keydown", closeOnEscape);
    return () => window.removeEventListener("keydown", closeOnEscape);
  }, [busy, onClose]);

  const update = (field, value) => setDraft((current) => ({ ...current, [field]: value }));

  function chooseMethod(nextMethod) {
    setMethod(nextMethod);
    setMessage("");
    setError("");
    if (nextMethod === "manual") setStep("details");
    else setStep("capture");
  }

  async function previewUrl() {
    if (!draft.sourceUrl.trim()) return setError("Paste a recipe or social-media link first.");
    setBusy(true);
    setError("");
    setMessage("Reading the page…");
    try {
      const response = await fetch("/api/recipes/import-preview", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url: draft.sourceUrl.trim() }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || data.ok === false) throw new Error(data.message || "Unable to import that link.");
      const recipe = data.recipe || {};
      setDraft((current) => ({
        ...current,
        title: recipe.title || current.title,
        description: recipe.description || current.description,
        servings: recipe.servings || current.servings,
        prepTime: recipe.prepTime || current.prepTime,
        cookTime: recipe.cookTime || current.cookTime,
        totalTime: recipe.totalTime || current.totalTime,
        ingredients: Array.isArray(recipe.ingredients) ? recipe.ingredients.join("\n") : current.ingredients,
        directions: Array.isArray(recipe.directions) ? recipe.directions.join("\n") : current.directions,
        tags: Array.isArray(recipe.tags) ? recipe.tags.join(", ") : current.tags,
        sourceUrl: recipe.sourceUrl || current.sourceUrl,
        sourceName: recipe.sourceName || current.sourceName,
        imageUrl: recipe.imageUrl || current.imageUrl,
      }));
      setMessage(data.message || "Recipe details imported. Review them before saving.");
      setStep("details");
    } catch (requestError) {
      setError(requestError.message || "Unable to import that link.");
      setMessage("");
    } finally {
      setBusy(false);
    }
  }

  async function previewPhoto(file) {
    if (!file) return;
    setBusy(true);
    setError("");
    setMessage("Reading the recipe photo…");
    try {
      const dataUrl = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ""));
        reader.onerror = () => reject(new Error("The selected photo could not be read."));
        reader.readAsDataURL(file);
      });
      setDraft((current) => ({ ...current, imageDataUrl: dataUrl }));
      const response = await fetch("/api/recipes/photo-preview", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ dataUrl }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || data.ok === false) throw new Error(data.message || "Unable to read that recipe photo.");
      const recipe = data.recipe || {};
      setDraft((current) => ({
        ...current,
        title: recipe.title || current.title,
        ingredients: Array.isArray(recipe.ingredients) ? recipe.ingredients.join("\n") : current.ingredients,
        directions: Array.isArray(recipe.directions) ? recipe.directions.join("\n") : current.directions,
        notes: !recipe.ingredients?.length && !recipe.directions?.length ? recipe.rawText || current.notes : current.notes,
      }));
      setMessage(data.message || "Photo text extracted. Review it carefully before saving.");
      setStep("details");
    } catch (requestError) {
      setError(requestError.message || "Unable to read that recipe photo.");
      setMessage("The photo is attached. You can continue and enter the recipe manually.");
    } finally {
      setBusy(false);
    }
  }

  async function saveRecipe() {
    if (!draft.title.trim()) return setError("Enter a recipe title before saving.");
    setBusy(true);
    setError("");
    try {
      const response = await fetch("/api/recipes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...draft,
          ingredients: draft.ingredients.split(/\r?\n/).map((line) => line.trim()).filter(Boolean),
          directions: draft.directions.split(/\r?\n/).map((line) => line.trim()).filter(Boolean),
          tags: draft.tags.split(/,|\r?\n/).map((tag) => tag.trim()).filter(Boolean),
        }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || data.ok === false) throw new Error(data.message || "Unable to save that recipe.");
      setSavedRecipe(data.recipe);
      setMessage(data.artworkWarning ? `Recipe saved. ${data.artworkWarning}` : "Recipe saved to your household library.");
      setStep("complete");
      onSaved?.(data.recipe);
      window.dispatchEvent(new CustomEvent("homestead-recipes-updated", { detail: { recipe: data.recipe } }));
    } catch (requestError) {
      setError(requestError.message || "Unable to save that recipe.");
    } finally {
      setBusy(false);
    }
  }

  const stepNumber = step === "choose" ? 1 : step === "capture" ? 2 : step === "details" ? 3 : step === "review" ? 4 : 4;
  return createPortal(
    <div className="recipe-wizard-overlay" role="dialog" aria-modal="true" aria-labelledby="recipe-wizard-title" onClick={(event) => { if (event.target === event.currentTarget && !busy) onClose?.(); }}>
      <section className="recipe-wizard-card" onClick={(event) => event.stopPropagation()}>
        <header className="recipe-wizard-header">
          <div><p>Recipes · Step {stepNumber} of 4</p><h2 id="recipe-wizard-title">{step === "complete" ? "Recipe Saved" : "Add a Recipe"}</h2><span>{step === "choose" ? "Choose how you want to begin." : step === "capture" ? "Bring in the source material." : step === "details" ? "Correct and complete the recipe." : step === "review" ? "Review everything before saving." : "It is now available throughout Homestead."}</span></div>
          <button type="button" className="secondary-button" onClick={onClose} disabled={busy} aria-label="Close recipe wizard">×</button>
        </header>

        <div className="recipe-wizard-progress" aria-hidden="true"><span style={{ width: `${stepNumber * 25}%` }} /></div>

        <div className="recipe-wizard-body">
          {step === "choose" && <div className="recipe-wizard-source-grid">
            <button type="button" onClick={() => chooseMethod("link")}><span>🔗</span><strong>Share or paste a link</strong><small>Recipe sites and public social-media posts</small></button>
            <button type="button" onClick={() => chooseMethod("photo")}><span>📷</span><strong>Upload a photo</strong><small>Printed, handwritten, or cookbook recipes</small></button>
            <button type="button" onClick={() => chooseMethod("manual")}><span>✍️</span><strong>Create manually</strong><small>Start with a clean recipe form</small></button>
          </div>}

          {step === "capture" && method === "link" && <div className="recipe-wizard-capture">
            <label><span>Recipe or social-media URL</span><input type="url" value={draft.sourceUrl} onChange={(event) => update("sourceUrl", event.target.value)} placeholder="https://…" autoFocus /></label>
            <p>Homestead will use structured recipe details when the page provides them. Blocked social posts can still be saved as a source and completed manually.</p>
          </div>}

          {step === "capture" && method === "photo" && <div className="recipe-wizard-capture">
            <label className="recipe-photo-dropzone"><span>📷</span><strong>Choose a recipe photo</strong><small>JPG, PNG, or WebP · up to 24 MB</small><input type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => previewPhoto(event.target.files?.[0])} /></label>
            {draft.imageDataUrl && <img className="recipe-photo-preview" src={draft.imageDataUrl} alt="Selected recipe" />}
          </div>}

          {step === "details" && <div className="recipe-wizard-form">
            {(draft.imageDataUrl || draft.imageUrl) && <img className="recipe-wizard-hero-preview" src={draft.imageDataUrl || draft.imageUrl} alt="Recipe preview" />}
            <label className="wide"><span>Recipe title</span><input value={draft.title} onChange={(event) => update("title", event.target.value)} autoFocus /></label>
            <label className="wide"><span>Description</span><textarea rows="3" value={draft.description} onChange={(event) => update("description", event.target.value)} /></label>
            <label><span>Category</span><select value={draft.categoryId} onChange={(event) => update("categoryId", event.target.value)}><option value="">Uncategorized</option>{categories.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label>
            <label><span>Servings</span><input value={draft.servings} onChange={(event) => update("servings", event.target.value)} placeholder="6 servings" /></label>
            <label><span>Preparation time</span><input value={draft.prepTime} onChange={(event) => update("prepTime", event.target.value)} placeholder="20 min" /></label>
            <label><span>Cooking time</span><input value={draft.cookTime} onChange={(event) => update("cookTime", event.target.value)} placeholder="45 min" /></label>
            <label className="wide"><span>Ingredients · one per line</span><textarea rows="8" value={draft.ingredients} onChange={(event) => update("ingredients", event.target.value)} placeholder={'2 cups flour\n1 tsp salt'} /></label>
            <label className="wide"><span>Directions · one step per line</span><textarea rows="9" value={draft.directions} onChange={(event) => update("directions", event.target.value)} placeholder={'Preheat the oven.\nMix the dry ingredients.'} /></label>
            <label className="wide"><span>Tags · separated by commas</span><input value={draft.tags} onChange={(event) => update("tags", event.target.value)} placeholder="family favorite, holiday, make ahead" /></label>
            <label className="wide"><span>Personal notes</span><textarea rows="3" value={draft.notes} onChange={(event) => update("notes", event.target.value)} /></label>
            <label className="recipe-favorite-check wide"><input type="checkbox" checked={draft.favorite} onChange={(event) => update("favorite", event.target.checked)} /><span><strong>Add to Favorites</strong><small>Show this recipe on the Recipes home page.</small></span></label>
          </div>}

          {step === "review" && <div className="recipe-wizard-review">
            {(draft.imageDataUrl || draft.imageUrl) && <img src={draft.imageDataUrl || draft.imageUrl} alt="" />}
            <div><span>{categories.find((category) => category.id === draft.categoryId)?.name || "Uncategorized"}</span><h3>{draft.title || "Untitled recipe"}</h3><p>{draft.description || "No description"}</p><dl><div><dt>Servings</dt><dd>{draft.servings || "Not set"}</dd></div><div><dt>Preparation</dt><dd>{draft.prepTime || "Not set"}</dd></div><div><dt>Cooking</dt><dd>{draft.cookTime || "Not set"}</dd></div><div><dt>Ingredients</dt><dd>{draft.ingredients.split(/\r?\n/).filter(Boolean).length}</dd></div><div><dt>Steps</dt><dd>{draft.directions.split(/\r?\n/).filter(Boolean).length}</dd></div><div><dt>Favorite</dt><dd>{draft.favorite ? "Yes" : "No"}</dd></div></dl>{draft.sourceUrl && <small>Source: {draft.sourceName || draft.sourceUrl}</small>}</div>
          </div>}

          {step === "complete" && <div className="recipe-wizard-complete"><span>✓</span><h3>{savedRecipe?.title || draft.title}</h3><p>{message}</p></div>}

          {(message && step !== "complete") && <p className="recipe-wizard-message">{message}</p>}
          {error && <p className="recipe-wizard-error">{error}</p>}
        </div>

        <footer className="recipe-wizard-actions">
          {step === "choose" && <button type="button" className="secondary-button" onClick={onClose}>Cancel</button>}
          {step === "capture" && <><button type="button" className="secondary-button" onClick={() => { setStep("choose"); setError(""); }}>Back</button>{method === "link" ? <><button type="button" className="secondary-button" onClick={() => setStep("details")}>Enter manually</button><button type="button" className="primary-button" disabled={busy || !draft.sourceUrl.trim()} onClick={previewUrl}>{busy ? "Importing…" : "Import & Review"}</button></> : <button type="button" className="primary-button" disabled={busy || !draft.imageDataUrl} onClick={() => setStep("details")}>{busy ? "Reading…" : "Continue"}</button>}</>}
          {step === "details" && <><button type="button" className="secondary-button" onClick={() => setStep(method === "manual" ? "choose" : "capture")}>Back</button><button type="button" className="primary-button" disabled={!draft.title.trim()} onClick={() => { setError(""); setStep("review"); }}>Review Recipe</button></>}
          {step === "review" && <><button type="button" className="secondary-button" disabled={busy} onClick={() => setStep("details")}>Edit</button><button type="button" className="primary-button" disabled={busy} onClick={saveRecipe}>{busy ? "Saving…" : "Save Recipe"}</button></>}
          {step === "complete" && <button type="button" className="primary-button" onClick={onClose}>Done</button>}
        </footer>
      </section>
    </div>, document.body
  );
}

function RecipeDetailsOverlay({ recipe, cookingMode = false, onClose, onToggleFavorite, onEdit }) {
  useEffect(() => {
    if (!recipe) return undefined;
    const closeOnEscape = (event) => { if (event.key === "Escape") onClose?.(); };
    window.addEventListener("keydown", closeOnEscape);
    return () => window.removeEventListener("keydown", closeOnEscape);
  }, [recipe, onClose]);

  if (!recipe) return null;

  const details = [
    ["Servings", recipe.servings],
    ["Prep time", recipe.prepTime],
    ["Cook time", recipe.cookTime],
    ["Total time", recipe.totalTime],
  ].filter(([, value]) => value);
  const ingredients = Array.isArray(recipe.ingredients) ? recipe.ingredients : [];
  const directions = Array.isArray(recipe.directions) ? recipe.directions : [];
  const quickSteps = Array.isArray(recipe.quickSteps) ? recipe.quickSteps : [];
  const isQuickInstruction = recipe.entryType === "quick-instruction";

  return createPortal(
    <div className={`recipe-detail-overlay ${cookingMode ? "recipe-cooking-mode" : ""}`} role="dialog" aria-modal="true" aria-labelledby="recipe-detail-title" onClick={(event) => { if (event.target === event.currentTarget) onClose?.(); }}>
      <section className="recipe-detail-card">
        <header className="recipe-detail-header">
          <div>
            <p>{isQuickInstruction ? "Quick Instructions" : "Homestead Recipes"}</p>
            <h2 id="recipe-detail-title">{recipe.title}</h2>
            <span>{isQuickInstruction ? [recipe.appliance, recipe.temperature].filter(Boolean).join(" · ") || "Everyday preparation" : recipe.category || "Recipe"}</span>
          </div>
          <div className="recipe-detail-header-actions">
            <button type="button" className={`recipe-favorite-button ${recipe.favorite ? "active" : ""}`} aria-label={recipe.favorite ? `Remove ${recipe.title} from favorites` : `Add ${recipe.title} to favorites`} title={recipe.favorite ? "Remove from Favorites" : "Add to Favorites"} onClick={() => onToggleFavorite?.(recipe)}>{recipe.favorite ? "♥" : "♡"}</button>
            {isQuickInstruction && <button type="button" className="secondary-button recipe-detail-edit" aria-label={`Edit ${recipe.title}`} title="Edit Quick Instruction" onClick={() => onEdit?.(recipe)}>✎ Edit</button>}
            <button type="button" className="secondary-button recipe-detail-close" aria-label="Close recipe details" title="Close" onClick={onClose}>×</button>
          </div>
        </header>

        <div className="recipe-detail-body">
          <aside className="recipe-detail-summary">
            {recipe.image ? <img className="recipe-detail-image" src={recipe.image} alt={recipe.title} /> : <div className="recipe-detail-image recipe-detail-image-fallback" aria-hidden="true">🍲</div>}
            {details.length > 0 && <dl className="recipe-detail-facts">{details.map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl>}
            {(recipe.tags || []).length > 0 && <div className="recipe-tags recipe-detail-tags">{recipe.tags.map((tag) => <span key={tag}>{tag}</span>)}</div>}
            {recipe.sourceUrl && <a className="primary-button recipe-detail-source" href={recipe.sourceUrl} target="_blank" rel="noreferrer">View original recipe ↗</a>}
            {recipe.sourceName && <small className="recipe-detail-source-name">Source: {recipe.sourceName}</small>}
          </aside>

          <div className="recipe-detail-content">
            {recipe.description && <section className="recipe-detail-section recipe-detail-description"><h3>About this recipe</h3><p>{recipe.description}</p></section>}
            <div className="recipe-detail-columns">
              <section className="recipe-detail-section">
                <h3>Ingredients</h3>
                {ingredients.length > 0 ? <ul>{ingredients.map((ingredient, index) => <li key={`${ingredient}-${index}`}>{ingredient}</li>)}</ul> : <p className="recipe-detail-missing">No ingredients were added.</p>}
              </section>
              <section className="recipe-detail-section">
                <h3>{isQuickInstruction ? "Steps & timers" : "Directions"}</h3>
                {isQuickInstruction && quickSteps.length > 0 ? <ol className="quick-instruction-cook-steps">{quickSteps.map((step, index) => <li key={`${step.text}-${index}`}><span>{step.text}</span><QuickStepTimer seconds={step.timerSeconds} /></li>)}</ol> : directions.length > 0 ? <ol>{directions.map((direction, index) => <li key={`${direction}-${index}`}>{direction}</li>)}</ol> : <p className="recipe-detail-missing">No directions were added.</p>}
              </section>
            </div>
            {recipe.notes && <section className="recipe-detail-section recipe-detail-notes"><h3>Personal notes</h3><p>{recipe.notes}</p></section>}
          </div>
        </div>
      </section>
    </div>, document.body
  );
}

function QuickStepTimer({ seconds = 0 }) {
  const [remaining, setRemaining] = useState(Number(seconds) || 0);
  const [running, setRunning] = useState(false);
  useEffect(() => {
    if (!running || remaining <= 0) return undefined;
    const timer = window.setInterval(() => setRemaining((value) => {
      if (value <= 1) { window.clearInterval(timer); setRunning(false); return 0; }
      return value - 1;
    }), 1000);
    return () => window.clearInterval(timer);
  }, [running, remaining]);
  if (!seconds) return null;
  const label = `${Math.floor(remaining / 60)}:${String(remaining % 60).padStart(2, "0")}`;
  return <button type="button" className={`quick-instruction-timer ${running ? "running" : ""}`} onClick={() => remaining > 0 ? setRunning((value) => !value) : setRemaining(Number(seconds) || 0)}>{remaining > 0 ? (running ? `Pause ${label}` : `Start ${label}`) : "Reset timer"}</button>;
}

function quickInstructionEditorDraft(recipe = null) {
  const quickSteps = Array.isArray(recipe?.quickSteps) && recipe.quickSteps.length
    ? recipe.quickSteps.map((step) => ({ text: String(step?.text || ""), timerMinutes: Number(step?.timerSeconds || 0) ? String(Number(step.timerSeconds) / 60) : "" }))
    : [{ text: "", timerMinutes: "" }];
  return {
    title: String(recipe?.title || ""),
    ingredients: Array.isArray(recipe?.ingredients) ? recipe.ingredients.join("\n") : String(recipe?.ingredients || ""),
    appliance: String(recipe?.appliance || ""),
    temperature: String(recipe?.temperature || ""),
    notes: String(recipe?.notes || ""),
    favorite: recipe?.favorite === true,
    householdVisible: recipe?.householdVisible !== false,
    quickSteps,
    image: String(recipe?.image || ""),
    imageDataUrl: "",
  };
}

function QuickInstructionEditor({ recipe = null, onClose, onSaved }) {
  const editing = Boolean(recipe?.id);
  const [draft, setDraft] = useState(() => quickInstructionEditorDraft(recipe));
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const updateStep = (index, field, value) => setDraft((current) => ({ ...current, quickSteps: current.quickSteps.map((step, stepIndex) => stepIndex === index ? { ...step, [field]: value } : step) }));
  const choosePoster = (file) => {
    if (!file) return;
    if (!/^image\/(?:jpeg|png|webp)$/i.test(file.type || "")) return setError("Choose a JPG, PNG, or WebP poster image.");
    if (file.size > 24 * 1024 * 1024) return setError("Poster images must be smaller than 24 MB.");
    const reader = new FileReader();
    reader.onload = () => { setDraft((current) => ({ ...current, imageDataUrl: String(reader.result || "") })); setError(""); };
    reader.onerror = () => setError("The selected poster could not be read.");
    reader.readAsDataURL(file);
  };
  const save = async () => {
    if (!draft.title.trim()) return setError("Enter an item name.");
    if (!draft.quickSteps.some((step) => step.text.trim())) return setError("Add at least one instruction step.");
    setBusy(true); setError("");
    try {
      const response = await fetch(editing ? `/api/recipes/${encodeURIComponent(recipe.id)}` : "/api/recipes", { method: editing ? "PATCH" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({
        ...draft,
        entryType: "quick-instruction",
        ingredients: draft.ingredients,
        directions: draft.quickSteps.map((step) => step.text).filter(Boolean),
        quickSteps: draft.quickSteps.map((step) => ({ text: step.text, timerSeconds: Math.round((Number(step.timerMinutes) || 0) * 60) })),
      }) });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || data.ok === false) throw new Error(data.message || `Could not ${editing ? "update" : "save"} these instructions.`);
      onSaved?.(data.recipe); onClose?.();
    } catch (requestError) { setError(requestError.message || `Could not ${editing ? "update" : "save"} these instructions.`); }
    finally { setBusy(false); }
  };
  return createPortal(<div className="recipe-wizard-overlay" role="dialog" aria-modal="true" onClick={(event) => { if (event.target === event.currentTarget && !busy) onClose?.(); }}>
    <section className="quick-instruction-editor" onClick={(event) => event.stopPropagation()}>
      <header><div><p>Everyday food memory</p><h2>{editing ? "Edit Quick Instruction" : "New Quick Instruction"}</h2><span>For packaged foods, favorite shortcuts, and repeatable kitchen routines.</span></div><button type="button" className="secondary-button" onClick={onClose}>×</button></header>
      <div className="quick-instruction-form">
        <div className="quick-instruction-poster wide">
          <div className="quick-instruction-poster-preview">{draft.imageDataUrl || draft.image ? <img src={draft.imageDataUrl || draft.image} alt="Quick Instruction poster preview" /> : <span aria-hidden="true">🍲</span>}</div>
          <div><strong>Poster image</strong><p>Add a photo so this item is easy to recognize in your Quick Instructions list.</p><label className="secondary-button quick-instruction-poster-button">{draft.imageDataUrl || draft.image ? "Replace Poster" : "Add Poster"}<input type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => choosePoster(event.target.files?.[0])} /></label></div>
        </div>
        <label className="wide"><span>Item name</span><input autoFocus value={draft.title} onChange={(event) => setDraft((current) => ({ ...current, title: event.target.value }))} placeholder="Ramen noodles" /></label>
        <label className="wide"><span>Ingredients / add-ons · one per line</span><textarea rows="4" value={draft.ingredients} onChange={(event) => setDraft((current) => ({ ...current, ingredients: event.target.value }))} placeholder={'1 bag ramen\n1/2 tsp chili powder'} /></label>
        <label><span>Appliance</span><input value={draft.appliance} onChange={(event) => setDraft((current) => ({ ...current, appliance: event.target.value }))} placeholder="Microwave" /></label>
        <label><span>Temperature / power</span><input value={draft.temperature} onChange={(event) => setDraft((current) => ({ ...current, temperature: event.target.value }))} placeholder="450°F or High" /></label>
        <div className="quick-instruction-steps wide"><div><strong>Ordered steps and timers</strong><button type="button" className="secondary-button" onClick={() => setDraft((current) => ({ ...current, quickSteps: [...current.quickSteps, { text: "", timerMinutes: "" }] }))}>＋ Add step</button></div>{draft.quickSteps.map((step, index) => <div className="quick-instruction-step-edit" key={index}><span>{index + 1}</span><input value={step.text} onChange={(event) => updateStep(index, "text", event.target.value)} placeholder={index === 0 ? "Cook for one minute" : "Stir, then cook again"} /><label><small>Timer (minutes)</small><input type="number" min="0" step="0.5" value={step.timerMinutes} onChange={(event) => updateStep(index, "timerMinutes", event.target.value)} placeholder="1" /></label>{draft.quickSteps.length > 1 && <button type="button" aria-label="Remove step" onClick={() => setDraft((current) => ({ ...current, quickSteps: current.quickSteps.filter((_, stepIndex) => stepIndex !== index) }))}>×</button>}</div>)}</div>
        <label className="wide"><span>Notes</span><textarea rows="3" value={draft.notes} onChange={(event) => setDraft((current) => ({ ...current, notes: event.target.value }))} /></label>
        <label className="recipe-favorite-check"><input type="checkbox" checked={draft.favorite} onChange={(event) => setDraft((current) => ({ ...current, favorite: event.target.checked }))} /><span><strong>Favorite</strong><small>Keep near the top.</small></span></label>
        <label className="recipe-favorite-check"><input type="checkbox" checked={draft.householdVisible} onChange={(event) => setDraft((current) => ({ ...current, householdVisible: event.target.checked }))} /><span><strong>Share with household</strong><small>Visible to signed-in family members.</small></span></label>
      </div>
      {error && <p className="recipe-wizard-error">{error}</p>}
      <footer><button type="button" className="secondary-button" disabled={busy} onClick={onClose}>Cancel</button><button type="button" className="primary-button" disabled={busy} onClick={save}>{busy ? "Saving…" : editing ? "Update Instructions" : "Save Instructions"}</button></footer>
    </section>
  </div>, document.body);
}

function RecipeCategoryEditor({ category, onClose, onSaved, onDeleted }) {
  const [draft, setDraft] = useState(() => ({ name: category?.name || "", icon: category?.icon || "🍽️", description: category?.description || "" }));
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  async function save() {
    if (!draft.name.trim()) return setError("Enter a category name.");
    setBusy(true); setError("");
    try {
      const response = await fetch(category ? `/api/recipes/categories/${encodeURIComponent(category.id)}` : "/api/recipes/categories", {
        method: category ? "PATCH" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(draft),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || data.ok === false) throw new Error(data.message || "Could not save that category.");
      onSaved?.(data.category);
    } catch (requestError) { setError(requestError.message || "Could not save that category."); }
    finally { setBusy(false); }
  }
  async function remove() {
    if (!category || !window.confirm(`Delete the “${category.name}” category? Recipes in it will become uncategorized.`)) return;
    setBusy(true); setError("");
    try {
      const response = await fetch(`/api/recipes/categories/${encodeURIComponent(category.id)}`, { method: "DELETE" });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || data.ok === false) throw new Error(data.message || "Could not delete that category.");
      onDeleted?.(category.id);
    } catch (requestError) { setError(requestError.message || "Could not delete that category."); setBusy(false); }
  }
  return createPortal(<div className="recipe-wizard-overlay" role="dialog" aria-modal="true" onClick={(event) => { if (event.target === event.currentTarget && !busy) onClose?.(); }}>
    <section className="recipe-category-editor">
      <header><div><p>Recipe organization</p><h2>{category ? "Edit Category" : "Create Category"}</h2></div><button type="button" className="secondary-button" onClick={onClose}>×</button></header>
      <div className="recipe-category-form"><label><span>Icon</span><input value={draft.icon} maxLength="16" onChange={(event) => setDraft((current) => ({ ...current, icon: event.target.value }))} /></label><label><span>Name</span><input value={draft.name} maxLength="80" autoFocus onChange={(event) => setDraft((current) => ({ ...current, name: event.target.value }))} /></label><label className="wide"><span>Description</span><textarea rows="3" value={draft.description} onChange={(event) => setDraft((current) => ({ ...current, description: event.target.value }))} /></label></div>
      {error && <p className="recipe-wizard-error">{error}</p>}
      <footer>{category && <button type="button" className="danger-button" disabled={busy} onClick={remove}>Delete Category</button>}<span /><button type="button" className="secondary-button" disabled={busy} onClick={onClose}>Cancel</button><button type="button" className="primary-button" disabled={busy || !draft.name.trim()} onClick={save}>{busy ? "Saving…" : "Save Category"}</button></footer>
    </section>
  </div>, document.body);
}

function RecipesPage({ setActiveLibrary, setupConfig }) {
  const [recipes, setRecipes] = useState([]);
  const [recipeView, setRecipeView] = useState("recipes");
  const [recipeSearch, setRecipeSearch] = useState("");
  const [categories, setCategories] = useState([]);
  const [selectedCategory, setSelectedCategory] = useState("all");
  const [selectedRecipeId, setSelectedRecipeId] = useState("");
  const [wizardOpen, setWizardOpen] = useState(false);
  const [quickEditorOpen, setQuickEditorOpen] = useState(null);
  const [categoryEditor, setCategoryEditor] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [focusMode, setFocusMode] = usePerDeviceFocusMode("recipes");

  const loadRecipes = useCallback(async () => {
    try {
      const [recipeResponse, categoryResponse] = await Promise.all([
        fetch("/api/recipes", { headers: { Accept: "application/json" } }),
        fetch("/api/recipes/categories", { headers: { Accept: "application/json" } }),
      ]);
      const recipeData = await recipeResponse.json().catch(() => ({}));
      const categoryData = await categoryResponse.json().catch(() => ({}));
      if (!recipeResponse.ok || recipeData.ok === false) throw new Error(recipeData.message || "Unable to load recipes.");
      if (!categoryResponse.ok || categoryData.ok === false) throw new Error(categoryData.message || "Unable to load recipe categories.");
      setRecipes(Array.isArray(recipeData.recipes) ? recipeData.recipes : []);
      setCategories(Array.isArray(categoryData.categories) ? categoryData.categories : []);
      setError("");
    } catch (requestError) { setError(requestError.message || "Unable to load recipes."); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => {
    loadRecipes();
    window.addEventListener("homestead-recipes-updated", loadRecipes);
    return () => window.removeEventListener("homestead-recipes-updated", loadRecipes);
  }, [loadRecipes]);

  useEffect(() => {
    window.dispatchEvent(new CustomEvent("homestead-page-context", { detail: {
      library: "recipes", title: "Recipes", appearanceScope: "recipes-home",
      addActions: [{ id: "add-recipe", label: "Add Recipe", icon: "🍲", description: "Import, photograph, or enter a recipe" }, { id: "add-quick-instruction", label: "Add Quick Instruction", icon: "⏱", description: "Save a repeat food-preparation routine" }, { id: "create-recipe-category", label: "Create Category", icon: "＋", description: "Make your own recipe collection" }],
      headerActions: [{ id: "recipes-focus", label: focusMode ? "Exit Full Screen" : "Cooking Full Screen", icon: "⛶" }],
    } }));
    const receiveAction = (event) => {
      if (event.detail?.library !== "recipes") return;
      if (event.detail?.action === "add-recipe") setWizardOpen(true);
      if (event.detail?.action === "add-quick-instruction") setQuickEditorOpen({});
      if (event.detail?.action === "create-recipe-category") setCategoryEditor({ category: null });
      if (event.detail?.action === "recipes-focus") setFocusMode(!focusMode);
    };
    window.addEventListener("homestead-page-action", receiveAction);
    return () => window.removeEventListener("homestead-page-action", receiveAction);
  }, [focusMode, setFocusMode]);

  useEffect(() => {
    if (!focusMode || !selectedRecipeId || !("wakeLock" in navigator)) return undefined;
    let lock = null; navigator.wakeLock.request("screen").then((value) => { lock = value; }).catch(() => {});
    return () => { lock?.release?.().catch(() => {}); };
  }, [focusMode, selectedRecipeId]);

  async function toggleFavorite(recipe) {
    const favorite = !recipe.favorite;
    setRecipes((current) => current.map((item) => item.id === recipe.id ? { ...item, favorite } : item));
    try {
      const response = await fetch(`/api/recipes/${encodeURIComponent(recipe.id)}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ favorite }) });
      if (!response.ok) throw new Error("Favorite could not be updated.");
    } catch (requestError) {
      setRecipes((current) => current.map((item) => item.id === recipe.id ? { ...item, favorite: recipe.favorite } : item));
      setError(requestError.message || "Favorite could not be updated.");
    }
  }

  const selectedCategoryDetails = categories.find((category) => category.id === selectedCategory);
  const visibleRecipes = (selectedCategory === "favorites" ? recipes.filter((recipe) => recipe.favorite) : selectedCategory === "all" ? recipes : recipes.filter((recipe) => recipe.categoryId === selectedCategory || (!recipe.categoryId && recipe.category === selectedCategoryDetails?.name)))
    .filter((recipe) => recipeView === "quick" ? recipe.entryType === "quick-instruction" : recipe.entryType !== "quick-instruction")
    .filter((recipe) => !recipeSearch.trim() || `${recipe.title || ""} ${recipe.description || ""} ${(recipe.ingredients || []).join(" ")} ${recipe.appliance || ""}`.toLowerCase().includes(recipeSearch.trim().toLowerCase()));
  const selectedRecipe = recipes.find((recipe) => recipe.id === selectedRecipeId) || null;

  return <div className={`recipes-page ${focusMode ? "recipes-focus-mode" : ""}`}>
    {focusMode && <button className="focus-mode-exit" onClick={() => setFocusMode(false)}>× Exit Full Screen</button>}
    <FamilySectionTabs activeLibrary="recipes" setActiveLibrary={setActiveLibrary} setupConfig={setupConfig}/>
    <div className="recipe-view-toolbar">
      <div className="recipe-view-tabs"><button type="button" className={recipeView === "recipes" ? "active" : ""} onClick={() => setRecipeView("recipes")}>Recipes</button><button type="button" className={recipeView === "quick" ? "active" : ""} onClick={() => { setRecipeView("quick"); setSelectedCategory("all"); }}>Quick Instructions</button></div>
      <label><span>Search</span><input value={recipeSearch} onChange={(event) => setRecipeSearch(event.target.value)} placeholder={recipeView === "quick" ? "Search food or appliance" : "Search recipes"} /></label>
      {recipeView === "quick" && <button type="button" className="primary-button" onClick={() => setQuickEditorOpen({})}>＋ Add Quick Instruction</button>}
    </div>
    {recipeView === "quick" && <div className="quick-instruction-intro"><span>⏱</span><div><strong>Your repeatable food routines</strong><p>Save packaged-food directions, exact temperatures, add-ons, and as many step timers as you need.</p></div></div>}
    {recipeView === "recipes" && <>
    <div className="recipe-grid" aria-label="Recipe categories">
      <button type="button" className={`recipe-card ${selectedCategory === "all" ? "active" : ""}`} onClick={() => setSelectedCategory("all")}><div className="recipe-icon">📖</div><div><h3>All Recipes</h3><p>Every recipe you have saved</p></div></button>
      <button type="button" className={`recipe-card ${selectedCategory === "favorites" ? "active" : ""}`} onClick={() => setSelectedCategory("favorites")}><div className="recipe-icon">♥</div><div><h3>Favorites</h3><p>Your quick-access recipes</p></div></button>
      {categories.map((category) => <article key={category.id} className={`recipe-card recipe-category-card ${selectedCategory === category.id ? "active" : ""}`}><button type="button" className="recipe-category-select" onClick={() => setSelectedCategory(category.id)}><div className="recipe-icon">{category.icon || "🍽️"}</div><div><h3>{category.name}</h3><p>{category.description || "Your recipe collection"}</p></div></button><button type="button" className="recipe-category-edit" aria-label={`Edit ${category.name}`} onClick={() => setCategoryEditor({ category })}>✎</button></article>)}
    </div>
    {categories.length === 0 && <div className="recipe-category-empty"><p>No custom categories yet. Recipes stay uncategorized until you create one.</p><button type="button" className="secondary-button" onClick={() => setCategoryEditor({ category: null })}>＋ Create Category</button></div>}
    </>}
    <section className="panel recipe-favorites-panel">
      <div className="recipe-section-heading"><div><p>{recipeView === "quick" ? "Fast reference" : selectedCategoryDetails ? "Recipe category" : selectedCategory === "favorites" ? "Saved for quick access" : "Personal cookbook"}</p><h3>{recipeView === "quick" ? "Quick Instructions" : selectedCategoryDetails?.name || (selectedCategory === "favorites" ? "Favorite Recipes" : "All Recipes")}</h3></div></div>
      {error && <p className="recipe-page-error">{error}</p>}
      {loading ? <p className="recipe-empty-state">Loading recipes…</p> : visibleRecipes.length ? <div className="recipe-list">{visibleRecipes.map((recipe) => <article key={recipe.id} className="recipe-row" role="button" tabIndex="0" aria-label={`View ${recipe.title} recipe`} onClick={() => setSelectedRecipeId(recipe.id)} onKeyDown={(event) => { if (event.target === event.currentTarget && (event.key === "Enter" || event.key === " ")) { event.preventDefault(); setSelectedRecipeId(recipe.id); } }}>
        {recipe.image ? <img className="recipe-row-image" src={recipe.image} alt="" loading="lazy" /> : <div className="recipe-row-image recipe-row-image-fallback">{recipe.entryType === "quick-instruction" ? "⏱" : "🍲"}</div>}<div className="recipe-row-copy"><h4>{recipe.title}</h4><p>{recipe.entryType === "quick-instruction" ? [recipe.appliance, recipe.temperature, `${(recipe.quickSteps || []).length} steps`].filter(Boolean).join(" · ") : [recipe.category || "Uncategorized", recipe.prepTime || recipe.cookTime, recipe.servings].filter(Boolean).join(" · ")}</p>{recipe.description && <small>{recipe.description}</small>}<div className="recipe-tags">{(recipe.tags || []).slice(0, 6).map((tag) => <span key={tag}>{tag}</span>)}</div>{recipe.sourceUrl && <a href={recipe.sourceUrl} target="_blank" rel="noreferrer" onClick={(event) => event.stopPropagation()}>View original source ↗</a>}</div><button type="button" className={`recipe-favorite-button ${recipe.favorite ? "active" : ""}`} aria-label={recipe.favorite ? `Remove ${recipe.title} from favorites` : `Add ${recipe.title} to favorites`} onClick={(event) => { event.stopPropagation(); toggleFavorite(recipe); }}>{recipe.favorite ? "♥" : "♡"}</button>
      </article>)}</div> : <div className="recipe-empty-state"><span>{recipeView === "quick" ? "⏱" : selectedCategoryDetails?.icon || (selectedCategory === "favorites" ? "♡" : "🍲")}</span><h4>{recipeView === "quick" ? "No quick instructions yet" : "No recipes here yet"}</h4><p>{recipeView === "quick" ? "Add the exact routine you want to remember." : "Use the global Add button to bring in a recipe."}</p></div>}
    </section>
    <RecipeDetailsOverlay recipe={selectedRecipe} cookingMode={focusMode} onClose={() => setSelectedRecipeId("")} onToggleFavorite={toggleFavorite} onEdit={(recipe) => { setSelectedRecipeId(""); setQuickEditorOpen(recipe); }} />
    {wizardOpen && <RecipeWizard categories={categories} onClose={() => setWizardOpen(false)} onSaved={loadRecipes} />}
    {quickEditorOpen && <QuickInstructionEditor recipe={quickEditorOpen.id ? quickEditorOpen : null} onClose={() => setQuickEditorOpen(null)} onSaved={loadRecipes} />}
    {categoryEditor && <RecipeCategoryEditor category={categoryEditor.category} onClose={() => setCategoryEditor(null)} onSaved={() => { setCategoryEditor(null); loadRecipes(); }} onDeleted={(id) => { if (selectedCategory === id) setSelectedCategory("all"); setCategoryEditor(null); loadRecipes(); }} />}
  </div>;
}

function normalizeYouTubeSeriesKey(value = "") {
  return String(value || "series").trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "series";
}

function parseYouTubeSeasonToken(value = "") {
  const token = String(value || "").trim().toUpperCase();
  if (/^\d{1,2}$/.test(token)) {
    const number = Number(token);
    return number >= 1 && number <= 99 ? number : 0;
  }
  if (!/^[IVXLCDM]+$/.test(token)) return 0;
  const values = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
  let number = 0;
  let previous = 0;
  for (let index = token.length - 1; index >= 0; index -= 1) {
    const current = values[token[index]] || 0;
    number += current < previous ? -current : current;
    previous = Math.max(previous, current);
  }
  return number >= 1 && number <= 99 ? number : 0;
}

function getYouTubeEpisodeNumber(video = {}) {
  const stored = Number(video.episodeNumber || video.metadata?.episodeNumber || 0);
  if (stored > 0) return stored;
  const raw = String(video.metadata?.title || video.metadata?.videoTitle || video.displayTitle || video.title || video.name || video.filename || video.file || "");
  const match = raw.match(/(?:^|\s)#\s*(\d{1,4})\b/i)
    || raw.match(/\b(?:episode|ep)\s*[#._-]?\s*(\d{1,4})\b/i)
    || raw.match(/\bE\s*(\d{1,4})\b/i)
    || raw.match(/\bS\d{1,3}[\s._-]*E(\d{1,4})\b/i);
  return match ? Number(match[1]) : 0;
}

function cleanYouTubeEpisodeTitle(video = {}, seriesName = "") {
  const raw = video.metadata?.title || video.metadata?.videoTitle || video.displayTitle || video.title || video.name || video.filename || video.file || "Untitled video";
  let title = String(raw).replace(/\\/g, "/").split("/").pop()
    .replace(/\.(mkv|mp4|m4v|mov|avi|webm)$/i, "")
    .replace(/^\s*\[(?:[^\]]+)\]\s*/, "")
    .replace(/\b[a-f0-9]{12,}\b/gi, "")
    .replace(/[_]+/g, " ").replace(/\s+/g, " ").trim();
  const episodeNumber = getYouTubeEpisodeNumber({ ...video, title });
  const marker = title.match(/(?:^|\s)(?:#\s*\d{1,4}|(?:episode|ep)\s*[#._-]?\s*\d{1,4}|S\d{1,3}[\s._-]*E\d{1,4}|E\s*\d{1,4})\b/i);
  if (marker && marker.index >= 0) {
    const remainder = title.slice(marker.index).replace(/^\s+/, "")
      .replace(/^(?:episode|ep)\s*[#._-]?\s*\d{1,4}\b\s*[-–:·]?\s*/i, `#${episodeNumber} `)
      .replace(/^S\d{1,3}[\s._-]*E\d{1,4}\b\s*[-–:·]?\s*/i, `#${episodeNumber} `)
      .replace(/^E\s*\d{1,4}\b\s*[-–:·]?\s*/i, `#${episodeNumber} `)
      .replace(/^#\s*(\d{1,4})\b\s*[-–:·]?\s*/i, "#$1 ");
    const prefix = title.slice(0, marker.index).trim().toLowerCase();
    const seriesWords = String(seriesName || video.seriesFolder || video.seriesName || video.series || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
    if (!prefix || prefix.includes("minecraft") || (seriesWords && prefix.includes(seriesWords.split(" ")[0]))) title = remainder;
  } else {
    const escapedSeries = String(seriesName || video.seriesFolder || "").trim().replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    if (escapedSeries) title = title.replace(new RegExp(`^\\s*(?:minecraft\\s+)?${escapedSeries}(?:\\s+[IVXLCDM]+|\\s+season\\s+\\d+)?\\s*[-–:·]?\\s*`, "i"), "");
  }
  return title.replace(/\s+/g, " ").trim() || "Untitled video";
}

function normalizeYouTubeSeason(video = {}, seriesName = "") {
  const rawTitle = String(
    video.metadata?.title ||
    video.metadata?.videoTitle ||
    video.displayTitle ||
    video.title ||
    video.name ||
    video.filename ||
    ""
  ).replace(/\b[a-f0-9]{12,}\b/gi, " ");
  const normalizedSeries = String(seriesName || video.series || video.seriesName || "").trim();
  const escapedSeries = normalizedSeries.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const seriesMatch = escapedSeries
    ? rawTitle.match(new RegExp(`\\b${escapedSeries}\\s+(?:season\\s*)?([ivxlcdm]+|\\d{1,2})\\b`, "i"))
    : null;
  const explicitMatch = rawTitle.match(/\bseason\s+(\d{1,2})\b/i);
  const folderStored = String(video.folderSeason || video.seasonFolder || "").trim();
  const folderMatch = folderStored.match(/^(?:season|s)?[\s._-]*([ivxlcdm]+|\d{1,2})$/i);
  const stored = String(video.season || video.seasonName || video.metadata?.season || "").trim();
  const storedMatch = stored.match(/^(?:season|s)?[\s._-]*([ivxlcdm]+|\d{1,2})$/i);
  const number = parseYouTubeSeasonToken(folderMatch?.[1]) || parseYouTubeSeasonToken(storedMatch?.[1]) || parseYouTubeSeasonToken(seriesMatch?.[1]) || Number(explicitMatch?.[1] || 0) || 1;
  return `Season ${number >= 1 && number <= 99 ? number : 1}`;
}

function getYouTubeVideoReleaseDate(video = {}) {
  return video.releaseDate || video.publishedAt || video.uploadDate || video.date || video.metadata?.releaseDate || video.metadata?.publishedAt || video.metadata?.published || video.metadata?.uploadDate || "";
}

function getYouTubeVideoReleaseTime(video = {}) {
  const parsed = Date.parse(getYouTubeVideoReleaseDate(video));
  return Number.isFinite(parsed) ? parsed : Number.MAX_SAFE_INTEGER;
}

function getYouTubeVideoArtworkCandidates(video = {}, creator = {}) {
  return [video.thumb, video.thumbnail, video.thumbnailUrl, video.thumbnailPath, video.sidecarThumbnail, video.metadata?.thumb, video.metadata?.thumbnail, video.metadata?.thumbnailUrl, video.metadata?.vid_thumb_url, video.poster, creator.poster]
    .map((value) => String(value || "").trim()).filter(Boolean);
}

function YouTubeArtwork({ candidates = [], alt = "", className = "" }) {
  const normalized = useMemo(() => Array.from(new Set(candidates.map((value) => String(value || "").trim()).filter(Boolean))), [candidates]);
  const [candidateIndex, setCandidateIndex] = useState(0);
  useEffect(() => setCandidateIndex(0), [normalized.join("|")]);
  const source = normalized[candidateIndex] || "";
  if (!source) return <div className={`youtube-artwork-fallback ${className}`} aria-label="Artwork unavailable"><span>▶</span></div>;
  return <img className={className} src={getLocalApiFileUrl(source)} alt={alt} loading="lazy" onError={() => setCandidateIndex((current) => current + 1)} />;
}

function buildYouTubeSeriesCatalog(creators = [], dedicatedSeries = []) {
  const records = new Map();
  const ensure = (name, seed = {}) => {
    const displayName = titleFromId(name || seed.title || seed.name || "Other Videos");
    const id = normalizeYouTubeSeriesKey(seed.id || name || displayName);
    if (!records.has(id)) records.set(id, { ...seed, id, title: displayName, seasons: {}, videos: [] });
    return records.get(id);
  };
  dedicatedSeries.forEach((series) => ensure(series.title || series.name || series.id, series));
  creators.forEach((creator) => {
    (creator.metadata?.importRules?.selectedPlaylists || creator.metadata?.playlists || []).forEach((playlist) => {
      const name = playlist.name || playlist.title || playlist.playlist_name || playlist.id;
      if (!name) return;
      const series = ensure(name);
      if (!series.poster) series.poster = playlist.thumbnail || playlist.thumb || playlist.playlist_thumbnail_url || playlist.playlist_thumbnail || "";
      if (!series.playlistId) series.playlistId = playlist.id || playlist.playlistId || playlist.playlist_id || "";
    });
    (Array.isArray(creator.videos) ? creator.videos : []).forEach((video) => {
      const seriesName = video.series || video.seriesName || video.playlistTitle || video.metadata?.series || video.metadata?.playlistTitle || "Other Videos";
      const seasonName = normalizeYouTubeSeason(video, seriesName);
      const series = ensure(seriesName);
      series.videos.push({ ...video, title: cleanYouTubeEpisodeTitle(video, seriesName), episodeNumber: getYouTubeEpisodeNumber(video), creatorId: video.creatorId || creator.id, creatorName: video.creatorName || creator.displayName || creator.name, creatorPoster: creator.poster || creator.metadata?.poster || "", releaseDate: getYouTubeVideoReleaseDate(video), series: seriesName, season: seasonName });
    });
  });
  return Array.from(records.values()).map((series) => {
    const videos = [...(series.videos || [])].sort((a, b) => (getYouTubeEpisodeNumber(a) || Number.MAX_SAFE_INTEGER) - (getYouTubeEpisodeNumber(b) || Number.MAX_SAFE_INTEGER) || getYouTubeVideoReleaseTime(a) - getYouTubeVideoReleaseTime(b) || cleanYouTubeEpisodeTitle(a, series.title).localeCompare(cleanYouTubeEpisodeTitle(b, series.title)));
    const seasons = {};
    videos.forEach((video) => {
      const seasonName = normalizeYouTubeSeason(video, series.title);
      if (!seasons[seasonName]) seasons[seasonName] = { id: seasonName, name: titleFromId(seasonName), videos: [] };
      seasons[seasonName].videos.push(video);
    });
    return { ...series, videos, seasons, videoCount: videos.length };
  }).sort((a, b) => a.title.localeCompare(b.title));
}

function YouTubePage({ setHideSidebar, setHideLibraryHeader, dashboardOpen, setDashboardOpen, setActiveLibrary, setupConfig, setRequestedMediaToolPage, mediaIndex, watchlist, setWatchlist, onOpenYouTubeAppearance }) {
  const [youtubeIndex, setYoutubeIndex] = useState(null);
  const [tab, setTab] = useState("creators");
  const [selectedCreator, setSelectedCreator] = useState(null);
  const [selectedSeries, setSelectedSeries] = useState(null);
  const [pendingVideoPath, setPendingVideoPath] = useState("");
  const [seriesArtwork, setSeriesArtwork] = useState({});
  const [seriesBanners, setSeriesBanners] = useState({});
  const [seriesAppearances, setSeriesAppearances] = useState({});

  useEffect(() => {
    fetchJsonIfExists("/data/youtube-index.json").then(setYoutubeIndex);
    fetchJsonIfExists("/api/youtube/series-artwork").then((data) => setSeriesArtwork(data?.artwork || {}));
    fetchJsonIfExists("/api/youtube/series-banners").then((data) => setSeriesBanners(data?.banners || {}));
    fetchJsonIfExists("/api/youtube/series-appearance").then((data) => setSeriesAppearances(data?.appearances || {}));
  }, []);

useEffect(() => {
  setHideSidebar(!!selectedCreator || !!selectedSeries);
  setHideLibraryHeader(!!selectedCreator || !!selectedSeries);

  return () => {
    setHideSidebar(false);
    setHideLibraryHeader(false);
  };
}, [selectedCreator, selectedSeries, setHideSidebar, setHideLibraryHeader]);

  const creators = Object.values(youtubeIndex?.creators || {});
  const series = useMemo(() => buildYouTubeSeriesCatalog(creators, Object.values(youtubeIndex?.series || {})), [youtubeIndex]);

  useEffect(() => {
    if (dashboardOpen?.type !== "youtube") return;
    if (!youtubeIndex) return;

    const targetCreator = String(dashboardOpen.id || "").toLowerCase().trim();

    const targetVideoPath = String(dashboardOpen.videoPath || "").toLowerCase().trim();

    const creator = creators.find((item) => {
      const creatorMatches =
        String(item.id || "").toLowerCase().trim() === targetCreator ||
        String(item.name || "").toLowerCase().trim() === targetCreator ||
        String(item.title || "").toLowerCase().trim() === targetCreator;

      const videoMatches = Object.values(item.videos || {}).some((video) => {
        return (
          String(video.path || "").toLowerCase().trim() === targetVideoPath ||
          String(video.file || "").toLowerCase().trim() === targetVideoPath ||
          String(video.src || "").toLowerCase().trim() === targetVideoPath
        );
      });

      return creatorMatches || videoMatches;
    });

    if (!creator) {
      console.log("YouTube creator not found from dashboard:", dashboardOpen, creators);
      return;
    }

    setPendingVideoPath(dashboardOpen.videoPath || dashboardOpen.path || "");
    setSelectedCreator(creator);
    setDashboardOpen(null);
  }, [dashboardOpen, creators, youtubeIndex, setDashboardOpen]);

if (!youtubeIndex) {
  return (
    <div className="generic-page">
      <MediaSectionTabs
        activeLibrary="youtube"
        setActiveLibrary={(nextTab) => {
  if (nextTab === "tools") {
    setRequestedMediaToolPage("home");
    setActiveLibrary("media");
    return;
  }

  if (nextTab === "media" || nextTab === "home") {
    setActiveLibrary("media");
    return;
  }

  setActiveLibrary(nextTab);
}}
        setupConfig={setupConfig}
      />

      <div className="panel">
        <h3>YouTube Library</h3>
        <p>Run npm run scan:youtube, then refresh.</p>
      </div>
    </div>
  );
}

  if (selectedCreator) {
    return (
      <div className="creator-focus-mode">
<YouTubeCreatorDetail
  creator={selectedCreator}
  initialVideoPath={pendingVideoPath}
  onBack={() => {
    setPendingVideoPath("");
    setSelectedCreator(null);
  }}
  setActiveLibrary={setActiveLibrary}
  mediaIndex={mediaIndex}
  watchlist={watchlist}
  setWatchlist={setWatchlist}
  onOpenAppearance={onOpenYouTubeAppearance}
/>
      </div>
    );
  }

  if (selectedSeries) {
    return (
      <div className="creator-focus-mode">
        <YouTubeSeriesDetail
          series={selectedSeries}
          artwork={seriesArtwork[selectedSeries.id] || ""}
          banner={seriesBanners[selectedSeries.id] || ""}
          appearance={seriesAppearances[selectedSeries.id] || {}}
          onArtworkSaved={(url) => setSeriesArtwork((current) => ({ ...current, [selectedSeries.id]: url }))}
          onBannerSaved={(url) => setSeriesBanners((current) => ({ ...current, [selectedSeries.id]: url }))}
          onAppearanceSaved={(values) => setSeriesAppearances((current) => ({ ...current, [selectedSeries.id]: values }))}
          onBack={() => setSelectedSeries(null)}
          onOpenAppearance={onOpenYouTubeAppearance}
          mediaIndex={mediaIndex}
          watchlist={watchlist}
          setWatchlist={setWatchlist}
        />
      </div>
    );
  }

return (
  <div className="youtube-page">
    <MediaSectionTabs
      activeLibrary="youtube"
      setActiveLibrary={(nextTab) => {
  if (nextTab === "tools") {
    setRequestedMediaToolPage("home");
    setActiveLibrary("media");
    return;
  }

  if (nextTab === "media" || nextTab === "home") {
    setActiveLibrary("media");
    return;
  }

  setActiveLibrary(nextTab);
}}
      setupConfig={setupConfig}
    />
      <div className="tabs">
        <TabButton active={tab === "creators"} onClick={() => setTab("creators")}>
          Creators
        </TabButton>

        <TabButton active={tab === "series"} onClick={() => setTab("series")}>
          Series
        </TabButton>

        <TabButton active={tab === "collections"} onClick={() => setTab("collections")}>
          Collections
        </TabButton>
      </div>

      {tab === "creators" && (
        <div className="youtube-grid">
          {creators.map((creator) => (
            <button
              key={creator.id}
              className="youtube-creator-card"
              onClick={() => setSelectedCreator(creator)}
            >
              <YouTubeArtwork candidates={[creator.poster, creator.thumbnail, creator.metadata?.poster, creator.metadata?.thumbnail]} alt="" />

              <div className="youtube-card-info">
                <h3>{creator.name}</h3>
                <p>{creator.videoCount || 0} archived videos</p>
              </div>
            </button>
          ))}
        </div>
      )}

      {tab === "series" && (
        <div className="youtube-grid">
          {series.map((item) => {
            const seasons = Object.values(item.seasons || {});
            const totalVideos = seasons.reduce(
              (sum, season) => sum + (season.videos?.length || 0),
              0
            );

            return (
              <button key={item.id} type="button" className="youtube-series-card" onClick={() => setSelectedSeries(item)}>
                <YouTubeArtwork
                  className="youtube-series-poster"
                  candidates={[seriesArtwork[item.id], item.poster, item.thumbnail, getYouTubeVideoArtworkCandidates(item.videos?.[0] || {})[0]]}
                  alt=""
                />

                <div className="youtube-card-info">
                  <h3>{titleFromId(item.title)}</h3>
                  <p>{seasons.length} seasons</p>
                  <p>{totalVideos} videos</p>
                </div>
              </button>
            );
          })}
        </div>
      )}

      {tab === "collections" && (
        <YouTubeCollectionsPanel creators={creators} onOpenVideo={(video) => {
          const creator = creators.find((item) => item.id === video.creatorId || item.name === video.creatorName || (item.videos || []).some((candidate) => candidate.path === video.path || candidate.sourcePath === video.sourcePath));
          if (!creator) return;
          setPendingVideoPath(video.path || video.sourcePath || video.publicPath || "");
          setSelectedCreator(creator);
        }} />
      )}
    </div>
  );
}

function YouTubeVideoCard({ video, creator = {}, onPlay, mediaIndex, watchlist, setWatchlist }) {
  const title = cleanYouTubeEpisodeTitle(video);
  const releaseDate = getYouTubeVideoReleaseDate(video);
  return (
    <article className="youtube-episode-card">
      <button type="button" className="youtube-video-card-main" onClick={() => onPlay?.(video)} title={`Play ${title}`}>
        <div className="youtube-episode-thumb"><YouTubeArtwork candidates={getYouTubeVideoArtworkCandidates(video, creator)} alt="" /></div>
        <div className="youtube-episode-info">
          <h4>{title}</h4>
          <p>{video.creatorName || creator.displayName || creator.name || "YouTube"}{releaseDate ? ` · ${formatHomesteadDate(releaseDate)}` : ""}</p>
        </div>
      </button>
      <div className="youtube-video-card-actions">
        <DetailMembershipButton kind="collection" item={{ ...video, title, poster: getYouTubeVideoArtworkCandidates(video, creator)[0] || "" }} library="youtube" mediaIndex={mediaIndex} legacyWatchlist={watchlist} setLegacyWatchlist={setWatchlist} />
      </div>
    </article>
  );
}

function YouTubeCollectionsPanel({ creators = [], onOpenVideo }) {
  const { customCollections, customCollectionsLoading, customCollectionsError } = useCustomMediaCollections(true);
  const videoLookup = useMemo(() => {
    const map = new Map();
    creators.forEach((creator) => (creator.videos || []).forEach((video) => {
      const enriched = { ...video, creatorId: video.creatorId || creator.id, creatorName: video.creatorName || creator.name, creatorPoster: creator.poster };
      [video.id, video.youtubeId, video.videoId, video.sourceId, video.sourcePath, video.path, video.publicPath, cleanYouTubeEpisodeTitle(video)].filter(Boolean).forEach((key) => map.set(String(key), enriched));
    }));
    return map;
  }, [creators]);
  const collections = customCollections.map((collection) => ({ ...collection, items: (collection.items || []).filter((item) => item.library === "youtube") })).filter((collection) => collection.items.length);
  if (customCollectionsLoading) return <div className="panel"><p>Loading YouTube collections…</p></div>;
  if (customCollectionsError) return <div className="panel"><p>{customCollectionsError}</p></div>;
  if (!collections.length) return <div className="panel"><h3>Collections</h3><p>Add any video to a custom collection from its card or player.</p></div>;
  return <div className="youtube-custom-collections">{collections.map((collection) => <section className="panel" key={collection.id}><div className="youtube-series-timeline-heading"><div><h3>{collection.name}</h3><p>{collection.description || "Custom YouTube collection"}</p></div><span>{collection.items.length} videos</span></div><div className="youtube-episode-grid">{collection.items.map((item, index) => { const video = videoLookup.get(String(item.sourceId)) || videoLookup.get(String(item.title)) || item; return <YouTubeVideoCard key={`${collection.id}:${item.sourceId || index}`} video={{ ...video, ...item, title: item.title || video.title }} creator={{ id: video.creatorId, name: video.creatorName, poster: video.creatorPoster }} onPlay={() => onOpenVideo?.(video)} />; })}</div></section>)}</div>;
}

function HomesteadVideoPlayerOverlay({ file, title, subtitle = "", pills = [], onClose, progressKey = "", progressPayload = {}, mediaIndex, collectionItem, library = "movies", watchlist, setWatchlist, onEnded }) {
  if (!file) return null;
  const savedProgress = progressKey ? getWatchProgress()[progressKey] : null;
  const savedTime = Number(savedProgress?.currentTime || 0);
  return typeof document !== "undefined" ? createPortal(
    <div className="scene-player-overlay homestead-global-player-overlay" role="dialog" aria-modal="true" aria-label={`Playing ${title || "video"}`}>
      <section className="scene-player-card homestead-global-player-card">
        <button className="scene-player-close homestead-global-player-close" type="button" onClick={onClose} aria-label="Close player" title="Close">✕</button>
        <SidecarVideoPlayer
          file={file}
          className="scene-player-video homestead-global-player-video"
          controls
          autoPlay
          playsInline
          resumeTime={savedTime}
          onTimeUpdate={(event, playback = {}) => {
            if (!progressKey) return;
            const currentTime = Number.isFinite(playback.currentTime) ? playback.currentTime : event.currentTarget.currentTime;
            const duration = Number.isFinite(playback.duration) && playback.duration > 0 ? playback.duration : event.currentTarget.duration || 0;
            saveWatchProgress(progressKey, { ...progressPayload, title, path: progressKey, currentTime, duration, resumeApplied: playback.resumeApplied === true });
          }}
          onEnded={onEnded}
        />
        <div className="scene-player-info homestead-global-player-info">
          <div><h3>{title || "Untitled video"}</h3>{subtitle && <p>{subtitle}</p>}<div className="scene-player-meta-row">{pills.filter(Boolean).map((pill) => <span key={pill}>{pill}</span>)}</div></div>
        </div>
      </section>
    </div>,
    document.body
  ) : null;
}

function YouTubeSeriesPosterUpload({ seriesId, onSaved }) {
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState("");
  const upload = async (file) => {
    if (!file) return;
    setBusy(true);
    setStatus("Uploading…");
    try {
      const response = await fetch(`/api/youtube/series/${encodeURIComponent(seriesId)}/poster`, { method: "POST", headers: { "Content-Type": "application/octet-stream", "X-Homestead-Content-Type": file.type || "image/jpeg" }, body: file });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data.ok) throw new Error(data.message || "Poster upload failed.");
      setStatus("Poster saved.");
      onSaved?.(data.url);
    } catch (error) { setStatus(error.message || "Poster upload failed."); }
    finally { setBusy(false); }
  };
  return <div className="youtube-series-poster-upload"><label className="secondary-button">{busy ? "Uploading…" : "Upload Series Poster"}<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" disabled={busy} onChange={(event) => { upload(event.target.files?.[0]); event.target.value = ""; }} /></label>{status && <small>{status}</small>}</div>;
}

function YouTubeSeriesBannerUpload({ seriesId, onSaved }) {
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState("");
  const upload = async (file) => {
    if (!file) return;
    setBusy(true);
    setStatus("Uploading…");
    try {
      const response = await fetch(`/api/youtube/series/${encodeURIComponent(seriesId)}/banner`, { method: "POST", headers: { "Content-Type": "application/octet-stream", "X-Homestead-Content-Type": file.type || "image/jpeg" }, body: file });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data.ok) throw new Error(data.message || "Banner upload failed.");
      setStatus("Banner saved.");
      onSaved?.(data.url);
    } catch (error) { setStatus(error.message || "Banner upload failed."); }
    finally { setBusy(false); }
  };
  return <div className="youtube-series-poster-upload"><label className="secondary-button">{busy ? "Uploading…" : "Upload Series Banner"}<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" disabled={busy} onChange={(event) => { upload(event.target.files?.[0]); event.target.value = ""; }} /></label>{status && <small>{status}</small>}</div>;
}

function YouTubeSeriesAppearanceEditor({ seriesId, values = {}, onSaved, onClose, onArtworkSaved, onBannerSaved }) {
  const [draft, setDraft] = useState({ backgroundPosition: values.backgroundPosition || "center", opacity: Number(values.opacity ?? 0.72), darkness: Number(values.darkness ?? 0.48), blur: Number(values.blur ?? 0) });
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    const close = (event) => { if (event.key === "Escape") onClose?.(); };
    window.addEventListener("keydown", close);
    return () => window.removeEventListener("keydown", close);
  }, [onClose]);
  const save = async () => {
    setBusy(true);
    try {
      const response = await fetch(`/api/youtube/series/${encodeURIComponent(seriesId)}/appearance`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(draft) });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data.ok) throw new Error(data.message || "Appearance save failed.");
      onSaved?.(data.appearance || draft);
      onClose?.();
    } catch (error) { alert(error.message || "Appearance save failed."); }
    finally { setBusy(false); }
  };
  return <div className="settings-modal-overlay youtube-series-appearance-overlay" role="dialog" aria-modal="true" aria-label="Series appearance" onClick={onClose}><section className="settings-modal-card youtube-series-appearance-card" onClick={(event) => event.stopPropagation()}><div className="settings-modal-header"><div><h2>Series Appearance</h2><p>Only this YouTube series page changes.</p></div><button className="secondary-button" type="button" onClick={onClose}>✕</button></div><div className="settings-modal-body"><div className="youtube-series-artwork-controls"><YouTubeSeriesPosterUpload seriesId={seriesId} onSaved={onArtworkSaved} /><YouTubeSeriesBannerUpload seriesId={seriesId} onSaved={onBannerSaved} /></div><label className="settings-field"><span>Banner position</span><select value={draft.backgroundPosition} onChange={(event) => setDraft((current) => ({ ...current, backgroundPosition: event.target.value }))}><option value="top">Top</option><option value="center">Center</option><option value="bottom">Bottom</option></select></label><label className="settings-field"><span>Banner opacity {Math.round(draft.opacity * 100)}%</span><input type="range" min="0" max="1" step="0.05" value={draft.opacity} onChange={(event) => setDraft((current) => ({ ...current, opacity: Number(event.target.value) }))} /></label><label className="settings-field"><span>Darkness {Math.round(draft.darkness * 100)}%</span><input type="range" min="0" max="0.95" step="0.05" value={draft.darkness} onChange={(event) => setDraft((current) => ({ ...current, darkness: Number(event.target.value) }))} /></label><label className="settings-field"><span>Blur {draft.blur}px</span><input type="range" min="0" max="30" step="1" value={draft.blur} onChange={(event) => setDraft((current) => ({ ...current, blur: Number(event.target.value) }))} /></label><div className="modal-actions"><button className="secondary-button" type="button" onClick={onClose}>Cancel</button><button className="primary-button" type="button" disabled={busy} onClick={save}>{busy ? "Saving…" : "Save Appearance"}</button></div></div></section></div>;
}

function YouTubeSeriesDetail({ series, artwork = "", banner = "", appearance = {}, onArtworkSaved, onBannerSaved, onAppearanceSaved, onBack, mediaIndex, watchlist, setWatchlist }) {
  const seasonNames = Object.keys(series.seasons || {}).sort((a, b) => (parseInt(a.match(/\d+/)?.[0] || "0", 10) - parseInt(b.match(/\d+/)?.[0] || "0", 10)) || a.localeCompare(b));
  const [activeSeason, setActiveSeason] = useState(seasonNames[0] || "Season 1");
  const [selectedVideo, setSelectedVideo] = useState(null);
  const [appearanceOpen, setAppearanceOpen] = useState(false);
  useEffect(() => setActiveSeason(seasonNames[0] || "Season 1"), [series.id]);
  const videos = [...(series.seasons?.[activeSeason]?.videos || [])].sort((a, b) => (getYouTubeEpisodeNumber(a) || Number.MAX_SAFE_INTEGER) - (getYouTubeEpisodeNumber(b) || Number.MAX_SAFE_INTEGER) || getYouTubeVideoReleaseTime(a) - getYouTubeVideoReleaseTime(b) || cleanYouTubeEpisodeTitle(a, series.title).localeCompare(cleanYouTubeEpisodeTitle(b, series.title)));
  const automaticPoster = series.poster || series.thumbnail || getYouTubeVideoArtworkCandidates(series.videos?.[0] || {})[0] || "";
  return (
    <div className="youtube-series-detail">
      <header className="youtube-series-detail-header youtube-series-detail-header-with-banner" style={{ "--youtube-series-banner-opacity": appearance.opacity ?? 0.72, "--youtube-series-banner-darkness": appearance.darkness ?? 0.48, "--youtube-series-banner-blur": `${appearance.blur ?? 0}px` }}>
        {banner && <div className="youtube-series-detail-banner" aria-hidden="true" style={{ backgroundImage: `url("${String(banner).replaceAll('"', '%22')}")`, backgroundPosition: appearance.backgroundPosition || "center" }} />}
        <div className="youtube-series-header-controls"><button className="secondary-button" type="button" onClick={onBack}>← Series</button><button className="global-search-icon-button app-ribbon-appearance-button" type="button" aria-label={`Customize ${series.title} appearance`} title="Appearance" onClick={() => setAppearanceOpen(true)}>◉</button></div>
        <YouTubeArtwork className="youtube-series-detail-poster" candidates={[artwork, automaticPoster]} alt="" />
        <div><p className="eyebrow">YouTube Series</p><h1>{series.title}</h1><p>{seasonNames.length} season{seasonNames.length === 1 ? "" : "s"} · {series.videoCount} videos across your creators</p></div>
      </header>
      <nav className="subtabs youtube-season-tabs" aria-label={`${series.title} seasons`}>{seasonNames.map((season) => <TabButton key={season} active={activeSeason === season} onClick={() => setActiveSeason(season)}>{titleFromId(season)}</TabButton>)}</nav>
      <div className="youtube-series-timeline-heading"><div><h2>{titleFromId(activeSeason)}</h2><p>All creators interleaved by release date.</p></div><span>{videos.length} videos</span></div>
      <div className="youtube-episode-grid">{videos.map((video, index) => <YouTubeVideoCard key={`${video.creatorId || "creator"}:${video.path || video.sourcePath || video.id || index}`} video={video} creator={{ id: video.creatorId, name: video.creatorName, poster: video.creatorPoster }} onPlay={setSelectedVideo} mediaIndex={mediaIndex} watchlist={watchlist} setWatchlist={setWatchlist} />)}</div>
      <HomesteadVideoPlayerOverlay file={selectedVideo} title={selectedVideo ? cleanYouTubeEpisodeTitle(selectedVideo) : ""} subtitle={selectedVideo?.creatorName || ""} pills={[titleFromId(series.title), titleFromId(activeSeason)]} onClose={() => setSelectedVideo(null)} progressKey={selectedVideo?.path || selectedVideo?.sourcePath || ""} progressPayload={{ type: "youtube", creatorId: selectedVideo?.creatorId, creatorName: selectedVideo?.creatorName, poster: getYouTubeVideoArtworkCandidates(selectedVideo || {})[0] || "" }} mediaIndex={mediaIndex} collectionItem={selectedVideo ? { ...selectedVideo, title: cleanYouTubeEpisodeTitle(selectedVideo), poster: getYouTubeVideoArtworkCandidates(selectedVideo)[0] || "" } : null} library="youtube" watchlist={watchlist} setWatchlist={setWatchlist} />
      {appearanceOpen && <YouTubeSeriesAppearanceEditor key={series.id} seriesId={series.id} onArtworkSaved={onArtworkSaved} onBannerSaved={onBannerSaved} values={appearance} onSaved={onAppearanceSaved} onClose={() => setAppearanceOpen(false)} />}
    </div>
  );
}

function YouTubeCreatorSeriesTabs({ groupedSeries, setSelectedVideo, creator, mediaIndex, watchlist, setWatchlist }) {
const sortByNumber = (a, b) => {
  const numA = parseInt(String(a).replace(/\D/g, ""), 10) || 0;
  const numB = parseInt(String(b).replace(/\D/g, ""), 10) || 0;

  return numA - numB;
};
  const seriesNames = Object.keys(groupedSeries).sort();
  const [activeSeries, setActiveSeries] = useState(seriesNames[0] || "");

  const seasonNames = Object.keys(groupedSeries[activeSeries] || {}).sort(sortByNumber);
  const [activeSeason, setActiveSeason] = useState(seasonNames[0] || "");

  useEffect(() => {
    const seasons = Object.keys(groupedSeries[activeSeries] || {}).sort(sortByNumber);
    setActiveSeason(seasons[0] || "");
  }, [activeSeries, groupedSeries]);

  const videos = [
  ...(groupedSeries[activeSeries]?.[activeSeason] || []),
].sort((a, b) => {
  const getEpisode = (video) => {
    const text =
      video.title ||
      video.filename ||
      video.name ||
      "";

    const bracketMatch = text.match(/\[(\d+)\]/);

    if (bracketMatch) {
      return parseInt(bracketMatch[1], 10);
    }

    const xMatch = text.match(/X\s*(\d+)/i);

    if (xMatch) {
      return parseInt(xMatch[1], 10);
    }

    return 0;
  };

  return getEpisode(a) - getEpisode(b) || getYouTubeVideoReleaseTime(a) - getYouTubeVideoReleaseTime(b);
});

  return (
    <div className="youtube-series-tabs-view">
      <div className="tabs">
        {seriesNames.map((seriesName) => (
          <TabButton
            key={seriesName}
            active={activeSeries === seriesName}
            onClick={() => setActiveSeries(seriesName)}
          >
            {titleFromId(seriesName)}
          </TabButton>
        ))}
      </div>

      <div className="subtabs">
        {seasonNames.map((seasonName) => (
          <TabButton
            key={seasonName}
            active={activeSeason === seasonName}
            onClick={() => setActiveSeason(seasonName)}
          >
            {titleFromId(seasonName)}
          </TabButton>
        ))}
      </div>

      <div className="youtube-episode-grid">
        {videos.map((video, index) => <YouTubeVideoCard key={video.path || video.sourcePath || video.id || index} video={video} creator={creator} onPlay={setSelectedVideo} mediaIndex={mediaIndex} watchlist={watchlist} setWatchlist={setWatchlist} />)}
      </div>
    </div>
  );
}

