function cleanBookSeriesValue(value = "") {
  const series = String(value || "").trim();
  if (/\b(?:international(?:ly)?|new\s+york\s+times|usa\s+today|award[- ]winning|bestsell(?:er|ing)|million\s+copies|special\s+edition|collector'?s\s+edition)\b/i.test(series)) return "";
  if (/^(?:book|volume|installment|edition|ordered|unordered|issue)\b/i.test(series)) return "";
  return series;
}

function bookSeriesSortNumber(value = "") {
  const match = String(value || "").match(/\d+(?:\.\d+)?/);
  return match ? Number(match[0]) : Number.POSITIVE_INFINITY;
}

function bookSeriesAppearanceKey(value = "") {
  return String(value || "series").trim().toLowerCase().replace(/[^a-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "") || "series";
}

function sortBooksInSeries(books = []) {
  return [...books].sort((a, b) => {
    const numberDifference = bookSeriesSortNumber(a.seriesIndex) - bookSeriesSortNumber(b.seriesIndex);
    if (Number.isFinite(numberDifference) && numberDifference !== 0) return numberDifference;
    if (Number.isFinite(bookSeriesSortNumber(a.seriesIndex)) !== Number.isFinite(bookSeriesSortNumber(b.seriesIndex))) {
      return Number.isFinite(bookSeriesSortNumber(a.seriesIndex)) ? -1 : 1;
    }
    return String(a.title || "").localeCompare(String(b.title || ""), undefined, { numeric: true });
  });
}

