function BookReader({ file, book, onClose, compact = false }) {
  const readerRef = useRef(null);
  const [readerError, setReaderError] = useState('');
  const renditionRef = useRef(null);
  const touchStartRef = useRef(null);
  const readerUrl = getPlayableMediaUrl(file || {});
  const progressKey = `book:${book?.id || "unknown"}:${file?.path || file?.name || "edition"}`;
  const isPdf = /\.pdf(?:$|[?#])/i.test(file?.name || file?.path || "");

  const goPrevPage = () => {
    renditionRef.current?.prev?.();
  };

  const goNextPage = () => {
    renditionRef.current?.next?.();
  };

  const handleBookTouchStart = (event) => {
    const touch = event.touches?.[0];
    if (!touch) return;

    touchStartRef.current = {
      x: touch.clientX,
      y: touch.clientY,
      time: Date.now(),
    };
  };

  const handleBookTouchEnd = (event) => {
    const start = touchStartRef.current;
    const touch = event.changedTouches?.[0];
    touchStartRef.current = null;

    if (!start || !touch) return;

    const deltaX = touch.clientX - start.x;
    const deltaY = touch.clientY - start.y;
    const elapsed = Date.now() - start.time;

    if (Math.abs(deltaX) > 55 && Math.abs(deltaX) > Math.abs(deltaY) * 1.35 && elapsed < 900) {
      if (deltaX < 0) goNextPage();
      else goPrevPage();
    }
  };

  const handleBookTap = (event) => {
    if (!readerRef.current) return;

    const bounds = readerRef.current.getBoundingClientRect();
    const x = event.clientX - bounds.left;
    const leftZone = bounds.width * 0.22;
    const rightZone = bounds.width * 0.78;

    if (x <= leftZone) goPrevPage();
    if (x >= rightZone) goNextPage();
  };

  useEffect(() => {
    if (!file || !readerRef.current || isPdf) return;

    let cancelled = false;
    let epubBook = null;
    let rendition = null;

    async function loadBook() {
      const savedProgress = getWatchProgress()[progressKey] || getWatchProgress()[book?.id];

      epubBook = ePub(readerUrl);

      await epubBook.ready;
      if (cancelled || !readerRef.current) return;

      rendition = epubBook.renderTo(readerRef.current, {
        width: "100%",
        height: "100%",
      });

      renditionRef.current = rendition;

      await rendition.display(savedProgress?.path === file.path ? savedProgress.location || undefined : undefined);
      // Display the first page immediately; location indexing can be expensive.
      epubBook.locations.generate(1000).catch(() => {});

      rendition.on("relocated", (location) => {
        const percentage =
          epubBook.locations.percentageFromCfi(location.start.cfi) || 0;

        saveWatchProgress(progressKey, {
          type: "book",
          title: book.title,
          author: book.author,
          poster: book.poster,
          path: file.path,
          fileName: file.name,
          location: location.start.cfi,
          percentage,
          currentTime: percentage,
          duration: 1,
        });
      });
    }

    setReaderError('');
    loadBook().catch((error) => { if (!cancelled) setReaderError(error.message || 'This ebook could not be opened.'); });

    return () => {
      cancelled = true;

      if (rendition) {
        rendition.destroy();
      }

      if (epubBook) {
        epubBook.destroy();
      }
    };
  }, [book?.id, file?.path, isPdf, progressKey, readerUrl]);

  useEffect(() => {
    const handleKeyDown = (event) => {
      if (compact && !readerRef.current?.contains(document.activeElement)) return;
      if (/INPUT|TEXTAREA|SELECT/.test(event.target?.tagName || '')) return;
      if (event.key === "ArrowLeft") goPrevPage();
      if (event.key === "ArrowRight") goNextPage();
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [compact]);

  return (
    <div className={compact ? "book-reader-inline" : "book-reader-overlay"}>
      <div className="book-reader-toolbar">
        <button className="secondary-button" onClick={onClose}>
          {compact ? 'Close Read Along' : 'Close'}
        </button>

        {!isPdf && <button className="secondary-button" onClick={goPrevPage}>← Prev</button>}

        <strong>{book?.title || file.name}</strong>

        {!isPdf && <button className="secondary-button" onClick={goNextPage}>Next →</button>}
      </div>

      {readerError && <p role="alert">{readerError}</p>}
      {compact && <p className="read-along-note">Turn pages as you listen. Reading position is saved separately from audio.</p>}

      {isPdf ? (
        <iframe className="book-reader-view book-reader-pdf" src={readerUrl} title={book?.title || file?.name || "Book"} />
      ) : (
        <div
          ref={readerRef}
          className="book-reader-view book-reader-touch-view"
          onTouchStart={handleBookTouchStart}
          onTouchEnd={handleBookTouchEnd}
          onClick={handleBookTap}
        />
      )}
    </div>
  );
}

function cleanMusicTrackTitle(value = "", artist = "") {
  const escapedArtist = String(artist).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return String(value || "Untitled Track")
    .replace(/^\s*\d{1,2}[\s._-]*[-x]\s*\d{1,3}[\s._-]+/i, "")
    .replace(/^\s*\d{1,3}[\s._-]+/, "")
    .replace(new RegExp(`^${escapedArtist}\\s*-\\s*`, "i"), "")
    .replace(/\s*\(official music video\)/i, "")
    .replace(/\s*\(official video\)/i, "")
    .replace(/\s*ft_.*$/i, "")
    .trim() || "Untitled Track";
}

function getMusicAlbumKey(artist = "", album = "") {
  return `${String(artist || "").trim().toLowerCase().replace(/[^a-z0-9]+/g, " ").trim()}::${String(album || "").trim().toLowerCase().replace(/[^a-z0-9]+/g, " ").trim()}`;
}

function readCachedMusicLibraryArtwork() {
  if (typeof sessionStorage === "undefined") return { artists: {}, albums: {} };
  try {
    const cached = JSON.parse(sessionStorage.getItem("homesteadMusicLibraryArtwork") || "null");
    return cached && typeof cached === "object" ? { artists: cached.artists || {}, albums: cached.albums || {} } : { artists: {}, albums: {} };
  } catch {
    return { artists: {}, albums: {} };
  }
}

function findLocalMusicAlbumArtwork(audioFile = {}, files = []) {
  const audioPath = String(audioFile.path || audioFile.sourcePath || "").replaceAll("\\", "/");
  const audioParts = audioPath.split("/").filter(Boolean);
  const directDirectory = audioParts.slice(0, -1).join("/");
  const directParent = audioParts.at(-2) || "";
  const albumDirectory = /^(?:cd|disc|disk)\s*\d+$/i.test(directParent)
    ? audioParts.slice(0, -2).join("/")
    : directDirectory;
  const preferredNames = ["cover", "folder", "front", "album", "albumart"];
  const candidates = (Array.isArray(files) ? files : [])
    .map((file) => {
      const filePath = String(file?.path || file?.sourcePath || file?.publicPath || "").replaceAll("\\", "/");
      const name = String(file?.name || filePath.split("/").pop() || "");
      const baseName = name.replace(/\.(jpe?g|png|webp)$/i, "").toLowerCase();
      const directory = filePath.split("/").filter(Boolean).slice(0, -1).join("/");
      return { file, filePath, baseName, directory, rank: preferredNames.indexOf(baseName) };
    })
    .filter((candidate) => candidate.rank >= 0 && /\.(jpe?g|png|webp)$/i.test(candidate.filePath));
  const match = candidates
    .filter((candidate) => candidate.directory === directDirectory || candidate.directory === albumDirectory)
    .sort((left, right) => left.rank - right.rank)[0];
  return match ? getPlayableMediaUrl(match.file) : "";
}

function normalizeLocalMusicSong(audioFile = {}, artistFolder = {}, files = []) {
  const pathParts = String(audioFile.path || audioFile.sourcePath || "").split("/").filter(Boolean);
  const embedded = audioFile.metadata || audioFile.tags || {};
  const artist = embedded.artist || embedded.albumArtist || artistFolder.name || pathParts[2] || "Unknown Artist";
  const directParent = pathParts[pathParts.length - 2] || '';
  const albumParent = /^(?:cd|disc|disk)\s*\d+$/i.test(directParent) ? pathParts[pathParts.length - 3] : directParent;
  const albumFolder = albumParent && albumParent !== artistFolder.name ? albumParent : '';
  const album = embedded.album || albumFolder;
  const fileTitle = String(audioFile.name || pathParts.at(-1) || "").replace(/\.(mp3|flac|m4a|aac|ogg|wav|m4b)$/i, "");
  const title = String(embedded.title || audioFile.title || "").trim() || cleanMusicTrackTitle(fileTitle, artist);
  const audioBaseName = String(audioFile.name || "").replace(/\.[^/.]+$/, "");
  const matchingVideo = files.find((file) => {
    const fileBaseName = String(file.name || "").replace(/\.[^/.]+$/, "");
    return (file.type === "video" || file.type === "musicvideo") && fileBaseName === audioBaseName;
  });
  const matchingLyrics = files.find((file) => {
    const fileBaseName = String(file.name || "").replace(/\.[^/.]+$/, "");
    return /\.(lrc|txt)$/i.test(file.name || file.path || "") && fileBaseName === audioBaseName;
  });
  const embeddedArtwork = String(
    audioFile.poster || audioFile.cover || audioFile.artwork ||
    embedded.poster || embedded.cover || embedded.artwork || embedded.image || ""
  ).trim();
  return {
    id: audioFile.path,
    title,
    artist,
    album,
    albumArtist: embedded.albumArtist || artist,
    year: embedded.year || embedded.date || audioFile.year || "",
    discNumber: embedded.disc || embedded.discNumber || "",
    trackNumber: embedded.track || embedded.trackNumber || "",
    embeddedArtwork,
    localAlbumArtwork: findLocalMusicAlbumArtwork(audioFile, files),
    path: audioFile.path,
    audioFile,
    videoFile: matchingVideo || null,
    lyricsFile: matchingLyrics || null,
    files: [audioFile, matchingVideo, matchingLyrics].filter(Boolean),
  };
}

