const [discoveredArtistAlbums, setDiscoveredArtistAlbums] = useState([]);
const [discoveredArtistSongs, setDiscoveredArtistSongs] = useState([]);
const [discoveredArtistLoading, setDiscoveredArtistLoading] = useState(false);
const [discoveredArtistStatus, setDiscoveredArtistStatus] = useState(null);
const [selectedDiscoveredAlbum, setSelectedDiscoveredAlbum] = useState(null);
const [discoveredAlbumStatus, setDiscoveredAlbumStatus] = useState(null);
