function getProfileBirthdayValue(profile) {
  const metadata = profile?.metadata || {};
  const details = profile?.details || {};
  const profileBlock = profile?.profile || {};
  const candidates = profile?.metadataCandidates || {};
  const candidateDetails = candidates?.details || {};
  const candidateProfile = candidates?.profile || {};

  return (
    profile?.birthday ||
    profile?.birthdate ||
    profile?.birthDate ||
    profile?.dateOfBirth ||
    profile?.dob ||
    profile?.birth_date ||
    metadata?.birthday ||
    metadata?.birthdate ||
    metadata?.birthDate ||
    metadata?.dateOfBirth ||
    metadata?.dob ||
    metadata?.birth_date ||
    metadata?.["Birth Date"] ||
    metadata?.["Date of Birth"] ||
    details?.birthday ||
    details?.birthdate ||
    details?.birthDate ||
    details?.dateOfBirth ||
    details?.dob ||
    profileBlock?.birthday ||
    profileBlock?.birthdate ||
    profileBlock?.birthDate ||
    profileBlock?.dateOfBirth ||
    profileBlock?.dob ||
    candidates?.birthday ||
    candidates?.birthdate ||
    candidates?.birthDate ||
    candidates?.dateOfBirth ||
    candidates?.dob ||
    candidates?.birth_date ||
    candidateDetails?.birthday ||
    candidateDetails?.birthdate ||
    candidateDetails?.birthDate ||
    candidateDetails?.dateOfBirth ||
    candidateDetails?.dob ||
    candidateProfile?.birthday ||
    candidateProfile?.birthdate ||
    candidateProfile?.birthDate ||
    candidateProfile?.dateOfBirth ||
    candidateProfile?.dob ||
    ""
  );
}

function parseBirthdayParts(rawBirthday) {
  if (!rawBirthday) return null;

  const raw = String(rawBirthday)
    .trim()
    .replace(/^(birthday|birthdate|birth date|date of birth|dob)\s*:\s*/i, "")
    .trim();

  if (!raw) return null;

  const normalizeYear = (value) => {
    if (!value) return null;
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return null;
    if (String(value).length === 2) return numeric > 30 ? 1900 + numeric : 2000 + numeric;
    return numeric >= 1800 && numeric <= 2200 ? numeric : null;
  };

  const iso = raw.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);
  if (iso) {
    return { year: normalizeYear(iso[1]), month: Number(iso[2]) - 1, day: Number(iso[3]) };
  }

  const us = raw.match(/^(\d{1,2})[-/](\d{1,2})(?:[-/](\d{2,4}))?/);
  if (us) {
    return { year: normalizeYear(us[3]), month: Number(us[1]) - 1, day: Number(us[2]) };
  }

  const monthNames = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
  const textMonth = raw.match(/^(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\s+(\d{1,2})(?:,?\s*(\d{2,4}))?/i);
  if (textMonth) {
    return {
      year: normalizeYear(textMonth[3]),
      month: monthNames.findIndex((name) => textMonth[1].toLowerCase().startsWith(name)),
      day: Number(textMonth[2]),
    };
  }

  const dayTextMonth = raw.match(/^(\d{1,2})\s+(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)(?:,?\s*(\d{2,4}))?/i);
  if (dayTextMonth) {
    return {
      year: normalizeYear(dayTextMonth[3]),
      month: monthNames.findIndex((name) => dayTextMonth[2].toLowerCase().startsWith(name)),
      day: Number(dayTextMonth[1]),
    };
  }

  const parsed = new Date(raw);
  if (Number.isNaN(parsed.getTime())) return null;

  return {
    year: parsed.getUTCFullYear() >= 1800 ? parsed.getUTCFullYear() : null,
    month: parsed.getUTCMonth(),
    day: parsed.getUTCDate(),
  };
}

function parseBirthdayMonthDay(rawBirthday) {
  const parts = parseBirthdayParts(rawBirthday);
  if (!parts) return null;
  return { month: parts.month, day: parts.day };
}

function normalizeProfileImageUrl(value) {
  if (!value) return "";

  const raw = String(value || "").trim();
  if (!raw) return "";

  if (/^(https?:|blob:|data:)/i.test(raw)) return raw;
  if (raw.startsWith("/api/file")) return raw;

  // Profile detail pages already render local profile posters through /api/file.
  // Use that same route here so birthday cards show the selected profile poster
  // instead of falling through to a random gallery image.
  if (
    raw.startsWith("/media/") ||
    raw.startsWith("/mnt/") ||
    /^[A-Za-z]:[\\/]/.test(raw) ||
    raw.startsWith("\\\\")
  ) {
    return getLocalApiFileUrl(raw);
  }

  return raw;
}

function normalizePosterCandidate(value) {
  if (!value) return "";

  const rawCandidate =
    typeof value === "string"
      ? value
      : value.poster ||
        value.posterUrl ||
        value.posterPath ||
        value.profilePoster ||
        value.selectedPoster ||
        value.primaryPoster ||
        value.headshot ||
        value.headshotUrl ||
        value.profileImage ||
        value.profileImageUrl ||
        value.image ||
        value.imageUrl ||
        value.avatar ||
        value.avatarUrl ||
        value.thumbnail ||
        value.thumb ||
        value.cover ||
        value.coverUrl ||
        value.photo ||
        value.photoUrl ||
        value.path ||
        value.filePath ||
        value.url ||
        value.src ||
        "";

  const normalized = normalizeProfileImageUrl(rawCandidate);
  if (!normalized) return "";

  const rawString = String(rawCandidate || "").trim();
  const looksLikeApiFile = normalized.startsWith("/api/file");
  const looksLikeRemote = /^(https?:|blob:|data:)/i.test(normalized);
  const looksLikeImage = /\.(jpg|jpeg|png|webp|gif|avif|svg|heic|heif)(\?.*)?$/i.test(rawString) || /\.(jpg|jpeg|png|webp|gif|avif|svg|heic|heif)(\?.*)?$/i.test(normalized);

  // Avoid trying to render a raw profile folder as an image. Folder-based poster
  // guesses are added separately by getProfilePosterCandidates().
  if (!looksLikeImage && !looksLikeRemote && !looksLikeApiFile) return "";

  return normalized;
}

function getProfileImageFolderCandidates(profile = {}) {
  const metadata = profile.metadata || {};
  const rawFolders = [
    profile.profileDir,
    profile.folderPath,
    profile.folder,
    profile.path,
    profile.sourcePath,
    profile.mediaPath,
    profile.root,
    profile.profileRoot,
    profile.directory,
    metadata.profileDir,
    metadata.folderPath,
    metadata.folder,
    metadata.path,
    metadata.sourcePath,
    metadata.mediaPath,
    metadata.root,
    metadata.profileRoot,
    metadata.directory,
  ];

  [profile.metadataPath, metadata.metadataPath, profile.jsonPath, metadata.jsonPath].forEach((value) => {
    const raw = String(value || "").trim();
    if (!raw) return;
    rawFolders.push(raw.replace(/[\/][^\/]*metadata\.json$/i, ""));
  });

  const names = [
    profile.slug,
    profile.id,
    profile.name,
    profile.displayName,
    profile.title,
    metadata.slug,
    metadata.id,
    metadata.name,
    metadata.displayName,
    metadata.title,
  ]
    .map((value) => String(value || "").trim())
    .filter(Boolean);

  const slugs = Array.from(new Set(names.flatMap((name) => {
    const lowerSlug = name
      .toLowerCase()
      .replace(/&/g, " and ")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "");
    const compactSlug = name
      .toLowerCase()
      .replace(/&/g, "and")
      .replace(/[^a-z0-9]+/g, "")
      .replace(/^-+|-+$/g, "");
    const titleFolder = name.replace(/[\/:*?"<>|]+/g, "").trim();
    return [lowerSlug, compactSlug, titleFolder].filter(Boolean);
  })));

  const roots = [
    // Public/API-style roots used by the app.
    "/media/personal",
    "/media/girls",
    "/media/performers",
    "/media/celebrities",
    "/media/adult/personal",
    "/media/adult/girls",
    "/media/adult/performers",
    "/media/adult/celebrities",

    // Real Unraid/share roots should render headshot.jpg directly from the
    // profile's main directory, e.g.
    // /mnt/disk2/Adult/personal/kenzie/headshot.jpg.
    "/Adult/personal",
    "/Adult/girls",
    "/Adult/performers",
    "/Adult/celebrities",
    "/mnt/user/Adult/personal",
    "/mnt/user/Adult/girls",
    "/mnt/user/Adult/performers",
    "/mnt/user/Adult/celebrities",
    "/mnt/disk1/Adult/personal",
    "/mnt/disk1/Adult/girls",
    "/mnt/disk1/Adult/performers",
    "/mnt/disk1/Adult/celebrities",
    "/mnt/disk2/Adult/personal",
    "/mnt/disk2/Adult/girls",
    "/mnt/disk2/Adult/performers",
    "/mnt/disk2/Adult/celebrities",
    "/mnt/cache/Adult/personal",
    "/mnt/cache/Adult/girls",
    "/mnt/cache/Adult/performers",
    "/mnt/cache/Adult/celebrities",
  ];

  slugs.forEach((slug) => {
    roots.forEach((root) => rawFolders.push(`${root}/${slug}`));
  });

  return Array.from(new Set(rawFolders.map((value) => String(value || "").trim()).filter(Boolean)));
}

function getProfilePosterCandidates(profile = {}) {
  const metadata = profile.metadata || {};
  const artwork = profile.artwork || {};
  const files = Array.isArray(profile.files) ? profile.files : [];
  const photos = Array.isArray(profile.photos) ? profile.photos : [];
  const images = Array.isArray(profile.images) ? profile.images : [];
  const media = Array.isArray(profile.media) ? profile.media : [];

  const imageFiles = files.filter((file) => {
    const type = String(file?.type || "").toLowerCase();
    const name = String(file?.name || file?.fileName || file?.filename || file?.path || file?.filePath || "").toLowerCase();
    return type === "image" || /\.(jpg|jpeg|png|webp|gif|heic|heif)$/i.test(name);
  });

  const preferredImageFiles = [
    ...imageFiles.filter((file) => /poster|folder|cover|avatar|headshot|profile/i.test(String(file?.name || file?.fileName || file?.filename || file?.path || ""))),
    ...imageFiles,
  ];

  const profileFolders = getProfileImageFolderCandidates(profile);
  const posterFileNames = [
    // The poster selected on the profile detail page is also the library-card
    // poster. Headshots are fallbacks when no selected poster exists.
    "poster.jpg",
    "poster.jpeg",
    "poster.png",
    "poster.webp",
    "poster.heic",
    "poster.heif",
    "folder.jpg",
    "folder.jpeg",
    "folder.png",
    "folder.webp",
    "folder.heic",
    "folder.heif",
    "headshot.jpg",
    "headshot.jpeg",
    "headshot.png",
    "headshot.webp",
    "headshot.heic",
    "headshot.heif",
    "profile.jpg",
    "profile.jpeg",
    "profile.png",
    "profile.webp",
    "profile.heic",
    "profile.heif",
    "avatar.jpg",
    "avatar.jpeg",
    "avatar.png",
    "avatar.webp",
    "avatar.heic",
    "avatar.heif",
    "cover.jpg",
    "cover.jpeg",
    "cover.png",
    "cover.heic",
    "cover.heif",
    "image.jpg",
    "image.jpeg",
    "image.png",
    "image.heic",
    "image.heif",
    "thumbnail.jpg",
    "thumbnail.jpeg",
    "thumbnail.png",
    "thumbnail.heic",
    "thumbnail.heif",
  ];
  const folderPosterCandidates = profileFolders.flatMap((folder) =>
    posterFileNames.map((fileName) => `${folder.replace(/[\\/]+$/, "")}/${fileName}`)
  );

  const rawCandidates = [
    ...(Array.isArray(profile.posterCandidates) ? profile.posterCandidates : []),
    profile.profilePoster,
    profile.selectedPoster,
    profile.primaryPoster,
    profile.poster,
    profile.posterUrl,
    profile.posterPath,
    metadata.profilePoster,
    metadata.selectedPoster,
    metadata.primaryPoster,
    metadata.poster,
    metadata.posterUrl,
    metadata.posterPath,
    artwork.poster,
    profile.headshot,
    profile.headshotUrl,
    profile.profileImage,
    profile.profileImageUrl,
    profile.avatar,
    profile.avatarUrl,
    profile.image,
    profile.imageUrl,
    profile.thumbnail,
    profile.thumb,
    profile.cover,
    profile.coverUrl,
    profile.photo,
    profile.photoUrl,
    metadata.headshot,
    metadata.headshotUrl,
    metadata.profileImage,
    metadata.profileImageUrl,
    metadata.avatar,
    metadata.avatarUrl,
    metadata.image,
    metadata.imageUrl,
    metadata.thumbnail,
    metadata.cover,
    metadata.photo,
    artwork.image,
    artwork.avatar,
    artwork.cover,
    ...folderPosterCandidates,
    ...photos,
    ...images,
    ...media,
    ...preferredImageFiles,
  ];

  const seen = new Set();
  return rawCandidates
    .map(normalizePosterCandidate)
    .filter(Boolean)
    .filter((candidate) => {
      const key = String(candidate);
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

function getProfilePosterValue(profile = {}) {
  return getProfilePosterCandidates(profile)[0] || "";
}


function getProfileHeadshotManifestKeys(profile = {}) {
  const metadata = profile.metadata || {};
  const rawKeys = [
    profile.id,
    profile.slug,
    profile.folderName,
    profile.name,
    profile.displayName,
    profile.title,
    metadata.id,
    metadata.slug,
    metadata.folderName,
    metadata.name,
    metadata.displayName,
    metadata.title,
  ];

  return Array.from(new Set(rawKeys
    .map((value) => String(value || "").trim())
    .filter(Boolean)
    .flatMap((value) => {
      const slug = value
        .toLowerCase()
        .replace(/&/g, " and ")
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "");
      const compact = value
        .toLowerCase()
        .replace(/&/g, "and")
        .replace(/[^a-z0-9]+/g, "")
        .replace(/^-+|-+$/g, "");
      return [slug, compact].filter(Boolean);
    })));
}

function applyHeadshotManifestToProfiles(profiles = [], headshotManifest = {}) {
  if (!headshotManifest || !Object.keys(headshotManifest).length) return profiles;

  return profiles.map((profile) => {
    const keys = getProfileHeadshotManifestKeys(profile);
    const manifestHeadshot = keys.map((key) => headshotManifest[key]).find(Boolean);
    if (!manifestHeadshot) return profile;

    const existingCandidates = Array.isArray(profile.posterCandidates) ? profile.posterCandidates : [];
    return {
      ...profile,
      headshot: manifestHeadshot,
      headshotUrl: manifestHeadshot,
      posterCandidates: Array.from(new Set([
        ...existingCandidates,
        manifestHeadshot,
      ])),
    };
  });
}

function getProfileInitials(person = {}) {
  const raw = person.name || person.displayName || person.title || person.metadata?.name || person.id || "?";
  const parts = String(raw).trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return "?";
  return parts.slice(0, 2).map((part) => part[0]?.toUpperCase() || "").join("") || "?";
}

function AdultBirthdayPoster({ person, className = "" }) {
  const candidates = Array.isArray(person?.posterCandidates) && person.posterCandidates.length
    ? person.posterCandidates
    : getProfilePosterCandidates(person);
  const [candidateIndex, setCandidateIndex] = useState(0);
  const [failedAllCandidates, setFailedAllCandidates] = useState(false);
  const src = !failedAllCandidates ? candidates[candidateIndex] || "" : "";
  const initials = getProfileInitials(person);

  useEffect(() => {
    setCandidateIndex(0);
    setFailedAllCandidates(false);
  }, [person?.id, person?.name, candidates.join("|")]);

  return (
    <span
      className={`adult-birthday-poster${src ? "" : " missing"}${className ? ` ${className}` : ""}`}
      title={!src && candidates.length ? "Profile image unavailable" : undefined}
    >
      {src ? (
        <img
          src={src}
          alt=""
          loading="lazy"
          onError={() => {
            setCandidateIndex((currentIndex) => {
              const nextIndex = currentIndex + 1;
              if (nextIndex < candidates.length) return nextIndex;
              setFailedAllCandidates(true);
              return currentIndex;
            });
          }}
        />
      ) : (
        <span className="adult-birthday-initials" aria-hidden="true">{initials}</span>
      )}
    </span>
  );
}

function getUpcomingAdultBirthdays(profiles = [], daysAhead = 7) {
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  return profiles
    .map((profile) => {
      const birthdayRaw = getProfileBirthdayValue(profile);
      const birthdayParts = parseBirthdayParts(birthdayRaw);
      if (!birthdayParts) return null;

      const nextBirthday = new Date(today.getFullYear(), birthdayParts.month, birthdayParts.day);
      nextBirthday.setHours(0, 0, 0, 0);

      if (nextBirthday < today) {
        nextBirthday.setFullYear(today.getFullYear() + 1);
      }

      const daysUntil = Math.round((nextBirthday - today) / (1000 * 60 * 60 * 24));
      if (daysUntil < 0 || daysUntil > daysAhead) return null;

      const turningAge = birthdayParts.year ? nextBirthday.getFullYear() - birthdayParts.year : null;

      return {
        ...profile,
        birthdayRaw,
        birthdayYear: birthdayParts.year || null,
        turningAge: Number.isFinite(turningAge) && turningAge >= 0 ? turningAge : null,
        poster: getProfilePosterValue(profile),
        posterCandidates: getProfilePosterCandidates(profile),
        daysUntilBirthday: daysUntil,
        birthdayLabel: formatHomesteadDate(nextBirthday),
      };
    })
    .filter(Boolean)
    .sort((a, b) => a.daysUntilBirthday - b.daysUntilBirthday || String(a.name || "").localeCompare(String(b.name || "")))
    .slice(0, 12);
}

function normalizeAdultProfileLibrary(value) {
  if (value === "girls") return "personal";
  if (value === "personalProfiles") return "personal";
  if (value === "performer") return "performers";
  if (value === "celebrity") return "celebrities";
  return value || "personal";
}

function collectAdultIndexProfiles(mediaIndex) {
  const sources = [
    { library: "personal", items: mediaIndex?.libraries?.personal },
    { library: "personal", items: mediaIndex?.personal },
    { library: "personal", items: mediaIndex?.libraries?.girls },
    { library: "personal", items: mediaIndex?.girls },
    { library: "performers", items: mediaIndex?.libraries?.performers },
    { library: "performers", items: mediaIndex?.performers },
    { library: "celebrities", items: mediaIndex?.libraries?.celebrities },
    { library: "celebrities", items: mediaIndex?.celebrities },
  ];

  return sources.flatMap(({ library, items }) => {
    if (!items) return [];

    const values = Array.isArray(items)
      ? items
      : Object.entries(items).map(([id, value]) => ({ id, ...(value || {}) }));

    return values.map((item) => ({
      ...item,
      library: normalizeAdultProfileLibrary(item?.library || library),
    }));
  });
}

function getAdultProfileMergeIdentity(profile = {}) {
  const rawIdentity =
    profile.name ||
    profile.displayName ||
    profile.title ||
    profile.metadata?.name ||
    profile.metadata?.displayName ||
    profile.metadata?.title ||
    profile.profile?.name ||
    profile.id ||
    "";

  return String(rawIdentity)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "") || String(profile.id || Math.random());
}

function getPreferredProfilePosterField(profile = {}) {
  return (
    profile.poster ||
    profile.profilePoster ||
    profile.selectedPoster ||
    profile.primaryPoster ||
    profile.posterUrl ||
    profile.posterPath ||
    profile.headshot ||
    profile.headshotUrl ||
    profile.profileImage ||
    profile.profileImageUrl ||
    profile.avatar ||
    profile.avatarUrl ||
    profile.image ||
    profile.imageUrl ||
    profile.cover ||
    profile.coverUrl ||
    profile.metadata?.poster ||
    profile.metadata?.profilePoster ||
    profile.metadata?.selectedPoster ||
    profile.metadata?.primaryPoster ||
    profile.metadata?.posterUrl ||
    profile.metadata?.posterPath ||
    profile.metadata?.headshot ||
    profile.metadata?.profileImage ||
    profile.metadata?.avatar ||
    profile.metadata?.image ||
    profile.metadata?.cover ||
    ""
  );
}

function mergeAdultProfileSources(...sources) {
  const byKey = new Map();

  sources.flat().filter(Boolean).forEach((profile) => {
    const library = normalizeAdultProfileLibrary(profile.library);
    const key = `${library}-${getAdultProfileMergeIdentity(profile)}`;
    const existing = byKey.get(key) || {};

    const existingBirthday = getProfileBirthdayValue(existing);
    const incomingBirthday = getProfileBirthdayValue(profile);
    const existingPoster = getPreferredProfilePosterField(existing);
    const incomingPoster = getPreferredProfilePosterField(profile);

    const merged = {
      ...existing,
      ...profile,
      library,
      // Keep the selected/profile poster path from the highest-priority source.
      // This prevents the birthday widget from falling back to a random gallery image.
      poster: existingPoster || incomingPoster || existing.poster || profile.poster || "",
      birthday: incomingBirthday || existingBirthday || profile.birthday || existing.birthday || "",
      metadata: {
        ...(existing.metadata || {}),
        ...(profile.metadata || {}),
        poster:
          existing.metadata?.poster ||
          existingPoster ||
          profile.metadata?.poster ||
          incomingPoster ||
          "",
        birthday:
          profile.metadata?.birthday ||
          incomingBirthday ||
          existing.metadata?.birthday ||
          existingBirthday ||
          "",
      },
      metadataCandidates: {
        ...(existing.metadataCandidates || {}),
        ...(profile.metadataCandidates || {}),
      },
    };

    byKey.set(key, merged);
  });

  return Array.from(byKey.values());
}

function getAdultProfileActivityKey(profile = {}) {
  const library = normalizeAdultProfileLibrary(profile.library || profile.libraryType || "personal");
  const id = profile.id || profile.slug || profile.folderName || getAdultProfileMergeIdentity(profile);
  return `${library}:${String(id || "").toLowerCase()}`;
}

function getAdultProfileLibraryLabel(profile = {}) {
  const library = normalizeAdultProfileLibrary(profile.library || profile.libraryType || "personal");
  if (library === "celebrities") return "Celebrity";
  if (library === "performers") return "Performer";
  return "Personal";
}

function normalizeAdultRecommendationValue(value) {
  const label = String(value || "")
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  const key = label.toLowerCase();
  if (!key || key.length > 64 || /^(true|false|null|undefined|unknown|n\/a|none)$/i.test(key)) return null;
  if (/^(?:https?:|\/|[a-z]:\\)/i.test(label) || /^\d+(?:\.\d+)?$/.test(key)) return null;
  return { key, label };
}

function flattenAdultRecommendationValues(value, output = []) {
  if (value === undefined || value === null || value === "") return output;

  if (Array.isArray(value)) {
    value.forEach((item) => flattenAdultRecommendationValues(item, output));
    return output;
  }

  if (typeof value === "object") {
    Object.entries(value).forEach(([key, item]) => {
      if (item === true) output.push(key);
      else if (typeof item !== "object" || Array.isArray(item)) flattenAdultRecommendationValues(item, output);
    });
    return output;
  }

  String(value)
    .split(/[,;|]+/)
    .map((item) => item.trim())
    .filter(Boolean)
    .forEach((item) => output.push(item));

  return output;
}

function getAdultProfileRecommendationSignals(profile = {}) {
  const metadata = profile.metadata || {};
  const candidates = profile.metadataCandidates || {};
  const values = [
    profile.tags,
    profile.categories,
    profile.genres,
    profile.collections,
    profile.interests,
    profile.niches,
    profile.specialties,
    profile.attributes,
    profile.studios,
    profile.bodyType,
    profile.bodyTypes,
    profile.breastType,
    profile.cupSize,
    profile.measurements,
    profile.hairColor,
    profile.eyeColor,
    profile.ethnicity,
    profile.nationality,
    metadata.tags,
    metadata.categories,
    metadata.genres,
    metadata.genre,
    metadata.collections,
    metadata.interests,
    metadata.niches,
    metadata.specialties,
    metadata.attributes,
    metadata.studios,
    metadata.bodyType,
    metadata.bodyTypes,
    metadata.bodyDetails,
    metadata.breastType,
    metadata.cupSize,
    metadata.measurements,
    metadata.height,
    metadata.weight,
    metadata.industry,
    metadata.industries,
    metadata.occupations,
    metadata.nationality,
    metadata.ethnicity,
    metadata.hairColor,
    metadata.eyeColor,
    candidates.tags,
    candidates.categories,
    candidates.genres,
    candidates.collections,
    candidates.interests,
    candidates.niches,
    candidates.specialties,
  ];

  const byKey = new Map();
  values.forEach((value) => {
    flattenAdultRecommendationValues(value).forEach((item) => {
      const normalized = normalizeAdultRecommendationValue(item);
      if (normalized && !byKey.has(normalized.key)) byKey.set(normalized.key, normalized);
    });
  });
  return Array.from(byKey.values());
}

function isAdultProfileFavorite(profile = {}) {
  const metadata = profile.metadata || {};
  return [
    profile.favorite,
    profile.isFavorite,
    profile.favourite,
    profile.starred,
    profile.pinned,
    metadata.favorite,
    metadata.isFavorite,
    metadata.favourite,
    metadata.starred,
    metadata.pinned,
  ].some((value) => value === true || value === 1 || String(value).toLowerCase() === "true");
}

function getAdultProfileLocalMediaCount(profile = {}) {
  const counts = profile.counts || {};
  const files = Array.isArray(profile.files) ? profile.files : [];
  const declared = Number(counts.total ?? profile.itemCount ?? profile.mediaCount);
  if (Number.isFinite(declared) && declared > 0) return declared;
  return files.length;
}

function getAdultProfileUpdateDetails(profile = {}) {
  const metadata = profile.metadata || {};
  const timestampCandidates = [
    [metadata.profileNotesUpdatedAt, "Notes updated"],
    [metadata.profileFactsUpdatedAt, "Profile details updated"],
    [metadata.manualMetadataEditedAt, "Metadata edited"],
    [metadata.metadataFetchedAt, "Metadata refreshed"],
    [metadata.lastMetadataFetchAt, "Metadata refreshed"],
    [metadata.updatedAt, "Metadata updated"],
    [profile.updatedAt, "Profile updated"],
    [profile.modifiedAt, "Profile updated"],
    [profile.createdAt, "Profile added"],
    [profile.addedAt, "Profile added"],
  ];

  (Array.isArray(profile.files) ? profile.files : []).forEach((file) => {
    const type = String(file?.type || "").toLowerCase();
    const label = type === "image" ? "Photo added" : type === "video" ? "Video added" : "Local media updated";
    timestampCandidates.push([file?.modifiedAt || file?.updatedAt || file?.createdAt, label]);
  });
  (Array.isArray(metadata.timeline) ? metadata.timeline : []).forEach((event) => {
    const changes = Array.isArray(event?.changes) ? event.changes : [];
    const compactChanges = changes.slice(0, 2).map((change) =>
      `${change.label || change.field}: ${formatHomesteadField(change.field, change.previous ?? change.previousLabel)} → ${formatHomesteadField(change.field, change.value ?? change.valueLabel)}`
    );
    const changeLabel = compactChanges.length
      ? `${compactChanges.join(" · ")}${changes.length > 2 ? ` · +${changes.length - 2} more` : ""}`
      : event?.title || "Timeline updated";
    timestampCandidates.push([event?.recordedAt || event?.updatedAt || event?.effectiveAt || event?.date, changeLabel]);
  });

  return timestampCandidates.reduce((latest, [rawTimestamp, label]) => {
    const timestamp = new Date(rawTimestamp || 0).getTime();
    if (!Number.isFinite(timestamp) || timestamp <= latest.timestamp) return latest;
    return { timestamp, label };
  }, { timestamp: 0, label: "Profile updated" });
}

function formatAdultProfileRelativeTime(timestamp) {
  if (!timestamp) return "";
  const elapsed = Math.max(0, Date.now() - timestamp);
  const minutes = Math.floor(elapsed / 60000);
  if (minutes < 1) return "Just now";
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  if (days < 30) return `${days}d ago`;
  const months = Math.floor(days / 30);
  if (months < 12) return `${months}mo ago`;
  return formatHomesteadDate(timestamp);
}

function getRecentlyUpdatedAdultProfiles(profiles = [], limit = 6) {
  return profiles
    .map((profile) => {
      const details = getAdultProfileUpdateDetails(profile);
      return {
        profile,
        activityLabel: details.label,
        timestamp: details.timestamp,
        whenLabel: formatAdultProfileRelativeTime(details.timestamp),
      };
    })
    .filter((item) => item.timestamp > 0)
    .sort((a, b) => b.timestamp - a.timestamp || String(a.profile?.name || "").localeCompare(String(b.profile?.name || "")))
    .slice(0, limit);
}

function getAdultRecommendationTieBreaker(profile = {}) {
  const value = `${getAdultProfileActivityKey(profile)}:${new Date().toISOString().slice(0, 10)}`;
  let hash = 0;
  for (let index = 0; index < value.length; index += 1) {
    hash = ((hash << 5) - hash + value.charCodeAt(index)) | 0;
  }
  return Math.abs(hash);
}

function buildAdultProfileRecommendations(profiles = [], library = "performers", recentActivity = [], limit = 6) {
  const normalizedLibrary = normalizeAdultProfileLibrary(library);
  const candidates = profiles.filter((profile) => normalizeAdultProfileLibrary(profile.library) === normalizedLibrary);
  if (!candidates.length) return [];

  const activityByKey = new Map(
    (Array.isArray(recentActivity) ? recentActivity : []).map((entry, index) => [
      `${normalizeAdultProfileLibrary(entry.library)}:${String(entry.profileId || entry.id || "").toLowerCase()}`,
      { ...entry, index },
    ])
  );
  const preferenceWeights = new Map();

  profiles.forEach((profile) => {
    const activity = activityByKey.get(getAdultProfileActivityKey(profile));
    const isPersonal = normalizeAdultProfileLibrary(profile.library) === "personal";
    const isFavorite = isAdultProfileFavorite(profile);
    if (!isPersonal && !isFavorite && !activity) return;

    const seedWeight = (isPersonal ? 2.5 : 0) + (isFavorite ? 5 : 0) + (activity ? Math.max(1, 4 - activity.index * 0.3) : 0);
    getAdultProfileRecommendationSignals(profile).forEach(({ key, label }) => {
      const current = preferenceWeights.get(key) || { weight: 0, label };
      preferenceWeights.set(key, { label: current.label || label, weight: current.weight + seedWeight });
    });
  });

  return candidates
    .map((profile) => {
      const signals = getAdultProfileRecommendationSignals(profile);
      const matchingSignals = signals
        .map((signal) => ({ ...signal, weight: preferenceWeights.get(signal.key)?.weight || 0 }))
        .filter((signal) => signal.weight > 0)
        .sort((a, b) => b.weight - a.weight || a.label.localeCompare(b.label));
      const sharedWeight = matchingSignals.reduce((total, signal) => total + signal.weight, 0);
      const mediaCount = getAdultProfileLocalMediaCount(profile);
      const updateTimestamp = getAdultProfileUpdateDetails(profile).timestamp;
      const ageInDays = updateTimestamp ? Math.max(0, (Date.now() - updateTimestamp) / 86400000) : Infinity;
      const recencyBonus = Number.isFinite(ageInDays) ? Math.max(0, 8 - Math.log2(ageInDays + 1) * 1.5) : 0;
      const activity = activityByKey.get(getAdultProfileActivityKey(profile));
      const favorite = isAdultProfileFavorite(profile);
      const hasPoster = Boolean(getProfilePosterValue(profile));
      const metadataRichness = Math.min(12, signals.length);
      const score =
        sharedWeight * 10 +
        Math.log2(mediaCount + 1) * 5 +
        metadataRichness * 1.2 +
        recencyBonus +
        (hasPoster ? 3 : 0) +
        (favorite ? 12 : 0) +
        (activity ? Math.max(0, 5 - activity.index * 0.4) : 0);

      let reason = "Saved in your local library";
      if (matchingSignals.length) {
        reason = `Matches ${matchingSignals.slice(0, 2).map((signal) => signal.label).join(" + ")}`;
      } else if (favorite) {
        reason = "Saved favorite";
      } else if (activity) {
        reason = "Based on recent profile activity";
      } else if (mediaCount > 0) {
        reason = `${mediaCount} local media item${mediaCount === 1 ? "" : "s"}`;
      } else if (metadataRichness > 0) {
        reason = "Rich local profile metadata";
      }

      const detail = mediaCount > 0
        ? `${mediaCount} local item${mediaCount === 1 ? "" : "s"}`
        : signals.length > 0
          ? `${signals.length} matching profile field${signals.length === 1 ? "" : "s"}`
          : getAdultProfileLibraryLabel(profile);

      return { profile, reason, detail, score, tieBreaker: getAdultRecommendationTieBreaker(profile) };
    })
    .sort((a, b) => b.score - a.score || a.tieBreaker - b.tieBreaker)
    .slice(0, limit);
}

function getAdultExternalRecommendationSignals(profiles = [], recentActivity = [], limit = 8) {
  const activityByKey = new Map(
    (Array.isArray(recentActivity) ? recentActivity : []).map((entry, index) => [
      `${normalizeAdultProfileLibrary(entry.library)}:${String(entry.profileId || entry.id || "").toLowerCase()}`,
      index,
    ])
  );
  const weights = new Map();

  profiles.forEach((profile) => {
    const activityIndex = activityByKey.get(getAdultProfileActivityKey(profile));
    const personal = normalizeAdultProfileLibrary(profile.library) === "personal";
    const favorite = isAdultProfileFavorite(profile);
    const seedWeight = (personal ? 4 : 0) + (favorite ? 8 : 0) + (activityIndex !== undefined ? Math.max(2, 7 - activityIndex * 0.45) : 0);
    if (seedWeight <= 0) return;
    getAdultProfileRecommendationSignals(profile).forEach((signal) => {
      weights.set(signal.label, (weights.get(signal.label) || 0) + seedWeight);
    });
  });

  return Array.from(weights.entries())
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, limit)
    .map(([label]) => label);
}

const DEFAULT_ADULT_RECOMMENDATION_PREFERENCES = {
  enabled: true, gender: "female", bodyTypes: ["petite"], breastShapes: ["perky"],
  heightCategories: ["short", "medium"], maxWeight: 125, pantySizeMax: "M",
  braBandMax: 36, cupSizeMax: "B", minAge: 18, maxAge: 35, requirePoster: true,
  ethnicityInclude: [], ethnicityExclude: [], includeUnknownEthnicity: true,
  matchMode: "strict",
};
const ADULT_RECOMMENDATION_ETHNICITIES = ["Asian", "Black", "Hispanic / Latino", "Middle Eastern", "Mixed", "Native / Indigenous", "Pacific Islander", "White"];

function normalizeAdultRecommendationPreferences(value = {}) {
  return {
    ...DEFAULT_ADULT_RECOMMENDATION_PREFERENCES,
    ...(value || {}),
    bodyTypes: Array.isArray(value?.bodyTypes) ? value.bodyTypes : DEFAULT_ADULT_RECOMMENDATION_PREFERENCES.bodyTypes,
    breastShapes: Array.isArray(value?.breastShapes) ? value.breastShapes : DEFAULT_ADULT_RECOMMENDATION_PREFERENCES.breastShapes,
    heightCategories: Array.isArray(value?.heightCategories) ? value.heightCategories : DEFAULT_ADULT_RECOMMENDATION_PREFERENCES.heightCategories,
    ethnicityInclude: Array.isArray(value?.ethnicityInclude) ? value.ethnicityInclude : [],
    ethnicityExclude: Array.isArray(value?.ethnicityExclude) ? value.ethnicityExclude : [],
    includeUnknownEthnicity: value?.includeUnknownEthnicity !== false,
    matchMode: value?.matchMode === "compatible" ? "compatible" : "strict",
  };
}

function adultRecommendationHeightLabel(item = {}) {
  const cm = Number(item.heightCm || 0);
  if (cm > 0) {
    const totalInches = Math.round(cm / 2.54);
    return `${Math.floor(totalInches / 12)}'${totalInches % 12}\"`;
  }
  return String(item.height || "").trim();
}

function adultRecommendationBodyFacts(item = {}) {
  const bra = [item.braBand, item.cupSize].filter((value) => value !== undefined && value !== null && String(value).trim()).join("");
  const measurements = String(item.measurements || "").trim();
  const height = adultRecommendationHeightLabel(item);
  const weight = Number(item.weightLb || 0) > 0 ? `${Math.round(Number(item.weightLb))} lb` : String(item.weight || "").trim();
  const dimensions = measurements || [item.bust, item.waist, item.hips].every((value) => Number(value) > 0)
    ? (measurements || `${item.bust}-${item.waist}-${item.hips}`)
    : "";
  return [
    height ? `Height ${height}` : "",
    weight ? `Weight ${weight}` : "",
    dimensions ? `Measurements ${dimensions}` : "",
    bra ? `Bra ${bra}` : "",
    item.pantySize ? `Panty ${item.pantySize}${item.pantySizeInferred ? " (estimated from hips)" : ""}` : "",
    item.bodyTypes?.length ? `Build ${item.bodyTypes.join(", ")}` : "",
    item.breastType ? `Breasts ${item.breastType}` : "",
  ].filter(Boolean);
}

function AdultRecommendationPosterGrid({ localItems = [], externalItems = [], setSelected, onOpenCandidate, emptyText = "No recommendations yet." }) {
  const combined = [
    ...externalItems.map((item) => ({ ...item, external: true })),
    ...localItems.map((item) => ({ ...item, external: false })),
  ].slice(0, 18);

  if (!combined.length) return <p className="adult-profile-feed-empty">{emptyText}</p>;

  return (
    <div className="adult-recommendation-poster-grid" tabIndex={0} aria-label="Profile cards" role="region">
      {combined.map((item, index) => {
        const profile = item.profile || item;
        const title = profile.name || profile.displayName || profile.title || profile.id || "Profile";
        const imageUrl = item.external ? item.imageUrl : "";
        const bodyFacts = item.external ? adultRecommendationBodyFacts(item) : [];
        const isPerformerRecommendation = item.external && /^performer/i.test(String(item.profileType || ""));
        return (
          <article
            key={`${item.external ? "external" : "local"}-${item.sourceId || getAdultProfileActivityKey(profile)}-${item.url || title}-${index}`}
            type="button"
            className="adult-recommendation-poster-card"
          >
            <button type="button" className="adult-recommendation-poster-main" onClick={() => item.external ? onOpenCandidate?.({ ...profile, ...item, name: title, title, url: item.url || item.sourceUrl, externalUrl: item.url || item.sourceUrl }) : setSelected?.(profile)}>
            <span className="adult-recommendation-poster-art">
              {imageUrl ? <img src={imageUrl} alt="" loading="lazy" referrerPolicy="no-referrer" /> : <AdultBirthdayPoster person={profile} />}
              <span className={`adult-recommendation-origin${item.external ? " external" : ""}`}>
                {item.external ? item.sourceName || "Source" : "In Homestead"}
              </span>
            </span>
            <span className="adult-recommendation-poster-copy">
              <strong>{title}</strong>
              {item.external && Number.isFinite(Number(item.matchScore)) && <b className="adult-recommendation-match-score">{item.matchScore}% match</b>}
              {(item.activityLabel || item.reason || item.detail || (item.external ? "External discovery" : "")) && (
                <small>{item.activityLabel || item.reason || item.detail || "External discovery"}</small>
              )}
              {item.whenLabel && <em className="adult-recommendation-when">{item.whenLabel}</em>}
              {isPerformerRecommendation && (
                <span className={`adult-recommendation-body${item.bodyMetadataStatus === "available" ? " available" : ""}`}>
                  {bodyFacts.length
                    ? bodyFacts.map((fact) => <i key={fact}>{fact}</i>)
                    : item.bodyMetadataEnriched
                      ? <i>Body metadata unavailable from enabled sources</i>
                      : <i>Loading body metadata…</i>}
                  {item.bodyMetadataSources?.length ? <i className="sources">From {item.bodyMetadataSources.join(" + ")}</i> : null}
                </span>
              )}
              {item.external && item.bodyMetadataEnriched && item.missingFields?.length > 0 && <em>Still missing: {item.missingFields.join(", ")}</em>}
            </span>
            </button>
            {item.external && (
              <span className="adult-recommendation-poster-actions">
                <button type="button" onClick={() => onOpenCandidate?.({ ...profile, ...item, name: title, title, url: item.url || item.sourceUrl, externalUrl: item.url || item.sourceUrl })}>+ Add profile</button>
                {(item.url || item.sourceUrl) && <button type="button" onClick={() => window.open(item.url || item.sourceUrl, "_blank", "noopener,noreferrer")}>View source</button>}
              </span>
            )}
          </article>
        );
      })}
    </div>
  );
}

function AdultProfileFeedList({ items = [], setSelected, emptyText = "No matching profiles yet." }) {
  if (!items.length) return <p className="adult-profile-feed-empty">{emptyText}</p>;

  return (
    <div className="adult-profile-feed-list">
      {items.map((item) => {
        const profile = item.profile || item;
        const title = profile.name || profile.displayName || profile.title || profile.id || "Profile";
        return (
          <button
            key={`${getAdultProfileActivityKey(profile)}-${item.timestamp || item.reason || "profile"}`}
            type="button"
            className="adult-profile-feed-row"
            onClick={() => setSelected?.(profile)}
          >
            <AdultBirthdayPoster person={profile} className="adult-profile-feed-poster" />
            <span className="adult-profile-feed-copy">
              <strong>{title}</strong>
              <small>{item.reason || item.activityLabel || "Local profile"}</small>
              {(item.detail || item.whenLabel) ? <em>{item.detail || item.whenLabel}</em> : null}
            </span>
            <span className="adult-profile-feed-type">{getAdultProfileLibraryLabel(profile)}</span>
          </button>
        );
      })}
    </div>
  );
}

function AdultUpcomingBirthdaysPanel({ profiles = [], setSelected }) {
  const upcomingBirthdays = getUpcomingAdultBirthdays(profiles, 7);

  return (
    <section className="panel hub-feed-panel adult-birthday-panel">
      <div className="section-header-row">
        <div>
          <h3>Upcoming Birthdays</h3>
          <p>Adult profiles with birthdays in the next 7 days.</p>
        </div>
      </div>

      <AdultRecommendationPosterGrid
        localItems={upcomingBirthdays.map((person) => ({
          profile: person,
          reason: `${person.birthdayLabel} · ${person.daysUntilBirthday === 0 ? "today" : `${person.daysUntilBirthday} day${person.daysUntilBirthday === 1 ? "" : "s"}`}${person.turningAge !== null ? ` · turns ${person.turningAge}` : ""}`,
        }))}
        setSelected={setSelected}
        emptyText="No adult profile birthdays in the next 7 days."
      />
    </section>
  );
}

function AdultHubPage({
  personalCount = 0,
  performerCount = 0,
  celebrityCount = 0,
  setActiveLibrary,
  adultConfig = {},
  people = [],
  performers = [],
  celebrities = [],
  setSelected,
  mediaIndex = null,
  recentProfileActivity = [],
  recentMediaActivity = [],
  onOpenCandidate,
  accountPreferences = {},
}) {
  const [externalRecommendations, setExternalRecommendations] = useState({ celebrities: [], performers: [] });
  const [externalRecommendationDiagnostics, setExternalRecommendationDiagnostics] = useState({ celebrities: [], performers: [] });
  const [externalRecommendationStatus, setExternalRecommendationStatus] = useState({ celebrities: "loading", performers: "loading" });
  const [recommendationRefresh, setRecommendationRefresh] = useState(0);
  const recommendationPreferences = normalizeAdultRecommendationPreferences(accountPreferences?.adultRecommendations || {});
  const adultProfiles = mergeAdultProfileSources(
    collectAdultIndexProfiles(mediaIndex),
    [
    ...people.map((person) => ({
      ...person,
      library: person.library === "girls" ? "personal" : (person.library || "personal"),
    })),
    ...performers.map((person) => ({ ...person, library: "performers" })),
    ...celebrities.map((person) => ({ ...person, library: "celebrities" })),
    ]
  );
  const recentlyUpdatedProfiles = getRecentlyUpdatedAdultProfiles(adultProfiles, 6);
  const existingAdultNames = adultProfiles
    .map((profile) => profile.name || profile.displayName || profile.title || "")
    .filter(Boolean);

  useEffect(() => {
    let cancelled = false;
    const controller = new AbortController();
    if (!recommendationPreferences.enabled) {
      setExternalRecommendations({ celebrities: [], performers: [] });
      setExternalRecommendationDiagnostics({ celebrities: [], performers: [] });
      setExternalRecommendationStatus({ celebrities: "empty", performers: "empty" });
      return () => { cancelled = true; };
    }

    setExternalRecommendations({ celebrities: [], performers: [] });
    setExternalRecommendationDiagnostics({ celebrities: [], performers: [] });
    setExternalRecommendationStatus({ celebrities: "loading", performers: "loading" });
    const load = async (profileType, lane) => {
      try {
      const response = await fetch("/api/discovery/adult/recommendations", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        signal: controller.signal,
        body: JSON.stringify({ profileType, signals: [], preferences: recommendationPreferences, existingNames: existingAdultNames, activities: [] }),
      });
      if (!response.ok) throw new Error(`Recommendation source returned HTTP ${response.status}`);
      const result = await response.json();
        if (cancelled) return;
      const initialItems = Array.isArray(result?.items) ? result.items : [];
      setExternalRecommendations((current) => ({ ...current, [lane]: initialItems }));
      setExternalRecommendationDiagnostics((current) => ({ ...current, [lane]: result?.diagnostics || [] }));
      setExternalRecommendationStatus((current) => ({ ...current, [lane]: "ready" }));
      if (lane === "performers" && initialItems.length) {
        try {
          const enrichmentResponse = await fetch("/api/discovery/adult/recommendations/enrich-bodies", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            signal: controller.signal,
            body: JSON.stringify({ items: initialItems }),
          });
          if (enrichmentResponse.ok) {
            const enriched = await enrichmentResponse.json();
            if (!cancelled && Array.isArray(enriched?.items)) {
              setExternalRecommendations((current) => ({ ...current, [lane]: enriched.items }));
            }
          }
        } catch {
          // Keep the discovery cards visible when supplemental body providers time out.
        }
      }
      } catch (error) {
        if (cancelled) return;
        // A slow lane must not erase the other lane or previously displayed cards.
        setExternalRecommendationStatus((current) => ({ ...current, [lane]: "error" }));
        setExternalRecommendationDiagnostics((current) => ({ ...current, [lane]: [{ ok: false, providerName: "Recommendations", message: "Temporarily unavailable. Try again shortly." }] }));
      }
    };
    load("celebrity", "celebrities");
    load("performer", "performers");

    return () => { cancelled = true; controller.abort(); };
  }, [JSON.stringify(recommendationPreferences), existingAdultNames.join("|"), recommendationRefresh]);

  const adultSublibraries = adultConfig?.adultSublibraries || {};
  const recommendationEmptyText = (profileType) => {
    if (externalRecommendationStatus[profileType] === "loading") return `Checking configured ${profileType} providers using your saved filters…`;
    if (externalRecommendationStatus[profileType] === "error") return `The ${profileType} recommendation service is temporarily unavailable. The other row is still independent.`;
    if (!recommendationPreferences.enabled) return "Recommendations are disabled in your Adult library settings.";
    const diagnostics = externalRecommendationDiagnostics[profileType] || [];
    if (!diagnostics.length) return `No structured ${profileType === "celebrities" ? "Celebrity" : "Performer"} provider is configured. Add one in your account's Recommendation data providers panel.`;
    const failed = diagnostics.filter((item) => !item.ok);
    if (failed.length === diagnostics.length) return failed.map((item) => `${item.providerName}: ${item.message}`).join(" · ");
    return recommendationPreferences.matchMode === "strict" ? "No exact matches were found. A selected filter may use a field your provider does not supply; check provider coverage or enable compatible partial matches." : "No compatible profiles matched the values your providers supplied.";
  };
  const adultTabs = [
    { id: "adultBrowse", icon: "🧭", title: "Browse", visible: true },
    {
      id: "adultTV",
      icon: "📺",
      title: "TV Channels",
      visible:
        !!adultConfig?.enabledLibraries?.liveTV &&
        !!adultSublibraries.adultTVChannels,
    },
    { id: "personal", icon: "🗂️", title: "Personal", visible: adultSublibraries.personalProfiles !== false },
    { id: "performers", icon: "🎭", title: "Performers", visible: adultSublibraries.performers !== false },
    { id: "celebrities", icon: "⭐", title: "Celebs", visible: adultSublibraries.celebrities !== false },
    { id: "adultPhotos", icon: "🖼️", title: "Photos", visible: (adultSublibraries.adultPhotos ?? adultSublibraries.photos) !== false },
    { id: "adultVideos", icon: "🎞️", title: "Videos", visible: (adultSublibraries.adultVideos ?? adultSublibraries.videos ?? adultSublibraries.scenes) !== false },
  ].filter((item) => item.visible);

  return (
    <div className="generic-page hub-page adult-hub-page">
      <AdultSectionTabs activeLibrary="adult" setActiveLibrary={setActiveLibrary} setupConfig={{ adultSublibraries: adultConfig?.adultSublibraries || {} }} />

      <section className="mobile-adult-directory panel">
        <div className="mobile-directory-grid mobile-icon-tab-grid">
          {adultTabs.map((item) => (
            <button
              key={item.id}
              type="button"
              className="mobile-directory-card mobile-icon-tab-card"
              onClick={() => {
                if (setActiveLibrary) setActiveLibrary(item.id);
                window.scrollTo({ top: 0, behavior: "smooth" });
              }}
            >
              <span className="mobile-directory-icon">{item.icon}</span>
              <span className="mobile-directory-copy">
                <strong>{item.title}</strong>
              </span>
            </button>
          ))}
        </div>
      </section>

      <div className="hub-two-column-row">
        <section className="panel hub-feed-panel">
          <div className="section-header-row adult-profile-feed-heading">
            <div>
              <h3>Recently Updated Profiles</h3>
              <p>New media, metadata, and profile changes from your local Adult library.</p>
            </div>
          </div>
          <AdultRecommendationPosterGrid
            localItems={recentlyUpdatedProfiles}
            setSelected={setSelected}
            emptyText="Add or update an Adult profile and it will appear here."
          />
        </section>

        <AdultUpcomingBirthdaysPanel profiles={adultProfiles} setSelected={setSelected} />
      </div>

      <div className="adult-recommendation-rows">
        <section className="panel hub-feed-panel">
          <div className="section-header-row adult-profile-feed-heading">
            <div>
              <h3>You May Like: Performers</h3>
              <p>People not in your library who match your saved Adult recommendation preferences.</p>
            </div>
            <button type="button" className="secondary-button" onClick={() => setRecommendationRefresh((value) => value + 1)}>↻ Refresh</button>
          </div>
          {externalRecommendations.performers.length > 0 && externalRecommendationDiagnostics.performers.some((entry) => !entry.ok || entry.partial || entry.stale) && <p className="small-muted" role="status">{externalRecommendationDiagnostics.performers.filter((entry) => !entry.ok || entry.partial || entry.stale).map((entry) => entry.message).filter(Boolean).join(" · ")}</p>}
          <AdultRecommendationPosterGrid
            externalItems={externalRecommendations.performers}
            setSelected={setSelected}
            onOpenCandidate={onOpenCandidate}
            emptyText={recommendationEmptyText("performers")}
          />
        </section>

        <section className="panel hub-feed-panel">
          <div className="section-header-row adult-profile-feed-heading">
            <div>
              <h3>You May Like: Celebrities</h3>
              <p>People not in your library who match your saved Adult recommendation preferences.</p>
            </div>
            <button type="button" className="secondary-button" onClick={() => setRecommendationRefresh((value) => value + 1)}>↻ Refresh</button>
          </div>
          {externalRecommendations.celebrities.length > 0 && externalRecommendationDiagnostics.celebrities.some((entry) => !entry.ok || entry.partial || entry.stale) && <p className="small-muted" role="status">{externalRecommendationDiagnostics.celebrities.filter((entry) => !entry.ok || entry.partial || entry.stale).map((entry) => entry.message).filter(Boolean).join(" · ")}</p>}
          <AdultRecommendationPosterGrid
            externalItems={externalRecommendations.celebrities}
            setSelected={setSelected}
            onOpenCandidate={onOpenCandidate}
            emptyText={recommendationEmptyText("celebrities")}
          />
        </section>
      </div>
    </div>
  );
}


const LIBRARY_IMPORT_TARGETS = {
  movies: { key: "movies", label: "Movies" },
  tv: { key: "tvshows", label: "TV Shows" },
  music: { key: "music", label: "Music" },
  books: { key: "books", label: "Books" },
  youtube: { key: "youtube", label: "YouTube" },
  photos: { key: "photos", label: "Photos" },
  family: { key: "family", label: "Family" },
  inventory: { key: "inventory", label: "Inventory" },
  cloud: { key: "cloud", label: "Cloud" },
  adultPhotos: { key: "adultPhotos", label: "Adult Photos" },
  adultVideos: { key: "adultVideos", label: "Adult Videos" },
};

function LibraryImportModal({ activeLibrary, setupConfig, onClose }) {
  const target = LIBRARY_IMPORT_TARGETS[activeLibrary];
  const mappingValue = target ? setupConfig?.folderMappings?.[target.key] : null;
  const directRoots = (Array.isArray(mappingValue) ? mappingValue : mappingValue ? [mappingValue] : []).filter(Boolean);
  const adultRootValue = setupConfig?.folderMappings?.adult;
  const adultRoots = (Array.isArray(adultRootValue) ? adultRootValue : adultRootValue ? [adultRootValue] : []).filter(Boolean);
  const adultDerivedRoots = target?.key === "adultPhotos"
    ? adultRoots.map((root) => `${String(root).replace(/\\/g, "/").replace(/\/$/, "")}/photos`)
    : target?.key === "adultVideos"
      ? adultRoots.map((root) => `${String(root).replace(/\\/g, "/").replace(/\/$/, "")}/videos`)
      : [];
  const defaultAdultRoot = target?.key === "adultPhotos"
    ? "/media/adult/photos"
    : target?.key === "adultVideos"
      ? "/media/adult/videos"
      : "";
  const roots = [...new Set([...directRoots, ...adultDerivedRoots, defaultAdultRoot].filter(Boolean))];
  const [rootPath, setRootPath] = useState(roots[0] || "");
  const [subfolder, setSubfolder] = useState("");
  const [files, setFiles] = useState([]);
  const [status, setStatus] = useState("");
  const [busy, setBusy] = useState(false);
  const inputRef = useRef(null);

  useEffect(() => {
    setRootPath(roots[0] || "");
    setSubfolder("");
    setFiles([]);
    setStatus("");
  }, [activeLibrary]);

  if (!target) return null;

  async function createFolderOnly() {
    if (!subfolder.trim()) {
      setStatus("Enter a subfolder name first.");
      return;
    }
    setBusy(true);
    setStatus("Creating subfolder…");
    try {
      const response = await fetch("/api/library/import-folder", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ library: target.key, rootPath, subfolder }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data.ok) throw new Error(data.error || "Unable to create subfolder.");
      setStatus(`Created ${data.relativePath || subfolder}.`);
    } catch (error) {
      setStatus(error.message || "Unable to create subfolder.");
    } finally {
      setBusy(false);
    }
  }

  async function uploadSelectedFiles() {
    if (!files.length) {
      setStatus("Choose one or more files from this device first.");
      return;
    }
    setBusy(true);
    try {
      for (let index = 0; index < files.length; index += 1) {
        const file = files[index];
        setStatus(`Uploading ${index + 1} of ${files.length}: ${file.name}`);
        const query = new URLSearchParams({
          library: target.key,
          rootPath,
          subfolder,
          fileName: file.name,
        });
        const response = await fetch(`/api/library/import-file?${query.toString()}`, {
          method: "POST",
          headers: { "Content-Type": "application/octet-stream" },
          body: file,
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok || !data.ok) throw new Error(data.error || `Unable to upload ${file.name}.`);
      }
      setStatus(`${files.length} file(s) imported into ${target.label}.`);
      setFiles([]);
      if (inputRef.current) inputRef.current.value = "";
    } catch (error) {
      setStatus(error.message || "Unable to import files.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="library-import-overlay" role="dialog" aria-modal="true" aria-label={`Add media to ${target.label}`}>
      <button className="library-import-backdrop" type="button" aria-label="Close import" onClick={onClose} />
      <section className="library-import-card">
        <header className="library-import-header">
          <div>
            <p className="eyebrow">Library Import</p>
            <h2>Add to {target.label}</h2>
            <p>Upload directly to this library root or create a subfolder first.</p>
          </div>
          <button className="secondary-button" type="button" onClick={onClose}>Close</button>
        </header>

        {roots.length > 1 && (
          <label className="settings-field">
            Library folder
            <select value={rootPath} onChange={(event) => setRootPath(event.target.value)}>
              {roots.map((root) => <option key={root} value={root}>{root}</option>)}
            </select>
          </label>
        )}

        <div className="library-import-destination">
          <strong>Destination root</strong>
          <code>{rootPath || `No ${target.label} folder is configured yet.`}</code>
        </div>

        <label className="settings-field">
          Optional subfolder
          <input value={subfolder} onChange={(event) => setSubfolder(event.target.value)} placeholder="Example: Christmas, Season 01, New Album…" />
        </label>

        <div className="library-import-folder-actions">
          <button className="secondary-button" type="button" onClick={createFolderOnly} disabled={busy || !rootPath}>Create Empty Subfolder</button>
        </div>

        <label className="library-import-dropzone">
          <input ref={inputRef} type="file" multiple onChange={(event) => setFiles(Array.from(event.target.files || []))} />
          <span>Browse this device</span>
          <small>{files.length ? `${files.length} file(s) selected` : "Choose one or more files to upload."}</small>
        </label>

        {status && <p className="library-import-status">{status}</p>}

        <footer className="library-import-actions">
          <button className="secondary-button" type="button" onClick={onClose} disabled={busy}>Cancel</button>
          <button className="primary-button" type="button" onClick={uploadSelectedFiles} disabled={busy || !rootPath || !files.length}>
            {busy ? "Importing…" : "Import Files"}
          </button>
        </footer>
      </section>
    </div>
  );
}

function AdultMediaSortingPage({
  type,
  setActiveLibrary,
  setupConfig,
  mediaIndex,
  openImageViewer,
  setNavBackAction,
  setNavBackLabel,
  setContextHeaderStats,
  setSuppressGlobalImport,
  appearance = {}, albumId = "", onAlbumChange, onAlbumsChange,
}) {
  const [selectedItem, setSelectedItem] = useState(null);
  const [showAddMedia, setShowAddMedia] = useState(false);
  const [newFolderName, setNewFolderName] = useState("");
  const [deviceFiles, setDeviceFiles] = useState([]);
  const [addMediaStatus, setAddMediaStatus] = useState("");
  const [addingMedia, setAddingMedia] = useState(false);
  const [directAlbums, setDirectAlbums] = useState([]);
  const [moveMenuOpen, setMoveMenuOpen] = useState(false);
  const deviceInputRef = useRef(null);

  const isVideo = type === "videos";
  const activeTab = isVideo ? "adultVideos" : "adultPhotos";
  const libraryKey = isVideo ? "adultVideos" : "adultPhotos";
  const itemLabel = isVideo ? "video" : "photo";
  const allowedType = isVideo ? "video" : "image";

  useEffect(() => {
    let cancelled = false;

    async function loadAdultMediaFoldersDirectly() {
      try {
        const response = await fetch(`/api/adult/media-folders?library=${encodeURIComponent(libraryKey)}`, { cache: "no-store" });
        const data = await response.json().catch(() => ({}));
        if (!cancelled) {
          setDirectAlbums(response.ok && Array.isArray(data.folders) ? data.folders : []);
        }
      } catch {
        if (!cancelled) setDirectAlbums([]);
      }
    }

    loadAdultMediaFoldersDirectly();
    return () => { cancelled = true; };
  }, [libraryKey]);

  const rawAlbums = useMemo(() => {
    const primary = Object.values(mediaIndex?.libraries?.[libraryKey] || {});

    // Older scans sometimes placed Adult Photos in the general Photos bucket. Search
    // both buckets, then enforce the configured Adult root below. This restores valid
    // private folders without allowing normal Photos to leak into Adult.
    const legacy = isVideo
      ? Object.values(mediaIndex?.libraries?.videos || {})
      : Object.values(mediaIndex?.libraries?.photos || {});

    const seen = new Set();
    return [...directAlbums, ...primary, ...legacy].filter((album) => {
      const key = String(
        album?.sourcePath ||
        album?.folderPath ||
        album?.path ||
        album?.id ||
        album?.title ||
        album?.name ||
        ""
      ).toLowerCase();
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }, [directAlbums, mediaIndex, libraryKey, isVideo]);

  function normalizeAdultImportPath(value = "") {
    let normalized = String(value || "").trim();
    if (!normalized) return "";

    try { normalized = decodeURIComponent(normalized); } catch {}

    normalized = normalized
      .replace(/^file:\/\//i, "")
      .replace(/^\/api\/file\?path=/i, "")
      .replace(/\\/g, "/")
      .replace(/\/{2,}/g, "/")
      .replace(/\/$/, "")
      .toLowerCase();

    return normalized;
  }

  const configuredRoots = useMemo(() => {
    const mapped = setupConfig?.folderMappings?.[libraryKey];
    const values = Array.isArray(mapped) ? mapped : mapped ? [mapped] : [];
    const fallback = isVideo ? "/media/adult/videos" : "/media/adult/photos";
    return [...new Set([...values, fallback].map(normalizeAdultImportPath).filter(Boolean))];
  }, [setupConfig, libraryKey, isVideo]);

  function getAdultImportAlbumPaths(album) {
    const values = [
      album?.sourcePath,
      album?.path,
      album?.folder,
      album?.folderPath,
      album?.root,
      album?.basePath,
      album?.publicPath,
      ...(Array.isArray(album?.files) ? album.files : []).flatMap((file) =>
        typeof file === "string"
          ? [file]
          : [
              file?.sourcePath,
              file?.path,
              file?.folder,
              file?.folderPath,
              file?.publicPath,
              file?.file?.sourcePath,
              file?.file?.path,
            ]
      ),
    ];

    return [...new Set(values.map(normalizeAdultImportPath).filter(Boolean))];
  }

  function pathIsInsideAdultRoot(candidate, root) {
    if (!candidate || !root) return false;
    return candidate === root || candidate.startsWith(`${root}/`);
  }

  function isAdultImportAlbum(album) {
    const paths = getAdultImportAlbumPaths(album);
    if (!paths.length) return false;

    return configuredRoots.some((root) =>
      paths.some((candidate) => pathIsInsideAdultRoot(candidate, root))
    );
  }

  const albums = useMemo(() => rawAlbums.filter(isAdultImportAlbum).map((album) => ({ ...album, id: album.id || album.sourcePath || album.folderPath || album.path, name: album.name || album.title || "Album" })), [rawAlbums, configuredRoots]);
  const selectedAlbum = !isVideo ? albums.find((album) => String(album.id) === albumId) : null;
  const setSelectedAlbum = (album) => onAlbumChange?.(album ? String(album.id) : "");
  useEffect(() => { if (!isVideo) onAlbumsChange?.(albums); }, [albums, isVideo, onAlbumsChange]);
  
  const flatVideos = isVideo
  ? albums.flatMap((album) => album.files || [])
      .filter((file) => file.type === "video")
  : [];

  function fileUrl(file) {
    const filePath = file?.sourcePath || file?.path || file?.publicPath || file?.url || "";
    return `/api/file?path=${encodeURIComponent(filePath)}`;
  }

  function defaultImportFolderName() {
    const now = new Date();
    return `Import ${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;
  }

  async function readFileAsBase64(file) {
    const buffer = await file.arrayBuffer();
    const bytes = new Uint8Array(buffer);
    let binary = "";
    const chunk = 0x8000;
    for (let index = 0; index < bytes.length; index += chunk) {
      binary += String.fromCharCode(...bytes.subarray(index, index + chunk));
    }
    return btoa(binary);
  }

  async function createAdultImportFolder({ uploadFiles = true } = {}) {
    const folderName = String(newFolderName || defaultImportFolderName()).trim();
    if (!folderName) return;

    if (uploadFiles && !deviceFiles.length) {
      setAddMediaStatus("Choose one or more files from this device first.");
      return;
    }

    setAddingMedia(true);
    setAddMediaStatus(uploadFiles ? "Creating folder and importing files…" : "Creating folder…");

    try {
      const createResponse = await fetch("/api/adult/media-folders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ library: libraryKey, folderName }),
      });
      const createData = await createResponse.json().catch(() => ({}));
      if (!createResponse.ok || !createData.ok) {
        throw new Error(createData.error || createData.message || "Unable to create the folder.");
      }

      if (uploadFiles) {
        for (let index = 0; index < deviceFiles.length; index += 1) {
          const file = deviceFiles[index];
          setAddMediaStatus(`Importing ${index + 1} of ${deviceFiles.length}: ${file.name}`);
          const base64 = await readFileAsBase64(file);
          const uploadResponse = await fetch("/api/adult/media-upload", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              library: libraryKey,
              folderName,
              fileName: file.name,
              mimeType: file.type,
              base64,
            }),
          });
          const uploadData = await uploadResponse.json().catch(() => ({}));
          if (!uploadResponse.ok || !uploadData.ok) {
            throw new Error(uploadData.error || uploadData.message || `Unable to import ${file.name}.`);
          }
        }
      }

      setAddMediaStatus(uploadFiles ? `${deviceFiles.length} file(s) imported.` : "Folder created.");
      setDeviceFiles([]);
      setNewFolderName("");
      if (deviceInputRef.current) deviceInputRef.current.value = "";
      window.setTimeout(() => window.location.reload(), 450);
    } catch (error) {
      setAddMediaStatus(error.message || "Unable to add media.");
    } finally {
      setAddingMedia(false);
    }
  }

useEffect(() => {
  if (!selectedAlbum) {
    setNavBackAction?.(null);
    setNavBackLabel?.("Back");
    setContextHeaderStats?.(null);
    setSuppressGlobalImport?.(false);
    return undefined;
  }

  const selectedItems = (selectedAlbum.files || []).filter((file) => file.type === allowedType);
  setNavBackAction?.(() => () => setSelectedAlbum(null));
  setNavBackLabel?.("Back to Albums");
  setContextHeaderStats?.([`${selectedItems.length} ${itemLabel}${selectedItems.length === 1 ? "" : "s"}`]);
  setSuppressGlobalImport?.(true);

  return () => {
    setNavBackAction?.(null);
    setNavBackLabel?.("Back");
    setContextHeaderStats?.(null);
    setSuppressGlobalImport?.(false);
  };
}, [selectedAlbum, allowedType, itemLabel, setNavBackAction, setNavBackLabel, setContextHeaderStats, setSuppressGlobalImport]);

async function moveToProfile(item, targetLibrary) {
  const profileName = prompt(
    `Move to which ${targetLibrary} profile folder name?`
  );

  if (!profileName?.trim()) return;

  const endpoint = isVideo
    ? "/api/adult/videos/move-to-profile"
    : "/api/adult/photos/move-to-profile";

  const response = await fetch(endpoint, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      sourcePath: item.sourcePath,
      targetLibrary,
      profileName: profileName.trim(),
    }),
  });

  const result = await response.json();

  if (!result.ok) {
    alert(result.error || "Move failed");
    return;
  }

  alert("Moved successfully.");
  window.location.reload();
}


  const addMediaModal = showAddMedia ? (
        <div className="adult-loose-media-modal" role="dialog" aria-modal="true" aria-label={`Add adult ${itemLabel}s`}>
          <button className="adult-loose-media-backdrop" type="button" aria-label="Close" onClick={() => !addingMedia && setShowAddMedia(false)} />
          <div className="adult-loose-media-card">
            <div className="adult-loose-media-header">
              <div>
                <p className="eyebrow">Adult {isVideo ? "Videos" : "Photos"}</p>
                <h2>Add Media Folder</h2>
                <p>Create a private sorting folder and import files directly from this device.</p>
              </div>
              <button className="secondary-button" type="button" disabled={addingMedia} onClick={() => setShowAddMedia(false)}>✕</button>
            </div>

            <label className="adult-loose-media-field">
              <span>New folder name</span>
              <input
                value={newFolderName}
                onChange={(event) => setNewFolderName(event.target.value)}
                placeholder={defaultImportFolderName()}
              />
            </label>

            <label className="adult-device-file-picker">
              <input
                ref={deviceInputRef}
                type="file"
                multiple
                accept={isVideo ? "video/*" : "image/*,.heic,.heif"}
                onChange={(event) => setDeviceFiles(Array.from(event.target.files || []))}
              />
              <span className="adult-device-file-picker-icon">{isVideo ? "🎞️" : "🖼️"}</span>
              <strong>Browse This Device</strong>
              <small>{deviceFiles.length ? `${deviceFiles.length} file(s) selected` : `Choose ${itemLabel}s to copy into the new folder`}</small>
            </label>

            {deviceFiles.length > 0 && (
              <div className="adult-device-file-list">
                {deviceFiles.slice(0, 8).map((file) => <span key={`${file.name}-${file.size}`}>{file.name}</span>)}
                {deviceFiles.length > 8 && <span>＋ {deviceFiles.length - 8} more</span>}
              </div>
            )}

            {addMediaStatus && <div className="adult-loose-media-status">{addMediaStatus}</div>}

            <div className="adult-loose-media-actions">
              <button className="secondary-button" type="button" disabled={addingMedia} onClick={() => createAdultImportFolder({ uploadFiles: false })}>
                Create Empty Folder
              </button>
              <button className="primary-button" type="button" disabled={addingMedia || !deviceFiles.length} onClick={() => createAdultImportFolder({ uploadFiles: true })}>
                {addingMedia ? "Adding…" : `Create Folder & Import ${deviceFiles.length || "Media"}`}
              </button>
            </div>
          </div>
        </div>
      
  ) : null;

  if (!isVideo) return <div className="generic-page adult-photos-library">
    <AdultSectionTabs activeLibrary={activeTab} setActiveLibrary={setActiveLibrary} setupConfig={setupConfig} />
    {selectedAlbum && <div className="adult-photo-album-actions">
      <button className="secondary-button" type="button" onClick={() => { setNewFolderName(selectedAlbum.title || selectedAlbum.name || ""); setShowAddMedia(true); }}>＋ Add Media</button>
      <div className="adult-album-move-menu-wrap">
        <button className="secondary-button" type="button" aria-expanded={moveMenuOpen} onClick={() => setMoveMenuOpen((open) => !open)}>Move To ▾</button>
        {moveMenuOpen && <div className="adult-album-move-menu">{["personal", "performers", "celebrities"].map((target) => <button key={target} type="button" onClick={() => { setMoveMenuOpen(false); moveToProfile(selectedAlbum, target); }}>{target === "personal" ? "Personal" : target === "performers" ? "Performer" : "Celebrity"}</button>)}</div>}
      </div>
    </div>}
    <PhotosPage mediaIndex={{ libraries: { adultPhotos: Object.fromEntries(albums.map((album) => [album.id, album])) } }} libraryKey="adultPhotos" appearance={appearance} albumId={albumId} onAlbumChange={onAlbumChange} openImageViewer={openImageViewer} />
    {addMediaModal}
  </div>;

  return <div className="generic-page adult-videos-library">
    <AdultSectionTabs activeLibrary={activeTab} setActiveLibrary={setActiveLibrary} setupConfig={setupConfig} />
    <div className="adult-video-grid">{flatVideos.map((video) => <AdultVideoCard key={video.sourcePath || video.path || video.id} video={video} onClick={setSelectedItem} />)}</div>
    {!flatVideos.length && <p>No adult videos found. Add media to your mapped Adult Videos folder and rescan.</p>}
    {addMediaModal}
    {selectedItem && createPortal(<div className="image-viewer-overlay" role="dialog" aria-modal="true" aria-label={parseVideoDisplay(selectedItem).displayTitle} onClick={() => setSelectedItem(null)}>
      <div className="image-viewer-content" onClick={(event) => event.stopPropagation()}>
        <button className="secondary-button image-viewer-close" type="button" onClick={() => setSelectedItem(null)}>✕ Close</button>
        <video src={fileUrl(selectedItem)} controls autoPlay playsInline />
        <h3>{parseVideoDisplay(selectedItem).displayTitle}</h3>
        <div className="button-row">{["personal", "performers", "celebrities"].map((target) => <button className="secondary-button" type="button" key={target} onClick={() => moveToProfile(selectedItem, target)}>Move to {target}</button>)}</div>
      </div>
    </div>, document.body)}
  </div>;
}

function parseAdultPantySize(value = "", explicitSystem = "") {
  const sizeRank = new Map([
    ["xxxxs", 0], ["xxxs", 1], ["xxs", 2], ["xs", 3],
    ["s", 4], ["m", 5], ["l", 6], ["xl", 7], ["xxl", 8], ["xxxl", 9], ["xxxxl", 10],
  ]);
  const normalized = String(value || "").trim().toLowerCase().replace(/\s+/g, " ");
  const systemText = `${explicitSystem || ""} ${normalized}`.toLowerCase();
  const system = /\b(?:junior|juniors|youth)\b/.test(systemText) ? "juniors" : "adult";
  const alpha = normalized.match(/(?:^|\s)(xxxxs|xxxs|xxs|xs|s|m|l|xl|xxl|xxxl|xxxxl)(?:\b|\/)/)?.[1] || "";
  const numeric = Number(normalized.match(/(?:us\s*)?(\d+(?:\.\d+)?)(?:\s*$|\s*\/)/)?.[1]);
  return {
    normalized,
    system,
    alpha,
    rank: alpha && sizeRank.has(alpha) ? sizeRank.get(alpha) : Number.POSITIVE_INFINITY,
    numeric: Number.isFinite(numeric) ? numeric : Number.POSITIVE_INFINITY,
  };
}

function compareAdultPantySizes(leftValue = "", rightValue = "", leftSystem = "", rightSystem = "") {
  const sizeRank = new Map([
    ["xxxxs", 0], ["xxxs", 1], ["xxs", 2], ["xs", 3],
    ["s", 4], ["m", 5], ["l", 6], ["xl", 7], ["xxl", 8], ["xxxl", 9], ["xxxxl", 10],
  ]);
  const parse = (value, explicitSystem) => {
    const normalized = String(value || "").trim().toLowerCase().replace(/\s+/g, " ");
    const alpha = normalized.match(/(?:^|\s)(xxxxs|xxxs|xxs|xs|s|m|l|xl|xxl|xxxl|xxxxl)(?:\b|\/)/)?.[1] || "";
    const numeric = Number(normalized.match(/(?:us\s*)?(\d+(?:\.\d+)?)(?:\s*$|\s*\/)/)?.[1]);
    return {
      normalized,
      system: /\b(?:junior|juniors|youth)\b/.test(`${explicitSystem || ""} ${normalized}`.toLowerCase()) ? "juniors" : "adult",
      rank: alpha && sizeRank.has(alpha) ? sizeRank.get(alpha) : Number.POSITIVE_INFINITY,
      numeric: Number.isFinite(numeric) ? numeric : Number.POSITIVE_INFINITY,
    };
  };
  const left = parse(leftValue, leftSystem);
  const right = parse(rightValue, rightSystem);
  if (left.system !== right.system) return left.system === "juniors" ? -1 : 1;
  if (left.rank !== right.rank) return left.rank - right.rank;
  if (left.numeric !== right.numeric) return left.numeric - right.numeric;
  return left.normalized.localeCompare(right.normalized, undefined, { sensitivity: "base", numeric: true });
}

function AdultLibraryPage({ activeLibrary, setActiveLibrary, setupConfig, items, onSelect, openImageViewer, onOpenPluginCard }) {
  const [pluginCards, setPluginCards] = useState({ panty: [], dominion: [] });
  const sortStorageKey = `homesteadAdultProfileSort:${activeLibrary}`;
  const [sortMode, setSortMode] = useState(() => localStorage.getItem(sortStorageKey) || localStorage.getItem("homesteadAdultProfileSort") || "alphabetical");
  const [sortMenuOpen, setSortMenuOpen] = useState(false);
  const filterStorageKey = `homesteadAdultProfileFilters:${activeLibrary}`;
  const [pantySystemFilter, setPantySystemFilter] = useState(() => {
    try { return JSON.parse(localStorage.getItem(filterStorageKey) || "{}").system || "all"; } catch { return "all"; }
  });
  const [pantySizeFilter, setPantySizeFilter] = useState(() => {
    try { return JSON.parse(localStorage.getItem(filterStorageKey) || "{}").size || ""; } catch { return ""; }
  });
  const [bulkStatus, setBulkStatus] = useState("idle");
  const [bulkMessage, setBulkMessage] = useState("");

  const filteredItems = useMemo(() => items.filter((item) => {
    if (pantySystemFilter === "all" && !pantySizeFilter) return true;
    const body = getAdultProfileBodyDetails(item?.metadata || item || {});
    const parsed = parseAdultPantySize(body.pantySize, body.pantySizeSystem || item?.metadata?.pantySizeSystem);
    if (pantySystemFilter !== "all" && parsed.system !== pantySystemFilter) return false;
    if (pantySizeFilter && parsed.alpha !== pantySizeFilter) return false;
    return true;
  }), [items, pantySystemFilter, pantySizeFilter]);

  const sortedItems = useMemo(() => [...filteredItems].sort((left, right) => {
    const nameCompare = String(left?.name || "").localeCompare(String(right?.name || ""), undefined, { sensitivity: "base", numeric: true });
    if (sortMode === "age-youngest" || sortMode === "age-oldest") {
      const leftAge = calculateProfileAge(left);
      const rightAge = calculateProfileAge(right);
      if (leftAge == null && rightAge != null) return 1;
      if (rightAge == null && leftAge != null) return -1;
      if (leftAge != null && rightAge != null && leftAge !== rightAge) return sortMode === "age-oldest" ? rightAge - leftAge : leftAge - rightAge;
    }
    if (sortMode === "bra" || sortMode === "panty") {
      const leftBody = getAdultProfileBodyDetails(left?.metadata || left || {});
      const rightBody = getAdultProfileBodyDetails(right?.metadata || right || {});
      const field = sortMode === "bra" ? "braSize" : "pantySize";
      const leftValue = String(leftBody[field] || "").trim();
      const rightValue = String(rightBody[field] || "").trim();
      if (!leftValue && rightValue) return 1;
      if (!rightValue && leftValue) return -1;
      const sizeCompare = sortMode === "panty"
        ? compareAdultPantySizes(leftValue, rightValue, leftBody.pantySizeSystem, rightBody.pantySizeSystem)
        : leftValue.localeCompare(rightValue, undefined, { sensitivity: "base", numeric: true });
      if (sizeCompare) return sizeCompare;
    }
    return nameCompare;
  }), [filteredItems, sortMode]);

  useEffect(() => {
    localStorage.setItem(filterStorageKey, JSON.stringify({ system: pantySystemFilter, size: pantySizeFilter }));
  }, [filterStorageKey, pantySystemFilter, pantySizeFilter]);

  useEffect(() => {
    try {
      const saved = JSON.parse(localStorage.getItem(filterStorageKey) || "{}");
      setPantySystemFilter(saved.system || "all");
      setPantySizeFilter(saved.size || "");
    } catch {
      setPantySystemFilter("all");
      setPantySizeFilter("");
    }
  }, [filterStorageKey]);

  const changeSortMode = (value) => {
    setSortMode(value);
    localStorage.setItem(sortStorageKey, value);
    setSortMenuOpen(false);
  };

  const refreshMissingMetadata = async () => {
    const label = activeLibrary === "personal" ? "Personal" : activeLibrary === "celebrities" ? "Celebrities" : "Performers";
    if (!window.confirm(`Refresh missing metadata for all ${label} profiles? Proposed changes will be staged in Activity Center for review and will not overwrite profiles automatically.`)) return;
    setBulkStatus("loading");
    setBulkMessage("Starting metadata refresh…");
    try {
      const response = await fetch("/api/metadata/adult/bulk-fetch", {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify({ libraryType: activeLibrary, overwrite: false, limit: 500 }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data.ok) throw new Error(data.message || "Bulk metadata refresh failed.");
      setBulkStatus("saved");
      setBulkMessage(data.message || "Metadata proposals are ready in Activity Center.");
      window.dispatchEvent(new CustomEvent("homestead-open-activity-center"));
    } catch (error) {
      setBulkStatus("error");
      setBulkMessage(error.message || "Bulk metadata refresh failed.");
    }
  };

  useEffect(() => {
    const label = activeLibrary === "personal" ? "Personal" : activeLibrary === "celebrities" ? "Celebrities" : "Performers";
    window.dispatchEvent(new CustomEvent("homestead-page-context", { detail: {
      library: activeLibrary,
      title: label,
      filterSort: true,
      filterSortActive: sortMode !== "alphabetical" || pantySystemFilter !== "all" || Boolean(pantySizeFilter),
      headerActions: [{ id: "refresh-missing-metadata", label: "Refresh Missing Metadata", icon: "↻" }],
    } }));
  }, [activeLibrary, sortMode, pantySystemFilter, pantySizeFilter]);

  useEffect(() => {
    const handlePageAction = (event) => {
      if (event?.detail?.library !== activeLibrary) return;
      if (event.detail.action === "filter-sort") setSortMenuOpen((open) => !open);
      if (event.detail.action === "refresh-missing-metadata") refreshMissingMetadata();
    };
    const handleKeyDown = (event) => { if (event.key === "Escape") setSortMenuOpen(false); };
    window.addEventListener("homestead-page-action", handlePageAction);
    window.addEventListener("keydown", handleKeyDown);
    return () => {
      window.removeEventListener("homestead-page-action", handlePageAction);
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [activeLibrary]);

  useEffect(() => {
    let cancelled = false;
    const controller = new AbortController();
    const timeout = window.setTimeout(() => controller.abort(), 2400);
    const request = async (url) => {
      const response = await fetch(url, { headers: { Accept: "application/json" }, cache: "no-store", signal: controller.signal });
      if (!response.ok) throw new Error("Plugin card summary unavailable.");
      const data = await response.json();
      return data?.ok && Array.isArray(data.cards) ? data.cards : [];
    };
    Promise.allSettled([
      request("/api/plugins/panty-archive/host/cards"),
      request("/api/plugins/dominion/host/cards"),
    ]).then(([panty, dominion]) => {
      if (cancelled) return;
      setPluginCards({
        panty: panty.status === "fulfilled" ? panty.value : [],
        dominion: dominion.status === "fulfilled" ? dominion.value : [],
      });
    }).finally(() => window.clearTimeout(timeout));
    return () => { cancelled = true; controller.abort(); window.clearTimeout(timeout); };
  }, [activeLibrary, items.length]);

  return (
    <div className="generic-page">
      <AdultSectionTabs activeLibrary={activeLibrary} setActiveLibrary={setActiveLibrary} setupConfig={setupConfig} />

      {sortMenuOpen && createPortal(
        <div className="adult-profile-sort-popover-layer">
          <button className="adult-profile-sort-popover-backdrop" type="button" aria-label="Close profile sorting" onClick={() => setSortMenuOpen(false)} />
          <div className="adult-profile-sort-popover" role="menu" aria-label="Sort profiles">
            <div><strong>Sort profiles</strong><small>Profiles missing the selected metadata stay at the end.</small></div>
            {[
              ["alphabetical", "Alphabetically"],
              ["age-youngest", "Age: youngest first"],
              ["age-oldest", "Age: oldest first"],
              ["bra", "Bra size"],
              ["panty", "Panty size"],
            ].map(([value, label]) => (
              <button key={value} type="button" role="menuitemradio" aria-checked={sortMode === value} className={sortMode === value ? "active" : ""} onClick={() => changeSortMode(value)}>
                <span>{sortMode === value ? "✓" : ""}</span><strong>{label}</strong>
              </button>
            ))}
            <div className="adult-profile-filter-fields">
              <label><span>Size system</span><select value={pantySystemFilter} onChange={(event) => setPantySystemFilter(event.target.value)}>
                <option value="all">All systems</option>
                <option value="juniors">Juniors / youth</option>
                <option value="adult">Adult</option>
              </select></label>
              <label><span>Panty size</span><select value={pantySizeFilter} onChange={(event) => setPantySizeFilter(event.target.value)}>
                <option value="">All sizes</option>
                {["xxxxs", "xxxs", "xxs", "xs", "s", "m", "l", "xl", "xxl", "xxxl"].map((size) => <option key={size} value={size}>{size.toUpperCase()}</option>)}
              </select></label>
            </div>
            {(pantySystemFilter !== "all" || pantySizeFilter) && <button type="button" className="adult-profile-filter-clear" onClick={() => { setPantySystemFilter("all"); setPantySizeFilter(""); }}><span>×</span><strong>Clear size filters</strong></button>}
            <small>{sortedItems.length} of {items.length} profiles shown. Adult XS and Juniors XS stay separate.</small>
            <small>Use Refresh Missing Metadata in the header to stage sourced values for review.</small>
          </div>
        </div>,
        document.body,
      )}

      {bulkMessage && <div className={`adult-profile-bulk-status ${bulkStatus}`} role="status">{bulkMessage}</div>}

      <PersonGrid
        items={sortedItems}
        onSelect={onSelect}
        openImageViewer={openImageViewer}
        pluginCards={pluginCards}
        onOpenPluginCard={onOpenPluginCard}
      />
    </div>
  );
}


