function getSeerrPreviewStatus(item, requests) {
  const mediaType = item.mediaType === "tv" ? "tv" : "movie";
  const bucket = mediaType === "tv" ? "tv" : "movies";

  const id = String(item.tmdbId || item.id || "");
  const info = item.mediaInfo || {};
  const rows = Array.isArray(requests?.[bucket]) ? requests[bucket] : [];
  const saved = rows.find((request) => id && (
    String(request?.tmdbId || "") === id ||
    String(request?.id || request) === `tmdb-${id}`
  ));
  const known = ["available", "owned", "partial", "downloading", "processing", "importing", "scanning", "pending", "declined", "failed", "needs-attention", "requested"];

  if (saved?.checkedAt && known.includes(saved.status)) return saved.status;
  const remoteStatus = Number(info.status || 0);
  if (remoteStatus === 5) return "available";
  const downloads = Array.isArray(info.downloadStatus) ? info.downloadStatus : [];
  if (downloads.some((entry) => ["failed", "error"].includes(String(entry.status).toLowerCase()))) return "needs-attention";
  if (downloads.length) return "downloading";
  if (remoteStatus === 4) return "partial";
  if (remoteStatus === 3) return "processing";
  if (remoteStatus === 2) return "requested";
  if (saved) return known.includes(saved.status) ? saved.status : "requested";
  if (Array.isArray(info.requests) && info.requests.some((request) => [1, 2].includes(Number(request.status)))) return "requested";
  return "discovery";
}

function buildRecentRequestItems(requests) {
  const movies = (requests?.movies || []).map((item) => ({
    ...item,
    mediaType: "movie",
    library: "movies",
    label: "Movie",
  }));

  const tv = (requests?.tv || []).map((item) => ({
    ...item,
    mediaType: "tv",
    library: "tv",
    label: "TV Show",
  }));

  return [...movies, ...tv]
    .sort((a, b) => {
      const aDate = new Date(a.requestedAt || 0).getTime();
      const bDate = new Date(b.requestedAt || 0).getTime();
      return bDate - aDate;
    })
    .slice(0, 12);
}

function normalizeOwnershipTitle(value = "") {
  return String(value).toLowerCase().replace(/\([^)]*\)/g, " ").replace(/[^a-z0-9]+/g, " ").trim();
}

function getSearchResultYear(item = {}) {
  const direct = item.year || item.releaseYear || item.metadata?.year;
  if (direct) return String(direct).slice(0, 4);
  return String(item.releaseDate || item.firstAirDate || item.release_date || item.first_air_date || "").slice(0, 4);
}

function getSearchProviderId(item = {}) {
  return String(item.tmdbId || item.metadata?.tmdbId || item.metadataMatch?.tmdbId || item.providerId || item.id || "").trim();
}

function searchItemsRepresentSameTitle(localItem = {}, discoveryItem = {}) {
  const localProviderId = getSearchProviderId(localItem);
  const discoveryProviderId = String(discoveryItem.id || discoveryItem.tmdbId || "").trim();
  if (localProviderId && discoveryProviderId && localProviderId === discoveryProviderId) return true;
  const localTitle = normalizeOwnershipTitle(localItem.title || localItem.name);
  const discoveryTitle = normalizeOwnershipTitle(discoveryItem.title || discoveryItem.name);
  if (!localTitle || localTitle !== discoveryTitle) return false;
  const localYear = getSearchResultYear(localItem);
  const discoveryYear = getSearchResultYear(discoveryItem);
  return !localYear || !discoveryYear || localYear === discoveryYear;
}

function mergeOwnedSearchDiscoveries(results = [], discoveryResults = []) {
  const consumed = new Set();
  const mergedLocal = results.map((localItem) => {
    if (!["movies", "tv", "movie"].includes(localItem.library || localItem.type)) return localItem;
    const matchIndex = discoveryResults.findIndex((candidate, index) => !consumed.has(index) && searchItemsRepresentSameTitle(localItem, candidate));
    if (matchIndex < 0) return localItem;
    consumed.add(matchIndex);
    const discovery = discoveryResults[matchIndex];
    return { ...discovery, ...localItem, poster: localItem.poster || discovery.poster, posterPath: localItem.posterPath || discovery.posterPath || discovery.poster_path, status: "owned", matchedDiscovery: discovery };
  });
  return { results: mergedLocal, discoveryResults: discoveryResults.filter((_, index) => !consumed.has(index)) };
}

function getDiscoveryOwnership(item, localItems = [], mediaType = "movie") {
  const providerId = String(item?.id || item?.tmdbId || "");
  const title = normalizeOwnershipTitle(item?.title || item?.name);
  const local = localItems.find((entry) => {
    const localProviderId = String(entry?.tmdbId || entry?.metadata?.tmdbId || entry?.metadataMatch?.tmdbId || "");
    return (providerId && localProviderId === providerId) || (title && normalizeOwnershipTitle(entry?.title || entry?.name) === title);
  });
  const remoteStatus = Number(item?.mediaInfo?.status || item?.mediaInfo?.status4k || 0);
  if (remoteStatus === 4) return "partial";
  if (remoteStatus === 5) return "owned";
  if (!local) return "missing";
  if (mediaType === "tv") {
    const localEpisodes = Number(local?.counts?.episodes || local?.episodeCount || local?.metadata?.episodeCount || 0);
    const expectedEpisodes = Number(item?.numberOfEpisodes || item?.episodeCount || item?.metadata?.episodeCount || 0);
    if (expectedEpisodes > 0 && localEpisodes > 0 && localEpisodes < expectedEpisodes) return "partial";
  }
  return "owned";
}

function TrendingMoviesWidget({ onSelectSeerr, localItems = [] }) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [errorMessage, setErrorMessage] = useState("");

  useEffect(() => {
    fetch("/api/integrations/seerr/discover/trending-movies")
      .then((res) => res.json())
      .then((data) => {
        if (data.ok === false) {
          throw new Error(data.message || "Failed to load trending movies");
        }

        setItems((data.results || []).slice(0, 12));
        setErrorMessage("");
      })
      .catch((err) => {
        console.error("Failed to load trending movies:", err);
        setErrorMessage(err.message);
        setItems([]);
      })
      .finally(() => {
        setLoading(false);
      });
  }, []);

  return (
    <section className="panel media-home-widget">
      <div className="section-header-row">
        <h2>Trending Movies</h2>
      </div>

      {loading && <p className="muted-text">Loading trending movies...</p>}

      {!loading && errorMessage && (
        <p className="muted-text">Trending movies unavailable: {errorMessage}</p>
      )}

      {!loading && !errorMessage && !items.length && (
        <p className="muted-text">No trending movies found.</p>
      )}

      {!loading && !errorMessage && !!items.length && (
        <div className="media-home-card-row">
          {items.map((item) => (
            <button
              key={`trending-movie-${item.id}`}
              className="media-home-request-card"
              type="button"
              onClick={() =>
                onSelectSeerr({
                  ...item,
                  id: item.id,
                  tmdbId: item.id,
                  mediaType: "movie",
                })
              }
            >
		<div className="media-home-request-poster">
			{getNormalizedTmdbCardImage(item, "movie", "poster") ? (
				<img
					src={getNormalizedTmdbCardImage(item, "movie", "poster")}
					loading="lazy" decoding="async"
					alt=""
				/>
			) : (
				<div className="poster-placeholder">🎬</div>
			)}
		</div>

              <div className="media-home-request-info">
                <span className="media-home-request-year">
                  {(item.releaseDate || "").slice(0, 4) || "Movie"}
                </span>

                <strong>{item.title || item.name}</strong>

                <span className="muted-text">Movie</span>

                <MediaStatusBadge status={getDiscoveryOwnership(item, localItems, "movie")} />
              </div>
            </button>
          ))}
        </div>
      )}
    </section>
  );
}

