async function setFolderOrganizerEnabled(enabled) {
  setFolderOrganizer((current) => ({ ...current, loading: true, message: "Saving…" }));
  try {
    const response = await fetch("/api/admin/media-folders/consolidation/settings", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ library: "tv", enabled }) });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) throw new Error(data.message || "Unable to save folder organization.");
    setFolderOrganizer((current) => ({ ...current, enabled: data.enabled === true, loading: false, message: data.enabled ? "Automatic safe consolidation enabled." : "Automatic consolidation disabled." }));
  } catch (error) { setFolderOrganizer((current) => ({ ...current, loading: false, message: error.message })); }
}

async function applySafeFolderMerges() {
  const safeGroups = folderOrganizer.groups.filter((group) => group.safeToApply);
  if (!safeGroups.length) return;
  if (!window.confirm(`Consolidate ${safeGroups.length} provider-matched TV folder group${safeGroups.length === 1 ? "" : "s"}? Existing destination files will never be overwritten.`)) return;
  setFolderOrganizer((current) => ({ ...current, loading: true, message: "Consolidating safe folder groups…" }));
  try {
    const response = await fetch("/api/admin/media-folders/consolidation/apply", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ library: "tv", groupIds: safeGroups.map((group) => group.id) }) });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.ok) throw new Error(data.message || "Folder consolidation failed.");
    await refreshFolderOrganizer();
    setFolderOrganizer((current) => ({ ...current, message: `${data.applied || 0} folder group${data.applied === 1 ? "" : "s"} processed. Open Activity for moved files or conflicts.` }));
    window.dispatchEvent(new Event("homestead-open-activity-center"));
  } catch (error) { setFolderOrganizer((current) => ({ ...current, loading: false, message: error.message })); }
}

