function getLibraryFolders(id) {
  const value = folderMappings[id];

  if (Array.isArray(value)) return value;

  if (typeof value === "string" && value.trim()) {
    return [value];
  }

  return [`/media/${id}`];
}

function normalizeScanHistoryLibraryId(id) {
  const aliases = {
    tvshows: "tv",
    tvShows: "tv",
    liveTV: "liveTV",
    adultphotos: "adultPhotos",
    adultvideos: "adultVideos",
  };

  return aliases[id] || id;
}

function formatScanDate(value) {
  return formatHomesteadDateTime(value, {}, "Never");
}

function summarizeScanHistoryEntries(entries = [], id) {
  const validEntries = entries.filter(Boolean);
  if (!validEntries.length) return null;

  const latestEntry = validEntries
    .slice()
    .sort((a, b) => new Date(b.completedAt || 0) - new Date(a.completedAt || 0))[0];

  const folders = Array.from(
    new Set(validEntries.flatMap((entry) => entry.folders || []))
  );

  return {
    libraryId: id,
    completedAt: latestEntry?.completedAt || "",
    folders,
    itemCount: validEntries.reduce((total, entry) => total + Number(entry.itemCount || 0), 0),
    newItemCount: validEntries.reduce((total, entry) => total + Number(entry.newItemCount || 0), 0),
    removedItemCount: validEntries.reduce((total, entry) => total + Number(entry.removedItemCount || 0), 0),
  };
}

function getLibraryScanHistory(id) {
  const scanKey = normalizeScanHistoryLibraryId(id);
  const responseHistory =
    libraryScanStatus.libraryId === id
      ? libraryScanStatus.result?.scanHistory ||
        libraryScanStatus.result?.mediaIndex?.scanHistory ||
        libraryScanStatus.result?.history ||
        null
      : null;

  const indexHistory = mediaIndex?.scanHistory || null;

  if (scanKey === "adult") {
    const adultKeys = ["personal", "performers", "celebrities", "adultPhotos", "adultVideos"];
    const adultEntries = adultKeys
      .map((key) => responseHistory?.[key] || indexHistory?.[key])
      .filter(Boolean);

    return summarizeScanHistoryEntries(adultEntries, id);
  }

  return responseHistory?.[scanKey] || indexHistory?.[scanKey] || null;
}

function renderLibraryScanHistory(id) {
  const history = getLibraryScanHistory(id);

  if (!history) {
    return (
      <div className="library-scan-history empty">
        <strong>Last scan</strong>
        <p>No scan history yet.</p>
      </div>
    );
  }

  const folderList = Array.isArray(history.folders)
    ? history.folders.filter(Boolean)
    : [];

  return (
    <div className="library-scan-history">
      <div className="library-scan-history-header">
        <div>
          <strong>Last scan</strong>
          <p>{formatScanDate(history.completedAt)}</p>
        </div>

        <span>{history.itemCount ?? 0} item{Number(history.itemCount || 0) === 1 ? "" : "s"}</span>
      </div>

      <div className="library-scan-history-grid">
        <div>
          <small>New</small>
          <b>{history.newItemCount ?? 0}</b>
        </div>

        <div>
          <small>Removed</small>
          <b>{history.removedItemCount ?? 0}</b>
        </div>

        <div>
          <small>Folders</small>
          <b>{folderList.length}</b>
        </div>
      </div>

      {folderList.length > 0 && (
        <div className="library-scan-folder-summary">
          {folderList.slice(0, 3).map((folder) => (
            <code key={folder}>{folder}</code>
          ))}
          {folderList.length > 3 && <span>+{folderList.length - 3} more</span>}
        </div>
      )}
    </div>
  );
}

function saveLibraryFolders(id, folders) {
  const updatedConfig = {
    ...setupConfig,
    folderMappings: {
      ...folderMappings,
      [id]: folders,
    },
  };

  saveSetupConfig(updatedConfig);
}

function addLibraryFolder(id) {
  const currentFolders = getLibraryFolders(id);

  saveLibraryFolders(id, [
    ...currentFolders,
    `/media/${id}`,
  ]);
}

function updateLibraryFolder(id, index, value) {
  const currentFolders = getLibraryFolders(id);

  const updatedFolders = currentFolders.map((folder, folderIndex) =>
    folderIndex === index ? value : folder
  );

  saveLibraryFolders(id, updatedFolders);
}

function removeLibraryFolder(id, index) {
  const currentFolders = getLibraryFolders(id);

  const updatedFolders = currentFolders.filter(
    (_, folderIndex) => folderIndex !== index
  );

  saveLibraryFolders(
    id,
    updatedFolders.length ? updatedFolders : [`/media/${id}`]
  );
}

async function manualScanLibraryFolder(id, folder) {
  const label = titleFromId(id);

  setLibraryScanStatus({
    state: "running",
    libraryId: id,
    message: `Scanning ${label} folder…`,
    result: null,
  });

  try {
    const response = await fetch("/api/scan-library", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        libraryId: id,
        folder,
        mode: "folder",
      }),
    });

    const data = await response.json().catch(() => ({}));

    if (!response.ok || data.ok === false) {
      throw new Error(data.message || data.error || "Scan failed");
    }

    const scanKey = normalizeScanHistoryLibraryId(id);
    const history =
      data.scanHistory?.[scanKey] ||
      data.mediaIndex?.scanHistory?.[scanKey] ||
      data.history ||
      null;
    const itemCount = history?.itemCount ?? data.itemCount ?? null;
    const newItemCount = history?.newItemCount ?? data.newItemCount ?? null;
    const removedItemCount = history?.removedItemCount ?? data.removedItemCount ?? null;
    const summary = [
      itemCount !== null ? `${itemCount} item${itemCount === 1 ? "" : "s"}` : "Scan complete",
      newItemCount !== null ? `${newItemCount} new` : "",
      removedItemCount !== null ? `${removedItemCount} removed` : "",
    ].filter(Boolean).join(" · ");

    setLibraryScanStatus({
      state: "complete",
      libraryId: id,
      message: `${label} folder scan completed. ${summary}`,
      result: data,
    });
  } catch (err) {
    console.error("Failed to start folder scan:", err);
    setLibraryScanStatus({
      state: "failed",
      libraryId: id,
      message: err.message || "Scan backend is not connected yet.",
      result: null,
    });
  }
}

