function getIntegrationSetting(id) {
  return integrationSettings[id] || {
    url: "",
    apiKey: "",
    enabled: !!integrations[id],
  };
}

function normalizeIntegrationBaseUrl(value = "") {
  return String(value || "").trim().replace(/\/+$/, "");
}

function getIptvProviderGeneratedUrls(settings = {}) {
  const serverUrl = normalizeIntegrationBaseUrl(settings.serverUrl || "");
  const username = String(settings.username || "").trim();
  const password = String(settings.password || "").trim();
  const output = String(settings.output || "ts").trim() || "ts";

  if (!serverUrl || !username || !password) {
    return { m3uUrl: "", epgUrl: "" };
  }

  const query =
    `username=${encodeURIComponent(username)}` +
    `&password=${encodeURIComponent(password)}`;

  return {
    m3uUrl: `${serverUrl}/get.php?${query}&type=m3u_plus&output=${encodeURIComponent(output)}`,
    epgUrl: `${serverUrl}/xmltv.php?${query}`,
  };
}

async function testIntegrationConnection(id) {
  await saveIntegrationSettings(id, true);

  try {
    const statusId = id === "jellyseerr" ? "seerr" : id;
    const res = await fetch(`/api/integrations/${statusId}/status`, { cache: "no-store" });
    const data = await res.json().catch(() => ({}));

    if (!res.ok) {
      throw new Error(data.error || data.message || "Connection failed");
    }

    const connected =
      data.connected === true ||
      data.ok === true ||
      data.status === "connected";

    if (!connected) {
      throw new Error(data.error || data.message || "Connection failed");
    }

    alert(
      data.message ||
      `${data.appName || integrationDisplayNames[id] || titleFromId(id)} connected successfully.`
    );
  } catch (err) {
    console.error("Connection test failed:", err);
    alert(`Connection failed: ${err.message}`);
  }
}

async function saveIntegrationSettings(id, silent = false) {
  const settings = getIntegrationSetting(id);

  try {
    const res = await fetch(`/api/integrations/${id}/settings`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(settings),
    });

    if (!res.ok) {
      throw new Error("Failed to save integration settings");
    }

if (!silent) {
  alert(`${integrationDisplayNames[id] || titleFromId(id)} settings saved.`);
}
  } catch (err) {
    console.error("Failed to save integration settings:", err);
    alert("Could not save integration settings to backend.");
  }
}

async function testLiveTvPlaylistFromSettings() {
  const playlistUrl = setupConfig?.liveTV?.m3uUrl || "";

  if (!playlistUrl) {
    setLiveTvStatus("Enter an M3U URL first.");
    return;
  }

  try {
    setLiveTvLoading(true);
    setLiveTvStatus("Testing playlist...");

    const res = await fetch("/api/livetv/playlist/test", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ playlistUrl }),
    });

    const data = await res.json();

    if (!res.ok || !data.ok) {
      throw new Error(data.error || "Playlist test failed");
    }

    const sample =
      data.sampleChannels
        ?.slice(0, 3)
        .map((channel) => channel.name)
        .join(", ") || "none";

    setLiveTvStatus(
      `Playlist OK. Found ${data.channelCount} channels. Sample: ${sample}`
    );
  } catch (err) {
    setLiveTvStatus(`Playlist test failed: ${err.message}`);
  } finally {
    setLiveTvLoading(false);
  }
}

async function saveLiveTvConfigFromSettings() {
  const playlistUrl = setupConfig?.liveTV?.m3uUrl || "";
  const epgUrl = setupConfig?.liveTV?.epgUrl || "";
  const xteveUrl = setupConfig?.liveTV?.xteveUrl || "";

  try {
    setLiveTvLoading(true);
    setLiveTvStatus("Saving Live TV config...");

    const res = await fetch("/api/livetv/config", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ playlistUrl, epgUrl, xteveUrl }),
    });

    const data = await res.json();

    if (!res.ok || !data.ok) {
      throw new Error(data.error || "Save failed");
    }

    setLiveTvStatus("Live TV config saved.");
  } catch (err) {
    setLiveTvStatus(`Save failed: ${err.message}`);
  } finally {
    setLiveTvLoading(false);
  }
}

async function refreshLiveTvChannelsFromSettings() {
  try {
    setLiveTvLoading(true);
    setLiveTvStatus("Refreshing channels...");

    const res = await fetch("/api/livetv/playlist/refresh", {
      method: "POST",
    });

    const data = await res.json();

    if (!res.ok || !data.ok) {
      throw new Error(data.error || "Refresh failed");
    }

    setLiveTvStatus(`Channels refreshed. Found ${data.channelCount} channels.`);
  } catch (err) {
    setLiveTvStatus(`Refresh failed: ${err.message}`);
  } finally {
    setLiveTvLoading(false);
  }
}

