function AdultRecommendationAccountPanel({ preferences = {}, onSaved }) {
  const [draft, setDraft] = useState(() => normalizeAdultRecommendationPreferences(preferences?.adultRecommendations || {}));
  const [emptyStates, setEmptyStates] = useState(() => ({ photos: preferences?.adultEmptyStates?.photos || "No sex photos found yet.", videos: preferences?.adultEmptyStates?.videos || "No sex videos found yet." }));
  const [status, setStatus] = useState("");
  useEffect(() => { setDraft(normalizeAdultRecommendationPreferences(preferences?.adultRecommendations || {})); setEmptyStates({ photos: preferences?.adultEmptyStates?.photos || "No sex photos found yet.", videos: preferences?.adultEmptyStates?.videos || "No sex videos found yet." }); }, [preferences]);
  const toggleList = (field, value) => setDraft((current) => ({ ...current, [field]: current[field].includes(value) ? current[field].filter((item) => item !== value) : [...current[field], value] }));
  const save = async () => {
    setStatus("Saving…");
    try {
      const response = await fetch("/api/account/preferences", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ preferences: { adultRecommendations: draft, adultEmptyStates: emptyStates } }) });
      const data = await response.json();
      if (!response.ok || !data.ok) throw new Error(data.message || "Could not save preferences.");
      onSaved?.(data.preferences || {}); setStatus("Saved for your account.");
    } catch (error) { setStatus(error.message || "Could not save preferences."); }
  };
  return <section className="panel adult-recommendation-preferences"><h3>Adult Recommendations</h3><p>Search enabled Celebrity and Performer databases for people not already in your library.</p>
    <label className="checkbox-row"><input type="checkbox" checked={draft.enabled !== false} onChange={(event) => setDraft({ ...draft, enabled: event.target.checked })} />Enable recommendations</label>
    <div className="adult-preference-grid">
      <label className="settings-field"><span>Gender</span><select value={draft.gender} onChange={(event) => setDraft({ ...draft, gender: event.target.value })}><option value="female">Female</option><option value="male">Male</option><option value="nonbinary">Nonbinary</option><option value="any">Any</option></select></label>
      <fieldset><legend>Body type</legend>{["petite", "slim", "athletic", "curvy"].map((value) => <label className="checkbox-row" key={value}><input type="checkbox" checked={draft.bodyTypes.includes(value)} onChange={() => toggleList("bodyTypes", value)} />{titleFromId(value)}</label>)}</fieldset>
      <fieldset><legend>Breast shape</legend>{["perky", "natural", "augmented"].map((value) => <label className="checkbox-row" key={value}><input type="checkbox" checked={draft.breastShapes.includes(value)} onChange={() => toggleList("breastShapes", value)} />{titleFromId(value)}</label>)}</fieldset>
      <fieldset><legend>Height</legend>{["short", "medium", "tall"].map((value) => <label className="checkbox-row" key={value}><input type="checkbox" checked={draft.heightCategories.includes(value)} onChange={() => toggleList("heightCategories", value)} />{titleFromId(value)}</label>)}</fieldset>
      <fieldset><legend>Race / ethnicity — include</legend>{ADULT_RECOMMENDATION_ETHNICITIES.map((value) => <label className="checkbox-row" key={value}><input type="checkbox" checked={draft.ethnicityInclude.includes(value)} onChange={() => toggleList("ethnicityInclude", value)} />{value}</label>)}</fieldset>
      <fieldset><legend>Race / ethnicity — exclude</legend>{ADULT_RECOMMENDATION_ETHNICITIES.map((value) => <label className="checkbox-row" key={value}><input type="checkbox" checked={draft.ethnicityExclude.includes(value)} onChange={() => toggleList("ethnicityExclude", value)} />{value}</label>)}</fieldset>
      <label className="checkbox-row"><input type="checkbox" checked={draft.includeUnknownEthnicity !== false} onChange={(event) => setDraft({ ...draft, includeUnknownEthnicity: event.target.checked })} />Include Unknown / Not listed</label>
      <label className="settings-field"><span>Maximum weight (lb)</span><input type="number" min="0" max="1000" value={draft.maxWeight || ""} onChange={(event) => setDraft({ ...draft, maxWeight: Number(event.target.value) || 0 })} /></label>
      <label className="settings-field"><span>Maximum panty size</span><select value={draft.pantySizeMax} onChange={(event) => setDraft({ ...draft, pantySizeMax: event.target.value })}><option value="">Any</option>{["XS", "S", "M", "L", "XL"].map((value) => <option key={value}>{value}</option>)}</select></label>
      <label className="settings-field"><span>Maximum bra size</span><span className="adult-bra-limit"><input aria-label="Maximum bra band" type="number" min="0" max="80" value={draft.braBandMax || ""} onChange={(event) => setDraft({ ...draft, braBandMax: Number(event.target.value) || 0 })} /><select aria-label="Maximum cup size" value={draft.cupSizeMax} onChange={(event) => setDraft({ ...draft, cupSizeMax: event.target.value })}>{["", "AA", "A", "B", "C", "D", "DD", "E", "F"].map((value) => <option key={value}>{value || "Any"}</option>)}</select></span></label>
      <label className="settings-field"><span>Age range</span><span className="adult-age-range"><input aria-label="Minimum age" type="number" min="18" max="100" value={draft.minAge} onChange={(event) => setDraft({ ...draft, minAge: Math.max(18, Number(event.target.value) || 18) })} /><input aria-label="Maximum age" type="number" min="18" max="100" value={draft.maxAge} onChange={(event) => setDraft({ ...draft, maxAge: Math.max(18, Number(event.target.value) || 35) })} /></span></label>
      <label className="checkbox-row"><input type="checkbox" checked={draft.requirePoster !== false} onChange={(event) => setDraft({ ...draft, requirePoster: event.target.checked })} />Require a valid poster</label>
      <label className="settings-field"><span>Match completeness</span><select value={draft.matchMode || "strict"} onChange={(event) => setDraft({ ...draft, matchMode: event.target.value })}><option value="strict">Require every selected field</option><option value="compatible">Allow compatible partial matches</option></select><small>Partial matches never include a known value that fails your filter; missing provider fields are labeled on the card.</small></label>
    </div><h4>Profile empty messages</h4><p className="small-muted">Use <code>{"{name}"}</code> and <code>{"{owner}"}</code> in either message.</p><div className="adult-preference-grid"><label className="settings-field"><span>Sex photos</span><input maxLength="220" value={emptyStates.photos} onChange={(event) => setEmptyStates((current) => ({ ...current, photos: event.target.value }))} /></label><label className="settings-field"><span>Sex videos</span><input maxLength="220" value={emptyStates.videos} onChange={(event) => setEmptyStates((current) => ({ ...current, videos: event.target.value }))} /></label></div><div className="settings-row-actions"><button className="primary-button" type="button" onClick={save}>Save Adult Preferences</button>{status && <span className="small-muted">{status}</span>}</div>
  </section>;
}

function AdultRecommendationProviderSettings() {
  const [providers, setProviders] = useState([]);
  const [status, setStatus] = useState("Loading provider settings…");
  const [testStatus, setTestStatus] = useState({});
  useEffect(() => {
    fetch("/api/discovery/adult/providers", { cache: "no-store" })
      .then(async (response) => ({ response, data: await response.json() }))
      .then(({ response, data }) => {
        if (!response.ok || !data.ok) throw new Error(data.message || "Could not load providers.");
        setProviders(data.providers || []);
        setStatus("");
      })
      .catch((error) => setStatus(error.message || "Could not load providers."));
  }, []);
  const updateProvider = (id, patch) => setProviders((current) => current.map((provider) => provider.id === id ? { ...provider, ...patch } : provider));
  const testProvider = async (provider) => {
    setTestStatus((current) => ({ ...current, [provider.id]: "Testing connection…" }));
    try {
      const response = await fetch(`/api/discovery/adult/providers/${encodeURIComponent(provider.id)}/test`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ provider }),
      });
      const data = await response.json();
      if (!response.ok || !data.ok) throw new Error(data.message || "Connection test failed.");
      setTestStatus((current) => ({ ...current, [provider.id]: data.message || "Connection succeeded." }));
    } catch (error) {
      setTestStatus((current) => ({ ...current, [provider.id]: error.message || "Connection test failed." }));
    }
  };
  const save = async () => {
    setStatus("Saving providers…");
    try {
      const response = await fetch("/api/discovery/adult/providers", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ providers }) });
      const data = await response.json();
      if (!response.ok || !data.ok) throw new Error(data.message || "Could not save providers.");
      setProviders(data.providers || []);
      setStatus("Provider settings saved.");
    } catch (error) {
      setStatus(error.message || "Could not save providers.");
    }
  };
  return <section className="panel adult-recommendation-providers"><h3>Recommendation data providers</h3><p>You May Like only uses structured person records. StashDB and ThePornDB supply performer fields; a custom JSON directory can supply celebrities and fields those services do not carry.</p>
    <div className="adult-provider-settings-list">{providers.map((provider) => <fieldset key={provider.id}><legend>{provider.name}</legend>
      <label className="checkbox-row"><input type="checkbox" checked={provider.enabled === true} onChange={(event) => updateProvider(provider.id, { enabled: event.target.checked })} />Enabled</label>
      <label className="settings-field"><span>Endpoint</span><input value={provider.endpoint || ""} onChange={(event) => updateProvider(provider.id, { endpoint: event.target.value })} /></label>
      <label className="settings-field"><span>{provider.id === "theporndb" ? "API token" : "API key"} {provider.apiKeyConfigured ? "(configured)" : ""}</span><input type="password" value={provider.apiKey || ""} onChange={(event) => updateProvider(provider.id, { apiKey: event.target.value })} placeholder={provider.apiKeyConfigured ? "Leave blank to keep current key" : provider.id === "theporndb" ? "Paste the token without Bearer" : "Paste provider API key"} /></label>
      {provider.apiKeyConfigured && <label className="checkbox-row"><input type="checkbox" checked={provider.clearApiKey === true} onChange={(event) => updateProvider(provider.id, { clearApiKey: event.target.checked })} />Remove saved {provider.id === "theporndb" ? "API token" : "API key"}</label>}
      {provider.id === "theporndb" && <small>Create a personal token on <a href={provider.tokenUrl || "https://theporndb.net/user/api-tokens"} target="_blank" rel="noreferrer">ThePornDB API Tokens ↗</a>. Homestead adds the Bearer prefix securely.</small>}
      <div className="settings-row-actions"><button className="secondary-button" type="button" onClick={() => testProvider(provider)}>Test Connection</button><small>{testStatus[provider.id] || `${(provider.profileTypes || []).map(titleFromId).join(" and ")} · ${provider.configured ? "Ready" : "Not configured"}`}</small></div>
    </fieldset>)}</div>
    <p className="small-muted">StashDB and ThePornDB can validate gender, age, height, weight when supplied, bra band/cup, ethnicity, poster, and other public performer details. They do not provide panty size, body type, or “perky,” so use compatible partial matches when those filters are selected.</p>
    <div className="settings-row-actions"><button className="primary-button" type="button" onClick={save}>Save Providers</button>{status && <span className="small-muted">{status}</span>}</div>
  </section>;
}

