function GlobalAudioPlayer({ track, onClose, onTrackChange }) {
  const audioRef = useRef(null);
  const [expanded, setExpanded] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [playError, setPlayError] = useState("");
  const [activePanel, setActivePanel] = useState("");
  const [lyricsText, setLyricsText] = useState("");
  const [lyricsLoading, setLyricsLoading] = useState(false);
  const [repeatMode, setRepeatMode] = useState("off");

  const audioUrl = track ? getPlayableMediaUrl(track.audioFile || track) : "";
  const progressKey = track?.audioFile?.path || track?.path || track?.id || audioUrl;
  const title = track?.title || track?.name || "Untitled Track";
  const artist = track?.artist || track?.albumArtist || "Unknown Artist";
  const album = track?.album || "Homestead Music";
  const poster = track?.poster || track?.cover || track?.artwork || `/media/music/${artist}/poster.jpg`;
  const progressPercent = duration ? Math.min(100, Math.max(0, (currentTime / duration) * 100)) : 0;
  const playbackQueue = Array.isArray(track?.playbackQueue) && track.playbackQueue.length ? track.playbackQueue : track ? [track] : [];
  const originalPlaybackQueue = Array.isArray(track?.originalPlaybackQueue) && track.originalPlaybackQueue.length ? track.originalPlaybackQueue : playbackQueue;
  const queueIndex = Math.max(0, Math.min(Number(track?.queueIndex) || 0, Math.max(0, playbackQueue.length - 1)));
  const queueShuffled = Boolean(track?.queueShuffled);
  const isAudiobook = track?.kind === "audiobook" || track?.type === "audiobook";
  const readAlongBook = track?.readAlongBook;
  const ebookFiles = readableEbooks(readAlongBook);
  const [ebookIndex, setEbookIndex] = useState(0);
  useEffect(() => { setEbookIndex(0); }, [readAlongBook?.id]);

  const formatTime = (value = 0) => {
    if (!Number.isFinite(value)) return "0:00";
    const minutes = Math.floor(value / 60);
    const seconds = Math.floor(value % 60).toString().padStart(2, "0");
    return `${minutes}:${seconds}`;
  };

  const togglePlayback = async () => {
    const audio = audioRef.current;
    if (!audio) return;

    if (audio.paused) {
      await audio.play().catch((error) => console.warn("Music play failed", error));
    } else {
      audio.pause();
    }
  };

  const seekBy = (amount) => {
    const audio = audioRef.current;
    if (!audio) return;
    audio.currentTime = Math.min(Math.max((audio.currentTime || 0) + amount, 0), audio.duration || Infinity);
  };

  const selectQueueTrack = (index, queue = playbackQueue, shuffled = queueShuffled) => {
    if (!queue.length || typeof onTrackChange !== "function") return;
    const normalizedIndex = (index + queue.length) % queue.length;
    onTrackChange({
      ...queue[normalizedIndex],
      playbackQueue: queue,
      originalPlaybackQueue,
      queueIndex: normalizedIndex,
      queueShuffled: shuffled,
    });
  };

  const advanceQueue = (direction = 1, fromEnded = false) => {
    if (fromEnded && repeatMode === "one" && audioRef.current) {
      audioRef.current.currentTime = 0;
      audioRef.current.play().catch(() => {});
      return;
    }
    const nextIndex = queueIndex + direction;
    if (nextIndex >= 0 && nextIndex < playbackQueue.length) {
      selectQueueTrack(nextIndex);
      return;
    }
    if (repeatMode === "all" && playbackQueue.length) {
      selectQueueTrack(direction > 0 ? 0 : playbackQueue.length - 1);
      return;
    }
    if (!fromEnded) seekBy(direction > 0 ? 10 : -10);
  };

  const shuffleQueue = () => {
    if (playbackQueue.length < 2 || typeof onTrackChange !== "function") return;
    const current = playbackQueue[queueIndex];
    if (queueShuffled) {
      const currentKey = String(current?.id || current?.path || current?.audioFile?.path || "");
      const restoredIndex = Math.max(0, originalPlaybackQueue.findIndex((candidate) =>
        String(candidate?.id || candidate?.path || candidate?.audioFile?.path || "") === currentKey
      ));
      selectQueueTrack(restoredIndex, originalPlaybackQueue, false);
      return;
    }
    const remaining = playbackQueue.filter((_, index) => index !== queueIndex);
    for (let index = remaining.length - 1; index > 0; index -= 1) {
      const swapIndex = Math.floor(Math.random() * (index + 1));
      [remaining[index], remaining[swapIndex]] = [remaining[swapIndex], remaining[index]];
    }
    const shuffled = [current, ...remaining];
    onTrackChange({ ...current, playbackQueue: shuffled, originalPlaybackQueue, queueIndex: 0, queueShuffled: true });
  };

  const handleProgressInput = (event) => {
    const audio = audioRef.current;
    const nextTime = Number(event.target.value);
    setCurrentTime(nextTime);
    if (audio) audio.currentTime = nextTime;
  };

  useEffect(() => {
    setCurrentTime(0);
    setDuration(0);
    setIsPlaying(false);
    setPlayError("");
    setLyricsText("");
  }, [progressKey]);

  useEffect(() => {
    if (activePanel !== "lyrics" || isAudiobook) return;
    const inlineLyrics = String(track?.lyrics || track?.metadata?.lyrics || "").trim();
    if (inlineLyrics) {
      setLyricsText(inlineLyrics);
      return;
    }
    if (!track?.lyricsFile) {
      setLyricsText("No lyrics file was found beside this track.");
      return;
    }
    let cancelled = false;
    setLyricsLoading(true);
    fetch(getPlayableMediaUrl(track.lyricsFile))
      .then((response) => response.ok ? response.text() : Promise.reject(new Error("Lyrics unavailable")))
      .then((value) => {
        if (!cancelled) setLyricsText(String(value || "").replace(/^\[[0-9:.]+\]\s*/gm, "").trim() || "The lyrics file is empty.");
      })
      .catch(() => { if (!cancelled) setLyricsText("Lyrics could not be loaded."); })
      .finally(() => { if (!cancelled) setLyricsLoading(false); });
    return () => { cancelled = true; };
  }, [activePanel, progressKey, isAudiobook, track?.lyricsFile, track?.lyrics]);

  useEffect(() => {
    if (!track || !audioUrl || !audioRef.current) return;

    const audio = audioRef.current;
    audio.load();

    const playPromise = audio.play();
    if (playPromise?.catch) {
      playPromise.catch((error) => {
        console.warn("Music autoplay failed", error);
        setPlayError("Tap play to start this track.");
      });
    }
  }, [track, audioUrl]);

  useEffect(() => {
    if (!track || !audioUrl) return;

    if ("mediaSession" in navigator) {
      navigator.mediaSession.metadata = new MediaMetadata({
        title,
        artist,
        album,
        artwork: poster
          ? [
              { src: poster, sizes: "512x512", type: "image/jpeg" },
            ]
          : [],
      });

      navigator.mediaSession.setActionHandler?.("play", () => audioRef.current?.play());
      navigator.mediaSession.setActionHandler?.("pause", () => audioRef.current?.pause());
      navigator.mediaSession.setActionHandler?.("seekbackward", () => seekBy(-10));
      navigator.mediaSession.setActionHandler?.("seekforward", () => seekBy(10));
      navigator.mediaSession.setActionHandler?.("previoustrack", () => advanceQueue(-1));
      navigator.mediaSession.setActionHandler?.("nexttrack", () => advanceQueue(1));
    }
  }, [track, audioUrl, title, artist, album, poster]);

  if (!track) return null;

  return (
    <>
      <div className="homestead-audio-mini" role="region" aria-label="Music player">
        <button className="homestead-audio-mini-info" type="button" onClick={() => setExpanded(true)}>
          <div className="homestead-audio-art">
            <img
              src={poster}
              alt=""
              onError={(event) => {
                event.currentTarget.style.display = "none";
              }}
            />
            <span>🎵</span>
          </div>

          <div className="homestead-audio-track-text">
            <strong>{title}</strong>
            <span>{artist}</span>
          </div>
        </button>

        <div className="homestead-audio-mini-controls">
          <button type="button" onClick={() => advanceQueue(-1)} aria-label="Previous track">⏮</button>
          <button type="button" className="homestead-audio-play" onClick={togglePlayback} aria-label={isPlaying ? "Pause" : "Play"}>
            {isPlaying ? "⏸" : "▶"}
          </button>
          <button type="button" onClick={() => advanceQueue(1)} aria-label="Next track">⏭</button>
        </div>

        <div className="homestead-audio-mini-progress" aria-hidden="true">
          <span style={{ width: `${progressPercent}%` }} />
        </div>

        {playError && (
          <div className="homestead-audio-inline-error">
            {playError}
          </div>
        )}

        <button className="homestead-audio-close" type="button" onClick={onClose} aria-label="Close music player">
          ✕
        </button>
      </div>

      {expanded && (
        <div className="homestead-audio-expanded-overlay" onClick={() => setExpanded(false)}>
          <div className={`homestead-audio-expanded ${activePanel ? "panel-open" : ""}`} onClick={(event) => event.stopPropagation()}>
            <div className="homestead-audio-bg" style={{ backgroundImage: `url(${poster})` }} />

            <div className="homestead-audio-expanded-topbar">
              <button type="button" onClick={() => setExpanded(false)} aria-label="Collapse player">⌄</button>
              <span>Now Playing</span>
              <button type="button" onClick={onClose} aria-label="Close music player">✕</button>
            </div>

            <div className="homestead-audio-expanded-art">
              <img
                src={poster}
                alt=""
                onError={(event) => {
                  event.currentTarget.style.display = "none";
                }}
              />
              <span>🎵</span>
            </div>

            <div className="homestead-audio-expanded-info">
              <h2>{title}</h2>
              <p>{artist}</p>
              <span>{album}</span>
            </div>

            <div className="homestead-audio-seek-row">
              <span>{formatTime(currentTime)}</span>
              <input
                type="range"
                min="0"
                max={duration || 0}
                value={Math.min(currentTime, duration || 0)}
                onChange={handleProgressInput}
                aria-label="Track progress"
              />
              <span>{formatTime(duration)}</span>
            </div>

            <div className="homestead-audio-expanded-controls">
              <button type="button" onClick={shuffleQueue} aria-label={queueShuffled ? "Restore queue order" : "Shuffle queue"} className={queueShuffled ? "active" : ""}>🔀</button>
              <button type="button" onClick={() => advanceQueue(-1)} aria-label="Previous track">⏮</button>
              <button type="button" className="homestead-audio-expanded-play" onClick={togglePlayback} aria-label={isPlaying ? "Pause" : "Play"}>
                {isPlaying ? "⏸" : "▶"}
              </button>
              <button type="button" onClick={() => advanceQueue(1)} aria-label="Next track">⏭</button>
              <button type="button" className={repeatMode !== "off" ? "active" : ""} onClick={() => setRepeatMode((current) => current === "off" ? "all" : current === "all" ? "one" : "off")} aria-label={`Repeat ${repeatMode}`}>{repeatMode === "one" ? "🔂" : "🔁"}</button>
            </div>

            <div className="homestead-audio-expanded-actions">
              <button type="button" className={activePanel === "queue" ? "active" : ""} onClick={() => setActivePanel((current) => current === "queue" ? "" : "queue")}>Queue</button>
              <button type="button" className={activePanel === "lyrics" ? "active" : ""} onClick={() => setActivePanel((current) => current === "lyrics" ? "" : "lyrics")}>{isAudiobook ? "Chapters" : "Lyrics"}</button>
              {isAudiobook && <button type="button" className={activePanel === 'read-along' ? 'active' : ''} onClick={() => setActivePanel((current) => current === 'read-along' ? '' : 'read-along')}>Read Along</button>}
            </div>

            {isAudiobook && activePanel === 'read-along' && <div className="homestead-read-along-panel">
              {ebookFiles.length > 1 && <label>Edition <select value={ebookIndex} onChange={(event) => setEbookIndex(Number(event.target.value))}>{ebookFiles.map((file, index) => <option key={file.path || index} value={index}>{file.name || `Edition ${index + 1}`}</option>)}</select></label>}
              {ebookFiles.length ? <BookReader compact file={ebookFiles[ebookIndex] || ebookFiles[0]} book={readAlongBook} onClose={() => setActivePanel('')} /> : <p>No paired EPUB or PDF is available for this audiobook. Add the matching ebook to this book's folder and scan Books.</p>}
            </div>}

            {activePanel === "queue" && (
              <div className="homestead-audio-panel" aria-label="Playback queue">
                <h3>Up Next</h3>
                {playbackQueue.map((queuedTrack, index) => (
                  <button key={`${queuedTrack.id || queuedTrack.path || queuedTrack.audioFile?.path || index}`} className={index === queueIndex ? "active" : ""} type="button" onClick={() => selectQueueTrack(index)}>
                    <span>{index === queueIndex ? "▶" : String(index + 1).padStart(2, "0")}</span>
                    <div><strong>{(isAudiobook && queuedTrack.chapterTitle) || queuedTrack.title || queuedTrack.name || `Track ${index + 1}`}</strong><small>{queuedTrack.artist || queuedTrack.album || ""}</small></div>
                  </button>
                ))}
              </div>
            )}

            {activePanel === "lyrics" && (
              <div className="homestead-audio-panel homestead-audio-lyrics" aria-label={isAudiobook ? "Audiobook chapters" : "Lyrics"}>
                <h3>{isAudiobook ? "Chapters" : "Lyrics"}</h3>
                {isAudiobook ? playbackQueue.map((chapter, index) => (
                  <button key={`${chapter.id || chapter.path || chapter.audioFile?.path || index}`} className={index === queueIndex ? "active" : ""} type="button" onClick={() => selectQueueTrack(index)}>
                    <span>{index + 1}</span><div><strong>{chapter.chapterTitle || chapter.title || chapter.name || `Chapter ${index + 1}`}</strong></div>
                  </button>
                )) : <pre>{lyricsLoading ? "Loading lyrics…" : lyricsText || "No lyrics available."}</pre>}
              </div>
            )}
          </div>
        </div>
      )}

      {audioUrl ? (
        <audio
          key={progressKey}
          ref={audioRef}
          autoPlay
          src={audioUrl}
          onPlay={() => setIsPlaying(true)}
          onPause={() => setIsPlaying(false)}
          onLoadedMetadata={(event) => {
            const audio = event.currentTarget;
            const progress = getWatchProgress()[progressKey];
            setDuration(audio.duration || 0);
            if ("mediaSession" in navigator && Number.isFinite(audio.duration) && audio.duration > 0) {
              navigator.mediaSession.setPositionState?.({ duration: audio.duration, playbackRate: audio.playbackRate || 1, position: Math.min(audio.currentTime || 0, audio.duration) });
            }
            if (progress?.currentTime) {
              audio.currentTime = progress.currentTime;
              setCurrentTime(progress.currentTime);
            }
          }}
          onTimeUpdate={(event) => {
            const audio = event.currentTarget;
            setCurrentTime(audio.currentTime || 0);
            setDuration(audio.duration || 0);
            if ("mediaSession" in navigator && Number.isFinite(audio.duration) && audio.duration > 0) {
              navigator.mediaSession.setPositionState?.({ duration: audio.duration, playbackRate: audio.playbackRate || 1, position: Math.min(audio.currentTime || 0, audio.duration) });
            }
            saveWatchProgress(progressKey, {
              type: isAudiobook ? "audiobook" : "music",
              bookId: readAlongBook?.id,
              title,
              artist,
              album,
              poster,
              path: progressKey,
              currentTime: audio.currentTime,
              duration: audio.duration || 0,
            });
          }}
          onEnded={() => advanceQueue(1, true)}
          onError={(event) => {
            console.error("Music failed:", event.currentTarget.src);
            setPlayError("Unable to play this file. Check the file path or format.");
          }}
        />
      ) : (
        <div className="homestead-audio-error">No playable audio URL found for this track.</div>
      )}
    </>
  );
}

function ImageViewer({ viewer, onClose, setViewer, slideshow, setSlideshow }) {
  const [showOptions, setShowOptions] = useState(false);
  const [viewerActionStatus, setViewerActionStatus] = useState("");
  const [fitMode, setFitMode] = useState("contain");
  const [transition, setTransition] = useState("fade");
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [imageLoadFailed, setImageLoadFailed] = useState(false);
  const isOpen = Boolean(viewer?.files?.length);
  const file = isOpen ? viewer.files[viewer.index] : null;

  function fileUrl(file) {
    return getPlayableMediaUrl(file, { width: 2560, quality: 88 });
  }

  const closeViewer = () => {
    setSlideshow?.({ active: false, speed: 5000 });
    setShowOptions(false);
    setIsFullscreen(false);
    if (document.fullscreenElement) {
      document.exitFullscreen?.().catch?.(() => {});
    }
    onClose?.();
  };

  const goPrev = () => {
    setViewer((current) => {
      if (!current?.files?.length) return current;
      return {
        ...current,
        index: current.index === 0 ? current.files.length - 1 : current.index - 1,
      };
    });
  };

  const goNext = () => {
    setViewer((current) => {
      if (!current?.files?.length) return current;
      return {
        ...current,
        index: current.index === current.files.length - 1 ? 0 : current.index + 1,
      };
    });
  };

  const setSlideshowSpeed = (speed) => {
    setSlideshow?.((current) => ({
      active: current?.active || false,
      speed,
    }));
  };

  useEffect(() => {
    if (!isOpen || !slideshow?.active) return;

    const timer = setInterval(() => {
      setViewer((current) => {
        if (!current?.files?.length) return current;
        return {
          ...current,
          index: current.index === current.files.length - 1 ? 0 : current.index + 1,
        };
      });
    }, slideshow.speed || 5000);

    return () => clearInterval(timer);
  }, [isOpen, slideshow?.active, slideshow?.speed, setViewer]);

  useEffect(() => {
    if (!isOpen) return;

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    const handleKeyDown = (event) => {
      if (event.key === "Escape") closeViewer();
      if (event.key === "ArrowLeft") goPrev();
      if (event.key === "ArrowRight") goNext();
      if (event.key === " ") {
        event.preventDefault();
        setSlideshow?.((current) => ({
          active: !current?.active,
          speed: current?.speed || 5000,
        }));
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => {
      document.body.style.overflow = previousOverflow;
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen) {
      setIsFullscreen(false);
      return;
    }

    const handleFullscreenChange = () => {
      setIsFullscreen(Boolean(document.fullscreenElement));
    };

    document.addEventListener("fullscreenchange", handleFullscreenChange);
    return () => document.removeEventListener("fullscreenchange", handleFullscreenChange);
  }, [isOpen]);

  useEffect(() => {
    setViewerActionStatus("");
    setImageLoadFailed(false);
  }, [viewer?.index, file?.path, file?.sourcePath, file?.name]);

  if (!isOpen || !file) return null;

  const isVideo = file.type === "video" || /\.(mp4|mkv|webm|mov|m4v)$/i.test(file.name || file.path || "");
  const adultArtworkActions = file?.adultArtworkActions;
  const canSetAdultArtwork = Boolean(adultArtworkActions?.enabled && adultArtworkActions?.selectionMode && !isVideo);
  const speed = slideshow?.speed || 5000;

  const setAdultArtworkFromViewer = async (action) => {
    if (!canSetAdultArtwork) return;
    setViewerActionStatus(action === "banner" ? "Setting banner…" : "Setting poster…");
    try {
      await adultArtworkActions.onAction?.(action, file);
      setViewerActionStatus(action === "banner" ? "Banner updated." : "Poster updated.");
    } catch (error) {
      setViewerActionStatus(error?.message || "Could not update artwork.");
    }
  };

  const toggleFullscreen = async (event) => {
    const target = event?.currentTarget?.closest?.(".image-viewer-shell") || document.documentElement;

    if (document.fullscreenElement) {
      await document.exitFullscreen?.().catch?.(() => {});
      setIsFullscreen(false);
      return;
    }

    // iOS/Safari may not support requestFullscreen on normal divs.
    // Always toggle a CSS fullscreen mode so the button visibly works,
    // then use the native Fullscreen API when the browser allows it.
    setIsFullscreen(true);
    await target?.requestFullscreen?.().catch?.(() => {});
  };

  return createPortal(
    <div className={`image-viewer-backdrop image-viewer-transition-${transition}`} onClick={closeViewer}>
      <div className={`image-viewer-shell ${isFullscreen ? "image-viewer-shell-fullscreen" : ""}`} onClick={(event) => event.stopPropagation()}>
        <div className="image-viewer-topbar">
          <div>
            <strong>{file.name || "Image"}</strong>
            <span>{viewer.index + 1} / {viewer.files.length}</span>
          </div>

          <div className="image-viewer-actions image-viewer-actions-close-only">
            <button type="button" className="image-viewer-close" onClick={closeViewer} aria-label="Close image viewer">
              ✕
            </button>
          </div>
        </div>

        {showOptions && (
          <div className="image-viewer-options-panel">
            <label>
              <span>Speed</span>
              <select value={speed} onChange={(event) => setSlideshowSpeed(Number(event.target.value))}>
                <option value={2000}>2 seconds</option>
                <option value={3000}>3 seconds</option>
                <option value={5000}>5 seconds</option>
                <option value={10000}>10 seconds</option>
                <option value={15000}>15 seconds</option>
              </select>
            </label>

            <label>
              <span>Transition</span>
              <select value={transition} onChange={(event) => setTransition(event.target.value)}>
                <option value="fade">Fade</option>
                <option value="slide">Slide</option>
                <option value="zoom">Zoom</option>
                <option value="none">None</option>
              </select>
            </label>

            <label>
              <span>Fit</span>
              <select value={fitMode} onChange={(event) => setFitMode(event.target.value)}>
                <option value="contain">Contain</option>
                <option value="cover">Cover</option>
                <option value="actual">Actual size</option>
              </select>
            </label>
          </div>
        )}

        <button type="button" className="image-viewer-nav left" onClick={goPrev} aria-label="Previous image">
          ‹
        </button>

        {isVideo ? (
          <video
            className="image-viewer-video"
            src={fileUrl(file)}
            controls
            autoPlay
          />
        ) : imageLoadFailed ? (
          <div className="image-viewer-load-error" role="status">
            <span>Image preview unavailable</span>
            <small>The original file is unchanged. Continue to the next image or try again after the preview cache is rebuilt.</small>
            <button type="button" className="secondary-button" onClick={goNext}>Next image</button>
          </div>
        ) : (
          <img
            key={`${file.path || file.sourcePath || file.name}-${viewer.index}`}
            className={`image-viewer-image image-viewer-fit-${fitMode}`}
            src={fileUrl(file)}
            alt={file.name || ""}
            onError={() => setImageLoadFailed(true)}
          />
        )}

        <button type="button" className="image-viewer-nav right" onClick={goNext} aria-label="Next image">
          ›
        </button>

        {(canSetAdultArtwork || viewerActionStatus) && (
          <div className="image-viewer-artwork-dock">
            {viewerActionStatus && <span>{viewerActionStatus}</span>}
            {canSetAdultArtwork && (
              <>
                <button type="button" disabled={adultArtworkActions.loading} onClick={() => setAdultArtworkFromViewer("poster")}>Set Poster</button>
                <button type="button" disabled={adultArtworkActions.loading} onClick={() => setAdultArtworkFromViewer("banner")}>Set Banner</button>
              </>
            )}
          </div>
        )}

        <div className="image-viewer-bottombar">
          <button type="button" onClick={goPrev} aria-label="Previous image" title="Previous">‹</button>
          <button
            type="button"
            aria-label={slideshow?.active ? "Pause slideshow" : "Play slideshow"}
            title={slideshow?.active ? "Pause slideshow" : "Play slideshow"}
            onClick={() => {
              setSlideshow((current) => ({
                active: !current?.active,
                speed: current?.speed || 5000,
              }));
            }}
          >
            {slideshow?.active ? "⏸" : "▶"}
          </button>
          <button type="button" onClick={goNext} aria-label="Next image" title="Next">›</button>
          <button type="button" onClick={toggleFullscreen} aria-label={isFullscreen ? "Exit full screen" : "Full screen"} title={isFullscreen ? "Exit full screen" : "Full screen"}>⛶</button>
          <button type="button" onClick={() => setShowOptions((value) => !value)} aria-label="Options" title="Options">⚙</button>
        </div>
      </div>
    </div>,
    document.body
  );
}


