  const [tcgBatchStats, setTcgBatchStats] = useState({ scanned: 0, added: 0, skipped: 0, needsReview: 0 });
  const [tcgRecentItems, setTcgRecentItems] = useState([]);
  const [mediaBatchMode, setMediaBatchMode] = useState(false);
  const [mediaBatchStats, setMediaBatchStats] = useState({ scanned: 0, added: 0, skipped: 0, needsReview: 0 });
  const [mediaRecentItems, setMediaRecentItems] = useState([]);
  const [mediaLookupBusy, setMediaLookupBusy] = useState(false);
  const [mediaLookupMessage, setMediaLookupMessage] = useState("");
  const [mediaProduct, setMediaProduct] = useState(null);
  const [mediaMatches, setMediaMatches] = useState([]);
  const [mediaSelectedMatch, setMediaSelectedMatch] = useState(null);
  const [mediaFormat, setMediaFormat] = useState("DVD");
