function ElectronicsSearchPanel({ onCreated }) {
  const [query, setQuery] = useState("");
  const [barcode, setBarcode] = useState("");
  const [results, setResults] = useState([]);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const [selected, setSelected] = useState(null);
  const [details, setDetails] = useState({
    serialNumber: "",
    condition: "Used - Good",
    location: "",
    purchasePrice: "",
  });

  async function searchElectronics(event) {
    event?.preventDefault?.();
    if (busy || (!query.trim() && !barcode.trim())) return;
    setBusy(true);
    setMessage("Searching product sources…");
    setResults([]);
    try {
      const response = await fetch("/api/intake/electronics/search", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query: query.trim(), barcode: barcode.trim() }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || data.ok === false) throw new Error(data.message || "Electronics search failed.");
      setResults(Array.isArray(data.results) ? data.results : []);
      setMessage(data.results?.length ? `${data.results.length} candidate${data.results.length === 1 ? "" : "s"} found.` : "No candidates found. Try a model number or barcode.");
    } catch (error) {
      setMessage(error.message || "Electronics search failed.");
    } finally {
      setBusy(false);
    }
  }

  async function addSelected() {
    if (!selected || busy) return;
    setBusy(true);
    setMessage("Adding electronics item…");
    try {
      const response = await fetch("/api/intake/electronics/add", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ candidate: selected, ...details }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || data.ok === false) throw new Error(data.message || "Unable to add electronics item.");
      setMessage(`${data.record?.title || "Electronics item"} added.`);
      setSelected(null);
      setResults([]);
      setQuery("");
      setBarcode("");
      onCreated?.(data.record);
    } catch (error) {
      setMessage(error.message || "Unable to add electronics item.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className="panel electronics-v1-search">
      <div className="electronics-v1-heading">
        <div>
          <h3>Find an electronics item</h3>
          <p>Scan a UPC/EAN or search by brand, product name, or manufacturer model number. Confirm the exact result before adding it.</p>
        </div>
      </div>

      <form className="electronics-v1-searchbar" onSubmit={searchElectronics}>
        <label>
          <span>Barcode</span>
          <input value={barcode} onChange={(event) => setBarcode(event.target.value)} inputMode="numeric" placeholder="UPC or EAN" />
        </label>
        <label className="wide">
          <span>Product or model</span>
          <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Sony WH-1000XM5, model number…" />
        </label>
        <button className="primary-button" type="submit" disabled={busy || (!query.trim() && !barcode.trim())}>
          {busy ? "Searching…" : "Search sources"}
        </button>
      </form>

      {message && <p className="electronics-v1-message">{message}</p>}

      {results.length > 0 && (
        <div className="electronics-v1-results">
          {results.map((result) => (
            <button
              key={result.id}
              type="button"
              className={selected?.id === result.id ? "selected" : ""}
              onClick={() => setSelected(result)}
            >
              <div className="electronics-v1-result-image">
                {result.image ? <img src={result.image} alt="" /> : <span>💻</span>}
              </div>
              <div>
                <strong>{result.title}</strong>
                <small>{[result.brand, result.model, result.condition].filter(Boolean).join(" · ") || result.source}</small>
                <em>{result.source} · {Math.round(Number(result.confidence || 0) * 100)}% match</em>
              </div>
              {Number(result.price || 0) > 0 && <b>${Number(result.price).toFixed(2)}</b>}
            </button>
          ))}
        </div>
      )}

      {selected && (
        <div className="electronics-v1-confirm">
          <div>
            <strong>Selected: {selected.title}</strong>
            <small>{selected.model || selected.brand || selected.source}</small>
          </div>
          <label><span>Serial number</span><input value={details.serialNumber} onChange={(event) => setDetails((current) => ({ ...current, serialNumber: event.target.value }))} /></label>
          <label><span>Condition</span><select value={details.condition} onChange={(event) => setDetails((current) => ({ ...current, condition: event.target.value }))}><option>New</option><option>Open Box</option><option>Used - Like New</option><option>Used - Good</option><option>Used - Fair</option><option>For Parts</option></select></label>
          <label><span>Location</span><input value={details.location} onChange={(event) => setDetails((current) => ({ ...current, location: event.target.value }))} placeholder="Office shelf…" /></label>
          <label><span>Purchase price</span><input type="number" min="0" step="0.01" value={details.purchasePrice} onChange={(event) => setDetails((current) => ({ ...current, purchasePrice: event.target.value }))} /></label>
          <button className="primary-button" type="button" disabled={busy} onClick={addSelected}>Add selected item</button>
        </div>
      )}
    </section>
  );
}

