function YouTubeCreatorDiscoveryPage({ creator, onBack }) {
  const [playlists, setPlaylists] = useState([]);

  useEffect(() => {
    fetch(`/api/youtube/channel/${creator.id}/playlists`)
      .then((res) => res.json())
      .then((data) => {
        setPlaylists(data.playlists || []);
      })
      .catch((err) => {
        console.error("Failed to load YouTube playlists:", err);
      });
  }, [creator.id]);

  async function markWanted(playlist) {
    try {
      const res = await fetch(
        "/api/integrations/tubearchivist/download-playlist",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            playlistUrl: playlist.playlistUrl,
            playlist,
          }),
        }
      );

      const data = await res.json();

if (
  !res.ok ||
  (data.ok === false) ||
  (data.connected === false)
) {
  throw new Error(
    data.message ||
    data.error ||
    "Connection failed"
  );
}

      alert(`Marked ${playlist.title} as wanted.`);
    } catch (err) {
      alert(`Failed: ${err.message}`);
    }
  }

  return (
    <div className="generic-page">
      <button className="secondary-button" type="button" onClick={onBack}>
        ← Back
      </button>

      <div className="panel">
        <h2>{creator.title}</h2>
        <p>YouTube Creator Discovery</p>
      </div>

      <div className="settings-toggle-grid">
        {playlists.map((playlist) => (
          <div key={playlist.playlistId} className="settings-toggle-card">
            <strong>{playlist.title}</strong>
            <p>{playlist.videoCount} Videos</p>

            <button
              className="secondary-button"
              type="button"
              onClick={() => markWanted(playlist)}
            >
              Mark Wanted
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}


function getAdultSourceFaviconUrl(source = {}) {
  const explicit = source.iconUrl || source.faviconUrl || source.favicon || source.logoUrl || source.logo;
  if (explicit && /^https?:\/\//i.test(String(explicit))) return explicit;

  const base = source.baseUrl || source.url || source.searchUrlTemplate || source.urlTemplate || "";
  try {
    const parsed = new URL(String(base));
    return `https://www.google.com/s2/favicons?domain=${parsed.hostname}&sz=64`;
  } catch {
    return "";
  }
}

function AdultSourceIcon({ source = {}, className = "adult-source-favicon" }) {
  const [failed, setFailed] = useState(false);
  const faviconUrl = !failed ? getAdultSourceFaviconUrl(source) : "";

  if (faviconUrl) {
    return (
      <img
        className={className}
        src={faviconUrl}
        alt={`${source.name || source.source || "Source"} icon`}
        loading="lazy"
        referrerPolicy="no-referrer"
        onError={() => setFailed(true)}
      />
    );
  }

  return <span className={`${className} adult-source-favicon-fallback`}>{source.icon || "🌐"}</span>;
}


// GLOBAL_ADULT_METADATA_JSON_HELPER

async function readAdultMetadataJson(response, actionLabel = "Adult metadata request") {
  const text = await response.text();
  if (!text) return {};

  try {
    return JSON.parse(text);
  } catch (error) {
    const compact = text.replace(/\s+/g, " ").slice(0, 180);
    const looksLikeHtml = /^\s*</.test(text) || /<!doctype|<html|<body/i.test(text);
    if (looksLikeHtml) {
      throw new Error(`${actionLabel} returned the Homestead HTML app instead of JSON. Restart the Homestead server/container and confirm the matching server.cjs file is installed.`);
    }
    throw new Error(`${actionLabel} returned invalid JSON: ${compact}`);
  }
}

function AdultSourceBrowserOverlay({ sourceBrowser, onClose, onOpenExternal, backLabel = "← Back", titleFallback = "Provider search" }) {
  const [tryEmbed, setTryEmbed] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const [importForm, setImportForm] = useState({
    url: sourceBrowser?.url || "",
    targetLibrary: "performers",
    profileName: "",
    importType: "photo",
    sourceName: sourceBrowser?.source || sourceBrowser?.title || sourceBrowser?.name || "provider",
  });
  const [importStatus, setImportStatus] = useState("");
  const [importing, setImporting] = useState(false);
  const label = sourceBrowser?.source || sourceBrowser?.title || sourceBrowser?.name || "Source";
  const subtitle = sourceBrowser?.adaptationNote || sourceBrowser?.subtitle || titleFallback;
  const url = sourceBrowser?.url || "";

  function handleExternal() {
    if (typeof onOpenExternal === "function") {
      onOpenExternal(sourceBrowser);
      return;
    }

    if (url) window.open(url, "_blank", "noopener,noreferrer");
  }

  function updateImportField(name, value) {
    setImportForm((current) => ({ ...current, [name]: value }));
  }

  async function submitAdultImport(event) {
    event?.preventDefault?.();
    setImporting(true);
    setImportStatus("Importing URL through Homestead server…");

    try {
      const response = await fetch("/api/adult/import-url", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(importForm),
      });
      const data = await readAdultMetadataJson(response, "Adult URL import");

      if (!response.ok || !data.ok) {
        throw new Error(data.error || data.message || "Import failed");
      }

      const scanMessage = data.scanRequested
        ? ` Library scan queued${data.scanLibrary ? ` for ${data.scanLibrary}` : ""}.`
        : "";
      setImportStatus(`${data.message || `Saved to ${data.relativeDestination || data.destination}`}${scanMessage}`.trim());
      window.dispatchEvent(new CustomEvent("homestead-adult-media-imported", { detail: data }));
      if (["poster", "banner"].includes(importForm.importType)) {
        window.dispatchEvent(new Event("homestead-metadata-match-updated"));
      }
      updateImportField("url", "");
    } catch (error) {
      setImportStatus(error.message || "Import failed");
    } finally {
      setImporting(false);
    }
  }

  return (
    <div className="adult-source-browser-overlay" role="dialog" aria-modal="true">
      <div className="adult-source-browser-topbar">
        <button className="secondary-button" type="button" onClick={onClose}>{backLabel}</button>
        <div className="adult-source-browser-title">
          <span>{label}</span>
          <strong>{subtitle}</strong>
          <code>{url}</code>
        </div>
        <div className="adult-source-browser-actions">
          <button className="secondary-button" type="button" onClick={() => setShowImport(true)}>Import</button>
          <button className="secondary-button" type="button" onClick={handleExternal}>Open External</button>
          <button className="image-viewer-close" type="button" onClick={onClose}>×</button>
        </div>
      </div>

      <div className="adult-source-browser-frame-wrap">
        {!tryEmbed ? (
          <div className="adult-source-browser-blocked-card">
            <div className="adult-source-browser-blocked-icon">↗</div>
            <h2>{label} blocks embedded viewing</h2>
            <p>
              Homestead can open the provider externally, import a direct image/video URL, or pull images from a supported gallery page into the selected profile folder.
              Photos save to /photos, nude/adult sets save to /nudes, and source attribution is tracked in metadata.
            </p>
            <code>{url}</code>
            <div className="adult-source-browser-blocked-actions">
              <button className="secondary-button" type="button" onClick={() => setShowImport(true)}>Import URL / Gallery</button>
              <button className="secondary-button" type="button" onClick={handleExternal}>Open External</button>
              <button className="secondary-button" type="button" onClick={() => setTryEmbed(true)}>Try Embedded Anyway</button>
            </div>
          </div>
        ) : (
          <>
            <iframe
              className="adult-source-browser-frame"
              title={`${label} search`}
              src={url}
              sandbox="allow-same-origin allow-scripts allow-forms allow-popups allow-popups-to-escape-sandbox allow-top-navigation-by-user-activation"
              referrerPolicy="no-referrer"
            />
            <div className="adult-source-browser-fallback">
              <strong>This provider may block embedded viewing.</strong>
              <span>If the page stays blank, use Open External. Use Import for a direct image/video URL.</span>
            </div>
          </>
        )}
      </div>

      {showImport && (
        <div className="adult-import-url-overlay" role="dialog" aria-modal="true">
          <form className="adult-import-url-card" onSubmit={submitAdultImport}>
            <div className="adult-import-url-header">
              <div>
                <p>Adult Import</p>
                <h2>Import URL to Homestead</h2>
                <span>Paste a direct image/video URL, supported gallery page URL, or save this provider page as a source reference for a profile.</span>
              </div>
              <button className="adult-profile-modal-close" type="button" onClick={() => setShowImport(false)}>×</button>
            </div>

            <label className="adult-import-url-field adult-import-url-wide">
              <span>Image / video / page URL</span>
              <textarea
                value={importForm.url}
                onChange={(event) => updateImportField("url", event.target.value)}
                rows={3}
                placeholder="Paste direct image/video URL from the provider page…"
              />
            </label>

            <div className="adult-import-url-grid">
              <label className="adult-import-url-field">
                <span>Library</span>
                <select value={importForm.targetLibrary} onChange={(event) => updateImportField("targetLibrary", event.target.value)}>
                  <option value="performers">Performers</option>
                  <option value="celebrities">Celebrities</option>
                  <option value="personal">Personal</option>
                </select>
              </label>
              <label className="adult-import-url-field">
                <span>Profile name</span>
                <input
                  value={importForm.profileName}
                  onChange={(event) => updateImportField("profileName", event.target.value)}
                  placeholder="Riley Reid"
                />
              </label>
              <label className="adult-import-url-field">
                <span>Import as</span>
                <select value={importForm.importType} onChange={(event) => updateImportField("importType", event.target.value)}>
                  <option value="photo">Photo → /photos</option>
                  <option value="nude">Nude/adult set → /nudes</option>
                  <option value="poster">Set as poster → poster.jpg</option>
                  <option value="banner">Set as banner → banner.jpg</option>
                  <option value="scene">Scene video/gallery</option>
                  <option value="source">Source reference only</option>
                </select>
              </label>
              <label className="adult-import-url-field">
                <span>Source</span>
                <input
                  value={importForm.sourceName}
                  onChange={(event) => updateImportField("sourceName", event.target.value)}
                  placeholder="Provider name"
                />
              </label>
            </div>

            {importStatus && <div className="adult-import-url-status">{importStatus}</div>}

            <div className="adult-import-url-actions">
              <button className="secondary-button" type="button" onClick={() => setShowImport(false)}>Cancel</button>
              <button className="secondary-button" type="submit" disabled={importing}>
                {importing ? "Importing…" : "Import to Profile"}
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

function normalizeAdultProfileType(value = "") {
  const normalized = String(value || "performer").toLowerCase();
  const allowed = new Set([
    "performer",
    "celebrity",
    "metadata",
    "media",
    "artwork",
    "studio",
    "general",
    "vr",
    "mature",
    "anime",
    "both",
    "all",
  ]);
  if (["celebrities", "celeb"].includes(normalized)) return "celebrity";
  if (["videos", "scenes"].includes(normalized)) return "media";
  if (["photos", "image", "images"].includes(normalized)) return "artwork";
  if (allowed.has(normalized)) return normalized;
  return "performer";
}

function adultSourceIsPersonSearchSource(source = {}) {
  if (!source || source.status === "disabled") return false;

  const supports = Array.isArray(source.supports) ? source.supports : [];
  const modes = Array.isArray(source.searchModes) ? source.searchModes.map((mode) => normalizeAdultProfileType(mode)) : [];
  const category = String(source.category || "").toLowerCase();
  const badges = Array.isArray(source.badges) ? source.badges.map((badge) => String(badge || "").toLowerCase()) : [];

  const hasIdentitySupport = supports.some((type) => [
    "performermetadata",
    "identifiers",
    "bio",
    "biography",
    "socials",
    "awards",
    "externallinks",
    "publicimage",
    "occupation",
    "credits",
    "timeline",
  ].includes(String(type || "").toLowerCase()));

  const hasPersonCategory = /metadata|bio|biography|profile|identity|agency|model|external id|credits|timeline|scene timeline/.test(category);
  const hasPersonBadge = badges.some((badge) => /metadata|bio|profile|id bridge|credits|timeline/.test(badge));
  const hasPersonMode = modes.some((mode) => ["performer", "celebrity", "metadata"].includes(mode));

  const isGeneralBrowseOnly = /general browse|photo galleries|media\/video only|anime|hentai|source directory/.test(category)
    && !source.supportsFixMatch
    && !source.supportsBulkMetadata
    && !hasIdentitySupport;

  if (isGeneralBrowseOnly) return false;

  return Boolean(
    source.supportsFixMatch ||
    source.supportsBulkMetadata ||
    source.providerIdKey ||
    hasIdentitySupport ||
    hasPersonCategory ||
    hasPersonBadge ||
    hasPersonMode
  );
}

function adultSourceMatchesProfileType(source = {}, profileType = "performer") {
  if (!adultSourceIsPersonSearchSource(source)) return false;

  const wanted = normalizeAdultProfileType(profileType);
  if (["both", "all"].includes(wanted)) return source.status !== "disabled";

  const modes = Array.isArray(source.searchModes) ? source.searchModes.map((mode) => normalizeAdultProfileType(mode)) : [];
  if (modes.includes(wanted)) return true;

  const profileTypes = Array.isArray(source.profileTypes) ? source.profileTypes.map((mode) => normalizeAdultProfileType(mode)) : [];
  const role = normalizeAdultProfileType(source.role || "both");
  if (wanted === "performer" && (profileTypes.includes("performer") || role === "performer" || role === "both")) return true;
  if (wanted === "celebrity" && (profileTypes.includes("celebrity") || role === "celebrity" || role === "both")) return true;

  return false;
}

function adultSourceMatchesBrowseMode(source = {}) {
  if (!source || source.status === "disabled") return false;
  if (source.directProfileOnly || source.supportsFixMatch || source.supportsBulkMetadata) return false;

  const supports = Array.isArray(source.supports) ? source.supports : [];
  const modes = Array.isArray(source.searchModes) ? source.searchModes.map((mode) => normalizeAdultProfileType(mode)) : [];
  const category = String(source.category || "").toLowerCase();

  return Boolean(
    source.supportsArtwork ||
    source.supportsImport ||
    source.supportsScenes ||
    supports.some((type) => ["photos", "photoSets", "images", "artwork", "scenes", "videos", "galleries", "gallery"].includes(type)) ||
    modes.some((mode) => ["general", "media", "artwork", "studio", "vr", "mature", "anime"].includes(mode)) ||
    /browse|photo|gallery|media|tags|studio/.test(category)
  );
}

function getAdultSourceRoleLabel(source = {}) {
  if (source.status === "disabled") return "Disabled";
  if (source.requiresSession) return "Session required";
  if (source.supportsFixMatch) return "Metadata";
  if (source.supportsArtwork && !source.supportsScenes) return "Artwork";
  if (source.supportsScenes || source.supportsImport) return "Media";
  const role = normalizeAdultProfileType(source.role || "both");
  if (role === "celebrity") return "Celebrity only";
  if (role === "performer") return "Performer";
  return "Both";
}

function normalizeAdultDiscoveryMode(value = "person") {
  const normalized = String(value || "person").toLowerCase();
  if (normalized === "browse") return "browse";
  if (normalized === "photo" || normalized === "face") return "photo";
  return "person";
}


function getAdultProviderRecommendationLabel(value = "") {
  if (value === "internal-browse") return "Internal Browse";
  if (value === "internal-preview") return "Internal Preview";
  if (value === "embed-preview") return "Embedded Preview";
  return "External Only";
}


