function CoedCherryInternalBrowser({
  source,
  initialUrl,
  onClose,
  onCreateProfile,
}) {
  const [page, setPage] = useState(null);
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedIds, setSelectedIds] = useState([]);
  const [importMode, setImportMode] = useState("");
  const [destination, setDestination] = useState("nude");
  const [profiles, setProfiles] = useState([]);
  const [profileId, setProfileId] = useState("");
  const [importing, setImporting] = useState(false);
  const [status, setStatus] = useState("");

  async function loadPage(url, pushHistory = true) {
    setLoading(true);
    setError("");
    setSelectedIds([]);
    setImportMode("");
    try {
      const response = await fetch("/api/discovery/adult/internal-browse", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ sourceId: source.id, url }),
      });
      const data = await response.json();
      if (!response.ok || !data.ok) throw new Error(data.message || "Unable to browse provider.");
      if (pushHistory && page?.url) setHistory((current) => [...current, page.url]);
      setPage(data.page);
    } catch (loadError) {
      setError(loadError.message || "Unable to browse provider.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadPage(initialUrl, false);
  }, [initialUrl]);

  useEffect(() => {
    if (importMode !== "existing") return;
    let cancelled = false;
    Promise.all(
      ["personal", "performers", "celebrities"].map(async (library) => {
        const response = await fetch(`/api/adult/profile-headshots?library=${encodeURIComponent(library)}`);
        const data = await response.json().catch(() => ({}));
        return (data.profiles || []).map((profile) => ({ ...profile, library }));
      })
    ).then((groups) => {
      if (!cancelled) setProfiles(groups.flat().sort((a, b) => String(a.name).localeCompare(String(b.name))));
    }).catch(() => {
      if (!cancelled) setProfiles([]);
    });
    return () => { cancelled = true; };
  }, [importMode]);

  function toggleSelection(itemId) {
    setSelectedIds((current) => current.includes(itemId)
      ? current.filter((id) => id !== itemId)
      : [...current, itemId]);
  }

  function toggleSelectAll() {
    const visibleIds = (page?.items || []).map((item) => item.id).filter(Boolean);
    const allSelected = visibleIds.length > 0 && visibleIds.every((id) => selectedIds.includes(id));
    setSelectedIds(allSelected ? [] : visibleIds);
  }

  async function loadMore() {
    if (!page?.nextPageUrl || loadingMore) return;
    setLoadingMore(true);
    setStatus("Loading more results…");
    try {
      const response = await fetch("/api/discovery/adult/internal-browse", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ sourceId: source.id, url: page.nextPageUrl }),
      });
      const data = await response.json();
      if (!response.ok || !data.ok) throw new Error(data.message || "Unable to load more results.");
      const incoming = Array.isArray(data.page?.items) ? data.page.items : [];
      setPage((current) => {
        const existing = Array.isArray(current?.items) ? current.items : [];
        const seen = new Set(existing.map((item) => item.id || item.url || item.imageUrl));
        const merged = [...existing, ...incoming.filter((item) => {
          const key = item.id || item.url || item.imageUrl;
          if (!key || seen.has(key)) return false;
          seen.add(key);
          return true;
        })];
        return { ...current, items: merged, nextPageUrl: data.page?.nextPageUrl || "" };
      });
      setStatus(`${incoming.length} more result${incoming.length === 1 ? "" : "s"} loaded.`);
    } catch (loadError) {
      setStatus(loadError.message || "Unable to load more results.");
    } finally {
      setLoadingMore(false);
    }
  }

  async function toggleFullscreen() {
    const card = browserCardRef.current;
    try {
      if (!document.fullscreenElement && card?.requestFullscreen) {
        await card.requestFullscreen();
        setIsFullscreen(true);
      } else if (document.fullscreenElement && document.exitFullscreen) {
        await document.exitFullscreen();
        setIsFullscreen(false);
      } else {
        setIsFullscreen((current) => !current);
      }
    } catch {
      setIsFullscreen((current) => !current);
    }
  }

  useEffect(() => {
    function syncFullscreen() {
      setIsFullscreen(Boolean(document.fullscreenElement));
    }
    document.addEventListener("fullscreenchange", syncFullscreen);
    return () => document.removeEventListener("fullscreenchange", syncFullscreen);
  }, []);

  const selectedItems = useMemo(
    () => (page?.items || []).filter((item) => selectedIds.includes(item.id)),
    [page, selectedIds]
  );

  async function importToExisting() {
    const profile = profiles.find((entry) => String(entry.id) === String(profileId));
    if (!profile || !selectedItems.length) return;
    setImporting(true);
    setStatus(`Importing ${selectedItems.length} photo${selectedItems.length === 1 ? "" : "s"}…`);
    let imported = 0;
    const failures = [];

    for (const item of selectedItems) {
      try {
        const response = await fetch("/api/adult/import-url", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            targetLibrary: profile.library,
            profileId: profile.id,
            profileName: profile.name,
            importType: destination,
            sourceName: "coedcherry-internal-browse",
            url: item.imageUrl || item.url,
          }),
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok || data.ok === false) throw new Error(data.message || data.error || "Import failed.");
        imported += 1;
      } catch (importError) {
        failures.push(importError.message || "Import failed.");
      }
    }

    setImporting(false);
    setStatus(
      failures.length
        ? `Imported ${imported}; ${failures.length} failed.`
        : `Imported ${imported} photo${imported === 1 ? "" : "s"} to ${profile.name}.`
    );
    if (imported) {
      window.dispatchEvent(new CustomEvent("homestead-adult-profile-updated", {
        detail: { profileId: profile.id, libraryType: profile.library },
      }));
    }
  }

  function createNewProfile() {
    if (!selectedItems.length) return;
    setStatus("Opening Add Performer…");
    onCreateProfile?.({
      defaultType: "performer",
      sourceName: source.name,
      sourceUrl: page?.url || initialUrl,
      media: selectedItems.map((item) => ({
        id: item.id,
        source: "url",
        kind: "image",
        name: item.title || "Imported photo",
        url: item.imageUrl || item.url,
        previewUrl: item.imageUrl || item.url,
        destination: destination === "nude" ? "nudes" : "photos",
        roles: [],
      })),
    });
  }

  function goBack() {
    const previous = history[history.length - 1];
    if (!previous) {
      onClose?.();
      return;
    }
    setHistory((current) => current.slice(0, -1));
    loadPage(previous, false);
  }

  return (
    <div className={`adult-internal-browser-backdrop ${isFullscreen ? "is-fullscreen" : ""}`} role="dialog" aria-modal="true">
      <section ref={browserCardRef} className={`adult-internal-browser-card ${isFullscreen ? "is-fullscreen" : ""}`}>
        <header className="adult-internal-browser-header">
          <button type="button" className="secondary-button" onClick={goBack}>← {history.length ? "Back" : "Browse Sources"}</button>
          <div>
            <p>{source.name} · Internal Browse</p>
            <h2>{page?.title || source.name}</h2>
          </div>
          <div className="adult-internal-browser-header-actions">
            <button type="button" className="secondary-button" onClick={toggleFullscreen}>
              {isFullscreen ? "Exit Fullscreen" : "Fullscreen"}
            </button>
            <button type="button" className="image-viewer-close" onClick={onClose}>×</button>
          </div>
        </header>

        {page?.tags?.length > 0 && (
          <div className="adult-internal-browser-tags">
            {page.tags.map((tag) => (
              <button key={tag.url} type="button" onClick={() => loadPage(tag.url)}>
                {tag.title}
              </button>
            ))}
          </div>
        )}

        <div className="adult-internal-browser-body">
          {loading && <div className="empty-state"><h3>Loading provider page…</h3></div>}
          {error && <div className="form-error">{error}</div>}

          {!loading && !error && page?.mode === "index" && (
            <div className="adult-internal-gallery-index">
              {(page.items || []).map((item) => (
                <article key={item.id}>
                  <button type="button" onClick={() => loadPage(item.url)}>
                    <img src={item.imageUrl} alt="" />
                  </button>
                  <strong>{item.title}</strong>
                  <button type="button" className="primary-button" onClick={() => loadPage(item.url)}>Open Gallery</button>
                </article>
              ))}
            </div>
          )}

          {!loading && !error && page?.mode === "gallery" && (
            <>
            <div className="adult-internal-photo-grid">
              {(page.items || []).map((item) => (
                <button
                  key={item.id}
                  type="button"
                  className={selectedIds.includes(item.id) ? "selected" : ""}
                  onClick={() => toggleSelection(item.id)}
                >
                  <img src={item.imageUrl} alt="" />
                  <span>{selectedIds.includes(item.id) ? "✓ Selected" : "Select"}</span>
                </button>
              ))}
            </div>
            {page?.nextPageUrl && (
              <div className="adult-internal-load-more-row">
                <button type="button" className="secondary-button" disabled={loadingMore} onClick={loadMore}>
                  {loadingMore ? "Loading…" : "Load More Results"}
                </button>
              </div>
            )}
            </>
          )}
        </div>

        {page?.mode === "gallery" && (
          <footer className="adult-internal-browser-actions">
            <div className="adult-internal-selection-summary">
              <strong>{selectedIds.length}</strong>
              <span>selected</span>
            </div>

            <button type="button" className="secondary-button adult-internal-select-all" onClick={toggleSelectAll}>
              {(page?.items || []).length > 0 && (page.items || []).every((item) => selectedIds.includes(item.id)) ? "Clear All" : "Select All"}
            </button>

            <label className="adult-internal-destination-control">
              <span>Import to</span>
              <select value={destination} onChange={(event) => setDestination(event.target.value)}>
              <option value="nude">Nudes</option>
              <option value="photo">Photos</option>
              </select>
            </label>

            {!importMode && (
              <>
                <button type="button" className="secondary-button" disabled={!selectedIds.length} onClick={() => setImportMode("existing")}>
                  Add to Existing Profile
                </button>
                <button type="button" className="primary-button" disabled={!selectedIds.length} onClick={() => setImportMode("new")}>
                  Create New Profile
                </button>
              </>
            )}

            {importMode === "existing" && (
              <>
                <select value={profileId} onChange={(event) => setProfileId(event.target.value)}>
                  <option value="">Choose profile…</option>
                  {profiles.map((profile) => (
                    <option key={`${profile.library}:${profile.id}`} value={profile.id}>
                      {profile.name} · {profile.library}
                    </option>
                  ))}
                </select>
                <button type="button" className="secondary-button" onClick={() => setImportMode("")}>Cancel</button>
                <button type="button" className="primary-button" disabled={!profileId || importing} onClick={importToExisting}>
                  {importing ? "Importing…" : "Import Selected"}
                </button>
              </>
            )}

            {importMode === "new" && (
              <>
                <button type="button" className="secondary-button" onClick={() => setImportMode("")}>Cancel</button>
                <button type="button" className="primary-button" onClick={createNewProfile}>
                  Continue to New Performer
                </button>
              </>
            )}
          </footer>
        )}

        {status && <div className="adult-internal-browser-status">{status}</div>}
      </section>
    </div>
  );
}


function AdultBrowseCollectionOverlay({ collection, result, loading, error, onClose, onOpenItem }) {
  const items = Array.isArray(result?.items) ? result.items : [];
  return (
    <div
      className="adult-provider-probe-backdrop adult-browse-collection-backdrop"
      role="dialog"
      aria-modal="true"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) onClose?.();
      }}
    >
      <div className="adult-provider-probe-card adult-browse-collection-card">
        <button className="image-viewer-close" type="button" onClick={onClose}>×</button>
        <p className="eyebrow">Cross-provider category</p>
        <h2>{collection.icon} {collection.title}</h2>
        <p className="adult-browse-collection-description">Results matching this category across all enabled browse-only providers.</p>

        {loading && <div className="empty-state"><h3>Building collection…</h3><p>Checking enabled browse sources for matching category pages.</p></div>}
        {error && <div className="form-error">{error}</div>}

        {!loading && !error && (
          <>
            <div className="adult-browse-collection-summary">
              <div><strong>{result?.providerCount || 0}</strong><span>Providers checked</span></div>
              <div><strong>{items.length}</strong><span>Matching results</span></div>
              <div><strong>{result?.testedCount || 0}</strong><span>Parsed internally</span></div>
            </div>

            {items.length === 0 ? (
              <div className="empty-state">
                <h3>No matching results found</h3>
                <p>The enabled providers may require external browsing, login, or provider-specific adapters.</p>
              </div>
            ) : (
              <div className="adult-browse-collection-grid">
                {items.map((item) => (
                  <article key={`${item.sourceId}:${item.url}`} className="adult-browse-collection-item">
                    <button
                      type="button"
                      className="adult-browse-collection-poster"
                      onClick={() => onOpenItem?.(item)}
                    >
                      {item.imageUrl
                        ? <img src={item.imageUrl} alt="" />
                        : <div className="adult-provider-preview-placeholder">↗</div>}
                    </button>
                    <div>
                      <strong>{item.title}</strong>
                      <span>{item.sourceName}</span>
                    </div>
                    <button
                      type="button"
                      className="secondary-button"
                      onClick={() => onOpenItem?.(item)}
                    >
                      {item.sourceId === "coedcherry" ? "Browse Inside" : "Open category"}
                    </button>
                  </article>
                ))}
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}


function AdultBrowseSourcesPage({ sources = [], onBack, onSwitchMode }) {
  const browseSources = useMemo(
    () => sources
      .filter(adultSourceMatchesBrowseMode)
      .sort((a, b) => (a.priority || 50) - (b.priority || 50)),
    [sources]
  );
  const [favorites, setFavorites] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem("homesteadAdultBrowseFavorites") || "[]");
    } catch {
      return [];
    }
  });
  const [recent, setRecent] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem("homesteadAdultBrowseRecent") || "[]");
    } catch {
      return [];
    }
  });
  const [probes, setProbes] = useState({});
  const [testingId, setTestingId] = useState("");
  const [selectedProbe, setSelectedProbe] = useState(null);
  const [sourceBrowser, setSourceBrowser] = useState(null);
  const [status, setStatus] = useState(`${browseSources.length} browse-oriented providers available.`);
  const [activeCollection, setActiveCollection] = useState(null);
  const [collectionResult, setCollectionResult] = useState(null);
  const [collectionLoading, setCollectionLoading] = useState(false);
  const [collectionError, setCollectionError] = useState("");
  const [categoryQuery, setCategoryQuery] = useState("");
  const [internalBrowser, setInternalBrowser] = useState(null);


  useEffect(() => {
    localStorage.setItem("homesteadAdultBrowseFavorites", JSON.stringify(favorites));
  }, [favorites]);

  useEffect(() => {
    localStorage.setItem("homesteadAdultBrowseRecent", JSON.stringify(recent.slice(0, 12)));
  }, [recent]);


  async function openBrowseCollection(collection) {
    setActiveCollection(collection);
    setCollectionResult(null);
    setCollectionError("");
    setCollectionLoading(true);

    try {
      const response = await fetch("/api/discovery/adult/browse-collection", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ categoryId: collection.id }),
      });
      const data = await response.json();
      if (!response.ok || !data.ok) throw new Error(data.message || "Unable to build browse collection.");
      setCollectionResult(data.collection);
    } catch (error) {
      setCollectionError(error.message || "Unable to build browse collection.");
    } finally {
      setCollectionLoading(false);
    }
  }

  function sourceUrl(source = {}) {
    return source.baseUrl || String(source.searchUrlTemplate || "")
      .replaceAll("{query}", "")
      .replaceAll("{queryPlus}", "")
      .replaceAll("{querySlug}", "");
  }

  function toggleFavorite(sourceId) {
    setFavorites((current) => current.includes(sourceId)
      ? current.filter((id) => id !== sourceId)
      : [...current, sourceId]);
  }

  function rememberVisit(source) {
    setRecent((current) => [source.id, ...current.filter((id) => id !== source.id)].slice(0, 12));
  }

  function openExternal(source) {
    const url = sourceUrl(source);
    if (!url) return;
    rememberVisit(source);
    window.open(url, "_blank", "noopener,noreferrer");
  }

  function openProviderOverlay(source) {
    rememberVisit(source);
    setSourceBrowser({
      ...source,
      url: sourceUrl(source),
      source: source.name,
      title: source.name,
      subtitle: source.notes || source.category || "Browse provider",
    });
  }

  async function testProvider(source, force = false) {
    setTestingId(source.id);
    setStatus(`Testing ${source.name}…`);
    try {
      const response = await fetch("/api/discovery/adult/provider-probe", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ sourceId: source.id, force }),
      });
      const data = await response.json();
      if (!response.ok || !data.ok) throw new Error(data.message || "Provider test failed.");
      setProbes((current) => ({ ...current, [source.id]: data.probe }));
      setSelectedProbe({ source, probe: data.probe });
      setStatus(`${source.name}: ${getAdultProviderRecommendationLabel(data.probe.recommendation)}.`);
    } catch (error) {
      const failed = { ok: false, fetchError: error.message || "Provider test failed.", recommendation: "external-only" };
      setProbes((current) => ({ ...current, [source.id]: failed }));
      setSelectedProbe({ source, probe: failed });
      setStatus(error.message || "Provider test failed.");
    } finally {
      setTestingId("");
    }
  }

  const ordered = [...browseSources].sort((a, b) => {
    const favoriteDiff = Number(favorites.includes(b.id)) - Number(favorites.includes(a.id));
    if (favoriteDiff) return favoriteDiff;
    const recentDiff = recent.indexOf(a.id) - recent.indexOf(b.id);
    if (recent.includes(a.id) && recent.includes(b.id) && recentDiff) return recentDiff;
    if (recent.includes(a.id)) return -1;
    if (recent.includes(b.id)) return 1;
    return (a.priority || 50) - (b.priority || 50);
  });

  return (
    <div className="generic-page adult-browse-sources-page">
      <section className="adult-advanced-compact-header adult-browse-sources-header">
        <button className="adult-advanced-back-button" type="button" onClick={onBack}>← Back</button>
        <div className="adult-advanced-compact-title">
          <p>Adult Discovery</p>
          <h1>Browse Sources</h1>
          <span>Explore browse-oriented providers without treating their galleries or category pages as identity matches.</span>
        </div>
        <div className="adult-advanced-compact-stats">
          <div><strong>{browseSources.length}</strong><span>Providers</span></div>
          <div><strong>{favorites.length}</strong><span>Favorites</span></div>
          <div><strong>{Object.keys(probes).length}</strong><span>Tested</span></div>
        </div>
      </section>

      <div className="adult-browse-workflow-switcher">
        <button type="button" onClick={() => onSwitchMode?.("person")}>
          <strong>Find Person</strong><span>Search identity and metadata sources</span>
        </button>
        <button type="button" onClick={() => onSwitchMode?.("photo")}>
          <strong>Search by Photo</strong><span>Start with a face-search provider</span>
        </button>
        <button type="button" className="active">
          <strong>Browse Sources</strong><span>Open galleries, categories, and newest pages</span>
        </button>
      </div>
      <section className="panel adult-browse-unified-collections">
        <div className="settings-section-header adult-browse-category-header">
          <div>
            <h3>Browse Categories</h3>
            <p>Choose a category and Homestead combines matching results from every enabled browse-only provider.</p>
          </div>
          <input
            type="search"
            value={categoryQuery}
            onChange={(event) => setCategoryQuery(event.target.value)}
            placeholder="Filter categories…"
          />
        </div>

        <div className="adult-browse-category-grid">
          {ADULT_BROWSE_CATEGORIES
            .filter((category) => {
              const query = categoryQuery.trim().toLowerCase();
              if (!query) return true;
              return [category.title, ...(category.aliases || [])]
                .some((value) => String(value).toLowerCase().includes(query));
            })
            .map((category) => (
              <button
                key={category.id}
                type="button"
                className="adult-browse-category-card"
                onClick={() => openBrowseCollection(category)}
              >
                <span>{category.icon}</span>
                <strong>{category.title}</strong>
              </button>
            ))}
        </div>
      </section>

      <section className="panel adult-browse-source-catalog">
        <div className="settings-section-header">
          <div>
            <h3>Provider Catalog</h3>
            <p>{status}</p>
          </div>
        </div>

        <div className="adult-browse-provider-grid">
          {ordered.map((source) => {
            const probe = probes[source.id];
            const url = sourceUrl(source);
            return (
              <article key={source.id} className={`adult-browse-provider-card ${favorites.includes(source.id) ? "favorite" : ""}`}>
                <div className="adult-browse-provider-card-head">
                  <AdultSourceIcon source={source} />
                  <div>
                    <strong>{source.name}</strong>
                    <span>{source.category || "Browse provider"}</span>
                  </div>
                  <button
                    type="button"
                    className={`adult-browse-favorite-button ${favorites.includes(source.id) ? "active" : ""}`}
                    onClick={() => toggleFavorite(source.id)}
                    aria-label={favorites.includes(source.id) ? "Remove favorite" : "Add favorite"}
                  >
                    {favorites.includes(source.id) ? "★" : "☆"}
                  </button>
                </div>

                <div className="adult-source-mini-badges">
                  <span>Browse only</span>
                  {(source.badges || []).slice(0, 3).map((badge) => <span key={badge}>{badge}</span>)}
                  {source.requiresSession && <span>Session</span>}
                </div>

                <p>{source.notes || "Open this provider to explore its own gallery, category, or newest-content pages."}</p>
                <code>{url}</code>

                {probe && (
                  <div className={`adult-provider-probe-summary recommendation-${probe.recommendation || "external-only"}`}>
                    <strong>{getAdultProviderRecommendationLabel(probe.recommendation)}</strong>
                    <span>
                      {probe.parsing?.cardCount || 0} cards ·
                      {probe.embed?.blocked ? " embed blocked" : " embed possible"} ·
                      {probe.pagination?.working ? " pagination found" : " no pagination detected"}
                    </span>
                  </div>
                )}

                <div className="adult-browse-provider-actions">
                  <button type="button" className="secondary-button" onClick={() => testProvider(source)}>
                    {testingId === source.id ? "Testing…" : probe ? "View Test" : "Test Provider"}
                  </button>
                  <button type="button" className="secondary-button" onClick={() => openProviderOverlay(source)}>Preview</button>
                  <button type="button" className="primary-button" onClick={() => openExternal(source)}>Open Source</button>
                </div>
              </article>
            );
          })}
        </div>
      </section>

      {selectedProbe && (
        <div className="adult-provider-probe-backdrop" role="dialog" aria-modal="true" onMouseDown={(event) => {
          if (event.target === event.currentTarget) setSelectedProbe(null);
        }}>
          <div className="adult-provider-probe-card">
            <button className="image-viewer-close" type="button" onClick={() => setSelectedProbe(null)}>×</button>
            <p className="eyebrow">Provider Capability Test</p>
            <h2>{selectedProbe.source.name}</h2>
            <div className={`adult-provider-probe-recommendation recommendation-${selectedProbe.probe.recommendation || "external-only"}`}>
              {getAdultProviderRecommendationLabel(selectedProbe.probe.recommendation)}
            </div>

            <div className="adult-provider-probe-metrics">
              <div><span>Fetch</span><strong>{selectedProbe.probe.ok ? `Working (${selectedProbe.probe.status})` : "Failed"}</strong></div>
              <div><span>Embed</span><strong>{selectedProbe.probe.embed?.blocked ? "Blocked" : "Possible"}</strong></div>
              <div><span>Category cards</span><strong>{selectedProbe.probe.parsing?.cardCount || 0} found</strong></div>
              <div><span>Images</span><strong>{selectedProbe.probe.images?.mode === "proxy-recommended" ? "Proxy recommended" : selectedProbe.probe.images?.mode || "Unknown"}</strong></div>
              <div><span>Pagination</span><strong>{selectedProbe.probe.pagination?.working ? "Working" : "Not detected"}</strong></div>
              <div><span>Session</span><strong>{selectedProbe.probe.requiresSession ? "Required/likely" : "Not detected"}</strong></div>
            </div>

            {selectedProbe.probe.fetchError && <p className="form-error">{selectedProbe.probe.fetchError}</p>}

            {selectedProbe.probe.parsing?.sampleCards?.length > 0 && (
              <>
                <h3>Parsed preview</h3>
                <div className="adult-provider-probe-preview-grid">
                  {selectedProbe.probe.parsing.sampleCards.map((item) => (
                    <button key={item.id} type="button" onClick={() => window.open(item.url, "_blank", "noopener,noreferrer")}>
                      {item.imageUrl ? <img src={item.imageUrl} alt="" /> : <div className="adult-provider-preview-placeholder">↗</div>}
                      <span>{item.title}</span>
                    </button>
                  ))}
                </div>
              </>
            )}

            <div className="adult-provider-probe-actions">
              <button type="button" className="secondary-button" onClick={() => testProvider(selectedProbe.source, true)}>Retest</button>
              <button type="button" className="secondary-button" onClick={() => openProviderOverlay(selectedProbe.source)}>Open Preview</button>
              <button type="button" className="primary-button" onClick={() => openExternal(selectedProbe.source)}>Open External</button>
            </div>
          </div>
        </div>
      )}


      {activeCollection && (
        <AdultBrowseCollectionOverlay
          collection={activeCollection}
          result={collectionResult}
          loading={collectionLoading}
          error={collectionError}
          onClose={() => {
            setActiveCollection(null);
            setCollectionResult(null);
            setCollectionError("");
          }}
          onOpenItem={(item) => {
            if (item.sourceId === "coedcherry") {
              const source = sources.find((entry) => entry.id === item.sourceId);
              if (source) setInternalBrowser({ source, url: item.url });
            } else {
              window.open(item.url, "_blank", "noopener,noreferrer");
            }
          }}
        />
      )}


      {internalBrowser && (
        <CoedCherryInternalBrowser
          source={internalBrowser.source}
          initialUrl={internalBrowser.url}
          onClose={() => setInternalBrowser(null)}
          onCreateProfile={(draft) => {
            setInternalBrowser(null);
            setActiveCollection(null);
            window.setTimeout(() => {
              window.dispatchEvent(new CustomEvent("homestead-open-adult-profile-create", {
                detail: draft,
              }));
            }, 0);
          }}
        />
      )}

      {sourceBrowser && (
        <AdultSourceBrowserOverlay
          sourceBrowser={sourceBrowser}
          onClose={() => setSourceBrowser(null)}
          onOpenExternal={() => openExternal(sourceBrowser)}
          backLabel="← Browse Sources"
          titleFallback="Provider browse preview"
        />
      )}
    </div>
  );
}


function AdultPersonBrowsePage({ candidate = {}, onBack }) {
  const [tab, setTab] = useState("overview");
  const [review, setReview] = useState(null);
  const [status, setStatus] = useState("Loading available source details…");
  const [loading, setLoading] = useState(true);
  const name = candidate.name || candidate.title || "Person results";
  const profileType = candidate.profileType === "celebrity" ? "celebrity" : "performer";
  const libraryType = profileType === "celebrity" ? "celebrities" : "performers";

  useEffect(() => {
    const controller = new AbortController();
    setLoading(true);
    fetch("/api/metadata/adult/person/full-fetch", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        query: name,
        profileType,
        libraryType,
        person: { name, profileType, library: libraryType, metadata: {} },
        candidate: candidate.sourceCandidates?.[0] || candidate,
        identityAnchor: candidate.sourceCandidates?.[0] || candidate,
        saveToProfile: false,
      }),
      signal: controller.signal,
    }).then(async (response) => {
      const data = await response.json().catch(() => ({}));
      if (!response.ok || data.ok === false) throw new Error(data.message || "Source details could not be loaded.");
      setReview(data);
      setStatus(data.message || "Source details loaded.");
    }).catch((error) => {
      if (error.name !== "AbortError") setStatus(error.message || "Source details could not be loaded; available source links remain below.");
    }).finally(() => setLoading(false));
    return () => controller.abort();
  }, [name, profileType, libraryType, candidate]);

  const sourceRows = [
    ...(Array.isArray(candidate.sources) ? candidate.sources : []),
    ...(Array.isArray(candidate.searchableSources) ? candidate.searchableSources : []),
    ...(Array.isArray(review?.sourceSummary) ? review.sourceSummary.map((source) => ({
      id: source.provider,
      name: source.source,
      url: source.url,
      status: "matched",
      capabilities: source.fields || [],
      packName: "Metadata sources",
    })) : []),
  ].filter((source, index, list) => list.findIndex((entry) => `${entry.id || entry.name}:${entry.url || ""}` === `${source.id || source.name}:${source.url || ""}`) === index);
  const sourcePacks = sourceRows.reduce((groups, source) => {
    const pack = source.packName || "Available sources";
    groups[pack] = groups[pack] || [];
    groups[pack].push(source);
    return groups;
  }, {});
  const mediaSources = sourceRows.filter((source) => (source.capabilities || []).some((capability) => /photo|video|scene|gallery|artwork/i.test(capability)));
  const externalLinks = review?.metadata?.externalLinks || review?.metadata?.providerLinks || {};

  return (
    <div className="generic-page adult-person-browse-page">
      <section className="adult-person-browse-hero">
        <button type="button" className="secondary-button" onClick={onBack}>← Search results</button>
        <GlobalSearchArtwork item={candidate} fallbackIcon={profileType === "celebrity" ? "🌟" : "🔎"} />
        <div><p>Browse-only person results</p><h1>{name}</h1><span>{profileType === "celebrity" ? "Celebrity" : "Performer"} · {sourceRows.length} available source{sourceRows.length === 1 ? "" : "s"}</span></div>
        <span className="adult-person-browse-readonly">No profile changes</span>
      </section>

      <nav className="adult-person-browse-tabs">
        {[["overview", "Overview"], ["sources", `Sources (${sourceRows.length})`], ["media", `Photos & Videos (${mediaSources.length})`], ["social", "Social"]].map(([id, label]) => <button type="button" key={id} className={tab === id ? "active" : ""} onClick={() => setTab(id)}>{label}</button>)}
      </nav>
      <p className="adult-person-browse-status">{loading ? "Searching enabled source packs…" : status}</p>

      {tab === "overview" && <div className="adult-person-browse-grid">
        {(review?.fieldGroups || []).map((group) => <section className="panel" key={group.id}><h2>{group.label}</h2><dl>{group.fields.map((field) => <div key={field.key}><dt>{field.label}</dt><dd><strong>{formatHomesteadField(field.key, field.chosen?.value ?? field.chosen?.valuePreview)}</strong><small>{field.chosen?.source || "Unknown source"}</small>{field.options?.length > 1 && <em>{field.options.length} reported values</em>}</dd></div>)}</dl></section>)}
        {!loading && !(review?.fieldGroups || []).length && <section className="panel"><h2>Source overview</h2><p>No structured fields were returned. Use the source cards to browse available results directly.</p><AdultPersonSourceChips result={candidate} limit={20} /></section>}
      </div>}

      {tab === "sources" && <div className="adult-person-source-pack-list">{Object.entries(sourcePacks).map(([pack, sources]) => <section className="panel" key={pack}><header><h2>{pack}</h2><span>{sources.length} source{sources.length === 1 ? "" : "s"}</span></header><div>{sources.map((source) => <article key={`${source.id || source.name}-${source.url || ""}`}><div><strong>{source.name || source.id}</strong><small>{source.status === "searchable" ? "Available to search" : "Matched this identity"}</small><span>{(source.capabilities || []).slice(0, 8).join(" · ") || "Identity and external results"}</span></div>{source.url && <button type="button" className="secondary-button" onClick={() => window.open(source.url, "_blank", "noopener,noreferrer")}>View source</button>}</article>)}</div></section>)}</div>}

      {tab === "media" && <section className="panel adult-person-media-sources"><h2>Available photo, video and scene sources</h2><p>These links browse available content. Nothing is imported from Global Search.</p>{mediaSources.length ? mediaSources.map((source) => <article key={`${source.id}-${source.url}`}><div><strong>{source.name}</strong><small>{(source.capabilities || []).filter((capability) => /photo|video|scene|gallery|artwork/i.test(capability)).join(" · ")}</small></div>{source.url && <button type="button" className="secondary-button" onClick={() => window.open(source.url, "_blank", "noopener,noreferrer")}>Browse</button>}</article>) : <p>No media-capable source links were returned.</p>}</section>}

      {tab === "social" && <section className="panel adult-person-social-results"><h2>Social and official links</h2>{Object.entries(externalLinks).length ? Object.entries(externalLinks).map(([label, url]) => <article key={label}><strong>{label}</strong><a href={typeof url === "string" ? url : url?.url} target="_blank" rel="noreferrer">{typeof url === "string" ? url : url?.url}</a></article>) : <p>No social links were reported by the enabled sources.</p>}</section>}
    </div>
  );
}

function AdultPhotoSearchLauncher({ initialQuery = "", onClose, onSubmitted }) {
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState("");
  const [query, setQuery] = useState(initialQuery || "");
  const [status, setStatus] = useState("Choose a photo, then Homestead will open the full results page after the search is submitted.");
  const [loading, setLoading] = useState(false);
  useEffect(() => () => { if (preview?.startsWith("blob:")) URL.revokeObjectURL(preview); }, [preview]);
  async function submit(event) {
    event.preventDefault();
    if (!file) { setStatus("Choose a photo first."); return; }
    setLoading(true); setStatus("Searching configured photo identity sources…");
    try {
      const imageData = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result || "")); reader.onerror = () => reject(reader.error || new Error("Could not read photo.")); reader.readAsDataURL(file); });
      const response = await fetch("/api/discovery/adult/face-search", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ imageData, fileName: file.name, query: query.trim(), profileTypes: ["performer", "celebrity", "personal"] }) });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || !data.ok) throw new Error(data.message || "Face search failed.");
      onSubmitted?.({ query: query.trim(), results: data.results || [], upload: data.uploaded || null, status: data.message || `${data.results?.length || 0} possible matches returned.` });
    } catch (error) { setStatus(error.message || "Face search failed."); }
    finally { setLoading(false); }
  }
  return createPortal(<div className="adult-profile-modal-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && !loading && onClose?.()}>
    <form className="adult-photo-search-launcher" role="dialog" aria-modal="true" aria-label="Search by photo" onSubmit={submit}>
      <header><div><p>Adult Discovery</p><h2>Search by Photo</h2><span>The full results page opens only after you submit a photo.</span></div><button type="button" disabled={loading} onClick={onClose}>×</button></header>
      <label className="adult-photo-search-dropzone">{preview ? <img src={preview} alt="Selected search" /> : <span>📷</span>}<input type="file" accept="image/*" onChange={(event) => { const next = event.target.files?.[0] || null; if (preview?.startsWith("blob:")) URL.revokeObjectURL(preview); setFile(next); setPreview(next ? URL.createObjectURL(next) : ""); }} /><strong>{file?.name || "Choose photo"}</strong><small>JPG, PNG, or WebP</small></label>
      <label><span>Optional name hint</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Name or note" /></label>
      <p role="status">{status}</p>
      <footer><button type="button" className="secondary-button" disabled={loading} onClick={onClose}>Cancel</button><button type="submit" className="primary-button" disabled={loading || !file}>{loading ? "Searching…" : "Search Photo"}</button></footer>
    </form>
  </div>, document.body);
}

function AdvancedAdultSearchPage({ initialQuery = "", initialMode = "person", initialPhotoResults = [], initialPhotoUpload = null, initialPhotoStatus = "", setupConfig, onBack, onSelectPersonCandidate }) {
  const [query, setQuery] = useState(initialQuery || "");
  const [sources, setSources] = useState([]);
  const [results, setResults] = useState(Array.isArray(initialPhotoResults) ? initialPhotoResults : []);
  const [status, setStatus] = useState(initialPhotoStatus || "Loading adult sources…");
  const [loading, setLoading] = useState(false);
  const [sourceBrowser, setSourceBrowser] = useState(null);
  const [adultProviderIds, setAdultProviderIds] = useState({});
  const [adultWikidataMatch, setAdultWikidataMatch] = useState(null);
  const [searchMode, setSearchMode] = useState(() => normalizeAdultDiscoveryMode(initialMode || localStorage.getItem("homesteadAdultAdvancedSearchMode") || "person"));
  const [photoSearchFile, setPhotoSearchFile] = useState(null);
  const [photoSearchPreview, setPhotoSearchPreview] = useState("");
  const [photoSearchUpload, setPhotoSearchUpload] = useState(initialPhotoUpload);
  const [filters, setFilters] = useState(() => {
    try {
      return { profileType: "performer", ...JSON.parse(localStorage.getItem("homesteadAdultAdvancedFilters") || "{}") };
    } catch {
      return { profileType: "performer" };
    }
  });

  useEffect(() => {
    let cancelled = false;
    fetch("/api/adult/sources")
      .then((res) => res.json())
      .then((data) => {
        if (cancelled) return;
        const nextSources = Array.isArray(data.sources) ? data.sources : [];
        setSources(nextSources.map((source) => ({ ...source, enabled: source.enabled !== false })));
        if (!initialPhotoStatus) setStatus(`${nextSources.length} adult source providers loaded.`);
      })
      .catch((error) => setStatus(error.message || "Could not load adult source providers."));

    return () => {
      cancelled = true;
    };
  }, [initialPhotoStatus]);

  useEffect(() => {
    localStorage.setItem("homesteadAdultAdvancedFilters", JSON.stringify(filters));
  }, [filters]);

  useEffect(() => {
    localStorage.setItem("homesteadAdultAdvancedSearchMode", searchMode);
  }, [searchMode]);

  const profileType = normalizeAdultProfileType(filters.profileType || "performer");
  const matchingSources = searchMode === "photo"
    ? []
    : sources
      .filter((source) => searchMode === "browse" ? adultSourceMatchesBrowseMode(source) : adultSourceMatchesProfileType(source, profileType))
      .sort((a, b) => (a.priority || 50) - (b.priority || 50));
  const selectedSourceIds = matchingSources.filter((source) => source.enabled !== false).map((source) => source.id);
  const hiddenByProfileTypeCount = sources.length - matchingSources.length;

  if (searchMode === "browse") {
    return (
      <AdultBrowseSourcesPage
        sources={sources}
        onBack={onBack}
        onSwitchMode={(mode) => {
          setSearchMode(normalizeAdultDiscoveryMode(mode));
          setResults([]);
          setStatus(mode === "photo" ? "Choose a photo to search." : "Ready to find a person.");
        }}
      />
    );
  }

  function hasFilterValue(value) {
    if (Array.isArray(value)) return value.length > 0;
    return Boolean(value);
  }

  function filterIncludes(currentValue, optionValue) {
    return Array.isArray(currentValue) ? currentValue.includes(optionValue) : currentValue === optionValue;
  }

  function formatFilterLabel(value) {
    if (Array.isArray(value)) return value.join(", ");
    return String(value || "");
  }

  function setFilter(name, value, options = {}) {
    if (options.multi) {
      setFilters((current) => {
        const existing = Array.isArray(current[name]) ? current[name] : (current[name] ? [current[name]] : []);
        const nextValues = existing.includes(value)
          ? existing.filter((item) => item !== value)
          : [...existing, value];
        return { ...current, [name]: nextValues.length ? nextValues : "" };
      });
      return;
    }

    setFilters((current) => ({ ...current, [name]: current[name] === value ? "" : value }));
  }

  function setTextFilter(name, value) {
    setFilters((current) => ({ ...current, [name]: value }));
  }

  function toggleSource(sourceId) {
    setSources((current) => current.map((source) => source.id === sourceId ? { ...source, enabled: source.enabled === false } : source));
  }

  function clearFilters() {
    setFilters({ profileType: profileType || "performer" });
  }

  function readFileAsDataUrl(file) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(String(reader.result || ""));
      reader.onerror = () => reject(reader.error || new Error("Could not read photo."));
      reader.readAsDataURL(file);
    });
  }

  async function handlePhotoSearchFileChange(event) {
    const file = event.target.files?.[0] || null;
    setPhotoSearchFile(file);
    setResults([]);
    setPhotoSearchUpload(null);

    if (!file) {
      setPhotoSearchPreview("");
      return;
    }

    const preview = URL.createObjectURL(file);
    setPhotoSearchPreview(preview);
    setStatus("Photo ready. Click Search Photo to start with BabeWiki Face Search. Local AI matching can be added later.");
  }

  async function runFaceSearch(event) {
    event?.preventDefault?.();
    if (!photoSearchFile) {
      setStatus("Choose a photo first.");
      return;
    }

    setLoading(true);
    setStatus("Uploading photo and preparing BabeWiki Face Search…");

    try {
      const imageData = await readFileAsDataUrl(photoSearchFile);
      const response = await fetch("/api/discovery/adult/face-search", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          imageData,
          fileName: photoSearchFile.name,
          query: query.trim(),
          profileTypes: ["performer", "celebrity", "personal"],
        }),
      });
      const data = await response.json();
      if (!response.ok || !data.ok) throw new Error(data.message || "Face search failed.");
      setPhotoSearchUpload(data.uploaded || null);
      setResults(data.results || []);
      setAdultProviderIds({});
      setAdultWikidataMatch(null);
      setStatus(data.message || `${data.results?.length || 0} possible face matches returned.`);
    } catch (error) {
      setStatus(error.message || "Face search failed.");
    } finally {
      setLoading(false);
    }
  }

  async function runSearch(event) {
    event?.preventDefault?.();
    if (searchMode === "photo") {
      return runFaceSearch(event);
    }

    const cleanQuery = query.trim();

    const hasRealFilters = Object.entries(filters).some(([key, value]) => key !== "profileType" && hasFilterValue(value));

    if (!cleanQuery && !hasRealFilters) {
      setStatus(searchMode === "browse" ? "Choose at least one browse filter or enter an optional search term." : "Enter a performer/search term or choose at least one filter.");
      return;
    }

    setLoading(true);
    setStatus(searchMode === "browse" ? "Building browse discovery pages…" : "Building provider searches…");

    try {
      const response = await fetch(searchMode === "browse" ? "/api/discovery/adult/browse-media" : "/api/discovery/adult/advanced-search", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query: cleanQuery, filters, sourceIds: selectedSourceIds, mode: searchMode }),
      });
      const data = await response.json();

      if (!response.ok || !data.ok) {
        throw new Error(data.message || "Adult advanced search failed.");
      }

      setResults(data.results || []);
      setAdultProviderIds(data.providerIds || {});
      setAdultWikidataMatch(data.wikidataMatch || null);
      setStatus(data.message || `${data.results?.length || 0} provider searches ready.`);
    } catch (error) {
      setStatus(error.message || "Adult advanced search failed.");
    } finally {
      setLoading(false);
    }
  }

  function openSource(result) {
    setSourceBrowser(result);
  }

  function openExternal(result = sourceBrowser) {
    if (!result?.url) return;
    window.open(result.url, "_blank", "noopener,noreferrer");
  }

  async function copyUrl(result) {
    try {
      await navigator.clipboard.writeText(result.url || "");
      setStatus(`Copied ${result.source || result.name} URL.`);
    } catch {
      setStatus(result.url || "No URL available.");
    }
  }

  function openMatchCreate(result) {
    if (!result) return;
    onSelectPersonCandidate?.({
      ...result,
      name: result.name || result.title || query.trim(),
      title: result.title || result.name || query.trim(),
      profileType: normalizeAdultProfileType(filters.profileType || result.profileType || result.libraryType || "performer"),
      libraryType: normalizeAdultProfileType(filters.profileType || result.profileType || result.libraryType) === "celebrity" ? "celebrities" : normalizeAdultProfileType(filters.profileType || result.profileType || result.libraryType) === "personal" ? "personal" : "performers",
      query: query.trim(),
    });
  }

  const filterSections = [
    {
      id: "profile",
      label: "Profile basics",
      hint: "Broad identity filters used to build source searches.",
      groups: [
        { key: "gender", label: "Gender", options: ["female", "male", "transgender", "non-binary"] },
        { key: "ethnicity", label: "Ethnicity", options: ["asian", "black", "caucasian", "indian", "latin", "middle eastern", "mixed"] },
        { key: "ageStyle", label: "Age style", multi: true, options: ["18+ young adult", "college", "mature", "milf", "cougar"] },
      ],
    },
    {
      id: "body",
      label: "Body",
      hint: "Body, cup, and feature filters. Cup size supports multiple selections.",
      groups: [
        { key: "bodyType", label: "Body Type", multi: true, options: ["petite", "slim", "athletic", "fit", "average", "curvy", "thick", "bbw", "plus size", "tall"] },
        { key: "breastType", label: "Breast Type", options: ["natural", "fake"] },
        { key: "cupSize", label: "Cup Size", multi: true, compact: true, options: ["A", "AA", "AAA", "B", "BB", "C", "CC", "D", "DD", "DDD", "E", "EE", "F", "FF", "G", "GG", "H", "I", "J", "K", "M", "N", "O"] },
      ],
    },
    {
      id: "appearance",
      label: "Appearance",
      hint: "Visual appearance filters for gallery/tag sources.",
      groups: [
        { key: "hairColor", label: "Hair", multi: true, options: ["blonde", "brunette", "black hair", "redhead", "auburn", "pink hair", "blue hair"] },
        { key: "tattoos", label: "Tattoos", options: ["yes", "no"] },
        { key: "piercings", label: "Piercings", options: ["yes", "no"] },
      ],
    },
    {
      id: "content",
      label: "Content tags",
      hint: "Browse tags are treated as adult-only discovery terms, not identity metadata.",
      groups: [
        { key: "contentType", label: "Content", multi: true, options: ["performers", "scenes", "videos", "photos", "artwork", "galleries"] },
        { key: "orientationTags", label: "Orientation / Scene", multi: true, options: ["lesbian", "straight", "solo", "couple", "threesome", "group"] },
        { key: "styleTags", label: "Style / Theme", multi: true, options: ["amateur", "professional", "glamour", "lingerie", "cosplay", "outdoor", "office", "massage"] },
      ],
    },
  ];

  const activeFilters = Object.entries(filters).filter(([key, value]) => key !== "profileType" && hasFilterValue(value));

  function normalizeAdultResultGroup(result = {}) {
    const rawGroup = String(result.resultGroup || "").toLowerCase();

    if (result.isPersonCandidate || rawGroup.includes("best metadata")) return "Best metadata matches";
    if (rawGroup.includes("face") || String(result.type || "").includes("face-search")) return "Face search providers";
    if (rawGroup.includes("profile") || rawGroup.includes("metadata") || rawGroup.includes("identity") || result.supportsFixMatch || result.supportsBulkMetadata) return "Profile / metadata provider searches";
    if (rawGroup.includes("tag") || rawGroup.includes("category") || String(result.type || "").includes("tag")) return "Tag / category pages";
    if (rawGroup.includes("photo") || rawGroup.includes("gallery") || rawGroup.includes("artwork") || result.supportsArtwork) return "Artwork / photo provider searches";
    if (rawGroup.includes("video") || rawGroup.includes("scene") || result.supportsScenes || result.supportsImport) return "Video / scene provider searches";
    if (rawGroup.includes("session") || rawGroup.includes("membership") || rawGroup.includes("locked") || result.requiresSession) return "Locked / session sources";
    if (rawGroup.includes("disabled")) return "Disabled sources";

    return "General provider searches";
  }

  const groupedResults = results.reduce((groups, result) => {
    const group = normalizeAdultResultGroup(result);
    groups[group] = groups[group] || [];
    groups[group].push(result);
    return groups;
  }, {});
  const resultGroupOrder = ["Best metadata matches", "Face search providers", "Profile / metadata provider searches", "Artwork / photo provider searches", "Video / scene provider searches", "Tag / category pages", "General provider searches", "Locked / session sources", "Disabled sources"];
  const orderedResultGroups = [
    ...resultGroupOrder.filter((group) => groupedResults[group]?.length),
    ...Object.keys(groupedResults).filter((group) => !resultGroupOrder.includes(group)),
  ];

  return (
    <div className="generic-page adult-advanced-search-page">
      <section className="adult-advanced-compact-header">
        <button className="adult-advanced-back-button" type="button" onClick={onBack}>← Back</button>
        <div className="adult-advanced-compact-title">
          <p>Adult Discovery</p>
          <h1>{searchMode === "browse" ? "Browse Sources" : searchMode === "photo" ? "Search by Photo" : "Advanced Person Search"}</h1>
          <span>
            {searchMode === "browse"
              ? "Name is optional here. Choose filters and Homestead builds browse/gallery source pages without treating results as identity matches."
              : searchMode === "photo"
                ? "Upload a photo to start with BabeWiki Face Search. Local Homestead AI matching can be added later as an optional second pass."
                : "Search across enabled person/provider sites with one Homestead filter model. Filters are adapted per source."}
          </span>
        </div>
        <div className="adult-advanced-compact-stats">
          <div><strong>{searchMode === "photo" ? results.length : matchingSources.length}</strong><span>{searchMode === "photo" ? "Matches" : searchMode === "browse" ? "Browse" : profileType === "celebrity" ? "Celebrity" : profileType === "both" ? "Sources" : "Performer"}</span></div>
          <div><strong>{selectedSourceIds.length}</strong><span>Enabled</span></div>
          <div><strong>{activeFilters.length}</strong><span>Filters</span></div>
        </div>
      </section>

      <form className="panel adult-advanced-search-form" onSubmit={runSearch}>
        <div className="adult-discovery-mode-tabs" role="group" aria-label="Adult discovery search mode">
          <button
            type="button"
            className={searchMode === "person" ? "active" : ""}
            onClick={() => setSearchMode("person")}
          >
            <strong>Find Person</strong>
            <span>Match/create a profile</span>
          </button>
          <button
            type="button"
            className={searchMode === "browse" ? "active" : ""}
            onClick={() => setSearchMode("browse")}
          >
            <strong>Browse Sources</strong>
            <span>Name optional; filter first</span>
          </button>
          <button
            type="button"
            className={searchMode === "photo" ? "active" : ""}
            onClick={() => setSearchMode("photo")}
          >
            <strong>Search by Photo</strong>
            <span>BabeWiki first</span>
          </button>
        </div>

        {searchMode === "browse" && (
          <div className="adult-browse-mode-note">
            <strong>Browse Discovery mode</strong>
            <span>Use this when the user does not have a specific performer in mind. Results are source/gallery pages that can later feed photo import or create/attach workflows.</span>
          </div>
        )}

        {searchMode === "photo" && (
          <div className="adult-photo-search-panel">
            <div className="adult-photo-search-copy">
              <strong>BabeWiki photo search</strong>
              <span>Upload a face/photo and Homestead starts with BabeWiki Face Search for performer lookup. Local Homestead AI matching remains available later through HOMESTEAD_FACE_RECOGNITION_URL.</span>
            </div>
            <label className="adult-photo-search-dropzone">
              {photoSearchPreview ? <img src={photoSearchPreview} alt="Photo search preview" /> : <span>📷</span>}
              <input type="file" accept="image/*" onChange={handlePhotoSearchFileChange} />
              <strong>{photoSearchFile?.name || "Choose photo"}</strong>
              <small>JPG, PNG, or WebP. Saved to Homestead for this search and used to prepare the BabeWiki handoff.</small>
            </label>
            {photoSearchUpload?.path && <code className="adult-photo-search-upload-path">Saved: {photoSearchUpload.path}</code>}
          </div>
        )}

        <div className="adult-advanced-query-row">
          <input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder={searchMode === "browse" ? "Optional: keyword, tag, source theme, or leave blank and use filters…" : searchMode === "photo" ? "Optional note/name hint for this photo search…" : "Search performer, celebrity, scene, studio, or keyword…"}
          />
          <button className="secondary-button" type="submit" disabled={loading}>
            {loading ? "Searching…" : searchMode === "browse" ? "Browse Sources" : searchMode === "photo" ? "Search Photo" : "Search Sources"}
          </button>
        </div>

        <div className={`adult-profile-type-selector ${searchMode === "photo" ? "adult-photo-hidden-filters" : ""}`} role="group" aria-label="Adult search profile type">
          {[
            { id: "performer", label: "Performers", hint: "Normal performer search" },
            { id: "metadata", label: "Metadata", hint: "Fix Match / profile fields" },
            { id: "media", label: "Videos", hint: "Media and scene results" },
            { id: "artwork", label: "Artwork", hint: "Posters, photos, covers" },
            { id: "studio", label: "Studio", hint: "Network/source browsing" },
            { id: "vr", label: "VR", hint: "VR-specific providers" },
            { id: "mature", label: "Mature", hint: "Niche mature providers" },
            { id: "celebrity", label: "Celebrities", hint: "Celebrity-only sources" },
            { id: "general", label: "Browse", hint: "General/tag browsing" },
            { id: "anime", label: "Anime/Tags", hint: "Tag image sources" },
            { id: "both", label: "All", hint: "All enabled providers" },
          ].map((type) => (
            <button
              key={type.id}
              type="button"
              className={`adult-profile-type-option ${profileType === type.id ? "active" : ""}`}
              onClick={() => setTextFilter("profileType", type.id)}
            >
              <strong>{type.label}</strong>
              <span>{type.hint}</span>
            </button>
          ))}
        </div>

        <div className={`adult-advanced-text-filters ${searchMode === "photo" ? "adult-photo-hidden-filters" : ""}`}>
          <label>
            <span>Age range</span>
            <input value={filters.ageRange || ""} onChange={(event) => setTextFilter("ageRange", event.target.value)} placeholder="18-25, 30+, etc." />
          </label>
          <label>
            <span>Country</span>
            <input value={filters.country || ""} onChange={(event) => setTextFilter("country", event.target.value)} placeholder="USA, Canada, Japan…" />
          </label>
          <label>
            <span>Studio/site</span>
            <input value={filters.studio || ""} onChange={(event) => setTextFilter("studio", event.target.value)} placeholder="Brazzers, Nubiles, etc." />
          </label>
          <label>
            <span>Quality</span>
            <input value={filters.quality || ""} onChange={(event) => setTextFilter("quality", event.target.value)} placeholder="1080p, 4K, VR…" />
          </label>
        </div>

        <div className={`adult-advanced-filter-sections ${searchMode === "photo" ? "adult-photo-hidden-filters" : ""}`}>
          {filterSections.map((section) => (
            <section key={section.id} className="adult-advanced-filter-section">
              <div className="adult-advanced-filter-section-header">
                <div>
                  <h3>{section.label}</h3>
                  <p>{section.hint}</p>
                </div>
              </div>
              <div className="adult-advanced-filter-grid">
                {section.groups.map((group) => (
                  <div key={group.key} className={`adult-advanced-filter-card ${group.compact ? "compact" : ""}`}>
                    <div className="adult-advanced-filter-title">
                      <strong>{group.label}</strong>
                      {hasFilterValue(filters[group.key]) && <button type="button" onClick={() => setTextFilter(group.key, "")}>clear</button>}
                    </div>
                    <div className="adult-advanced-chip-row">
                      {group.options.map((option) => (
                        <button
                          key={option}
                          type="button"
                          className={`adult-advanced-chip ${filterIncludes(filters[group.key], option) ? "active" : ""}`}
                          onClick={() => setFilter(group.key, option, { multi: Boolean(group.multi) })}
                        >
                          {option}
                        </button>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </section>
          ))}
        </div>

        {searchMode !== "photo" && activeFilters.length > 0 && (
          <div className="adult-active-filter-row">
            {activeFilters.map(([key, value]) => <span key={key}>{key}: {formatFilterLabel(value)}</span>)}
            <button type="button" onClick={clearFilters}>Clear all</button>
          </div>
        )}
      </form>

      <section className="panel adult-browse-results-panel">
        <div className="settings-section-header adult-browse-results-header">
          <div>
            <h3>{searchMode === "browse" ? "Browse Results" : "Provider Searches"}</h3>
            <p>{status}</p>
          </div>
          {results.length > 0 && (
            <div className="adult-browse-results-count">
              <strong>{results.length}</strong>
              <span>{searchMode === "browse" ? "source cards" : "searches"}</span>
            </div>
          )}
        </div>

        {searchMode === "browse" && (
          <div className="adult-browse-provider-notice" role="note" aria-label="Adult provider compatibility notice">
            <span className="adult-browse-provider-notice-icon" aria-hidden="true">⚠️</span>
            <div>
              <strong>External provider compatibility is experimental</strong>
              <p>
                These cards build links to third-party browse and gallery pages. Some providers may be offline,
                blocked by region or network filters, require an account/session, or change their page structure
                without notice. A card can therefore open a missing or unsupported page even when Homestead is working normally.
              </p>
            </div>
          </div>
        )}

        {adultProviderIds && Object.keys(adultProviderIds).length > 0 && (
          <div className="adult-provider-id-bridge-card">
            <strong>Wikidata ID bridge{adultWikidataMatch?.name ? ` · ${adultWikidataMatch.name}` : ""}</strong>
            <p>Homestead found provider IDs and used them before fallback search templates where a site supports direct IDs.</p>
            <div className="adult-provider-id-chip-row">
              {Object.entries(adultProviderIds).map(([key, value]) => (
                <code key={key}>{key}: {String(value)}</code>
              ))}
            </div>
          </div>
        )}

        {results.length === 0 ? (
          <p className="small-muted">{searchMode === "browse" ? "Choose filters and click Browse Sources to build gallery/media discovery source cards." : searchMode === "photo" ? "Choose a photo and click Search Photo. Homestead starts with BabeWiki Face Search and saves the upload for later local AI matching." : "Run a search to build provider-specific search pages."}</p>
        ) : orderedResultGroups.length === 0 ? (
          <div className="adult-source-result-grid adult-source-result-grid-flat">
            {results.map((result, index) => (
              <div key={result.id || `${result.source || "source"}-${index}`} className={`adult-source-result-card ${result.requiresSession ? "locked" : ""} ${String(result.type || "").includes("tag") ? "tag-page" : ""} ${result.reliabilityTier ? `candidate-${result.reliabilityTier}` : ""}`}>
                <div className="adult-source-result-icon"><AdultSourceIcon source={result} /></div>
                <div className="adult-source-result-main">
                  <strong>{result.title || result.source || result.name || "Adult source"}</strong>
                  <span>{result.adaptationNote || result.subtitle || result.notes || "Browse/search page ready."}</span>
                  <div className="adult-source-mini-badges result-badges">
                    {result.category && <span>{result.category}</span>}
                    {result.isPersonCandidate && <span>Person candidate</span>}
                    {result.canCreateProfile && <span>{result.reliabilityLabel || "Review candidate"}</span>}
                    {result.type && String(result.type).includes("browse") && <span>Browse result</span>}
                    {result.type && String(result.type).includes("tag") && <span>Virtual tag click</span>}
                    {result.canAttachToProfile && <span>Attach later</span>}
                    {(result.badges || []).slice(0, 4).map((badge) => <span key={badge}>{badge}</span>)}
                    {result.requiresSession && <span>Session</span>}
                  </div>
                  <code>{result.url}</code>
                </div>
                <div className="adult-source-card-actions">
                  {searchMode !== "browse" && (result.isPersonCandidate || result.canCreateProfile) && (
                    <button className="secondary-button request-button" type="button" onClick={() => openMatchCreate(result)}>{result.actionLabel || "Review/Create"}</button>
                  )}
                  <button className="secondary-button" type="button" onClick={() => openSource(result)}>Overlay</button>
                  <button className="secondary-button" type="button" onClick={() => openExternal(result)}>External</button>
                  <button className="secondary-button" type="button" onClick={() => copyUrl(result)}>Copy</button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="adult-provider-result-groups">
            {orderedResultGroups.map((group) => (
              <section key={group} className="adult-provider-result-group">
                <div className="adult-provider-result-group-header">
                  <h4>{group}</h4>
                  <span>{groupedResults[group].length} sources</span>
                </div>
                <div className="adult-source-result-grid">
                  {groupedResults[group].map((result, index) => (
                    <div key={result.id || `${group}-${result.source || "source"}-${index}`} className={`adult-source-result-card ${result.requiresSession ? "locked" : ""} ${String(result.type || "").includes("tag") ? "tag-page" : ""} ${result.reliabilityTier ? `candidate-${result.reliabilityTier}` : ""}`}>
                      <div className="adult-source-result-icon"><AdultSourceIcon source={result} /></div>
                      <div className="adult-source-result-main">
                        <strong>{result.title || result.source || result.name || "Adult source"}</strong>
                        <span>{result.adaptationNote || result.subtitle || result.notes || "Provider search ready."}</span>
                        <div className="adult-source-mini-badges result-badges">
                          {result.category && <span>{result.category}</span>}
                          {result.isPersonCandidate && <span>Person candidate</span>}
                          {result.canCreateProfile && <span>{result.reliabilityLabel || "Review candidate"}</span>}
                          {result.type && String(result.type).includes("browse") && <span>Browse result</span>}
                    {result.type && String(result.type).includes("tag") && <span>Virtual tag click</span>}
                          {result.canAttachToProfile && <span>Attach later</span>}
                          {(result.badges || []).slice(0, 4).map((badge) => <span key={badge}>{badge}</span>)}
                          {result.supportsFixMatch && <span>Fix Match</span>}
                          {result.supportsArtwork && <span>Artwork</span>}
                          {result.supportsImport && <span>Import</span>}
                          {result.requiresSession && <span>Session</span>}
                          {result.usedProviderId && <span>Wikidata ID</span>}
                        </div>
                        <code>{result.url}</code>
                      </div>
                      <div className="adult-source-card-actions">
                        {searchMode !== "browse" && (result.isPersonCandidate || result.canCreateProfile) && (
                          <button className="secondary-button request-button" type="button" onClick={() => openMatchCreate(result)}>{result.actionLabel || "Review/Create"}</button>
                        )}
                        <button className="secondary-button" type="button" onClick={() => openSource(result)}>Overlay</button>
                        <button className="secondary-button" type="button" onClick={() => openExternal(result)}>External</button>
                        <button className="secondary-button" type="button" onClick={() => copyUrl(result)}>Copy</button>
                      </div>
                    </div>
                  ))}
                </div>
              </section>
            ))}
          </div>
        )}
      </section>

      <details className="panel adult-included-sites-details">
        <summary>
          <div>
            <h3>Included Sites</h3>
            <p>Toggle sources on/off for this search. {hiddenByProfileTypeCount > 0 ? `${hiddenByProfileTypeCount} source(s) hidden by ${searchMode === "browse" ? "browse mode" : "profile type"}.` : "Source settings/templates can still be edited under Settings → Libraries → Adult."}</p>
          </div>
          <span>{selectedSourceIds.length} enabled</span>
        </summary>
        <div className="adult-source-toggle-grid adult-source-toggle-grid-collapsed">
          {matchingSources.map((source) => (
            <button key={source.id} type="button" className={`adult-source-toggle-card compact ${source.enabled !== false ? "active" : ""}`} onClick={() => toggleSource(source.id)}>
              <AdultSourceIcon source={source} />
              <div className="adult-source-toggle-info">
                <strong>{source.name}</strong>
                <small>{source.enabled !== false ? "Included" : "Off"} · {getAdultSourceRoleLabel(source)}</small>
                <div className="adult-source-mini-badges">
                  {(source.badges || []).slice(0, 3).map((badge) => <span key={badge}>{badge}</span>)}
                  {source.supportsFixMatch && <span>Fix Match</span>}
                  {source.supportsImport && <span>Import</span>}
                  {source.directProfileOnly && <span>Direct only</span>}
                  {source.requiresSession && <span>Session</span>}
                  {source.status === "disabled" && <span>Disabled</span>}
                </div>
              </div>
            </button>
          ))}
        </div>
      </details>

      {sourceBrowser && (
        <AdultSourceBrowserOverlay
          sourceBrowser={sourceBrowser}
          onClose={() => setSourceBrowser(null)}
          onOpenExternal={openExternal}
          backLabel="← Back to Search"
          titleFallback="Provider search"
        />
      )}
    </div>
  );
}


function inferAdultMatchProfileType(candidate = {}, fallbackType = "performer") {
  const rawType = normalizeAdultProfileType(candidate?.profileType || candidate?.libraryType || fallbackType || "performer");
  const providerText = String([
    candidate?.provider,
    candidate?.source,
    candidate?.sourceLabel,
    candidate?.url,
    candidate?.externalUrl,
    candidate?.subtitle,
  ].filter(Boolean).join(" ")).toLowerCase();

  const performerProviderPattern = /(definebabe|freeones|iafd|xxxbios|babewiki|thenude|eporner|pics-x|youpor[n]?|redtube|tube8|pornhub|xhamster|brazzers|iknowthatgirl|nubiles|adulttime|bangbros|whisparr|stash)/i;
  const celebrityProviderPattern = /(tmdb|themoviedb|models\.com|modeling|agency|imdb)/i;

  if (performerProviderPattern.test(providerText)) return "performer";
  if (celebrityProviderPattern.test(providerText) && rawType !== "personal") return "celebrity";
  return rawType;
}

function getAdultSuggestedSizes(metadata = {}) {
  const raw = String(metadata.measurements || metadata.measurementsRaw || metadata.bodyMeasurements || "").trim();
  const nums = raw.match(/\d+(?:\.\d+)?/g)?.map(Number) || [];
  const bust = Number(metadata.bust || nums[0]);
  const waist = Number(metadata.waist || nums[1]);
  const hips = Number(metadata.hips || nums[2]);
  const bra = String(metadata.braSize || metadata.bra || "").trim();
  let panty = String(metadata.pantySize || metadata.underwearSize || "").trim();
  if (!panty && (waist || hips)) {
    const basis = Math.max(waist || 0, (hips || 0) - 10);
    panty = basis <= 24 ? "XXS" : basis <= 26 ? "XS" : basis <= 28 ? "S" : basis <= 31 ? "M" : basis <= 34 ? "L" : basis <= 38 ? "XL" : "XXL";
  }
  return {
    bra: bra || (bust ? "Needs underbust measurement" : ""),
    panty,
    confidence: bra && panty ? "source" : panty ? "estimated" : "",
  };
}

const ADULT_PERSON_FULL_FETCH_CLIENT_TIMEOUT_MS = 30000;

function AdultPersonMatchCreatePage({ candidate, setupConfig, people = [], performers = [], celebrities = [], onBack, onCreated, onMatched, onOpenProfile }) {
  const initialType = inferAdultMatchProfileType(candidate, candidate?.libraryType === "celebrities" ? "celebrity" : "performer");
  const [profileType, setProfileType] = useState(initialType);
  const [name, setName] = useState(candidate?.name || candidate?.title || "");
  const [metadata, setMetadata] = useState(candidate?.metadata || {});
  const [bestCandidate, setBestCandidate] = useState(candidate || null);
  const [candidates, setCandidates] = useState(candidate ? [candidate] : []);
  const [selectedExistingId, setSelectedExistingId] = useState("");
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState("");
  const [viewMode, setViewMode] = useState("split");
  const [createdProfile, setCreatedProfile] = useState(null);
  const [fullFetchResult, setFullFetchResult] = useState(null);
  const [selectedFetchedMediaIds, setSelectedFetchedMediaIds] = useState([]);
  const [sourceUrlsText, setSourceUrlsText] = useState(() => {
    const urls = [candidate?.url || candidate?.externalUrl || candidate?.sourceUrl || ""];
    if (Array.isArray(candidate?.providerSearchLinks)) {
      urls.push(...candidate.providerSearchLinks.map((link) => link?.url).filter(Boolean));
    }
    if (Array.isArray(candidate?.referenceLinks)) {
      urls.push(...candidate.referenceLinks.map((link) => typeof link === "string" ? link : link?.url).filter(Boolean));
    }
    return [...new Set(urls.filter(Boolean))].join("\n");
  });

  const [manualMetadataFields, setManualMetadataFields] = useState(() => (
    Array.isArray(candidate?.metadata?.manualMetadataFields) ? candidate.metadata.manualMetadataFields : []
  ));

  function markManualMetadataFields(fields = []) {
    const cleanFields = fields.map((field) => String(field || "").trim()).filter(Boolean);
    if (!cleanFields.length) return;
    setManualMetadataFields((current) => [...new Set([...(current || []), ...cleanFields])]);
  }

  function hasManualMetadataValue(value) {
    if (value === undefined || value === null) return false;
    if (Array.isArray(value)) return value.length > 0;
    if (typeof value === "object") return Object.keys(value).length > 0;
    return String(value).trim() !== "";
  }

  function metadataInputValue(...fields) {
    for (const field of fields) {
      const value = metadata?.[field];
      if (Array.isArray(value)) return value.join(", ");
      if (value !== undefined && value !== null && String(value).trim() !== "") return String(value);
    }
    return "";
  }

  function metadataListText(...fields) {
    for (const field of fields) {
      const value = metadata?.[field];
      if (Array.isArray(value)) return value.join(", ");
      if (value !== undefined && value !== null && String(value).trim() !== "") return String(value);
    }
    return "";
  }

  function updateManualMetadataField(field, value, mirrorFields = []) {
    const fields = [field, ...mirrorFields].filter(Boolean);
    markManualMetadataFields(fields);
    setMetadata((current) => {
      const next = { ...(current || {}) };
      for (const target of fields) next[target] = value;
      next.manualMetadataFields = [...new Set([...(manualMetadataFields || []), ...fields])];
      next.manualMetadataUpdatedAt = new Date().toISOString();
      return next;
    });
  }

  function updateManualMetadataListField(field, value, mirrorFields = []) {
    const entries = String(value || "")
      .split(/[\n,]+/)
      .map((entry) => entry.trim())
      .filter(Boolean);
    const fields = [field, ...mirrorFields].filter(Boolean);
    markManualMetadataFields(fields);
    setMetadata((current) => {
      const next = { ...(current || {}) };
      for (const target of fields) next[target] = entries;
      next.manualMetadataFields = [...new Set([...(manualMetadataFields || []), ...fields])];
      next.manualMetadataUpdatedAt = new Date().toISOString();
      return next;
    });
  }

  const libraryType = profileType === "celebrity" ? "celebrities" : profileType === "personal" ? "personal" : "performers";
  const existingProfiles = libraryType === "celebrities"
    ? celebrities
    : libraryType === "personal"
      ? people
      : performers;
  const selectedExisting = existingProfiles.find((profile) => String(profile.id) === String(selectedExistingId));
  const normalizedWantedName = name.trim().toLowerCase();
  const suggestedExistingProfiles = existingProfiles
    .map((profile) => {
      const profileName = String(profile.name || profile.title || profile.id || "");
      const normalizedProfileName = profileName.toLowerCase();
      let score = 0;
      if (normalizedWantedName && normalizedProfileName === normalizedWantedName) score += 100;
      if (normalizedWantedName && normalizedProfileName.includes(normalizedWantedName)) score += 45;
      if (normalizedWantedName && normalizedWantedName.includes(normalizedProfileName)) score += 35;
      return { profile, score, profileName };
    })
    .filter((entry) => entry.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, 5);

  async function fullFetch() {
    if (!name.trim()) {
      setStatus("Enter a person name first.");
      return;
    }

    setLoading(true);
    setStatus("Fetching full metadata…");
    const requestController = new AbortController();
    const requestTimeoutHandle = window.setTimeout(
      () => requestController.abort(),
      ADULT_PERSON_FULL_FETCH_CLIENT_TIMEOUT_MS,
    );

    try {
      const response = await fetch("/api/metadata/adult/person/full-fetch", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        signal: requestController.signal,
        body: JSON.stringify({
          query: name.trim(),
          profileType,
          libraryType,
          candidate: bestCandidate,
          identityAnchor: {
            name: bestCandidate?.name || bestCandidate?.title || name.trim(),
            provider: bestCandidate?.provider || bestCandidate?.source || "",
            url: bestCandidate?.url || bestCandidate?.sourceUrl || bestCandidate?.externalUrl || "",
            profileType,
            libraryType,
          },
        }),
      });
      const data = await response.json();
      if (!response.ok || !data.ok) throw new Error(data.message || "Full metadata fetch failed");

      const fetchedMetadata = data.mergedMetadata || data.metadata || {};
      setMetadata((current) => {
        const preservedManual = {};
        for (const field of manualMetadataFields || []) {
          if (hasManualMetadataValue(current?.[field])) preservedManual[field] = current[field];
        }
        const next = { ...fetchedMetadata, ...preservedManual };
        if ((manualMetadataFields || []).length) {
          next.manualMetadataFields = [...new Set(manualMetadataFields)];
          next.manualMetadataUpdatedAt = current?.manualMetadataUpdatedAt || new Date().toISOString();
        }
        return next;
      });
      // Keep the user-selected identity anchored. A same-name result from another
      // profile lane must never replace the chosen performer/celebrity candidate.
      const anchoredCandidate = data.anchorCandidate || data.candidate || bestCandidate;
      setBestCandidate(anchoredCandidate || bestCandidate);
      setCandidates(data.candidates?.length ? data.candidates : candidates);
      setFullFetchResult(data.aggregation ? data : null);
      setSelectedFetchedMediaIds((data.mediaCandidates || []).map((item) => item.id));
      setStatus(data.message || "Full metadata fetched.");
    } catch (error) {
      setStatus(error?.name === "AbortError"
        ? `Metadata providers did not finish within ${Math.ceil(ADULT_PERSON_FULL_FETCH_CLIENT_TIMEOUT_MS / 1000)} seconds. The selected result is still available; retry or create the profile with its current fields.`
        : error.message || "Full metadata fetch failed.");
    } finally {
      window.clearTimeout(requestTimeoutHandle);
      setLoading(false);
    }
  }

  async function createProfile() {
    if (!name.trim()) {
      setStatus("Enter a profile name first.");
      return;
    }

    setLoading(true);
    setStatus("Creating profile…");

    try {
      const response = await fetch("/api/adult/profiles/create", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: name.trim(),
          profileType,
          libraryType,
          metadata: addDetectedSocialLinksToMetadata({
            ...metadata,
            manualMetadataFields,
            ...(manualMetadataFields.length ? { manualMetadataUpdatedAt: metadata.manualMetadataUpdatedAt || new Date().toISOString() } : {}),
          }, sourceUrlsText, bestCandidate, candidates),
          candidate: bestCandidate,
          sourceUrls: sourceUrlsText.split(/\n+/).map((url) => url.trim()).filter(Boolean),
        }),
      });
      const data = await response.json();
      if (!response.ok || !data.ok) throw new Error(data.message || "Profile creation failed");

      const selectedFetchedMedia = (fullFetchResult?.mediaCandidates || []).filter((item) => selectedFetchedMediaIds.includes(item.id));
      const syntheticMedia = selectedFetchedMedia.filter((item) => item.suspectedSynthetic);
      if (syntheticMedia.length && !window.confirm(`${syntheticMedia.length} selected image${syntheticMedia.length === 1 ? " is" : "s are"} flagged as potentially AI-generated or deepfaked. Continue importing the selected media?`)) {
        setStatus("Profile created. Flagged media was not imported.");
        selectedFetchedMedia.length = 0;
      }
      let importedMediaCount = 0;
      for (const item of selectedFetchedMedia) {
        try {
          const mediaResponse = await fetch("/api/adult/import-url", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              targetLibrary: libraryType,
              profileId: data.profile?.id || data.profileId || "",
              profileName: name.trim(),
              importType: item.kind === "gallery" ? "gallery" : "photo",
              sourceName: item.source || "profile-metadata-fetch",
              url: item.url,
            }),
          });
          const mediaData = await mediaResponse.json().catch(() => ({}));
          if (mediaResponse.ok && mediaData.ok !== false) importedMediaCount += Number(mediaData.importedCount || mediaData.imported?.length || 1);
        } catch { /* An individual candidate must not prevent profile creation. */ }
      }

      const createdProfileForUi = {
        ...(data.profile || {}),
        id: data.profile?.id || name.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""),
        name: data.profile?.name || name.trim(),
        library: libraryType,
        metadata: data.profile?.metadata || metadata,
        poster: data.profile?.poster || bestCandidate?.poster || bestCandidate?.profileImage || "/placeholder-poster.jpg",
        profileDir: data.profileDir || data.profile?.profileDir,
        metadataPath: data.metadataPath || data.profile?.metadataPath,
        createdFolders: data.createdFolders || data.profile?.createdFolders || [],
      };
      setCreatedProfile(createdProfileForUi);
      setStatus(`${data.message || `${createdProfileForUi.name} was created in ${libraryType}.`}${importedMediaCount ? ` Imported ${importedMediaCount} selected photo${importedMediaCount === 1 ? "" : "s"}.` : ""}`);
      onCreated?.(createdProfileForUi, libraryType, { keepOpen: true });
      window.dispatchEvent(new CustomEvent("homestead-adult-profile-updated", {
        detail: {
          reason: "profile-created",
          profile: createdProfileForUi,
          profileId: createdProfileForUi.id,
          profileName: createdProfileForUi.name,
          libraryType,
          metadata: createdProfileForUi.metadata || metadata,
        },
      }));
      window.dispatchEvent(new Event("homestead-metadata-match-updated"));
    } catch (error) {
      setStatus(error.message || "Profile creation failed.");
    } finally {
      setLoading(false);
    }
  }

  async function matchExisting() {
    if (!selectedExisting) {
      setStatus("Choose an existing profile to match first.");
      return;
    }

    setLoading(true);
    setStatus("Saving match to existing profile…");

    try {
      const response = await fetch("/api/metadata/adult/apply", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          person: selectedExisting,
          metadata: addDetectedSocialLinksToMetadata(metadata, sourceUrlsText, bestCandidate, candidates),
          candidate: bestCandidate,
        }),
      });
      const data = await response.json();
      if (!response.ok || !data.ok) throw new Error(data.message || "Match save failed");

      setStatus(data.message || "Matched existing profile.");
      onMatched?.(selectedExisting, data.metadata || metadata, libraryType);
      window.dispatchEvent(new CustomEvent("homestead-adult-profile-updated", {
        detail: {
          reason: "profile-matched",
          profile: selectedExisting,
          profileId: selectedExisting.id,
          profileName: selectedExisting.name || selectedExisting.title,
          libraryType,
          metadata: data.metadata || metadata,
        },
      }));
      window.dispatchEvent(new Event("homestead-metadata-match-updated"));
    } catch (error) {
      setStatus(error.message || "Match save failed.");
    } finally {
      setLoading(false);
    }
  }

  const confidence = bestCandidate?.confidence || candidate?.confidence || "";
  const numericConfidence = Number(confidence);
  const confidenceLabel = Number.isFinite(numericConfidence) && numericConfidence > 0
    ? `${Math.round(numericConfidence * 100)}% confidence`
    : confidence
      ? `${confidence} confidence`
      : "Confidence not scored";
  const sourceName = bestCandidate?.source || bestCandidate?.provider || candidate?.source || candidate?.provider || "External source";
  const sourceUrl = bestCandidate?.url || bestCandidate?.externalUrl || candidate?.url || candidate?.externalUrl || "";
  const reliabilityLabel = bestCandidate?.reliabilityLabel || bestCandidate?.matchLabel || (numericConfidence >= 0.85 ? "Likely profile" : numericConfidence >= 0.65 ? "Possible profile" : "Review needed");
  const exactExistingProfile = suggestedExistingProfiles.find(({ score }) => score >= 100);
  const sourceUrlCount = sourceUrlsText.split(/\n+/).map((url) => url.trim()).filter(Boolean).length;
  const fullFetchCoverage = fullFetchResult?.coverage || fullFetchResult?.aggregation?.coverage || null;
  const fullFetchSources = fullFetchResult?.sourceSummary || fullFetchResult?.aggregation?.sourceSummary || [];
  const fullFetchFieldGroups = fullFetchResult?.fieldGroups || fullFetchResult?.aggregation?.fieldGroups || [];
  const fullFetchConflicts = fullFetchResult?.conflicts || fullFetchResult?.aggregation?.conflicts || [];
  const fullFetchReviewNotes = fullFetchResult?.reviewNotes || fullFetchResult?.aggregation?.reviewNotes || [];
  const previewPayload = { profileType, libraryType, source: sourceName, confidence, sourceUrls: sourceUrlsText.split(/\n+/).map((url) => url.trim()).filter(Boolean), metadata, bestCandidate, fullFetch: fullFetchResult };

  return (
    <div className="generic-page adult-person-match-page adult-person-match-page-polished">
      <header className="adult-person-match-topbar">
        <button className="secondary-button adult-person-match-back" type="button" onClick={onBack}>← Back</button>
        <div>
          <strong>Match / Create Profile</strong>
        </div>
      </header>

      <section className="panel adult-person-match-hero adult-person-match-hero-clean">
        <div className="adult-person-match-poster adult-person-match-poster-clean">
          {bestCandidate?.poster || bestCandidate?.profileImage || bestCandidate?.image ? (
            <img src={bestCandidate.poster || bestCandidate.profileImage || bestCandidate.image} alt="" />
          ) : (
            <span>{profileType === "celebrity" ? "🌟" : "🔎"}</span>
          )}
        </div>

        <div className="adult-person-match-hero-main">
          <p className="adult-match-kicker">Review identity candidate</p>
          <h1>{name || candidate?.title || "Person result"}</h1>
          <div className="adult-match-pill-row">
            <span>{profileType === "celebrity" ? "Celebrity" : profileType === "personal" ? "Personal" : "Performer"}</span>
            <span>{sourceName}</span>
            <span>{confidenceLabel}</span>
            <span>{reliabilityLabel}</span>
          </div>
          <p className="adult-match-helper">
            Confirm the profile type, choose an existing Homestead profile when one already matches, or create a new profile with this source saved as a reference.
          </p>
          <div className="adult-person-match-source-actions">
            {sourceUrl && (
              <button className="secondary-button" type="button" onClick={() => window.open(sourceUrl, "_blank", "noopener,noreferrer")}>
                Open Source
              </button>
            )}
            <button className="secondary-button" type="button" onClick={fullFetch} disabled={loading}>
              {loading ? "Working…" : "Fetch Full Metadata"}
            </button>
          </div>
        </div>

        <aside className="adult-person-match-summary-card">
          <span>Recommended action</span>
          <strong>{exactExistingProfile ? "Match existing profile" : "Review, then create or match"}</strong>
          <p>{exactExistingProfile ? `${exactExistingProfile.profile.name || exactExistingProfile.profile.title || "Existing profile"} already exists in ${libraryType}.` : `${sourceUrlCount || 0} source URL${sourceUrlCount === 1 ? "" : "s"} ready to save.`}</p>
        </aside>
      </section>

      <section className="adult-person-match-workflow">
        <div className="panel adult-person-match-panel adult-person-match-details-panel">
          <div className="adult-person-match-section-title">
            <span>1</span>
            <div>
              <h3>Profile details</h3>
              <p>Choose the Homestead profile lane and confirm the saved name/source references.</p>
            </div>
          </div>

          <div className="adult-match-type-grid">
            {[
              ["performer", "Performer", "Adult performer source profile", "🎭"],
              ["celebrity", "Celebrity", "TMDB/Wikidata/Wikipedia source profile", "🌟"],
              ["personal", "Personal", "Private/person profile", "👤"],
            ].map(([id, label, hint, icon]) => (
              <button key={id} type="button" className={`adult-match-type-card ${profileType === id ? "active" : ""}`} onClick={() => setProfileType(id)}>
                <span>{icon}</span>
                <strong>{label}</strong>
                <small>{hint}</small>
              </button>
            ))}
          </div>

          <div className="adult-person-match-form-grid">
            <label className="adult-person-match-field">
              <span>Profile name</span>
              <input value={name} onChange={(event) => setName(event.target.value)} />
            </label>

            <label className="adult-person-match-field adult-person-match-wide-field">
              <span>Source URL(s)</span>
              <textarea value={sourceUrlsText} onChange={(event) => setSourceUrlsText(event.target.value)} rows={3} placeholder="One source URL per line…" />
            </label>
          </div>

          <details className="adult-manual-metadata-panel" open>
            <summary>
              <div>
                <strong>Manual metadata</strong>
                <p>Add or correct fields before creating the profile. Manual fields are preserved if you fetch metadata again.</p>
              </div>
              <span>{manualMetadataFields.length ? `${manualMetadataFields.length} edited` : "Optional"}</span>
            </summary>

            <div className="adult-manual-metadata-section">
              <h4>Identity</h4>
              <div className="adult-manual-metadata-grid">
                <label className="adult-person-match-field">
                  <span>Aliases</span>
                  <input value={metadataListText("aliases", "alsoKnownAs")} onChange={(event) => updateManualMetadataListField("aliases", event.target.value, ["alsoKnownAs"])} placeholder="Comma-separated aliases" />
                </label>
                <label className="adult-person-match-field">
                  <span>Birthday</span>
                  <DisplayFieldInput field="birthday" value={metadataInputValue("birthday", "birthDate")} onChange={(event) => updateManualMetadataField("birthday", event.target.value, ["birthDate"])} placeholder="YYYY-MM-DD or source text" />
                </label>
                <label className="adult-person-match-field">
                  <span>Birthplace</span>
                  <input value={metadataInputValue("birthPlace", "placeOfBirth")} onChange={(event) => updateManualMetadataField("birthPlace", event.target.value, ["placeOfBirth"])} placeholder="City, state/country" />
                </label>
                <label className="adult-person-match-field">
                  <span>Official website</span>
                  <input value={metadataInputValue("officialWebsite")} onChange={(event) => updateManualMetadataField("officialWebsite", event.target.value)} placeholder="https://…" />
                </label>
              </div>
            </div>

            <div className="adult-manual-metadata-section">
              <h4>Body / appearance</h4>
              <div className="adult-manual-metadata-grid">
                <label className="adult-person-match-field">
                  <span>Height</span>
                  <DisplayFieldInput field="height" value={metadataInputValue("height")} onChange={(event) => updateManualMetadataField("height", event.target.value)} placeholder={'5\'2" / 157 cm'} />
                </label>
                <label className="adult-person-match-field">
                  <span>Weight</span>
                  <DisplayFieldInput field="weight" value={metadataInputValue("weight")} onChange={(event) => updateManualMetadataField("weight", event.target.value)} placeholder="Source text" />
                </label>
                <label className="adult-person-match-field">
                  <span>Measurements</span>
                  <DisplayFieldInput field="measurements" value={metadataInputValue("measurements", "measurementsRaw")} onChange={(event) => updateManualMetadataField("measurements", event.target.value, ["measurementsRaw"])} placeholder="Bust-waist-hips" />
                </label>
                <label className="adult-person-match-field">
                  <span>Bra / cup size</span>
                  <input value={metadataInputValue("braSize", "cupSize")} onChange={(event) => updateManualMetadataField("braSize", event.target.value, ["cupSize"])} placeholder="Example: 32B" />
                </label>
                <label className="adult-person-match-field">
                  <span>Hair color</span>
                  <input value={metadataInputValue("hairColor", "hair")} onChange={(event) => updateManualMetadataField("hairColor", event.target.value, ["hair"])} placeholder="Blonde, brunette…" />
                </label>
                <label className="adult-person-match-field">
                  <span>Eye color</span>
                  <input value={metadataInputValue("eyeColor", "eyes")} onChange={(event) => updateManualMetadataField("eyeColor", event.target.value, ["eyes"])} placeholder="Blue, brown…" />
                </label>
                <label className="adult-person-match-field">
                  <span>Tattoos</span>
                  <input value={metadataListText("tattoos")} onChange={(event) => updateManualMetadataListField("tattoos", event.target.value)} placeholder="Comma-separated notes" />
                </label>
                <label className="adult-person-match-field">
                  <span>Piercings</span>
                  <input value={metadataListText("piercings")} onChange={(event) => updateManualMetadataListField("piercings", event.target.value)} placeholder="Comma-separated notes" />
                </label>
              </div>
            </div>

            <div className="adult-manual-metadata-section">
              <h4>Bio / notes</h4>
              <div className="adult-manual-metadata-grid">
                <label className="adult-person-match-field adult-person-match-wide-field">
                  <span>Biography</span>
                  <textarea value={metadataInputValue("biography", "description")} onChange={(event) => updateManualMetadataField("biography", event.target.value, ["description"])} rows={4} placeholder="Short biography or source-backed summary…" />
                </label>
                <label className="adult-person-match-field adult-person-match-wide-field">
                  <span>Private notes</span>
                  <textarea value={metadataInputValue("notes", "manualNotes")} onChange={(event) => updateManualMetadataField("notes", event.target.value, ["manualNotes"])} rows={3} placeholder="Optional notes for your library only…" />
                </label>
              </div>
            </div>
          </details>
        </div>

        <div className="panel adult-person-match-panel adult-person-match-decision-panel">
          <div className="adult-person-match-section-title">
            <span>2</span>
            <div>
              <h3>Match or create</h3>
              <p>Prefer matching when Homestead already has the person to avoid duplicates.</p>
            </div>
          </div>

          {exactExistingProfile && (
            <div className="adult-person-match-warning-card">
              <strong>Existing profile detected</strong>
              <p>{exactExistingProfile.profile.name || exactExistingProfile.profile.title || "This profile"} looks like an exact match. Matching is safer than creating a duplicate.</p>
            </div>
          )}

          <label className="adult-person-match-field">
            <span>Existing {libraryType}</span>
            <select value={selectedExistingId} onChange={(event) => setSelectedExistingId(event.target.value)}>
              <option value="">Choose existing profile…</option>
              {existingProfiles.map((profile) => (
                <option key={profile.id || profile.name} value={profile.id}>{profile.name || profile.title || profile.id}</option>
              ))}
            </select>
          </label>

          {suggestedExistingProfiles.length > 0 && (
            <div className="adult-person-match-suggestions adult-person-match-suggestions-clean">
              <strong>Possible existing matches</strong>
              {suggestedExistingProfiles.map(({ profile, score }) => (
                <button key={profile.id || profile.name} type="button" onClick={() => setSelectedExistingId(profile.id)} className={String(selectedExistingId) === String(profile.id) ? "active" : ""}>
                  <span>{profile.name || profile.title || profile.id}</span>
                  <em>{score >= 100 ? "Exact" : "Similar"}</em>
                </button>
              ))}
            </div>
          )}

          <div className="adult-person-match-actions adult-person-match-actions-clean">
            <button className="secondary-button" type="button" onClick={matchExisting} disabled={loading || !selectedExistingId || Boolean(createdProfile)}>
              Match Existing
            </button>
            <button className="secondary-button request-button" type="button" onClick={createProfile} disabled={loading || Boolean(createdProfile)}>
              {createdProfile ? "Profile Created" : "Create New Profile"}
            </button>
          </div>

          {status && <p className={`adult-person-match-status ${createdProfile ? "success" : ""}`}>{status}</p>}

          {createdProfile && (
            <div className="adult-person-match-created-card">
              <div>
                <strong>Created successfully</strong>
                <p>{createdProfile.name || name} was added to {libraryType}. The profile list has already been refreshed in the background.</p>
                {createdProfile.profileDir && <small>Folder: {createdProfile.profileDir}</small>}
                {createdProfile.metadataPath && <small>Metadata: {createdProfile.metadataPath}</small>}
              </div>
              <div className="adult-person-match-created-actions">
                <button className="secondary-button request-button" type="button" onClick={() => onOpenProfile?.(createdProfile, libraryType)}>
                  Open Profile
                </button>
                <button className="secondary-button" type="button" onClick={onBack}>
                  Back to {libraryType === "celebrities" ? "Celebrities" : libraryType === "personal" ? "Personal" : "Performers"}
                </button>
              </div>
            </div>
          )}
        </div>
      </section>

      {fullFetchResult && (
        <section className="panel adult-full-fetch-review-panel">
          <div className="settings-section-header">
            <div>
              <p className="small-muted">Phase 3 full metadata aggregation</p>
              <h3>Metadata Review</h3>
              <p>Homestead merged the best available fields from the enabled source profile. Low-confidence and conflicting values stay source-tagged for review.</p>
            </div>
            {fullFetchCoverage && (
              <div className="adult-full-fetch-score-card">
                <strong>{fullFetchCoverage.percent}%</strong>
                <span>{fullFetchCoverage.filledFields}/{fullFetchCoverage.totalFields} fields</span>
              </div>
            )}
          </div>

          {fullFetchReviewNotes.length > 0 && (
            <div className="adult-full-fetch-note-list">
              {fullFetchReviewNotes.map((note) => <span key={note}>{note}</span>)}
            </div>
          )}

          <div className="adult-full-fetch-summary-grid">
            <div><strong>{fullFetchSources.length}</strong><span>Sources used</span></div>
            <div><strong>{fullFetchConflicts.length}</strong><span>Conflicts</span></div>
            <div><strong>{Object.keys(metadata || {}).length}</strong><span>Merged fields</span></div>
          </div>

          {fullFetchSources.length > 0 && (
            <div className="adult-full-fetch-source-row">
              {fullFetchSources.slice(0, 6).map((source) => (
                <div key={`${source.provider}-${source.url || source.source}`} className={`adult-full-fetch-source-chip ${source.lowConfidenceFallback ? "weak" : ""}`}>
                  <strong>{source.source || source.provider}</strong>
                  <span>{source.fields?.length || 0} fields • {Number.isFinite(Number(source.confidence)) && Number(source.confidence) > 0 ? `${Math.round(Number(source.confidence) * 100)}%` : "unscored"}</span>
                </div>
              ))}
            </div>
          )}

          {(fullFetchResult.mediaCandidates || []).length > 0 && (
            <details className="adult-full-fetch-media-review" open>
              <summary>Photos and galleries to import ({selectedFetchedMediaIds.length} selected)</summary>
              <p>Uncheck anything you want to skip. Homestead imports selected media only after the profile is created and keeps its source name.</p>
              <div className="adult-full-fetch-media-grid">
                {(fullFetchResult.mediaCandidates || []).map((item) => (
                  <label key={item.id} className="adult-full-fetch-media-option">
                    <input type="checkbox" checked={selectedFetchedMediaIds.includes(item.id)} onChange={() => setSelectedFetchedMediaIds((current) => current.includes(item.id) ? current.filter((id) => id !== item.id) : [...current, item.id])} />
                    <img src={item.url} alt="" loading="lazy" referrerPolicy="no-referrer" />
                    <span><strong>{item.title || "Photo"}</strong><small>{item.source || "External source"}{item.suspectedSynthetic ? " · AI/deepfake warning" : ""}</small></span>
                  </label>
                ))}
              </div>
            </details>
          )}

          {fullFetchFieldGroups.length > 0 && (
            <div className="adult-full-fetch-field-groups">
              {fullFetchFieldGroups.slice(0, 4).map((group) => (
                <details key={group.id} className="adult-full-fetch-field-group" open={group.id === "identity" || group.id === "body"}>
                  <summary>
                    <strong>{group.label}</strong>
                    <span>{group.fields.length} fields</span>
                  </summary>
                  <div className="adult-full-fetch-field-list">
                    {group.fields.slice(0, 10).map((field) => (
                      <div key={field.key} className="adult-full-fetch-field-row">
                        <span>{field.label}</span>
                        <strong>{formatHomesteadField(field.key, field.chosen?.value ?? field.chosen?.valuePreview)}</strong>
                        <em>{field.chosen?.source || "Source"}</em>
                      </div>
                    ))}
                  </div>
                </details>
              ))}
            </div>
          )}

          {fullFetchConflicts.length > 0 && (
            <details className="adult-full-fetch-conflicts">
              <summary>Review conflicting fields ({fullFetchConflicts.length})</summary>
              <div className="adult-full-fetch-conflict-list">
                {fullFetchConflicts.slice(0, 8).map((conflict) => (
                  <div key={conflict.field} className="adult-full-fetch-conflict-card">
                    <strong>{conflict.label}</strong>
                    <span>Chosen: {conflict.chosen}</span>
                    {conflict.options?.slice(0, 3).map((option) => (
                      <p key={`${conflict.field}-${option.source}-${option.value}`}>{option.source}: {option.value}</p>
                    ))}
                  </div>
                ))}
              </div>
            </details>
          )}
        </section>
      )}

      <details className="panel adult-person-metadata-details">
        <summary>
          <div>
            <h3>Metadata Preview</h3>
            <p>Collapsed by default so the create/match decision stays visible.</p>
          </div>
          <span>{Object.keys(metadata || {}).length} metadata fields</span>
        </summary>
        <pre className="metadata-review-json">{JSON.stringify(previewPayload, null, 2)}</pre>
      </details>

      {candidates.length > 1 && (
        <details className="panel adult-person-other-candidates">
          <summary>
            <div>
              <h3>Other candidates</h3>
              <p>Review alternates only when the top candidate looks wrong.</p>
            </div>
            <span>{Math.min(candidates.length - 1, 8)} shown</span>
          </summary>
          <div className="full-search-result-list adult-person-other-candidate-list">
            {candidates.slice(1, 9).map((item) => (
              <button key={item.id || item.url || item.name} className="global-search-result" type="button" onClick={() => { setBestCandidate(item); setName(item.name || item.title || name); }}>
                <span>{item.icon || "🔎"}</span>
                <div>
                  <strong>{item.name || item.title}</strong>
                  <p>{item.subtitle || item.source || item.provider}</p>
                </div>
              </button>
            ))}
          </div>
        </details>
      )}
    </div>
  );
}

function AdultPerformerDiscoveryPage({ discoverySeed, setupConfig, onBack }) {
  const seedQuery = discoverySeed?.title || discoverySeed?.name || discoverySeed?.query || "";
  const initialDiscovery = discoverySeed?.discovery || null;
  const [discovery, setDiscovery] = useState(initialDiscovery);
  const [loading, setLoading] = useState(!initialDiscovery);
  const [selectedItems, setSelectedItems] = useState({});
  const [mode, setMode] = useState(
    setupConfig?.adultWhisparrMode ||
      setupConfig?.libraryPreferences?.adult?.whisparrMode ||
      initialDiscovery?.mode ||
      "browse"
  );
  const [status, setStatus] = useState("");
  const [viewMode, setViewMode] = useState("split");
  const [whisparrStatus, setWhisparrStatus] = useState({ loading: true, connected: false, configured: false });
  const [sourceStatus, setSourceStatus] = useState("");
  const [sourceBrowser, setSourceBrowser] = useState(null);

  useEffect(() => {
    let cancelled = false;

    fetch("/api/integrations/whisparr/status")
      .then((res) => res.json())
      .then((data) => {
        if (!cancelled) setWhisparrStatus({ ...data, loading: false });
      })
      .catch((error) => {
        if (!cancelled) {
          setWhisparrStatus({ loading: false, connected: false, configured: false, message: error.message });
        }
      });

    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (!seedQuery) return;

    let cancelled = false;
    setLoading(true);

    fetch(`/api/discovery/adult/search?q=${encodeURIComponent(seedQuery)}`)
      .then((res) => res.json())
      .then((data) => {
        if (cancelled) return;
        setDiscovery(data?.ok ? data : initialDiscovery);
      })
      .catch((error) => {
        if (!cancelled) setStatus(error.message || "Adult discovery failed");
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [seedQuery]);

  const performer = discovery?.performer || discoverySeed || { name: seedQuery };
  const scenes = discovery?.scenes || [];
  const photos = discovery?.photos || [];
  const artwork = discovery?.artwork || [];
  const sources = discovery?.sources || [];
  const allSelectable = [...scenes, ...photos, ...artwork];
  const selectedList = allSelectable.filter((item) => selectedItems[item.id]);

  function toggleSelected(item) {
    setSelectedItems((current) => ({ ...current, [item.id]: !current[item.id] }));
  }

  async function requestSelected() {
    if (!selectedList.length) {
      setStatus("Select at least one scene/photo/artwork item first.");
      return;
    }

    setStatus("Sending selected items…");

    try {
      const response = await fetch("/api/discovery/adult/request-selected", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query: performer.name || seedQuery, mode, selected: selectedList }),
      });
      const data = await response.json();

      if (!response.ok || !data.ok) {
        throw new Error(data.message || "Failed to request selected items");
      }

      setStatus(data.message || "Selected adult discovery items were saved/requested.");
    } catch (error) {
      setStatus(error.message || "Failed to request selected items");
    }
  }

  async function refreshWhisparrStatus() {
    setWhisparrStatus((current) => ({ ...current, loading: true }));

    try {
      const response = await fetch("/api/integrations/whisparr/status?refresh=1");
      const data = await response.json();
      setWhisparrStatus({ ...data, loading: false });
    } catch (error) {
      setWhisparrStatus({ loading: false, connected: false, configured: false, message: error.message });
    }
  }

  async function searchWhisparr() {
    if (!seedQuery) return;

    setStatus("Searching Whisparr…");

    try {
      const response = await fetch(`/api/discovery/adult/whisparr-search?q=${encodeURIComponent(seedQuery)}`);
      const data = await response.json();

      if (!response.ok || !data.ok) {
        throw new Error(data.message || "Whisparr search failed");
      }

      setDiscovery((current) => ({
        ...(current || {}),
        ...data.discovery,
        scenes: data.scenes || data.discovery?.scenes || [],
        summary: {
          ...(current?.summary || {}),
          ...(data.discovery?.summary || {}),
          scenes: (data.scenes || []).length,
        },
      }));
      setStatus(data.message || `Whisparr returned ${(data.scenes || []).length} candidate scenes.`);
    } catch (error) {
      setStatus(error.message || "Whisparr search failed");
    }
  }

  function openSource(source) {
    if (!source?.url) return;
    setSourceBrowser({
      title: source.source || source.provider || source.title || "Adult Source",
      subtitle: source.subtitle || source.title || "Source search",
      url: source.url,
    });
  }

  function closeSourceBrowser() {
    setSourceBrowser(null);
  }

  function openSourceExternal() {
    if (!sourceBrowser?.url) return;
    window.open(sourceBrowser.url, "_blank", "noopener,noreferrer");
  }

  async function copySourceUrl(source) {
    if (!source?.url) return;

    try {
      await navigator.clipboard.writeText(source.url);
      setSourceStatus(`Copied ${source.source || source.provider} search URL.`);
    } catch {
      setSourceStatus(source.url);
    }
  }

  function renderCandidate(item) {
    const isSelected = !!selectedItems[item.id];
    return (
      <button
        key={item.id}
        className={`adult-discovery-card ${isSelected ? "selected" : ""}`}
        type="button"
        onClick={() => toggleSelected(item)}
      >
        <div className="adult-discovery-thumb">
          {item.thumbnail || item.poster ? <img src={item.thumbnail || item.poster} alt="" /> : <span>{item.type === "artwork" ? "🖼️" : "🎞️"}</span>}
        </div>
        <div className="adult-discovery-card-body">
          <strong>{item.title || item.name}</strong>
          <p>{item.source || item.provider || "Source"} {item.date ? `• ${formatHomesteadDate(item.date)}` : ""}</p>
          <span>{isSelected ? "Selected" : item.status || "Available"}</span>
        </div>
      </button>
    );
  }

  return (
    <div className="generic-page adult-discovery-page">
      <button className="secondary-button" type="button" onClick={onBack}>← Back</button>

      <section className="panel adult-discovery-hero-panel">
        <div>
          <p className="small-muted">Adult Discovery</p>
          <h1>{performer.name || seedQuery}</h1>
          <p>
            Browse configured sources and select the exact scenes/photos/artwork to request. Homestead does not auto-grab everything for a monitored performer.
          </p>
        </div>
        <div className="adult-discovery-summary-grid">
          <div><strong>{discovery?.summary?.scenes || scenes.length}</strong><span>Scenes</span></div>
          <div><strong>{discovery?.summary?.artwork || artwork.length}</strong><span>Artwork</span></div>
          <div><strong>{discovery?.summary?.sources || sources.length}</strong><span>Sources</span></div>
        </div>
      </section>

      <section className="panel adult-discovery-whisparr-panel">
        <div className="settings-section-header">
          <div>
            <h3>Whisparr Connection</h3>
            <p>Use Whisparr as the acquisition handoff. Source websites can still be opened manually while provider parsers are built.</p>
          </div>
          <div className="adult-discovery-action-row">
            <button className="secondary-button" type="button" onClick={refreshWhisparrStatus}>
              Test
            </button>
            <button className="secondary-button" type="button" onClick={searchWhisparr} disabled={!whisparrStatus.configured}>
              Search Whisparr
            </button>
          </div>
        </div>

        <div className="adult-discovery-status-grid">
          <div className={`adult-discovery-status-card ${whisparrStatus.connected ? "good" : whisparrStatus.configured ? "warning" : "neutral"}`}>
            <strong>{whisparrStatus.loading ? "Checking…" : whisparrStatus.connected ? "Connected" : whisparrStatus.configured ? "Configured" : "Not configured"}</strong>
            <span>{whisparrStatus.message || (whisparrStatus.connected ? "Whisparr is reachable." : "Add Whisparr URL/API key in Integrations.")}</span>
          </div>
          <div className="adult-discovery-status-card">
            <strong>{whisparrStatus.baseUrl || "No URL"}</strong>
            <span>{whisparrStatus.apiKeyPresent ? "API key present" : "API key missing"}</span>
          </div>
          <div className="adult-discovery-status-card">
            <strong>{scenes.length}</strong>
            <span>Whisparr/source scene candidates loaded</span>
          </div>
        </div>
      </section>

      <section className="panel adult-discovery-mode-panel">
        <div className="settings-section-header">
          <div>
            <h3>Whisparr Mode</h3>
            <p>Browse first by default. Only selected items are sent to Whisparr/indexers/torrent workflow.</p>
          </div>
          <button className="secondary-button" type="button" onClick={requestSelected} disabled={mode === "browse" || !selectedList.length}>
            Request Selected ({selectedList.length})
          </button>
        </div>

        <div className="adult-discovery-mode-grid">
          {[
            ["browse", "Browse only", "Search and preview without sending requests."],
            ["requestSelected", "Request selected", "Send only checked items to Whisparr when supported."],
            ["monitorNew", "Monitor new", "Future mode for selective monitoring."],
            ["autoGrabAll", "Auto-grab all", "Advanced/off-by-default bulk mode."],
          ].map(([id, title, description]) => (
            <button key={id} className={`settings-toggle-card ${mode === id ? "active" : ""}`} type="button" onClick={() => setMode(id)}>
              <strong>{title}</strong>
              <p>{description}</p>
            </button>
          ))}
        </div>
        {status && <p className="small-muted">{status}</p>}
      </section>

      {loading && <section className="panel"><p>Loading adult discovery…</p></section>}

      {scenes.length > 0 && (
        <section className="panel">
          <h3>Available Scenes</h3>
          <div className="adult-discovery-grid">{scenes.map(renderCandidate)}</div>
        </section>
      )}

      {artwork.length > 0 && (
        <section className="panel">
          <h3>Artwork / Photo Sources</h3>
          <div className="adult-discovery-grid">{artwork.map(renderCandidate)}</div>
        </section>
      )}

      {sources.length > 0 && (
        <section className="panel">
          <div className="settings-section-header">
            <div>
              <h3>Configured Source Searches</h3>
              <p>Open the exact provider search now. Later, each provider parser can turn these results into selectable scene/photo candidates.</p>
            </div>
          </div>

          <div className="adult-source-link-grid adult-source-search-grid">
            {sources.map((source) => (
              <div key={source.id} className="adult-source-link-card adult-source-search-card">
                <strong>{source.source || source.provider}</strong>
                <span>{source.subtitle || source.title}</span>
                <code>{source.url}</code>
                <div className="adult-source-card-actions">
                  <button className="secondary-button" type="button" onClick={() => openSource(source)}>
                    Open Search
                  </button>
                  <button className="secondary-button" type="button" onClick={() => copySourceUrl(source)}>
                    Copy URL
                  </button>
                </div>
              </div>
            ))}
          </div>
          {sourceStatus && <p className="small-muted">{sourceStatus}</p>}
        </section>
      )}

      {sourceBrowser && (
        <AdultSourceBrowserOverlay
          sourceBrowser={sourceBrowser}
          onClose={closeSourceBrowser}
          onOpenExternal={openSourceExternal}
          backLabel="← Back to Discovery"
          titleFallback="Provider search"
        />
      )}
    </div>
  );
}


