          <label><span>Tab transparency</span><input type="range" min="0" max="1" step="0.01" value={values.tabOpacity} onChange={(e) => setNumber("tabOpacity", e.target.value)} /><strong>{Math.round(values.tabOpacity * 100)}%</strong></label>
