useEffect(() => {
  function slugProfileName(value = "") {
    return String(value || "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/(^-|-$)/g, "") || "untitled";
  }

  function handleAdultMediaImported(event) {
    const detail = event?.detail || {};
    const importedAs = String(detail.importedAs || detail.destination || detail.record?.type || "").toLowerCase();
    if (!["poster", "banner"].includes(importedAs)) return;

    const libraryType = String(detail.targetLibrary || detail.libraryType || detail.scanLibrary || "performers").toLowerCase();
    const profileId = detail.profileId || slugProfileName(detail.profileName || "");
    if (!profileId) return;

    const relativeDestination = detail.relativeDestination || detail.record?.relativeDestination || `${importedAs}.jpg`;
    const cacheBuster = `?v=${Date.now()}`;
    const mediaUrl = `/media/${libraryType}/${profileId}/${relativeDestination}${cacheBuster}`;
    const applyUpdate = (item) => item.id === profileId
      ? { ...item, [importedAs]: mediaUrl, poster: importedAs === "poster" ? mediaUrl : item.poster }
      : item;

    if (libraryType === "celebrities") setCelebrities((current) => current.map(applyUpdate));
    else if (libraryType === "personal" || libraryType === "girls") setPeople((current) => current.map(applyUpdate));
    else setPerformers((current) => current.map(applyUpdate));

    setSelected((current) => current?.id === profileId ? applyUpdate(current) : current);
  }

  window.addEventListener("homestead-adult-media-imported", handleAdultMediaImported);
  return () => window.removeEventListener("homestead-adult-media-imported", handleAdultMediaImported);
}, []);

useEffect(() => {
  function slugProfileName(value = "") {
    return String(value || "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/(^-|-$)/g, "") || "untitled";
  }

  function normalizeAdultLibrary(value = "") {
    const clean = String(value || "performers").toLowerCase();
    if (clean === "celebrity") return "celebrities";
    if (clean === "performer") return "performers";
    if (clean === "girls") return "personal";
    return clean || "performers";
  }

  function handleAdultProfileUpdated(event) {
    const detail = event?.detail || {};
    const profile = detail.profile || {};
    const metadata = detail.metadata || profile.metadata || {};
    const libraryType = normalizeAdultLibrary(detail.libraryType || profile.library || detail.targetLibrary || detail.scanLibrary || "performers");
    const profileId = detail.profileId || profile.id || slugProfileName(detail.profileName || profile.name || profile.title || "");
    if (!profileId) return;
    const assignedArtwork = detail.publicUrl || detail.publicPath || "";

    const mergeProfile = (item) => {
      if (String(item.id) !== String(profileId)) return item;

      const nextMetadata = {
        ...(item.metadata || {}),
        ...(metadata || {}),
      };

      return {
        ...item,
        ...profile,
        id: item.id,
        metadata: nextMetadata,
        name: nextMetadata.name || profile.name || item.name,
        title: nextMetadata.name || profile.title || item.title,
        birthday: nextMetadata.birthday || nextMetadata.birthDate || profile.birthday || item.birthday,
        summary: nextMetadata.biography || nextMetadata.description || profile.summary || item.summary,
        poster: detail.poster || (detail.action === "poster" ? assignedArtwork : "") || profile.poster || item.poster,
        banner: detail.banner || (detail.action === "banner" ? assignedArtwork : "") || profile.banner || item.banner,
        headshot: detail.headshot || (detail.action === "headshot" ? assignedArtwork : "") || profile.headshot || item.headshot,
      };
    };

    if (libraryType === "celebrities") setCelebrities((current) => current.map(mergeProfile));
    else if (libraryType === "personal") setPeople((current) => current.map(mergeProfile));
    else setPerformers((current) => current.map(mergeProfile));

    setSelected((current) => {
      if (!current || String(current.id) !== String(profileId)) return current;
      return mergeProfile(current);
    });
  }

  window.addEventListener("homestead-adult-profile-updated", handleAdultProfileUpdated);
  return () => window.removeEventListener("homestead-adult-profile-updated", handleAdultProfileUpdated);
}, []);
  
