function handleSearchSelect(result) {
  setQuery("");

  if (result.pluginId) {
    setActiveLibrary(`plugin:${result.pluginId}`);
    sendPluginHostCommand(result.pluginId, "open-result", { target: result.searchTarget || { id: result.id, title: result.title } });
    return;
  }

  if (result.person) {
    setSelected(result.person);
    setActiveLibrary(result.library);
    return;
  }

  if (result.type === "movie") {
    setDashboardOpen({ type: "movie", id: result.id });
    setActiveLibrary("movies");
    return;
  }

  if (result.type === "tv") {
    setDashboardOpen({ type: "tv", id: result.id });
    setActiveLibrary("tv");
    return;
  }

  if (result.type === "book") {
    setDashboardOpen({ type: "book", id: result.id });
    setActiveLibrary("books");
    return;
  }

  if (result.type === "music") {
    setDashboardOpen({ type: "music", id: result.id });
    setActiveLibrary("music");
    return;
  }

  if (result.type === "youtube") {
    setDashboardOpen({ type: "youtube", id: result.id });
    setActiveLibrary("youtube");
    return;
  }

  if (result.type === "tcg-card" || result.type === "inventory-item") {
    setActiveLibrary("inventory");
    return;
  }
}

